('part_noun_0', 'part', 'noun', 0, 'A piece or component of a larger object or system.', '["piece", "component", "section", "segment", "portion"]', '["whole", "entirety", "total"]', '["entity", "object", "unit"]', '["piece", "section", "segment", "module"]', '["part of speech", "part of the day", "take part", "part time", "part of the plan", "part of a machine"]', '{"noun_forms": ["parting"], "verb_forms": [], "adjective_forms": ["partial"], "adverb_forms": ["partly"]}', '["Each part of the machine must be checked.", "A single part helps explain the system."]', 'technology', '1', 2216807, 100, NULL, 'opengloss-v1.1'),
('part_verb_0', 'part', 'verb', 0, 'To divide something into parts or pieces; to separate a whole into smaller portions.', '["divide", "split", "separate"]', '["join", "unite"]', '["division", "separation"]', '["slice", "section", "partition"]', '["part ways", "part with", "part the cake", "part the hair", "part company", "part the dough"]', '{"noun_forms": ["partition", "parting"], "verb_forms": [], "adjective_forms": ["partial"], "adverb_forms": ["partly"]}', '["We part the dough into four equal pieces for the class.", "To bake evenly, the teacher asked us to part the pizza into eight slices."]', 'technology', '1', 2216807, 100, NULL, 'opengloss-v1.1'),
('part_noun_1', 'part', 'noun', 1, 'A role or function a person or thing can play in a group.', '["role", "function", "duty", "position"]', '["whole", "irrelevance"]', '["position", "function"]', '["lead role", "supporting role", "team task", "project duty"]', '["part of speech", "part of the day", "take part", "part time", "part of the plan", "part of a machine"]', '{"noun_forms": ["parting"], "verb_forms": [], "adjective_forms": ["partial"], "adverb_forms": ["partly"]}', '["Her part in the class play was the lead role.", "He played a supporting part in the debate."]', 'technology', '1', 2216807, 100, NULL, 'opengloss-v1.1'),
('part_verb_1', 'part', 'verb', 1, 'To leave or separate from someone or something; to go away or to part ways.', '["depart", "disengage"]', '["reunite", "join"]', '["departure", "separation"]', '["depart", "diverge"]', '["part ways", "part with", "part the cake", "part the hair", "part company", "part the dough"]', '{"noun_forms": ["partition", "parting"], "verb_forms": [], "adjective_forms": ["partial"], "adverb_forms": ["partly"]}', '["After the meeting, the students parted ways and went home.", "The crowd parted to let the speaker through."]', 'technology', '1', 2216807, 100, NULL, 'opengloss-v1.1'),
('part_noun_2', 'part', 'noun', 2, 'A share or portion of a total amount.', '["portion", "share", "fraction", "quota"]', '["whole", "entirety", "total"]', '["amount", "quantity"]', '["fraction", "percent", "portion", "quota"]', '["part of speech", "part of the day", "take part", "part time", "part of the plan", "part of a machine"]', '{"noun_forms": ["parting"], "verb_forms": [], "adjective_forms": ["partial"], "adverb_forms": ["partly"]}', '["Each student receives a part of the class budget.", "A part of the total is set aside for reserves."]', 'technology', '1', 2216807, 100, NULL, 'opengloss-v1.1'),
('part_verb_2', 'part', 'verb', 2, 'To give up or relinquish possession or use; to part with something.', '["relinquish", "forgo"]', '["keep", "retain"]', '["transfer", "possession change"]', '["cede", "forsake"]', '["part ways", "part with", "part the cake", "part the hair", "part company", "part the dough"]', '{"noun_forms": ["partition", "parting"], "verb_forms": [], "adjective_forms": ["partial"], "adverb_forms": ["partly"]}', '["He would not part with his grandmother''s ring.", "She finally parted with the old bicycle for a charity sale."]', 'technology', '1', 2216807, 100, NULL, 'opengloss-v1.1'),
