INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('can_noun_0', 'can', 'noun', 0, 'A metal container, typically cylindrical, with a removable lid, used for preserving and storing foods and liquids.', '["tin can", "metal can", "food can"]', '["open container", "unsealed container"]', '["container", "receptacle"]', '["soup can", "vegetable can", "fruit can", "beverage can"]', '["soda can", "beer can", "aluminum can", "tin can", "canned goods", "metal can"]', '{"noun_forms": ["canning", "cannery"], "verb_forms": ["can"], "adjective_forms": [], "adverb_forms": []}', '["The samples were stored in steel cans prior to analysis.", "Canned vegetables were distributed under controlled storage conditions."]', 'technology', 'K', 2206595, 102, NULL, 'opengloss-v1.1'),
('can_verb_0', 'can', 'verb', 0, 'Be able to do something; have the capacity to perform an action, often expressed as a modal or auxiliary verb.', '["be able to", "be capable of", "have the ability to"]', '["unable", "incapable"]', '["ability", "capability"]', '["skill", "competence"]', '["canned foods", "canning process", "cannery industry", "canned goods", "tin can"]', '{"noun_forms": ["cannery", "canning"], "verb_forms": [], "adjective_forms": ["canned"], "adverb_forms": []}', '["Participants can demonstrate proficiency after the training.", "Researchers can replicate the experiment under controlled conditions."]', 'technology', 'K', 2206595, 102, NULL, 'opengloss-v1.1'),
('can_noun_1', 'can', 'noun', 1, 'A slang term for prison or jail; a place of confinement.', '["slammer", "pen", "jail", "prison"]', '["freedom", "release"]', '["facility", "institution"]', '["state prison", "federal prison", "penitentiary", "detention center"]', '["soda can", "beer can", "aluminum can", "tin can", "canned goods", "metal can"]', '{"noun_forms": ["canning", "cannery"], "verb_forms": ["can"], "adjective_forms": [], "adverb_forms": []}', '["Ethnographic interviews use the can to denote imprisonment.", "Legal corpora rarely use can in formal descriptions of imprisonment."]', 'technology', 'K', 2206595, 102, NULL, 'opengloss-v1.1'),
('can_verb_1', 'can', 'verb', 1, 'To preserve edible items by sealing them in a metal container to extend shelf life.', '["tin", "jar", "bottle"]', '["unseal", "open", "spoil"]', '["preservation", "food processing"]', '["canned vegetables", "canned fruit"]', '["canned foods", "canning process", "cannery industry", "canned goods", "tin can"]', '{"noun_forms": ["cannery", "canning"], "verb_forms": [], "adjective_forms": ["canned"], "adverb_forms": []}', '["The factory canned peaches for distribution.", "Industrial facilities can peaches using hermetic seals."]', 'technology', 'K', 2206595, 102, NULL, 'opengloss-v1.1'),
('can_verb_2', 'can', 'verb', 2, 'To terminate the employment of someone; to dismiss from a job.', '["fire", "dismiss", "sack"]', '["hire", "employ", "retain"]', '["dismissal", "termination"]', '["layoff", "firing"]', '["canned foods", "canning process", "cannery industry", "canned goods", "tin can"]', '{"noun_forms": ["cannery", "canning"], "verb_forms": [], "adjective_forms": ["canned"], "adverb_forms": []}', '["The company canned several workers after the merger.", "Management warned that additional positions might be canned."]', 'technology', 'K', 2206595, 102, NULL, 'opengloss-v1.1')
