('house_noun_0', 'house', 'noun', 0, 'A building designed for human habitation and used as a dwelling, within architectural and real estate contexts.', '["dwelling", "residence", "domicile", "habitation"]', '["office", "nonresidential building"]', '["building", "structure"]', '["bungalow", "detached house", "terraced house", "townhouse"]', '["detached house", "bungalow", "townhouse", "terraced house", "house price", "house plan"]', '{"noun_forms": ["household", "householder", "housekeeping"], "verb_forms": [], "adjective_forms": ["housebound"], "adverb_forms": []}', '["The energy performance of new house constructions was evaluated under climate simulations.", "Housing policy influences the accessibility of affordable dwellings in urban areas."]', 'technology', 'K', 1712633, 148, NULL, 'opengloss-v1.1'),
('house_verb_0', 'house', 'verb', 0, 'In professional and technical contexts such as urban planning, architecture, and facilities management, to house means to provide housing or shelter for occupants, typically for people or organizations.', '["accommodate", "shelter", "lodge"]', '["evict", "displace"]', '["accommodation"]', '["dwelling", "apartment", "dormitory", "residence"]', '["house data", "house data centers", "house software", "house records", "house personnel"]', '{"noun_forms": ["housing", "householder", "household", "housekeeper", "housekeeping"], "verb_forms": ["rehouse"], "adjective_forms": ["housebound"], "adverb_forms": []}', '["The city project will house 800 residents.", "The university plans to house graduate students in new suites."]', 'technology', 'K', 1712633, 148, NULL, 'opengloss-v1.1'),
('house_noun_1', 'house', 'noun', 1, 'An institutional assembly that debates, amends, and enacts laws within a legislative system.', '["legislature", "assembly", "chamber", "parliament"]', '["senate"]', '["legislative body", "government body"]', '["lower house", "unicameral house", "parliamentary chamber"]', '["detached house", "bungalow", "townhouse", "terraced house", "house price", "house plan"]', '{"noun_forms": ["household", "householder", "housekeeping"], "verb_forms": [], "adjective_forms": ["housebound"], "adverb_forms": []}', '["The bill was referred to the lower house for debate.", "In bicameral systems, coordination between the house and senate is essential."]', 'technology', 'K', 1712633, 148, NULL, 'opengloss-v1.1'),
('house_verb_1', 'house', 'verb', 1, 'To place or contain something within a building, container, or enclosure for storage, protection, or processing.', '["store", "contain", "enclose"]', '[]', '["containment"]', '["archive", "storage facility", "cabinet"]', '["house data", "house data centers", "house software", "house records", "house personnel"]', '{"noun_forms": ["housing", "householder", "household", "housekeeper", "housekeeping"], "verb_forms": ["rehouse"], "adjective_forms": ["housebound"], "adverb_forms": []}', '["The data is housed in a secure database.", "The chemicals are housed in reinforced storage cabinets."]', 'technology', 'K', 1712633, 148, NULL, 'opengloss-v1.1'),
('house_noun_2', 'house', 'noun', 2, 'A commercial firm that designs, manufactures, or distributes products or services, commonly used in publishing and fashion industries.', '["firm", "company", "business", "corporation"]', '["individual"]', '["organization", "enterprise", "entity"]', '["publishing house", "fashion house", "design house"]', '["detached house", "bungalow", "townhouse", "terraced house", "house price", "house plan"]', '{"noun_forms": ["household", "householder", "housekeeping"], "verb_forms": [], "adjective_forms": ["housebound"], "adverb_forms": []}', '["The publishing house released a scholarly monograph.", "A luxury fashion house often collaborates with designers for limited editions."]', 'technology', 'K', 1712633, 148, NULL, 'opengloss-v1.1'),
('house_verb_2', 'house', 'verb', 2, 'In organizational or facilities management contexts, to be located within or assigned to a particular building or space; to occupy a designated place in a facility or campus.', '["locate", "situate", "occupy"]', '["evacuate", "empty"]', '["place"]', '["office", "laboratory", "data center", "campus building"]', '["house data", "house data centers", "house software", "house records", "house personnel"]', '{"noun_forms": ["housing", "householder", "household", "housekeeper", "housekeeping"], "verb_forms": ["rehouse"], "adjective_forms": ["housebound"], "adverb_forms": []}', '["The division is housed in Building A.", "The satellite office is housed within the corporate campus."]', 'technology', 'K', 1712633, 148, NULL, 'opengloss-v1.1')
