BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('well_adjective_0', 'well', 'adjective', 0, 'In good health; not ill.', '["healthy", "hale", "fit"]', '["unhealthy", "ill", "sick"]', '["health", "state of health", "physical condition"]', '["hale", "robust", "fit", "sound"]', '["well educated", "well behaved", "well rounded", "well written", "well planned", "well designed"]', '{"noun_forms": ["wellness", "wellbeing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The patient is well after the surgery.", "The student is well and ready to learn."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_adverb_0', 'well', 'adverb', 0, 'In a good or satisfactory way; with skill or care; performed competently.', '["properly", "correctly", "competently", "skillfully", "efficiently"]', '["badly", "ineptly", "poorly"]', '["manner adverb"]', '["competently", "skillfully", "efficiently", "properly"]', '["well above", "well below", "well known", "well designed", "well written", "well prepared"]', '{"noun_forms": ["wellness", "wellbeing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["She did well on the math test.", "The team played well during the science fair."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_interjection_0', 'well', 'interjection', 0, 'Interjection expressing mild surprise or astonishment in response to unexpected information.', '["gosh", "wow", "goodness"]', '[]', '["interjection", "exclamation"]', '["surprise exclamation", "expression of surprise"]', '["well done", "well known", "well established", "well ahead", "well behaved", "wellbeing"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Well, I never imagined you''d finish that quickly.", "Well, the data show a surprising trend."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_noun_0', 'well', 'noun', 0, 'A well is a deep hole or shaft dug to reach groundwater or other liquids, typically lined to prevent collapse.', '["borehole", "shaft", "drilled well"]', '["dry well"]', '["hole", "structure"]', '["oil well", "borehole"]', '["water well", "oil well", "deep well", "shallow well", "well water", "borehole"]', '{"noun_forms": ["wellness", "wellbeing", "wellhead"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Ancient villages built wells to reach groundwater.", "A modern well is often fitted with a pump to raise water to the surface."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_verb_0', 'well', 'verb', 0, 'To rise to the surface from a source, such as liquid, tears, or moisture.', '["rise", "emerge", "surge"]', '["drain", "deplete"]', '["motion"]', '["gush", "spurt"]', '["tears", "laughter", "emotion", "water", "eyes"]', '{"noun_forms": ["wellness", "wellbeing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Water welled from the crack after the rain.", "Tears welled from her eyes during the story."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_adverb_1', 'well', 'adverb', 1, 'To a high degree or extent; used as an intensifier to emphasize degree.', '["considerably", "greatly", "highly", "extremely"]', '["barely", "slightly", "partially"]', '["degree adverb"]', '["extremely", "highly", "very", "quite"]', '["well above", "well below", "well known", "well designed", "well written", "well prepared"]', '{"noun_forms": ["wellness", "wellbeing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Attendance was well above target.", "The exam results were well above expectations."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_interjection_1', 'well', 'interjection', 1, 'Interjection used as a discourse marker to shift topics or introduce a statement in conversation.', '["now", "so", "anyway"]', '[]', '["interjection"]', '["transition marker", "discourse cue", "topic shifter"]', '["well done", "well known", "well established", "well ahead", "well behaved", "wellbeing"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Well, according to the chart the results are consistent.", "Well, for our next point we will review the data."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_noun_1', 'well', 'noun', 1, 'A well can also mean a plentiful source or supply of something intangible.', '["source", "fountain", "reservoir"]', '["scarcity", "dearth"]', '["source", "resource"]', '["well of wisdom", "well of ideas", "well of patience"]', '["water well", "oil well", "deep well", "shallow well", "well water", "borehole"]', '{"noun_forms": ["wellness", "wellbeing", "wellhead"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The field guide is a well of information for students.", "The teacher drew from a well of strategies for teaching."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_verb_1', 'well', 'verb', 1, 'To become filled with a strong feeling or quality.', '["flood", "fill"]', '["empty", "drain"]', '["change"]', '["joy", "anger", "excitement"]', '["tears", "laughter", "emotion", "water", "eyes"]', '{"noun_forms": ["wellness", "wellbeing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The hall welled with laughter as the speaker finished.", "The crowd welled with excitement at the announcement."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_interjection_2', 'well', 'interjection', 2, 'Interjection used as a hesitation filler while thinking or deciding.', '["hmm", "uh", "er"]', '[]', '["interjection"]', '["filler word", "hesitation marker"]', '["well done", "well known", "well established", "well ahead", "well behaved", "wellbeing"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Well, I am not sure which method to pick.", "Well, maybe we should try a different approach."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1'),
('well_interjection_3', 'well', 'interjection', 3, 'Interjection used to express mild concession or acceptance.', '["okay", "fine", "alright"]', '[]', '["interjection"]', '["concession marker", "softener phrase"]', '["well done", "well known", "well established", "well ahead", "well behaved", "wellbeing"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Well, okay then we can move forward.", "Well, I suppose that works for today."]', 'science', '2', 1689936, 153, NULL, 'opengloss-v1.1')
