BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('television_adjective_0', 'television', 'adjective', 0, 'Relating to television as a mass medium; used as an attributive modifier to describe content, devices, or contexts associated with TV.', '["televisual", "television based", "TV related"]', '["nontelevision"]', '["descriptor", "adjective"]', '["television program", "television set", "television broadcast"]', '["television program", "television broadcast", "television set", "television show", "television lesson", "television segment"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": ["televisual"], "adverb_forms": []}', '["The television schedule includes science demonstrations.", "A television lesson plan integrates video clips with reading."]', 'technology', '1', 1427614, 185, NULL, 'opengloss-v1.1'),
('television_noun_0', 'television', 'noun', 0, 'The device that receives broadcast television signals and displays moving images and sound for viewers.', '["TV", "television set", "television receiver"]', '["radio"]', '["electronic device"]', '["television set", "smart TV"]', '["television program", "television screen", "television schedule", "television documentary", "television viewing", "television lesson"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Students watched a science documentary on the television.", "The teacher connected a lesson to the television for students."]', 'technology', '1', 1427614, 185, NULL, 'opengloss-v1.1'),
('television_adjective_1', 'television', 'adjective', 1, 'Relating to educational content designed for television-based instruction.', '["televised", "television based"]', '["print based", "offline"]', '["instructional descriptor"]', '["television lesson", "television segment"]', '["television program", "television broadcast", "television set", "television show", "television lesson", "television segment"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": ["televisual"], "adverb_forms": []}', '["The unit uses television based activities for science review.", "Students compare television based explanations with textbook notes."]', 'technology', '1', 1427614, 185, NULL, 'opengloss-v1.1'),
('television_noun_1', 'television', 'noun', 1, 'The system for transmitting moving images and sound to audiences via broadcast.', '["television industry", "tv broadcasting"]', '["print media", "radio"]', '["mass media"]', '["broadcasting", "cable television"]', '["television program", "television screen", "television schedule", "television documentary", "television viewing", "television lesson"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Class discussions cover how television broadcasting reaches audiences.", "A project compares cable television to streaming services."]', 'technology', '1', 1427614, 185, NULL, 'opengloss-v1.1'),
('television_noun_2', 'television', 'noun', 2, 'Programs or content that are broadcast on television.', '["shows", "programming"]', '["theatre"]', '["media content"]', '["news program", "documentary", "sitcom"]', '["television program", "television screen", "television schedule", "television documentary", "television viewing", "television lesson"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["A documentary on television informs students about science topics.", "News programs on television help learners practice reading."]', 'technology', '1', 1427614, 185, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
