INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('band_noun_0', 'band', 'noun', 0, 'A long narrow strip or loop of flexible material used to bind, fasten, or encircle objects.', '["strip", "strap", "ribbon"]', '[]', '["fastener", "strip"]', '["armband", "headband", "wristband"]', '["band member", "headband", "wristband", "band gap", "frequency band", "band structure"]', '{"noun_forms": ["banding"], "verb_forms": ["banded", "banding", "bands"], "adjective_forms": ["banded"], "adverb_forms": []}', '["A metal band secured the pipe joint.", "A plastic band encircled the package to secure it."]', 'technology', '2', 1151832, 234, NULL, 'opengloss-v1.1'),
('band_verb_0', 'band', 'verb', 0, 'Band (verb) to unite or bring people or groups into a single entity for a common purpose, often to act together.', '["unite", "combine", "cohere", "join"]', '["separate", "divide", "disband"]', '["cooperation", "grouping", "organization"]', '["coalition", "alliance", "union"]', '["elastic band", "rubber band", "headband", "hairband", "frequency band", "band saw"]', '{"noun_forms": ["banding", "bander"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers band together to form a consortium.", "Communities banded together to oppose the policy."]', 'technology', '2', 1151832, 234, NULL, 'opengloss-v1.1'),
('band_noun_1', 'band', 'noun', 1, 'A group of musicians who perform together as a unit.', '["ensemble", "group", "combo"]', '["soloist"]', '["musical group"]', '["quartet", "trio", "big band", "combo"]', '["band member", "headband", "wristband", "band gap", "frequency band", "band structure"]', '{"noun_forms": ["banding"], "verb_forms": ["banded", "banding", "bands"], "adjective_forms": ["banded"], "adverb_forms": []}', '["The university ensemble formed a band to perform at convocation.", "A four member band recorded a departmental compilation."]', 'technology', '2', 1151832, 234, NULL, 'opengloss-v1.1'),
('band_verb_1', 'band', 'verb', 1, 'Band (verb) to fasten or bind with a band or belt; to encircle or secure with a strip or ring.', '["bind", "fasten", "secure"]', '["unbind", "loosen", "unfasten"]', '["binding", "fastening", "securing"]', '["strap", "binding strip", "metal ring"]', '["elastic band", "rubber band", "headband", "hairband", "frequency band", "band saw"]', '{"noun_forms": ["banding", "bander"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The surgeon banded the wound with a cloth strip.", "They band the packages with a metal strap."]', 'technology', '2', 1151832, 234, NULL, 'opengloss-v1.1'),
('band_noun_2', 'band', 'noun', 2, 'A stripe or zone distinguished by color, material, or boundary.', '["stripe", "belt"]', '["unstriped"]', '["stripe", "zone", "region"]', '["color band", "security band", "temperature band"]', '["band member", "headband", "wristband", "band gap", "frequency band", "band structure"]', '{"noun_forms": ["banding"], "verb_forms": ["banded", "banding", "bands"], "adjective_forms": ["banded"], "adverb_forms": []}', '["A band of color formed a stripe along the edge of the sheet.", "A band of light appeared as the sun rose over the horizon."]', 'technology', '2', 1151832, 234, NULL, 'opengloss-v1.1'),
('band_verb_2', 'band', 'verb', 2, 'Band (verb) to mark or identify an animal or object by placing a physical band, common in wildlife management and research.', '["tag", "mark", "identify"]', '["unmark", "erase", "unidentify"]', '["marking", "identification", "tracking"]', '["bird tagging", "ornithological marking", "animal tagging"]', '["elastic band", "rubber band", "headband", "hairband", "frequency band", "band saw"]', '{"noun_forms": ["banding", "bander"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The scientists band wild birds for long term study.", "Birds are banded to identify individuals in populations."]', 'technology', '2', 1151832, 234, NULL, 'opengloss-v1.1'),
('band_noun_3', 'band', 'noun', 3, 'A contiguous range of frequencies allocated for a particular service or signal transmission.', '["frequency range", "spectral band"]', '["narrowband"]', '["range", "spectrum segment"]', '["AM band", "FM band", "HF band", "VHF band"]', '["band member", "headband", "wristband", "band gap", "frequency band", "band structure"]', '{"noun_forms": ["banding"], "verb_forms": ["banded", "banding", "bands"], "adjective_forms": ["banded"], "adverb_forms": []}', '["The 2 gigahertz frequency band is allocated for satellite communications.", "Operators monitor frequency bands to avoid interference."]', 'technology', '2', 1151832, 234, NULL, 'opengloss-v1.1')
