INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('building_noun_0', 'building', 'noun', 0, 'A permanent or semi-permanent constructed edifice with a roof and walls, such as a house, school, factory, or office block, intended for human occupancy, use, or storage.', '["structure", "edifice", "premises"]', '["ruin", "vacancy"]', '["structure", "construction"]', '["skyscraper", "warehouse"]', '["tall building", "office building", "historic building", "public building"]', '{"noun_forms": ["building", "rebuilding"], "verb_forms": ["build", "rebuild"], "adjective_forms": ["building-wide", "built"], "adverb_forms": ["structurally"]}', '["The new science building was designed to meet strict environmental standards.", "Several historic buildings were damaged during the earthquake."]', 'technology', 'K', 1113552, 246, NULL, 'opengloss-v1.1'),
('building_verb_0', 'building', 'verb', 0, 'Present participle of build; engaging in the act of constructing or assembling something, especially a physical structure or system, over time.', '["constructing", "erecting", "assembling"]', '["demolishing", "dismantling"]', '["making", "creating"]', '["bricklaying", "carpentering"]', '["building a house", "building consensus", "building relationships", "building momentum"]', '{"noun_forms": ["building", "builder", "rebuilding"], "verb_forms": ["overbuild", "rebuild"], "adjective_forms": ["built", "building-wide"], "adverb_forms": ["structurally"]}', '["The company is currently building a new headquarters outside the city center.", "They are building temporary shelters for displaced residents."]', 'technology', 'K', 1113552, 246, NULL, 'opengloss-v1.1'),
('building_noun_1', 'building', 'noun', 1, 'The act, process, or result of constructing, developing, or assembling components into a more complex whole, especially in physical, social, or conceptual domains.', '["construction", "formation", "development"]', '["demolition", "destruction"]', '["creation", "development"]', '["brand building", "capacity building"]', '["tall building", "office building", "historic building", "public building"]', '{"noun_forms": ["building", "rebuilding"], "verb_forms": ["build", "rebuild"], "adjective_forms": ["building-wide", "built"], "adverb_forms": ["structurally"]}', '["Team building is essential for improving organizational performance.", "Vocabulary building in early childhood has long-term cognitive benefits."]', 'technology', 'K', 1113552, 246, NULL, 'opengloss-v1.1'),
('building_verb_1', 'building', 'verb', 1, 'Engaging in the gradual development, enhancement, or consolidation of an abstract entity such as a relationship, institution, or body of knowledge.', '["developing", "cultivating", "strengthening"]', '["undermining", "weakening"]', '["developing", "improving"]', '["capacity building", "confidence building"]', '["building a house", "building consensus", "building relationships", "building momentum"]', '{"noun_forms": ["building", "builder", "rebuilding"], "verb_forms": ["overbuild", "rebuild"], "adjective_forms": ["built", "building-wide"], "adverb_forms": ["structurally"]}', '["Researchers are building a comprehensive database of climate records.", "The program is building trust between local authorities and community members."]', 'technology', 'K', 1113552, 246, NULL, 'opengloss-v1.1'),
('building_noun_2', 'building', 'noun', 2, 'A specific facility or block within a larger institutional or urban complex, usually identified by a letter, number, or functional label.', '["facility", "block", "unit"]', '[]', '["facility", "unit"]', '["main building", "annex"]', '["tall building", "office building", "historic building", "public building"]', '{"noun_forms": ["building", "rebuilding"], "verb_forms": ["build", "rebuild"], "adjective_forms": ["building-wide", "built"], "adverb_forms": ["structurally"]}', '["The chemistry labs are located in Building C on the northern side of campus.", "All administrative offices were moved to the main building last year."]', 'technology', 'K', 1113552, 246, NULL, 'opengloss-v1.1'),
('building_verb_2', 'building', 'verb', 2, 'Accumulating or increasing something progressively, often used of quantitative measures such as pressure, tension, or momentum.', '["accumulating", "mounting", "intensifying"]', '["receding", "dissipating"]', '["increasing", "rising"]', '["snowballing", "ramping up"]', '["building a house", "building consensus", "building relationships", "building momentum"]', '{"noun_forms": ["building", "builder", "rebuilding"], "verb_forms": ["overbuild", "rebuild"], "adjective_forms": ["built", "building-wide"], "adverb_forms": ["structurally"]}', '["Tension was building as the negotiation deadline approached.", "Clouds had been building all afternoon before the storm finally broke."]', 'technology', 'K', 1113552, 246, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
