INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('built_adjective_0', 'built', 'adjective', 0, 'Describing a thing produced by construction or fabrication rather than arising naturally.', '["constructed", "manufactured", "engineered", "fabricated"]', '["unbuilt", "unmade", "natural"]', '["property", "descriptor"]', '["prebuilt component", "manufactured item", "erected structure"]', '["built environment", "well built", "built to last", "built-in feature", "prebuilt component", "factory built"]', '{"noun_forms": ["builder", "building"], "verb_forms": ["build", "building", "built"], "adjective_forms": ["buildable", "well-built"], "adverb_forms": []}', '["The built environment shapes urban form.", "Prebuilt components reduce assembly time."]', 'technology', '1', 1106060, 249, NULL, 'opengloss-v1.1'),
('built_verb_0', 'built', 'verb', 0, 'To construct or assemble something by putting together parts or materials; to cause to exist in physical form.', '["construct", "erect", "assemble", "fabricate"]', '["demolish", "destroy", "dismantle"]', '["create", "manufacture", "fabricate"]', '["constructed building", "assembled components"]', '["build a model", "build a case", "build a framework", "built environment", "well built", "build consensus"]', '{"noun_forms": ["builder"], "verb_forms": ["rebuild"], "adjective_forms": [], "adverb_forms": []}', '["Researchers built a computational model to test hypotheses.", "The bridge was built using modular steel components."]', 'technology', '1', 1106060, 249, NULL, 'opengloss-v1.1'),
('built_adjective_1', 'built', 'adjective', 1, 'Describing a person with a robust, muscular physique; physically well formed.', '["muscular", "sturdy", "burly", "robust"]', '["frail", "weak", "slender"]', '["physical attribute", "body form"]', '["muscular frame", "burly build", "stocky body"]', '["built environment", "well built", "built to last", "built-in feature", "prebuilt component", "factory built"]', '{"noun_forms": ["builder", "building"], "verb_forms": ["build", "building", "built"], "adjective_forms": ["buildable", "well-built"], "adverb_forms": []}', '["The athlete has a well built physique.", "He is built for sprinting and power."]', 'technology', '1', 1106060, 249, NULL, 'opengloss-v1.1'),
('built_verb_1', 'built', 'verb', 1, 'To develop or formulate something intangible, such as a case, argument, model, or theory, by assembling evidence or reasoning.', '["develop", "form", "construct", "cultivate"]', '["undercut", "deconstruct", "undermine"]', '["create", "develop", "form"]', '["model building", "theory building", "case development"]', '["build a model", "build a case", "build a framework", "built environment", "well built", "build consensus"]', '{"noun_forms": ["builder"], "verb_forms": ["rebuild"], "adjective_forms": [], "adverb_forms": []}', '["Scholars built a persuasive argument from the available data.", "Analysts built a predictive model by integrating multiple datasets."]', 'technology', '1', 1106060, 249, NULL, 'opengloss-v1.1'),
('built_adjective_2', 'built', 'adjective', 2, 'Having components or functions integrated into the object during manufacture; not added later.', '["embedded", "integrated", "inbuilt"]', '["external", "standalone", "removable"]', '["functional feature", "system integration"]', '["embedded sensor", "integrated circuit", "preinstalled software"]', '["built environment", "well built", "built to last", "built-in feature", "prebuilt component", "factory built"]', '{"noun_forms": ["builder", "building"], "verb_forms": ["build", "building", "built"], "adjective_forms": ["buildable", "well-built"], "adverb_forms": []}', '["The device includes a built in fingerprint reader.", "A built in sensor reduces the need for external hardware."]', 'technology', '1', 1106060, 249, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
