('video_adjective_0', 'video', 'adjective', 0, 'Relating to or produced by the use of video technology, especially for recording or displaying moving pictures and sound.', '["digital", "electronic"]', '["analog", "live"]', '["media", "technology", "communication"]', '["video recording", "video clip"]', '["video lesson", "video clip", "video camera", "video editing", "video tutorial", "video conference"]', '{"noun_forms": ["videography"], "verb_forms": [], "adjective_forms": ["videographic"], "adverb_forms": []}', '["The video camera captured the science experiment for later study.", "Our classroom uses video equipment to document field trips and demonstrations."]', 'technology', '2', 926574, 302, NULL, 'opengloss-v1.1'),
('video_noun_0', 'video', 'noun', 0, 'A recording of moving pictures and sound that can be viewed on a screen and stored digitally or on tape.', '["video recording", "motion picture", "film", "footage", "clip"]', '["static image", "still photo", "still image"]', '["recording", "media", "visual medium", "audiovisual medium"]', '["video clip", "video file", "video presentation"]', '["video lesson", "video clip", "video file", "video camera", "video game", "video recording"]', '{"noun_forms": ["videography", "videographer"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The science teacher showed a video to illustrate the life cycle of a butterfly.", "Students created a video to explain how plants absorb sunlight."]', 'technology', '2', 926574, 302, NULL, 'opengloss-v1.1'),
('video_verb_0', 'video', 'verb', 0, 'To record moving images and sound of a scene using video equipment, producing a video file or recording for later viewing.', '["videotape", "film", "record"]', '["erase", "delete"]', '["recording", "filming"]', '["video recording", "live video"]', '["video recording", "video camera", "video clip", "video file", "video portfolio"]', '{"noun_forms": ["videography"], "verb_forms": ["videoize"], "adjective_forms": [], "adverb_forms": []}', '["The teacher videoed the science demonstration for the portfolio.", "Students will video the experiment and share the clip with their peers."]', 'technology', '2', 926574, 302, NULL, 'opengloss-v1.1'),
('video_adjective_1', 'video', 'adjective', 1, 'Describing content or materials that are designed to be viewed as a video for instruction or study.', '["video-based", "screen-based"]', '["print-based", "text-based"]', '["digital media", "educational material"]', '["video lesson", "video tutorial", "video demonstration"]', '["video lesson", "video clip", "video camera", "video editing", "video tutorial", "video conference"]', '{"noun_forms": ["videography"], "verb_forms": [], "adjective_forms": ["videographic"], "adverb_forms": []}', '["The teacher prepared a video lesson to reinforce the concept.", "Students watch a video demonstration before performing the experiment."]', 'technology', '2', 926574, 302, NULL, 'opengloss-v1.1'),
('video_noun_1', 'video', 'noun', 1, 'A live or real time transmission of moving pictures and sound that is broadcast or streamed over the internet or a school network.', '["live stream", "video feed", "video broadcast"]', '["pre-recorded video", "offline video", "delayed video"]', '["broadcast", "streaming media", "visual medium"]', '["webcast", "video conference", "live feed"]', '["video lesson", "video clip", "video file", "video camera", "video game", "video recording"]', '{"noun_forms": ["videography", "videographer"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The teacher hosted a live video conference with remote learners.", "The class watched a live video feed from the field trip."]', 'technology', '2', 926574, 302, NULL, 'opengloss-v1.1'),
('video_verb_1', 'video', 'verb', 1, 'To create video content for educational purposes by recording and producing a short instructional clip for a class project.', '["video production", "video creation", "make a video"]', '["omit video", "delete video"]', '["content creation", "media production"]', '["instructional video", "demonstration video"]', '["video recording", "video camera", "video clip", "video file", "video portfolio"]', '{"noun_forms": ["videography"], "verb_forms": ["videoize"], "adjective_forms": [], "adverb_forms": []}', '["For literacy, students will video a short reading and submit the clip.", "Educators may video a math lesson and post it to the portfolio."]', 'technology', '2', 926574, 302, NULL, 'opengloss-v1.1'),
('video_adjective_2', 'video', 'adjective', 2, 'Relating to the craft or process of making videos; pertaining to videography and video production.', '["videographic", "video making"]', '["static", "still-image"]', '["media production", "visual arts"]', '["videography", "video editing"]', '["video lesson", "video clip", "video camera", "video editing", "video tutorial", "video conference"]', '{"noun_forms": ["videography"], "verb_forms": [], "adjective_forms": ["videographic"], "adverb_forms": []}', '["A videographic explanation helps illustrate the steps with diagrams.", "The class discussed basic videography during the video production unit."]', 'technology', '2', 926574, 302, NULL, 'opengloss-v1.1')
