BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('still_adjective_0', 'still', 'adjective', 0, 'Not moving; not changing position.', '["motionless", "unmoving", "stationary"]', '["moving", "in motion", "mobile"]', '["state", "condition"]', '["motionless", "immobile", "unmoving", "stationary"]', '["still water", "still life", "still air", "still image", "stay still", "still night"]', '{"noun_forms": ["stillness"], "verb_forms": ["stilled", "stilling"], "adjective_forms": [], "adverb_forms": []}', '["The statue remained still during the examination.", "The lake surface was still after the wind ceased."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1'),
('still_adverb_0', 'still', 'adverb', 0, 'Adverb indicating that a situation continues to exist or occur up to the present moment.', '["yet", "as yet"]', '["already", "no longer"]', '["temporal adverb", "adverb of time"]', '["continuously", "constantly"]', '["still life", "still water", "still in use", "still alive", "still today", "still more"]', '{"noun_forms": ["stillness"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The road is still closed to traffic.", "The students are still working on the assignment."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1'),
('still_noun_0', 'still', 'noun', 0, 'A still is a distillation apparatus used to heat a liquid and collect its vapor, especially in the production of alcoholic spirits, so the liquid becomes purer as it passes through the apparatus.', '["distillation apparatus", "copper still", "distillery equipment"]', '["raw liquid"]', '["apparatus"]', '["pot still", "column still"]', '["copper still", "pot still", "column still", "distillation apparatus", "film still", "movie still", "freeze frame", "still image", "photographic still"]', '{"noun_forms": ["stillness"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Historically, distillers used a copper still to purify alcohol.", "A still is heated to turn liquid into vapor for separation in older laboratories."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1'),
('still_verb_0', 'still', 'verb', 0, 'to cause to become quiet or still; to stop noise or movement', '["calm", "quiet", "quell", "hush", "soothe"]', '["stir", "disturb", "excite", "agitate"]', '["calm verb"]', '["quieten", "hush"]', '["still the crowd", "still the class", "be still", "still water", "still the noise", "the still room"]', '{"noun_forms": ["stillness", "stiller"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The instructor stills the class with a firm voice.", "The nurse stills the anxious patient with soothing words."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1'),
('still_adjective_1', 'still', 'adjective', 1, 'Calm or quiet; free from noise or disturbance.', '["quiet", "calm", "peaceful"]', '["noisy", "loud", "turbulent"]', '["state", "condition"]', '["silent", "hushed"]', '["still water", "still life", "still air", "still image", "stay still", "still night"]', '{"noun_forms": ["stillness"], "verb_forms": ["stilled", "stilling"], "adjective_forms": [], "adverb_forms": []}', '["The classroom grew still as the lesson began.", "The forest was still at dusk, with only the distant owls."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1'),
('still_adverb_1', 'still', 'adverb', 1, 'Adverb meaning in spite of what has just been stated; nevertheless.', '["nevertheless", "however"]', '["therefore", "thus"]', '["conjunctive adverb", "transition adverb"]', '["nonetheless", "even so"]', '["still life", "still water", "still in use", "still alive", "still today", "still more"]', '{"noun_forms": ["stillness"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The plan failed, but they still proceeded.", "She was tired, but she still persisted."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1'),
('still_noun_1', 'still', 'noun', 1, 'A still is a still image, a single photograph taken from a film or video, often used to illustrate a moment in a movie or documentary.', '["freeze frame", "photograph", "still image"]', '["moving image"]', '["image"]', '["frame", "freeze frame"]', '["copper still", "pot still", "column still", "distillation apparatus", "film still", "movie still", "freeze frame", "still image", "photographic still"]', '{"noun_forms": ["stillness"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The still shows the hero entering the room.", "Teachers used a still to discuss camera composition in class."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1'),
('still_verb_1', 'still', 'verb', 1, 'to distill by heating and condensing a liquid to separate its components', '["distill", "purify"]', '["dilute", "concentrate"]', '["chemistry process"]', '["rectify", "purify"]', '["still the crowd", "still the class", "be still", "still water", "still the noise", "the still room"]', '{"noun_forms": ["stillness", "stiller"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The distillery stills the mash to make whiskey.", "Ancient apothecaries still herbs to extract aromas."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1'),
('still_adverb_2', 'still', 'adverb', 2, 'Adverb used for degree emphasis, meaning to a greater extent; more.', '["even more", "further"]', '["less"]', '["degree adverb", "intensifier adverb"]', '["further", "additionally"]', '["still life", "still water", "still in use", "still alive", "still today", "still more"]', '{"noun_forms": ["stillness"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["If the first test was hard, the second was still harder.", "The assignment was long, and the final part was still more demanding."]', 'science', '1', 879823, 326, NULL, 'opengloss-v1.1')
