('railway_adjective_0', 'railway', 'adjective', 0, 'Relating to or designed for railways; used to describe things associated with railway transport and infrastructure.', '["railroad"]', '["road"]', '["infrastructure", "transportation"]', '["railway engineering", "railway construction", "railway signaling"]', '["railway network", "railway line", "railway station", "railway timetable", "railway infrastructure", "railway policy"]', '{"noun_forms": ["railwayman", "railwaywoman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The railway network expansion requires substantial funding and planning.", "A railway company may operate several railway lines across the region."]', 'technology', '3', 831812, 357, NULL, 'opengloss-v1.1'),
('railway_noun_0', 'railway', 'noun', 0, 'An integrated system of tracks and related infrastructure used for rail-based transportation within a geographic region.', '["railroad", "rail system", "rail network"]', '["road", "highway"]', '["infrastructure", "transport infrastructure"]', '["mainline railway", "branch line", "freight railway"]', '["railway network", "railway station", "railway timetable", "railway infrastructure", "railway line", "railway system"]', '{"noun_forms": ["railwayman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The railway infrastructure requires regular maintenance to ensure safety.", "The railway network demonstrates throughput variability under peak demand."]', 'technology', '3', 831812, 357, NULL, 'opengloss-v1.1'),
('railway_noun_1', 'railway', 'noun', 1, 'A specific route within a railway network designed to connect particular terminals.', '["rail line", "railway route"]', '[]', '["route", "line"]', '["mainline railway", "branch line"]', '["railway network", "railway station", "railway timetable", "railway infrastructure", "railway line", "railway system"]', '{"noun_forms": ["railwayman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The branch line connects rural communities to the mainline.", "A mainline railway provides high-capacity service along major corridors."]', 'technology', '3', 831812, 357, NULL, 'opengloss-v1.1'),
('railway_noun_2', 'railway', 'noun', 2, 'The rail transport industry comprising operators, manufacturers, regulators, and related service providers involved in rail transport.', '["railway industry", "rail transport sector"]', '["road transport sector"]', '["industry", "transport sector"]', '["train operating company", "railway maintenance", "rolling stock leasing"]', '["railway network", "railway station", "railway timetable", "railway infrastructure", "railway line", "railway system"]', '{"noun_forms": ["railwayman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Policy reforms reshaped the structure of the railway industry.", "Competition among train operating companies reshaped the railway market."]', 'technology', '3', 831812, 357, NULL, 'opengloss-v1.1')
