BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('off_adjective_0', 'off', 'adjective', 0, 'Not currently on or activated; not functioning.', '["inactive", "unpowered", "inoperative"]', '["on", "active", "powered"]', '["state", "condition"]', '["dormant", "idle", "inoperative"]', '["off switch", "off limits", "off campus", "off course", "off the shelf"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The computer is off until you press the power button.", "The lights were off after the power outage."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_adverb_0', 'off', 'adverb', 0, 'not operating or active; in a powered-down state.', '["deactivated", "inactive", "disengaged"]', '["on", "active", "operating"]', '["inactivity", "unpowered state"]', '["shutdown", "power off", "switch off"]', '["off topic", "off switch", "off campus", "off course", "off duty", "off limits"]', '{"noun_forms": ["offness"], "verb_forms": [], "adjective_forms": ["offline", "offhand"], "adverb_forms": []}', '["The projector is off, so we cannot display slides.", "Make sure the computer is off before the experiment begins."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_interjection_0', 'off', 'interjection', 0, 'An interjection used to command someone to go away or to signal that someone should depart.', '["begone", "shoo"]', '["stay", "come"]', '["interjection", "exclamation"]', '["imperative exclamation", "dismissal exclamation"]', '["off switch", "off course", "off limits", "offstage", "offline", "offhand"]', '{"noun_forms": ["offness"], "verb_forms": [], "adjective_forms": [], "adverb_forms": ["offhand", "offline"]}', '["Off you go, children, and wash your hands before supper.", "The teacher waved dismissively and said, Off with you now."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_preposition_0', 'off', 'preposition', 0, 'Away from contact or position; used to show movement away from a surface or from something.', '["away from", "separate from", "removed from"]', '["on", "attached to", "in contact with"]', '["spatial relation", "preposition"]', '["off the shelf", "off the coast", "off campus"]', '["off the coast", "off the shelf", "off campus", "off the table", "off limits", "off track"]', '{"noun_forms": ["offset"], "verb_forms": [], "adjective_forms": ["offline"], "adverb_forms": ["offline"]}', '["The ball rolled off the table during the science demo.", "Keep the lid off the beaker while noting observations."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_adjective_1', 'off', 'adjective', 1, 'Located away from the usual place or position.', '["distant", "remote"]', '["onsite", "nearby"]', '["location", "place"]', '["offsite"]', '["off switch", "off limits", "off campus", "off course", "off the shelf"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The meeting is offsite to avoid distractions.", "The classroom is offsite from the main campus."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_adverb_1', 'off', 'adverb', 1, 'away from a surface or position; not in contact.', '["away", "detached", "separated"]', '["on", "attached", "in contact"]', '["directional adverb"]', '["fall off", "roll off", "slide off"]', '["off topic", "off switch", "off campus", "off course", "off duty", "off limits"]', '{"noun_forms": ["offness"], "verb_forms": [], "adjective_forms": ["offline", "offhand"], "adverb_forms": []}', '["The ball rolled off the table and fell to the floor.", "The label peeled off the bottle during inspection."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_preposition_1', 'off', 'preposition', 1, 'Excluding or not part of something official or recorded.', '["not official", "not on record", "excluded from"]', '["official", "on the record", "public"]', '["exclusion", "record policy"]', '["off the record", "off limits"]', '["off the coast", "off the shelf", "off campus", "off the table", "off limits", "off track"]', '{"noun_forms": ["offset"], "verb_forms": [], "adjective_forms": ["offline"], "adverb_forms": ["offline"]}', '["The spokesperson''s comments were kept off the record.", "Access to the files is off limits to students."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_adjective_2', 'off', 'adjective', 2, 'Having lost freshness; spoiled or not fresh.', '["spoiled", "stale", "rotten"]', '["fresh", "new", "ripe"]', '["quality", "condition"]', '["spoiled", "rotten"]', '["off switch", "off limits", "off campus", "off course", "off the shelf"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The milk has gone off and should be discarded.", "If the bread tastes off, throw it away."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_adverb_2', 'off', 'adverb', 2, 'not fresh or acceptable in taste or smell; spoiled.', '["spoiled", "rotten", "stale"]', '["fresh", "ripe", "new"]', '["taste descriptor", "quality adjective"]', '["rancid", "smelly", "stale"]', '["off topic", "off switch", "off campus", "off course", "off duty", "off limits"]', '{"noun_forms": ["offness"], "verb_forms": [], "adjective_forms": ["offline", "offhand"], "adverb_forms": []}', '["The milk tastes off and should be discarded.", "If the sauce tastes off, adjust the seasoning."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_preposition_2', 'off', 'preposition', 2, 'Indicating a deviation from a standard or expected value; not exactly right.', '["out of line", "not in line with", "incorrect"]', '["on target", "in line with", "accurate"]', '["measurement error"]', '["off by a degree"]', '["off the coast", "off the shelf", "off campus", "off the table", "off limits", "off track"]', '{"noun_forms": ["offset"], "verb_forms": [], "adjective_forms": ["offline"], "adverb_forms": ["offline"]}', '["The thermometer reads two degrees off from the target.", "The test score was off by a degree from the benchmark."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1'),
('off_adjective_3', 'off', 'adjective', 3, 'Not accurate or correct; deviating from expected.', '["wrong", "incorrect", "amiss"]', '["correct", "accurate", "right"]', '["accuracy", "quality"]', '["amiss", "faulty"]', '["off switch", "off limits", "off campus", "off course", "off the shelf"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The calculation is off by two units.", "If your answer is off, check your steps."]', 'technology', 'K', 810361, 370, NULL, 'opengloss-v1.1')
