('support_adjective_0', 'support', 'adjective', 0, 'Providing help, encouragement, or backing; supportive.', '["helpful", "encouraging", "kind"]', '["unsupportive", "unhelpful", "indifferent"]', '["descriptive adjective", "qualifying term"]', '["encouraging", "nurturing"]', '["supportive evidence", "supportive environment", "supportive classroom", "supportive parents", "emotional support", "financial support"]', '{"noun_forms": ["supportiveness"], "verb_forms": [], "adjective_forms": ["supportive"], "adverb_forms": ["supportively"]}', '["A supportive teacher offers feedback that guides students.", "A supportive classroom climate fosters student willingness to take risks."]', 'technology', '2', 795196, 378, NULL, 'opengloss-v1.1'),
('support_noun_0', 'support', 'noun', 0, 'A structure or object that bears weight and keeps something from falling, such as a column, beam, or brace.', '["prop", "brace", "stay"]', '["unsupported", "unstable", "unpropped"]', '["structure", "prop"]', '["pillar", "beam", "column", "brace"]', '["emotional support", "financial support", "academic support", "peer support", "support network"]', '{"noun_forms": ["supporter", "support system", "supportability"], "verb_forms": ["supporting"], "adjective_forms": ["supportive"], "adverb_forms": []}', '["A sturdy column provides roof support.", "The beam acts as a temporary support during repairs."]', 'technology', '2', 795196, 378, NULL, 'opengloss-v1.1'),
('support_verb_0', 'support', 'verb', 0, 'To give help or backing to someone or something; to advocate or endorse.', '["assist", "aid", "help", "back"]', '["oppose", "hinder"]', '["assistance"]', '["sponsor", "fund", "back"]', '["academic support", "financial support", "emotional support", "moral support", "tangible support", "support system"]', '{"noun_forms": ["supporter", "supportability"], "verb_forms": [], "adjective_forms": ["supportive"], "adverb_forms": []}', '["The tutor will support students with extra practice.", "Parents support their children''s learning by attending lessons."]', 'technology', '2', 795196, 378, NULL, 'opengloss-v1.1'),
('support_noun_1', 'support', 'noun', 1, 'Help or assistance given to someone who needs it.', '["aid", "assistance", "help", "backing"]', '["hindrance", "obstruction"]', '["assistance", "aid"]', '["financial support", "emotional support", "academic support", "tangible support"]', '["emotional support", "financial support", "academic support", "peer support", "support network"]', '{"noun_forms": ["supporter", "support system", "supportability"], "verb_forms": ["supporting"], "adjective_forms": ["supportive"], "adverb_forms": []}', '["The school provides academic support for struggling students.", "Parents donate financial support to the science fair."]', 'technology', '2', 795196, 378, NULL, 'opengloss-v1.1'),
('support_verb_1', 'support', 'verb', 1, 'To bear the weight of something; to hold up physically.', '["uphold", "bear", "sustain", "prop"]', '["collapse", "drop"]', '["hold"]', '["brace", "prop"]', '["academic support", "financial support", "emotional support", "moral support", "tangible support", "support system"]', '{"noun_forms": ["supporter", "supportability"], "verb_forms": [], "adjective_forms": ["supportive"], "adverb_forms": []}', '["A strong column supports the roof.", "Tower beams support the balcony''s edge."]', 'technology', '2', 795196, 378, NULL, 'opengloss-v1.1'),
('support_noun_2', 'support', 'noun', 2, 'Evidence or reasoning that backs up a claim or proposal.', '["evidence", "proof", "justification", "basis"]', '["contradiction", "refutation", "doubt"]', '["evidence", "justification"]', '["proof", "data", "case study", "citation"]', '["emotional support", "financial support", "academic support", "peer support", "support network"]', '{"noun_forms": ["supporter", "support system", "supportability"], "verb_forms": ["supporting"], "adjective_forms": ["supportive"], "adverb_forms": []}', '["The data provides support for the hypothesis.", "Peer review supports the argument."]', 'technology', '2', 795196, 378, NULL, 'opengloss-v1.1'),
('support_verb_2', 'support', 'verb', 2, 'To provide evidence or reasons that uphold a claim or argument.', '["verify", "confirm", "justify", "validate"]', '["disprove", "refute"]', '["evidence"]', '["cite", "document"]', '["academic support", "financial support", "emotional support", "moral support", "tangible support", "support system"]', '{"noun_forms": ["supporter", "supportability"], "verb_forms": [], "adjective_forms": ["supportive"], "adverb_forms": []}', '["The data support the hypothesis with clear results.", "The chart supports the conclusion by showing trends."]', 'technology', '2', 795196, 378, NULL, 'opengloss-v1.1')
