('make_noun_0', 'make', 'noun', 0, 'The brand or manufacturer of a product; the company that produced it, especially for items like cars electronics and appliances.', '["brand", "manufacturer", "maker", "label"]', '[]', '["brand", "product line"]', '["Ford", "Toyota"]', '["car make", "make and model", "the make of a car", "popular make", "well known make"]', '{"noun_forms": ["maker", "making"], "verb_forms": [], "adjective_forms": ["makeable"], "adverb_forms": []}', '["The car''s make is listed in the warranty booklet.", "Students compare the make of a laptop to determine quality."]', 'economics', 'K', 743920, 407, NULL, 'opengloss-v1.1'),
('make_verb_0', 'make', 'verb', 0, 'To create something by putting parts together or combining materials.', '["construct", "build", "form", "fabricate"]', '["destroy", "undo", "ruin", "break"]', '["produce", "create"]', '["assemble", "construct", "fabricate", "manufacture"]', '["make a decision", "make progress", "make a plan", "make money", "make friends", "make sense"]', '{"noun_forms": ["maker", "makeup", "makeover"], "verb_forms": ["remake"], "adjective_forms": ["makeable"], "adverb_forms": []}', '["Students will make a model by combining clay pieces.", "The artist makes a sculpture from recycled metal."]', 'economics', 'K', 743920, 407, NULL, 'opengloss-v1.1'),
