('joined_adjective_0', 'joined', 'adjective', 0, 'Physically connected or attached to another object or part; not detached.', '["connected", "attached", "fused", "bound together", "joined-up"]', '["separated", "disconnected", "loose", "unattached"]', '["connection", "attachment"]', '["welded", "stitched", "bolted", "glued"]', '["joined edges", "joined panels", "joined sections", "joined units", "joined forces", "joined handwriting"]', '{"noun_forms": ["joiner", "joining", "joint"], "verb_forms": ["join"], "adjective_forms": ["joint", "jointed"], "adverb_forms": []}', '["The joined edges of the wood panels remained secure after drilling.", "Two sections that are joined form a single continuous unit."]', 'technology', '2', 721760, 423, NULL, 'opengloss-v1.1'),
('joined_verb_0', 'joined', 'verb', 0, 'To connect two or more things by physically joining them, such as attaching pieces or linking edges.', '["connect", "unite", "attach", "fuse"]', '["detach", "separate", "disconnect", "sever"]', '["transitive verb"]', '["tie", "bind", "fasten", "weld"]', '["joined forces", "joined together", "joined hands", "joined at the hip", "joined the team", "joined the discussion"]', '{"noun_forms": ["joining"], "verb_forms": ["join"], "adjective_forms": ["joinable"], "adverb_forms": ["joiningly"]}', '["The two boards were joined with glue.", "The seam joined the panels into a single surface."]', 'technology', '2', 721760, 423, NULL, 'opengloss-v1.1'),
('joined_adjective_1', 'joined', 'adjective', 1, 'Having several parts or people acting together to form a single unit; a cooperative or combined effort.', '["combined", "cooperative", "united", "collaborative", "integrated"]', '["individual", "separate", "isolated", "divided"]', '["cooperation", "integration"]', '["teamwork", "joint effort", "collaboration"]', '["joined edges", "joined panels", "joined sections", "joined units", "joined forces", "joined handwriting"]', '{"noun_forms": ["joiner", "joining", "joint"], "verb_forms": ["join"], "adjective_forms": ["joint", "jointed"], "adverb_forms": []}', '["The joined effort of students and teachers improved test scores.", "The class organized a joined project to study ecosystems."]', 'technology', '2', 721760, 423, NULL, 'opengloss-v1.1'),
('joined_verb_1', 'joined', 'verb', 1, 'To come together with others in order to form a group or to work toward a common goal.', '["collaborate", "cooperate", "team up", "ally"]', '["oppose", "resist", "separate", "go it alone"]', '["transitive verb"]', '["collaborate", "cooperate", "team up", "ally"]', '["joined forces", "joined together", "joined hands", "joined at the hip", "joined the team", "joined the discussion"]', '{"noun_forms": ["joining"], "verb_forms": ["join"], "adjective_forms": ["joinable"], "adverb_forms": ["joiningly"]}', '["The students joined forces to raise funds for charity.", "Researchers joined forces with the local museum to study pollutants."]', 'technology', '2', 721760, 423, NULL, 'opengloss-v1.1'),
('joined_adjective_2', 'joined', 'adjective', 2, 'In handwriting, letters are connected in a continuous stroke as in cursive writing.', '["cursive", "handwriting in cursive", "joined script"]', '["print handwriting", "block letters", "disconnected letters"]', '["handwriting style"]', '["cursive"]', '["joined edges", "joined panels", "joined sections", "joined units", "joined forces", "joined handwriting"]', '{"noun_forms": ["joiner", "joining", "joint"], "verb_forms": ["join"], "adjective_forms": ["joint", "jointed"], "adverb_forms": []}', '["In many schools, children learn joined handwriting as a step beyond print.", "The teacher noted that the student\\''s joined handwriting improved legibility."]', 'technology', '2', 721760, 423, NULL, 'opengloss-v1.1')
