('project_noun_0', 'project', 'noun', 0, 'A planned undertaking aimed at achieving a specific outcome, often with stages and a deadline.', '["undertaking", "assignment", "enterprise", "endeavor"]', '["chaos", "disorder", "improvisation"]', '["work", "activity"]', '["science project", "group project", "history project", "art project"]', '["group project", "class project", "science project", "independent project", "project plan", "final project"]', '{"noun_forms": ["projector", "projection"], "verb_forms": ["projecting"], "adjective_forms": [], "adverb_forms": []}', '["The science project will explore plant growth over eight weeks.", "Our group project requires a written report and a presentation."]', 'technology', '3', 720070, 425, NULL, 'opengloss-v1.1'),
('project_verb_0', 'project', 'verb', 0, 'To estimate or forecast a future value or outcome based on data or trends.', '["forecast", "estimate", "predict"]', '["ignore", "neglect"]', '["estimation", "forecasting", "calculation"]', '["sales forecast", "population projection", "budget projection"]', '["project a plan", "project confidence", "project growth", "project onto screen", "project future outcomes"]', '{"noun_forms": ["projection", "projector"], "verb_forms": [], "adjective_forms": ["projectable"], "adverb_forms": []}', '["Researchers project a rise in temperatures next year.", "We project sales for the next quarter."]', 'technology', '3', 720070, 425, NULL, 'opengloss-v1.1'),
('project_noun_1', 'project', 'noun', 1, 'A school assignment consisting of a project work meant to demonstrate learning or research, typically completed over several days.', '["assignment", "task", "classwork"]', '["spontaneity", "improvisation"]', '["education task", "class activity"]', '["science project", "history project", "art project"]', '["group project", "class project", "science project", "independent project", "project plan", "final project"]', '{"noun_forms": ["projector", "projection"], "verb_forms": ["projecting"], "adjective_forms": [], "adverb_forms": []}', '["The fourth grade project asks students to research a historical event.", "Each student submits a personal science project with a poster."]', 'technology', '3', 720070, 425, NULL, 'opengloss-v1.1'),
('project_verb_1', 'project', 'verb', 1, 'To display or convey a quality or impression to others through behavior, appearance, or expression.', '["display", "convey", "exude"]', '["conceal", "hide"]', '["expression", "display", "demonstration"]', '["confident demeanor", "positive image", "clear message"]', '["project a plan", "project confidence", "project growth", "project onto screen", "project future outcomes"]', '{"noun_forms": ["projection", "projector"], "verb_forms": [], "adjective_forms": ["projectable"], "adverb_forms": []}', '["She projects confidence during the interview.", "The poster projects a hopeful image."]', 'technology', '3', 720070, 425, NULL, 'opengloss-v1.1'),
('project_noun_2', 'project', 'noun', 2, 'A projection or forecast of future numbers or outcomes used in planning and budgeting.', '["estimate", "forecast", "projection"]', '["reality", "actuals"]', '["forecast", "estimate"]', '["sales projection", "budget projection", "population projection", "weather projection"]', '["group project", "class project", "science project", "independent project", "project plan", "final project"]', '{"noun_forms": ["projector", "projection"], "verb_forms": ["projecting"], "adjective_forms": [], "adverb_forms": []}', '["The budget projection shows expected costs for next semester.", "Enrollment projection helps plan classroom space and staffing."]', 'technology', '3', 720070, 425, NULL, 'opengloss-v1.1'),
('project_verb_2', 'project', 'verb', 2, 'To throw forward or outward beyond a surface or boundary; to cast forward light, a shadow, an image, or other material.', '["cast", "throw", "emit"]', '["absorb", "receive"]', '["outward extension", "visual display"]', '["shadow projection", "beam projection"]', '["project a plan", "project confidence", "project growth", "project onto screen", "project future outcomes"]', '{"noun_forms": ["projection", "projector"], "verb_forms": [], "adjective_forms": ["projectable"], "adverb_forms": []}', '["The lamp projects a bright beam onto the wall.", "The satellite projects a beam toward the Earth."]', 'technology', '3', 720070, 425, NULL, 'opengloss-v1.1')
