('program_noun_0', 'program', 'noun', 0, 'A planned series of activities or events designed to achieve a goal, often used in education or entertainment.', '["plan", "schedule", "course", "curriculum"]', '["disorder", "chaos", "unplanned"]', '["plan", "scheme"]', '["lesson plan", "field trip itinerary", "weekly schedule"]', '["school program", "reading program", "computer program", "summer program", "after school program", "math program"]', '{"noun_forms": ["programmer", "programming"], "verb_forms": [], "adjective_forms": ["programmable", "programmatic"], "adverb_forms": []}', '["Our program includes science, reading, and math.", "The school concert offered a program of music and dance."]', 'technology', '3', 713225, 429, NULL, 'opengloss-v1.1'),
('program_verb_0', 'program', 'verb', 0, 'To arrange or schedule activities or tasks in a planned sequence for a day, unit, or project.', '["schedule", "plan", "arrange", "organize"]', '["disorganize", "neglect", "forget"]', '["coordinate", "manage"]', '["timetable", "calendar"]', '["computer program", "programming language", "education program", "class schedule", "robot program", "software program"]', '{"noun_forms": ["programmer", "programming"], "verb_forms": [], "adjective_forms": ["programmable", "programmatic", "unprogrammed"], "adverb_forms": ["programmatically"]}', '["The teacher will program the science day with hands on labs.", "We program the daily routine to balance reading and math."]', 'technology', '3', 713225, 429, NULL, 'opengloss-v1.1'),
('program_noun_1', 'program', 'noun', 1, 'A set of instructions that a computer can execute to perform a task.', '["application", "software", "app"]', '["manual process"]', '["software"]', '["script", "executable", "module"]', '["school program", "reading program", "computer program", "summer program", "after school program", "math program"]', '{"noun_forms": ["programmer", "programming"], "verb_forms": [], "adjective_forms": ["programmable", "programmatic"], "adverb_forms": []}', '["Students write a small program to solve a puzzle.", "The computer runs a program that calculates averages."]', 'technology', '3', 713225, 429, NULL, 'opengloss-v1.1'),
('program_verb_1', 'program', 'verb', 1, 'To create a computer program that tells a device how to perform tasks.', '["code", "develop", "create"]', '["deprogram", "erase", "undo"]', '["configure", "set up"]', '["script", "module"]', '["computer program", "programming language", "education program", "class schedule", "robot program", "software program"]', '{"noun_forms": ["programmer", "programming"], "verb_forms": [], "adjective_forms": ["programmable", "programmatic", "unprogrammed"], "adverb_forms": ["programmatically"]}', '["Students program a simple calculator in Python.", "We program the microcontroller to blink LEDs."]', 'technology', '3', 713225, 429, NULL, 'opengloss-v1.1'),
('program_noun_2', 'program', 'noun', 2, 'A plan of study consisting of courses and activities designed to teach a subject.', '["curriculum", "course", "study plan", "education program"]', '["disorganization", "chaos"]', '["plan", "education"]', '["reading program", "math program", "after school program"]', '["school program", "reading program", "computer program", "summer program", "after school program", "math program"]', '{"noun_forms": ["programmer", "programming"], "verb_forms": [], "adjective_forms": ["programmable", "programmatic"], "adverb_forms": []}', '["The reading program covers phonics and fluency.", "Our science program includes experiments and field trips."]', 'technology', '3', 713225, 429, NULL, 'opengloss-v1.1')
