('press_noun_0', 'press', 'noun', 0, 'A machine that uses pressure to shape or reproduce materials such as text or metal.', '["machine", "device", "apparatus"]', '["release"]', '["machine", "device", "apparatus"]', '["printing press", "wine press", "hydraulic press", "juice press"]', '["press conference", "press release", "press room", "press freedom", "printing press", "wine press"]', '{"noun_forms": ["pressing"], "verb_forms": [], "adjective_forms": ["pressing"], "adverb_forms": []}', '["The metal was formed by a hydraulic press.", "A printing press changed how books were made."]', 'technology', '1', 707157, 433, NULL, 'opengloss-v1.1'),
('press_verb_0', 'press', 'verb', 0, 'To apply physical force to a surface or object by hand or tool, in order to shape, move, or pack it.', '["push", "compress", "squeeze"]', '["release", "loosen"]', '["force", "action"]', '["flatten", "stamp"]', '["press conference", "press release", "press forward", "press on", "button press", "press the issue"]', '{"noun_forms": ["pressure"], "verb_forms": ["compress", "impress", "express", "oppress"], "adjective_forms": ["expressive"], "adverb_forms": ["expressly"]}', '["The student pressed the clay into the mold to form a seal.", "The teacher reminded the class to press gently when cleaning the lab bench."]', 'technology', '1', 707157, 433, NULL, 'opengloss-v1.1'),
('press_noun_1', 'press', 'noun', 1, 'The act of applying pressure by pressing.', '["compression", "squeeze", "push"]', '["release", "relaxation"]', '["action", "physical force", "maneuver"]', '["squeezing", "pushing", "crowding"]', '["press conference", "press release", "press room", "press freedom", "printing press", "wine press"]', '{"noun_forms": ["pressing"], "verb_forms": [], "adjective_forms": ["pressing"], "adverb_forms": []}', '["The scientist observed the squeezing of the sample under test.", "The design reduces the amount of pressing required to seal."]', 'technology', '1', 707157, 433, NULL, 'opengloss-v1.1'),
('press_verb_1', 'press', 'verb', 1, 'To produce printed copies or to publish a work, usually by using a printing press.', '["print", "publish"]', '["destroy", "withdraw"]', '["production", "publication"]', '["edition", "newspaper"]', '["press conference", "press release", "press forward", "press on", "button press", "press the issue"]', '{"noun_forms": ["pressure"], "verb_forms": ["compress", "impress", "express", "oppress"], "adjective_forms": ["expressive"], "adverb_forms": ["expressly"]}', '["The publisher will press the next edition next month.", "The school newspaper will press the article tomorrow."]', 'technology', '1', 707157, 433, NULL, 'opengloss-v1.1'),
('press_noun_2', 'press', 'noun', 2, 'The news media regarded as a group or industry.', '["media", "journalism", "news"]', '["privacy", "silence"]', '["mass media", "media outlets"]', '["newspaper", "news outlet", "television network", "radio station"]', '["press conference", "press release", "press room", "press freedom", "printing press", "wine press"]', '{"noun_forms": ["pressing"], "verb_forms": [], "adjective_forms": ["pressing"], "adverb_forms": []}', '["The press reported the study results yesterday.", "The class studied how the press covers science topics."]', 'technology', '1', 707157, 433, NULL, 'opengloss-v1.1'),
('press_verb_2', 'press', 'verb', 2, 'To urge strongly or insist on something, or to try to persuade someone to do something.', '["urge", "insist"]', '["dissuade", "permit"]', '["persuasion", "convincing"]', '["urging", "insistence"]', '["press conference", "press release", "press forward", "press on", "button press", "press the issue"]', '{"noun_forms": ["pressure"], "verb_forms": ["compress", "impress", "express", "oppress"], "adjective_forms": ["expressive"], "adverb_forms": ["expressly"]}', '["The coach pressed the team to practice harder.", "Parents pressed their child to study for exams."]', 'technology', '1', 707157, 433, NULL, 'opengloss-v1.1')
