('design_noun_0', 'design', 'noun', 0, 'A detailed plan or drawing that shows how to build or test a physical object or an experiment.', '["plan", "blueprint", "schematic", "drawing"]', '[]', '["plan", "specification", "document"]', '["blueprint", "schematic", "prototype", "circuit diagram"]', '["design process", "design plan", "design constraint", "design brief", "design model", "design sketch"]', '{"noun_forms": ["designer", "redesign"], "verb_forms": ["design", "redesign"], "adjective_forms": ["designed", "designable"], "adverb_forms": []}', '["Students sketched a schematic design for their wind turbine model before building.", "The lab notebook recorded the design for the paperclip catapult experiment."]', 'technology', '2', 706603, 434, NULL, 'opengloss-v1.1'),
('design_verb_0', 'design', 'verb', 0, 'To plan and create an investigation device or model to answer a scientific question or test a hypothesis.', '["plan", "devise", "draft", "sketch"]', '[]', '["create", "develop", "organize"]', '["experimental design", "prototype design", "model design"]', '["design an experiment", "design a model", "design a prototype", "design process", "design constraint", "redesign a device"]', '{"noun_forms": ["design", "designer", "design plan"], "verb_forms": ["redesign"], "adjective_forms": ["designed"], "adverb_forms": []}', '["Students will design an experiment to test how mass affects falling speed.", "We design a model rocket to measure thrust and stability."]', 'technology', '2', 706603, 434, NULL, 'opengloss-v1.1'),
('design_noun_1', 'design', 'noun', 1, 'The arrangement or organization of parts that determines how a device or system works.', '["arrangement", "layout", "structure", "configuration"]', '[]', '["structure", "system", "physical system"]', '["support frame", "gear train", "circuit layout", "load bearing frame"]', '["design process", "design plan", "design constraint", "design brief", "design model", "design sketch"]', '{"noun_forms": ["designer", "redesign"], "verb_forms": ["design", "redesign"], "adjective_forms": ["designed", "designable"], "adverb_forms": []}', '["The bridge design arranged the beams to spread weight evenly.", "They improved the circuit layout design to reduce electrical resistance."]', 'technology', '2', 706603, 434, NULL, 'opengloss-v1.1'),
('design_verb_1', 'design', 'verb', 1, 'To specify the arrangement and relationships of parts in a system so it performs a physical function.', '["configure", "arrange", "shape", "assemble"]', '[]', '["specify", "structure", "organize"]', '["circuit design", "mechanical design", "structural design"]', '["design an experiment", "design a model", "design a prototype", "design process", "design constraint", "redesign a device"]', '{"noun_forms": ["design", "designer", "design plan"], "verb_forms": ["redesign"], "adjective_forms": ["designed"], "adverb_forms": []}', '["Engineers design the pulley system to reduce force required to lift loads.", "We design circuits that control light and sound in the project."]', 'technology', '2', 706603, 434, NULL, 'opengloss-v1.1'),
