BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('board_noun_0', 'board', 'noun', 0, 'A flat rectangular piece of wood or other material used in construction or manufacture.', '["plank", "panel"]', '["beam", "joist", "girder"]', '["material", "piece", "component"]', '["plank", "plywood", "slat"]', '["board game", "board meeting", "school board", "board member", "whiteboard marker", "chalkboard"]', '{"noun_forms": ["boarder", "boardroom", "boardwalk"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The student measured a wooden board for the science project.", "The teacher cut a board to size for the model."]', 'technology', '1', 693658, 440, NULL, 'opengloss-v1.1'),
('board_verb_0', 'board', 'verb', 0, 'To enter or mount a vehicle as part of a journey.', '["embark", "enter", "mount"]', '["disembark", "alight", "exit"]', '["travel"]', '["plane boarding", "train boarding"]', '["boarding pass", "boarding gate", "plane boarding", "ship boarding", "train boarding", "boarding house"]', '{"noun_forms": ["boarder", "boarding"], "verb_forms": [], "adjective_forms": ["boardlike"], "adverb_forms": []}', '["Students will board the bus after lunch.", "Passengers boarded the plane at gate twelve."]', 'technology', '1', 693658, 440, NULL, 'opengloss-v1.1'),
('board_noun_1', 'board', 'noun', 1, 'A group of people elected or appointed to govern an organization.', '["panel", "governing body"]', '["staff", "employees"]', '["organization", "body"]', '["school board", "board of directors", "advisory board"]', '["board game", "board meeting", "school board", "board member", "whiteboard marker", "chalkboard"]', '{"noun_forms": ["boarder", "boardroom", "boardwalk"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The school board approved the science curriculum.", "The board of directors met to discuss the budget."]', 'technology', '1', 693658, 440, NULL, 'opengloss-v1.1'),
('board_verb_1', 'board', 'verb', 1, 'To seal openings by covering with wooden boards.', '["cover", "seal", "shut"]', '["uncover", "unseal", "open"]', '["covering"]', '["window boarding", "door boarding"]', '["boarding pass", "boarding gate", "plane boarding", "ship boarding", "train boarding", "boarding house"]', '{"noun_forms": ["boarder", "boarding"], "verb_forms": [], "adjective_forms": ["boardlike"], "adverb_forms": []}', '["Workers boarded up the broken storefront window.", "Officials boarded the doors to secure the building."]', 'technology', '1', 693658, 440, NULL, 'opengloss-v1.1'),
('board_noun_2', 'board', 'noun', 2, 'A surface used for writing or displaying information, such as chalkboard or whiteboard.', '["chalkboard", "whiteboard"]', '[]', '["surface", "writing surface"]', '["blackboard", "slate", "greenboard"]', '["board game", "board meeting", "school board", "board member", "whiteboard marker", "chalkboard"]', '{"noun_forms": ["boarder", "boardroom", "boardwalk"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The teacher wrote the equation on the chalkboard.", "Students recorded notes on the whiteboard during the lesson."]', 'technology', '1', 693658, 440, NULL, 'opengloss-v1.1'),
('board_verb_2', 'board', 'verb', 2, 'To provide with meals and lodging as part of accommodation.', '["host", "accommodate"]', '["evict", "refuse"]', '["provision"]', '["guest housing", "rooming service"]', '["boarding pass", "boarding gate", "plane boarding", "ship boarding", "train boarding", "boarding house"]', '{"noun_forms": ["boarder", "boarding"], "verb_forms": [], "adjective_forms": ["boardlike"], "adverb_forms": []}', '["The inn boards guests staying for a week.", "The school boards its visiting scholars during the conference."]', 'technology', '1', 693658, 440, NULL, 'opengloss-v1.1')
