('case_noun_0', 'case', 'noun', 0, 'A case is a portable container used to hold and protect small items.', '["box", "container", "holder"]', '[]', '["container"]', '["pencil case", "phone case"]', '["case study", "case file", "case number", "case law", "suitcase", "briefcase"]', '{"noun_forms": ["casebook", "caseload", "casework", "caseworker"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The student keeps pencils in a pencil case during science class.", "A protective case shields the tablet from drops during fieldwork."]', 'technology', '2', 608805, 508, NULL, 'opengloss-v1.1'),
('case_verb_0', 'case', 'verb', 0, 'To inspect a location to gather information for planning or security purposes.', '["inspect", "survey", "scout", "examine"]', '["ignore", "overlook", "neglect"]', '["examine"]', '["scout", "survey"]', '["case study", "case file", "laptop case", "protective casing", "case by case"]', '{"noun_forms": ["casing", "casework"], "verb_forms": ["encase", "caser"], "adjective_forms": ["caseable"], "adverb_forms": []}', '["The class case the campus to map safe routes for a drill", "For a criminology unit students case a campus to understand evidence gathering"]', 'technology', '2', 608805, 508, NULL, 'opengloss-v1.1'),
('case_noun_1', 'case', 'noun', 1, 'A case is a specific instance or example used to illustrate a point or analyze a situation in study or discussion.', '["example", "instance", "illustration", "occurrence"]', '[]', '["instance", "situation"]', '["case study", "use case"]', '["case study", "case file", "case number", "case law", "suitcase", "briefcase"]', '{"noun_forms": ["casebook", "caseload", "casework", "caseworker"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["In this case, the experiment supports the hypothesis.", "The teacher presented a real case to illustrate reasoning."]', 'technology', '2', 608805, 508, NULL, 'opengloss-v1.1'),
('case_verb_1', 'case', 'verb', 1, 'To enclose or protect with a case; to place into a protective casing.', '["cover", "enclose", "wrap", "encase"]', '["unwrap", "expose"]', '["enclose"]', '["encase", "box"]', '["case study", "case file", "laptop case", "protective casing", "case by case"]', '{"noun_forms": ["casing", "casework"], "verb_forms": ["encase", "caser"], "adjective_forms": ["caseable"], "adverb_forms": []}', '["The technician cased the laptop in a protective shell", "Students practice casing fragile instruments for safe transport"]', 'technology', '2', 608805, 508, NULL, 'opengloss-v1.1'),
('case_noun_2', 'case', 'noun', 2, 'A case is a legal matter brought before a court such as a lawsuit or dispute.', '["lawsuit", "court case", "legal action"]', '["settlement"]', '["legal matter", "litigation"]', '["criminal case", "civil case"]', '["case study", "case file", "case number", "case law", "suitcase", "briefcase"]', '{"noun_forms": ["casebook", "caseload", "casework", "caseworker"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The civil case was heard in the county court.", "The lawyer argued the criminal case with supporting evidence."]', 'technology', '2', 608805, 508, NULL, 'opengloss-v1.1'),
('case_noun_3', 'case', 'noun', 3, 'A case is an instance of illness or disease occurring in a person or population.', '["occurrence", "instance", "episode"]', '[]', '["illness", "disease"]', '["case of flu", "case of measles"]', '["case study", "case file", "case number", "case law", "suitcase", "briefcase"]', '{"noun_forms": ["casebook", "caseload", "casework", "caseworker"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["A case of influenza appeared in the classroom.", "Researchers reported a case of measles in the region."]', 'technology', '2', 608805, 508, NULL, 'opengloss-v1.1')
