INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('stations_noun_0', 'stations', 'noun', 0, 'A building or designated area where passengers or goods load and unload from transportation vehicles, or where such vehicles are housed or dispatched.', '["depot", "terminal", "hub"]', '[]', '["facility", "location", "structure"]', '["train station", "bus station", "metro station", "railway station"]', '["train station", "bus station", "radio station", "television station", "central station", "police station"]', '{"noun_forms": ["stationing"], "verb_forms": ["stations", "stationed", "stationing"], "adjective_forms": ["stationary"], "adverb_forms": []}', '["Urban planners studied passenger flow at major railway stations.", "The central bus station serves as a transfer hub for regional routes."]', 'technology', '3', 534560, 582, NULL, 'opengloss-v1.1'),
('stations_verb_0', 'stations', 'verb', 0, 'To place or assign in a specified location or position.', '["locate", "position", "deploy", "post"]', '["remove", "withdraw"]', '["placement", "positioning", "assignment"]', '["deploy", "post"]', '["station troops", "station personnel", "station base", "station post", "stationing points", "station duty"]', '{"noun_forms": ["stationing"], "verb_forms": [], "adjective_forms": ["stationary"], "adverb_forms": []}', '["Military planners station troops along the border.", "Researchers station sensors at predetermined coordinates."]', 'technology', '3', 534560, 582, NULL, 'opengloss-v1.1'),
('stations_noun_1', 'stations', 'noun', 1, 'A fixed post or assignment within an organization or service where an individual is stationed for duty.', '["posting", "assignment", "duty post", "post"]', '[]', '["position", "duty", "role"]', '["duty station", "military post", "embassy posting", "remote posting"]', '["train station", "bus station", "radio station", "television station", "central station", "police station"]', '{"noun_forms": ["stationing"], "verb_forms": ["stations", "stationed", "stationing"], "adjective_forms": ["stationary"], "adverb_forms": []}', '["Soldiers report to their new duty station at the eastern frontier.", "Diplomatic postings often require cultural and linguistic preparation."]', 'technology', '3', 534560, 582, NULL, 'opengloss-v1.1'),
('stations_verb_1', 'stations', 'verb', 1, 'To assign or appoint a person to a particular post or duty.', '["appoint", "assign", "post"]', '["dismiss", "unassign", "relieve"]', '["appointment", "assignment", "posting"]', '["posting", "appointment"]', '["station troops", "station personnel", "station base", "station post", "stationing points", "station duty"]', '{"noun_forms": ["stationing"], "verb_forms": [], "adjective_forms": ["stationary"], "adverb_forms": []}', '["The commander stations officers at the gate.", "Policy requires officers to be stationed at regional posts."]', 'technology', '3', 534560, 582, NULL, 'opengloss-v1.1'),
('stations_noun_2', 'stations', 'noun', 2, 'A fixed point or facility for observing or measuring phenomena in science or engineering; an observation or data collection site.', '["observation point", "monitoring site", "data site"]', '[]', '["facility", "site", "location"]', '["weather station", "seismology station", "air quality station", "meteorological station"]', '["train station", "bus station", "radio station", "television station", "central station", "police station"]', '{"noun_forms": ["stationing"], "verb_forms": ["stations", "stationed", "stationing"], "adjective_forms": ["stationary"], "adverb_forms": []}', '["A meteorological station records daily temperature and humidity.", "Researchers installed a weather station to monitor urban climate."]', 'technology', '3', 534560, 582, NULL, 'opengloss-v1.1'),
('stations_noun_3', 'stations', 'noun', 3, 'An organization or facility that transmits audio or video content to the public; a broadcasting station.', '["radio station", "television station", "broadcasting outlet", "media outlet"]', '[]', '["outlet", "media organization"]', '["radio station", "television station", "internet radio station", "public radio station"]', '["train station", "bus station", "radio station", "television station", "central station", "police station"]', '{"noun_forms": ["stationing"], "verb_forms": ["stations", "stationed", "stationing"], "adjective_forms": ["stationary"], "adverb_forms": []}', '["The local radio station aired a series of lectures on climate science.", "The university operates a television station that broadcasts campus events."]', 'technology', '3', 534560, 582, NULL, 'opengloss-v1.1')
