('network_adjective_0', 'network', 'adjective', 0, 'An adjective meaning connected to a computer or information network, enabling sharing and communication across devices and systems.', '["interconnected", "connected", "linked", "wired"]', '["isolated", "unconnected", "disconnected", "standalone"]', '["connectivity"]', '["wired devices", "online platforms", "distributed systems"]', '["networked learning", "networked classroom", "networked systems", "netlike pattern", "networkable devices"]', '{"noun_forms": ["networker", "networkability"], "verb_forms": ["networked", "networking"], "adjective_forms": ["networkable", "netlike"], "adverb_forms": []}', '["Classroom computers become networked to share resources.", "The school database is networked to support collaborative projects."]', 'technology', '3', 513321, 604, NULL, 'opengloss-v1.1'),
('network_noun_0', 'network', 'noun', 0, 'A system of interconnected people or organizations that share information or resources.', '["system", "web", "net", "mesh"]', '["isolation", "disconnection"]', '["system", "organization"]', '["social network", "information network", "transport network"]', '["computer network", "data network", "local area network", "wide area network", "network protocol", "network security"]', '{"noun_forms": ["networker"], "verb_forms": ["networking", "networked"], "adjective_forms": ["networked"], "adverb_forms": []}', '["Researchers mapped a network of collaborations among universities.", "A public health network connects clinics for data sharing."]', 'technology', '3', 513321, 604, NULL, 'opengloss-v1.1'),
('network_verb_0', 'network', 'verb', 0, 'To connect computers or other devices so they can share information and resources.', '["connect", "link", "join"]', '["disconnect", "detach"]', '["act of connecting", "communication"]', '["computers", "printers"]', '["professional network", "networking skills", "online network", "social network", "networking opportunities"]', '{"noun_forms": ["networker"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Students will network classroom computers to share projects.", "The classroom will network computers for sharing documents."]', 'technology', '3', 513321, 604, NULL, 'opengloss-v1.1'),
('network_adjective_1', 'network', 'adjective', 1, 'An adjective describing a structure or pattern that resembles a network, with many nodes and interconnections.', '["weblike", "netlike", "reticulated", "interconnected"]', '["linear", "unconnected", "simple"]', '["structure"]', '["reticulated pattern", "netlike lattice"]', '["networked learning", "networked classroom", "networked systems", "netlike pattern", "networkable devices"]', '{"noun_forms": ["networker", "networkability"], "verb_forms": ["networked", "networking"], "adjective_forms": ["networkable", "netlike"], "adverb_forms": []}', '["The map shows a networked pattern of roads.", "Reticulated bone shows a networklike arrangement of trabeculae."]', 'technology', '3', 513321, 604, NULL, 'opengloss-v1.1'),
('network_noun_1', 'network', 'noun', 1, 'A fabric or structure formed by crossing threads or wires to form a mesh.', '["mesh", "lattice", "grid", "netting"]', '[]', '["structure", "fabric"]', '["lattice", "grid"]', '["computer network", "data network", "local area network", "wide area network", "network protocol", "network security"]', '{"noun_forms": ["networker"], "verb_forms": ["networking", "networked"], "adjective_forms": ["networked"], "adverb_forms": []}', '["The screen is made of a fine mesh to keep insects out.", "Woven lattice provides support for climbing plants."]', 'technology', '3', 513321, 604, NULL, 'opengloss-v1.1'),
