('technology_noun_0', 'technology', 'noun', 0, 'Physical tools and machines people use in the past or present to do work and change their environment.', '["tool", "instrument", "machine", "device"]', '[]', '["artifact", "tool", "object", "material culture"]', '["wheel", "plow", "printing press", "steam engine", "sewing machine"]', '["ancient technology", "modern technology", "farm technology", "transport technology", "printing technology", "communication technology"]', '{"noun_forms": ["technologist"], "verb_forms": ["technologize"], "adjective_forms": ["technological"], "adverb_forms": ["technologically"]}', '["Historians examine ancient tools and technology like the wheel to understand travel.", "School projects compare stone tools and metal machines from different periods."]', 'technology', '2', 483384, 644, NULL, 'opengloss-v1.1'),
('technology_noun_1', 'technology', 'noun', 1, 'Methods and techniques people develop to solve problems or produce goods over time.', '["method", "technique", "process", "procedure"]', '[]', '["method", "process", "practice"]', '["irrigation method", "smelting technique", "crop rotation process", "navigation technique"]', '["ancient technology", "modern technology", "farm technology", "transport technology", "printing technology", "communication technology"]', '{"noun_forms": ["technologist"], "verb_forms": ["technologize"], "adjective_forms": ["technological"], "adverb_forms": ["technologically"]}', '["Irrigation technology helped ancient farmers grow crops in dry fields.", "Students study printing technology to learn how books spread ideas."]', 'technology', '2', 483384, 644, NULL, 'opengloss-v1.1'),
('technology_noun_2', 'technology', 'noun', 2, 'The body of practical knowledge and skills people learn and pass on to make or repair things.', '["knowhow", "skill", "expertise", "practical knowledge"]', '[]', '["knowledge", "skill", "practice"]', '["carpentry skill", "weaving skill", "metalworking skill", "repair skill"]', '["ancient technology", "modern technology", "farm technology", "transport technology", "printing technology", "communication technology"]', '{"noun_forms": ["technologist"], "verb_forms": ["technologize"], "adjective_forms": ["technological"], "adverb_forms": ["technologically"]}', '["Blacksmith technology includes the skills to shape metal with heat and hammering.", "Children learn simple repair technology when they practice fixing a broken toy."]', 'technology', '2', 483384, 644, NULL, 'opengloss-v1.1')
