('library_noun_0', 'library', 'noun', 0, 'A building or room that houses books and is used for reading, study, and borrowing.', '["book repository", "reading room", "lending library"]', '["bookstore"]', '["facility", "establishment", "building"]', '["public library", "school library", "university library", "mobile library"]', '["public library", "library card", "library catalog", "library hours", "library shelves", "school library"]', '{"noun_forms": ["librarian"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Students visit the library after class to read, study, and borrow books for research.", "The librarian helps students locate materials for research in the library."]', 'technology', '1', 473508, 663, NULL, 'opengloss-v1.1'),
('library_noun_1', 'library', 'noun', 1, 'The set of materials owned by a library; the library''s collection.', '["collection", "stock"]', '["dearth", "scarcity"]', '["collection", "inventory"]', '["reference collection", "fiction collection", "nonfiction collection", "periodicals"]', '["public library", "library card", "library catalog", "library hours", "library shelves", "school library"]', '{"noun_forms": ["librarian"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The library''s collection includes science journals and classic novels.", "Students compare items in the collection to gather sources for reports."]', 'technology', '1', 473508, 663, NULL, 'opengloss-v1.1'),
