-- lexi ETL: model (2026-09-18T16:20:08Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('model_noun_0', 'model', 'noun', 0, 'A physical replica used to represent a real object so learners can observe form and test how parts behave.', '["replica", "scale model", "physical model", "mockup"]', '[]', '["representation", "artifact", "object"]', '["globe", "bridge model", "atom model", "model airplane"]', '["scale model", "mathematical model", "physical model", "computer model", "conceptual model", "model building"]', '{"noun_forms": ["modeler", "modeling"], "verb_forms": ["model"], "adjective_forms": ["modeled"], "adverb_forms": []}', '["We built a scale model of the bridge to test how weight spreads across beams.", "A globe is a physical model that shows Earth''s shape and continents for study."]', 'science', '4', 466178, 678, NULL, 'opengloss-v1.1'),
('model_verb_0', 'model', 'verb', 0, 'To make or build a physical representation of an object or system so learners can observe its parts and behavior.', '["build", "construct", "make", "assemble"]', '[]', '["representation", "activity", "scientific practice"]', '["scale model", "paper model", "globe model"]', '["build a model", "construct a model", "scale model", "physical model", "computer model", "mathematical model"]', '{"noun_forms": ["model", "modeler", "modeller", "modeling"], "verb_forms": [], "adjective_forms": ["modelable", "modelled"], "adverb_forms": []}', '["Students model a river using sand clay and water to see erosion.", "We model the solar system with balls to show planet sizes."]', 'science', '4', 466178, 678, NULL, 'opengloss-v1.1'),
('model_noun_1', 'model', 'noun', 1, 'A simplified conceptual or mathematical representation used to explain observations and predict outcomes in physical science.', '["mathematical model", "conceptual model", "representation", "theory"]', '[]', '["scientific representation", "explanation", "scientific tool"]', '["particle model", "motion model", "heat model", "equation model"]', '["scale model", "mathematical model", "physical model", "computer model", "conceptual model", "model building"]', '{"noun_forms": ["modeler", "modeling"], "verb_forms": ["model"], "adjective_forms": ["modeled"], "adverb_forms": []}', '["A mathematical model uses equations to predict how a swinging pendulum moves over time.", "Scientists use a particle model to explain gas behavior in experiments."]', 'science', '4', 466178, 678, NULL, 'opengloss-v1.1'),
('model_verb_1', 'model', 'verb', 1, 'To create or use a mathematical or computer description that represents how a physical system behaves to test predictions.', '["simulate", "represent", "approximate", "calculate"]', '[]', '["simulation", "analysis", "representation"]', '["computer model", "mathematical model", "simulation model"]', '["build a model", "construct a model", "scale model", "physical model", "computer model", "mathematical model"]', '{"noun_forms": ["model", "modeler", "modeller", "modeling"], "verb_forms": [], "adjective_forms": ["modelable", "modelled"], "adverb_forms": []}', '["We model temperature change with a graph to predict warming over time.", "The class uses a simple computer program to model how heat moves."]', 'science', '4', 466178, 678, NULL, 'opengloss-v1.1'),
('model_noun_2', 'model', 'noun', 2, 'A computer program or numerical simulation that calculates the behavior of a physical system to test hypotheses and make predictions.', '["computer model", "simulation", "numerical model", "simulation model"]', '[]', '["simulation", "computer program", "scientific tool"]', '["weather model", "climate model", "orbit simulator"]', '["scale model", "mathematical model", "physical model", "computer model", "conceptual model", "model building"]', '{"noun_forms": ["modeler", "modeling"], "verb_forms": ["model"], "adjective_forms": ["modeled"], "adverb_forms": []}', '["A computer model simulated asteroid paths so students could study collision risk.", "The class ran a simulation to observe how temperature changes with time in a model room."]', 'science', '4', 466178, 678, NULL, 'opengloss-v1.1'),
('model_verb_2', 'model', 'verb', 2, 'To demonstrate or show a scientific procedure or thinking aloud so learners can follow steps and strategies.', '["demonstrate", "show", "explain", "display"]', '[]', '["instruction", "teaching", "communication"]', '["teacher demonstration", "think aloud", "guided example"]', '["build a model", "construct a model", "scale model", "physical model", "computer model", "mathematical model"]', '{"noun_forms": ["model", "modeler", "modeller", "modeling"], "verb_forms": [], "adjective_forms": ["modelable", "modelled"], "adverb_forms": []}', '["The teacher models measuring mass and explains each step clearly.", "The scientist models making a hypothesis before testing the idea."]', 'science', '4', 466178, 678, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
