('process_noun_0', 'process', 'noun', 0, 'A set of actions, steps, or operations designed to achieve a particular result.', '["procedure", "method", "sequence"]', '["stagnation", "halt"]', '["activity", "transformation"]', '["industrial process", "digestive process", "cognitive process"]', '["design process", "manufacturing process", "natural process", "aging process", "cognitive process", "data processing"]', '{"noun_forms": ["processor", "processing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The production line follows a strict design process.", "Researchers map the research process from hypothesis to conclusion."]', 'technology', '3', 465768, 681, NULL, 'opengloss-v1.1'),
('process_verb_0', 'process', 'verb', 0, 'To perform a series of steps or actions in order to achieve a result, often according to a plan.', '["perform", "execute", "conduct"]', '["neglect", "omit"]', '["operation", "action", "procedure"]', '["task execution", "step execution", "procedure completion"]', '["process data", "process information", "process a request", "process a form", "process efficiently", "process thoroughly"]', '{"noun_forms": ["processing", "processor", "processability"], "verb_forms": ["reprocess"], "adjective_forms": ["processable", "processed", "unprocessed"], "adverb_forms": ["processably"]}', '["Researchers processed the data using defined criteria.", "Students must process the information before answering."]', 'technology', '3', 465768, 681, NULL, 'opengloss-v1.1'),
('process_noun_1', 'process', 'noun', 1, 'A natural series of changes or development in a system or organism.', '["development", "progression", "transformation"]', '["stagnation", "regression"]', '["change", "transformation"]', '["aging process", "metabolic process", "cellular differentiation"]', '["design process", "manufacturing process", "natural process", "aging process", "cognitive process", "data processing"]', '{"noun_forms": ["processor", "processing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The aging process affects many tissues.", "Metabolic processes regulate energy in all cells."]', 'technology', '3', 465768, 681, NULL, 'opengloss-v1.1'),
('process_verb_1', 'process', 'verb', 1, 'To subject something to a series of transformations or treatments to change its form or content.', '["treat", "refine", "transform"]', '["untreated", "unprocessed", "unmodified"]', '["transformation", "treatment"]', '["data processing", "chemical processing", "thermal processing"]', '["process data", "process information", "process a request", "process a form", "process efficiently", "process thoroughly"]', '{"noun_forms": ["processing", "processor", "processability"], "verb_forms": ["reprocess"], "adjective_forms": ["processable", "processed", "unprocessed"], "adverb_forms": ["processably"]}', '["The lab processed the sample to remove impurities.", "Data were processed to reveal patterns."]', 'technology', '3', 465768, 681, NULL, 'opengloss-v1.1'),
('process_noun_2', 'process', 'noun', 2, 'An instance of a running program in a computer.', '["program instance", "task", "execution"]', '["terminated process", "idle process"]', '["program", "task"]', '["daemon", "foreground process", "background process"]', '["design process", "manufacturing process", "natural process", "aging process", "cognitive process", "data processing"]', '{"noun_forms": ["processor", "processing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The system started a new process to handle the request.", "Multiple processes run concurrently on modern operating systems."]', 'technology', '3', 465768, 681, NULL, 'opengloss-v1.1'),
('process_verb_2', 'process', 'verb', 2, 'To think about and analyze information in a structured, deliberate way.', '["contemplate", "reason", "analyze"]', '["ignore", "disregard", "neglect"]', '["cognition", "reasoning", "analysis"]', '["critical thinking", "data interpretation"]', '["process data", "process information", "process a request", "process a form", "process efficiently", "process thoroughly"]', '{"noun_forms": ["processing", "processor", "processability"], "verb_forms": ["reprocess"], "adjective_forms": ["processable", "processed", "unprocessed"], "adverb_forms": ["processably"]}', '["Students must process evidence before drawing conclusions.", "Experts processed conflicting data to form a theory."]', 'technology', '3', 465768, 681, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
