-- lexi ETL: bridge (2026-09-18T16:20:09Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('bridge_noun_0', 'bridge', 'noun', 0, 'A structure built to span physical obstacles such as a river or valley, providing passage for vehicles and pedestrians.', '["overpass", "viaduct", "crossing"]', '["barrier", "gap", "obstacle"]', '["structure", "infrastructure"]', '["suspension bridge", "cantilever bridge", "arch bridge", "beam bridge"]', '["bridge design", "bridge span", "pedestrian bridge", "suspension bridge", "cantilever bridge", "highway bridge"]', '{"noun_forms": ["bridgework", "bridging"], "verb_forms": [], "adjective_forms": ["bridgeable", "bridgelike"], "adverb_forms": []}', '["The bridge''s load rating depends on its structural system.", "Seismic retrofitting improves resilience of long span bridges."]', 'technology', '1', 434763, 740, NULL, 'opengloss-v1.1'),
('bridge_verb_0', 'bridge', 'verb', 0, 'To connect or bring together two or more things by providing a link or passage, physically or metaphorically.', '["connect", "link", "join"]', '["disconnect", "separate"]', '["connect"]', '["interconnect"]', '["gap", "divide", "data", "networks", "cultures", "barrier"]', '{"noun_forms": ["bridging"], "verb_forms": [], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["The new policy bridges the gap between theory and practice.", "A common model bridges economics and sociology."]', 'technology', '1', 434763, 740, NULL, 'opengloss-v1.1'),
('bridge_noun_1', 'bridge', 'noun', 1, 'A conceptual or rhetorical device that connects ideas, groups, or theories to create coherence.', '["link", "linkage", "connector"]', '["barrier", "disconnect"]', '["metaphor", "rhetorical device"]', '["conceptual bridge", "theoretical bridge"]', '["bridge design", "bridge span", "pedestrian bridge", "suspension bridge", "cantilever bridge", "highway bridge"]', '{"noun_forms": ["bridgework", "bridging"], "verb_forms": [], "adjective_forms": ["bridgeable", "bridgelike"], "adverb_forms": []}', '["The term serves as a conceptual bridge between theory and practice.", "The bridge metaphor enhances assimilation of disparate findings."]', 'technology', '1', 434763, 740, NULL, 'opengloss-v1.1'),
('bridge_verb_1', 'bridge', 'verb', 1, 'To overcome a discrepancy or gap between entities, making them more compatible or coherent.', '["reconcile", "resolve", "harmonize"]', '["exacerbate", "worsen"]', '["connect"]', '["harmonize"]', '["gap", "divide", "data", "networks", "cultures", "barrier"]', '{"noun_forms": ["bridging"], "verb_forms": [], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["The committee bridged disciplinary divides to reach a consensus.", "The study bridges the gap in data quality across sources."]', 'technology', '1', 434763, 740, NULL, 'opengloss-v1.1'),
('bridge_noun_2', 'bridge', 'noun', 2, 'A fixed dental prosthesis used to replace missing teeth by anchoring to adjacent teeth.', '["dental bridge", "tooth prosthesis", "fixed prosthesis"]', '["dental implant", "removable denture"]', '["dental restoration", "oral prosthesis"]', '["cantilever bridge", "maryland bridge"]', '["bridge design", "bridge span", "pedestrian bridge", "suspension bridge", "cantilever bridge", "highway bridge"]', '{"noun_forms": ["bridgework", "bridging"], "verb_forms": [], "adjective_forms": ["bridgeable", "bridgelike"], "adverb_forms": []}', '["A dental bridge requires adjacent teeth to act as abutments.", "A Maryland bridge provides a conservative replacement option for single missing tooth."]', 'technology', '1', 434763, 740, NULL, 'opengloss-v1.1'),
('bridge_verb_2', 'bridge', 'verb', 2, 'To span a physical space by constructing a passage or by extending across an obstacle; to link two points with a bridge or bridging element.', '["span", "cross", "construct"]', '["separate", "disconnect"]', '["connect"]', '["span"]', '["gap", "divide", "data", "networks", "cultures", "barrier"]', '{"noun_forms": ["bridging"], "verb_forms": [], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["The arch bridges the river.", "A walkway bridges two wings of the hospital."]', 'technology', '1', 434763, 740, NULL, 'opengloss-v1.1'),
('bridge_noun_3', 'bridge', 'noun', 3, 'A trick-taking card game for four players in two partnerships, requiring bidding and strategic play.', '["card game", "contract game"]', '["board game", "video game"]', '["game"]', '["duplicate bridge", "rubber bridge"]', '["bridge design", "bridge span", "pedestrian bridge", "suspension bridge", "cantilever bridge", "highway bridge"]', '{"noun_forms": ["bridgework", "bridging"], "verb_forms": [], "adjective_forms": ["bridgeable", "bridgelike"], "adverb_forms": []}', '["Bridge is played by four players in two partnerships.", "Bidding determines the final contract and scoring."]', 'technology', '1', 434763, 740, NULL, 'opengloss-v1.1')
