('base_adjective_0', 'base', 'adjective', 0, 'Morally low; lacking honorable principles.', '["ignoble", "dishonorable", "mean"]', '["noble", "honorable", "virtuous"]', '["moral quality"]', '["dishonorable", "corrupt"]', '["base knowledge", "base concept", "base principle", "base rate", "base layer"]', '{"noun_forms": ["baseness"], "verb_forms": [], "adjective_forms": ["baseless"], "adverb_forms": ["basically", "basely"]}', '["The proposal rested on base motives rather than evidence.", "A student should avoid base excuses in class."]', 'technology', '2', 424648, 763, NULL, 'opengloss-v1.1'),
('base_noun_0', 'base', 'noun', 0, 'The bottom support that provides stability for a structure or object.', '["foundation", "footing", "underpinning", "groundwork"]', '["top", "apex", "peak", "summit"]', '["structural element", "support"]', '["footing", "pedestal", "baseplate"]', '["base of operations", "base camp", "base ten", "base of support", "base pair"]', '{"noun_forms": ["basement"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The statue stood securely on its broad base.", "Foundations are poured to form the base of a house."]', 'technology', '2', 424648, 763, NULL, 'opengloss-v1.1'),
('base_verb_0', 'base', 'verb', 0, 'To use as a foundation or starting point for a conclusion, decision, or claim.', '["rely on", "depend on", "derive from", "base on"]', '["doubt", "ignore", "disregard", "overlook"]', '["justify", "underpin", "support"]', '["fact", "data", "premise", "evidence"]', '["base on evidence", "base on data", "base decisions on facts", "base of operations", "based in the region", "base policy on evidence"]', '{"noun_forms": ["basis"], "verb_forms": [], "adjective_forms": ["basal", "baseless"], "adverb_forms": ["basically"]}', '["Researchers base their conclusions on reliable data.", "Policy makers base decisions on facts and evidence."]', 'technology', '2', 424648, 763, NULL, 'opengloss-v1.1'),
