('base_noun_1', 'base', 'noun', 1, 'A substance that can accept hydrogen ions or neutralize acids; a base in chemistry.', '["alkali", "alkaline substance"]', '["acid"]', '["chemical substance"]', '["sodium hydroxide", "ammonia", "potash"]', '["base of operations", "base camp", "base ten", "base of support", "base pair"]', '{"noun_forms": ["basement"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Sodium hydroxide is a strong base used in soap making.", "Milk acts as a weak base when buffering stomach acid."]', 'technology', '2', 424648, 763, NULL, 'opengloss-v1.1'),
('base_verb_1', 'base', 'verb', 1, 'To station, locate, or operate from a particular place; to have a base.', '["station", "locate", "position"]', '["relocate", "withdraw", "disperse"]', '["location", "facility", "station"]', '["military base", "headquarters", "camp", "lab"]', '["base on evidence", "base on data", "base decisions on facts", "base of operations", "based in the region", "base policy on evidence"]', '{"noun_forms": ["basis"], "verb_forms": [], "adjective_forms": ["basal", "baseless"], "adverb_forms": ["basically"]}', '["The company bases its operations in New York.", "The research group bases its fieldwork in the university lab."]', 'technology', '2', 424648, 763, NULL, 'opengloss-v1.1'),
