-- lexi ETL: operations (2026-09-18T16:20:09Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('operations_noun_0', 'operations', 'noun', 0, 'The activities and processes that keep an organization running and serving its purpose.', '["activities", "tasks", "processes", "functions"]', '["inaction", "shutdown"]', '["activities", "work"]', '["workflows", "procedures", "tasks"]', '["business operations", "math operations", "standard operating procedures", "surgical operations", "field operations", "military operations"]', '{"noun_forms": ["operator"], "verb_forms": [], "adjective_forms": ["operational"], "adverb_forms": ["operationally"]}', '["The school''s operations include scheduling classes and managing the library.", "Efficient operations help a small business serve customers quickly."]', 'economics', '3', 417182, 778, NULL, 'opengloss-v1.1'),
('operations_noun_1', 'operations', 'noun', 1, 'A math or computer action that produces a result such as adding numbers or processing data.', '["calculations", "computations", "arithmetic"]', '["guess", "estimation"]', '["math concept", "arithmetic concept"]', '["addition", "subtraction", "multiplication", "division"]', '["business operations", "math operations", "standard operating procedures", "surgical operations", "field operations", "military operations"]', '{"noun_forms": ["operator"], "verb_forms": [], "adjective_forms": ["operational"], "adverb_forms": ["operationally"]}', '["Students learn to perform math operations with integers.", "The program applies several operations to the data."]', 'economics', '3', 417182, 778, NULL, 'opengloss-v1.1'),
('operations_noun_2', 'operations', 'noun', 2, 'A surgical procedure performed by doctors to diagnose or treat a condition.', '["surgery", "operation"]', '["watchful waiting", "nonoperation"]', '["medical procedure", "surgical procedure"]', '["appendectomy", "tonsillectomy"]', '["business operations", "math operations", "standard operating procedures", "surgical operations", "field operations", "military operations"]', '{"noun_forms": ["operator"], "verb_forms": [], "adjective_forms": ["operational"], "adverb_forms": ["operationally"]}', '["The hospital performed several operations last week.", "The patient underwent two operations yesterday."]', 'economics', '3', 417182, 778, NULL, 'opengloss-v1.1'),
