-- lexi ETL: channel (2026-09-18T16:20:09Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('channel_noun_0', 'channel', 'noun', 0, 'A means by which information, signals, or messages are transmitted.', '["medium", "conduit", "means", "vehicle"]', '["barrier", "blockage", "obstruction"]', '["conduit", "medium", "means"]', '["television channel", "radio channel", "water channel"]', '["television channel", "radio channel", "water channel", "channel of communication", "distribution channel", "channel capacity"]', '{"noun_forms": ["channeler", "channeling", "channelization"], "verb_forms": ["channelize", "rechannel"], "adjective_forms": [], "adverb_forms": []}', '["A classroom email is a channel for announcements to students.", "Teachers use a classroom discussion as a channel for questions."]', 'technology', '2', 388547, 837, NULL, 'opengloss-v1.1'),
('channel_verb_0', 'channel', 'verb', 0, 'To guide or direct energy, information, or other resources toward a specific destination or outcome.', '["direct", "guide", "funnel", "convey"]', '["misdirect", "divert", "block"]', '["direct action", "control", "management"]', '["channel energy", "channel data", "channel emotions"]', '["channel data", "channel energy", "channel information", "channel signals", "channel emotions", "channel a broadcast"]', '{"noun_forms": ["channeler", "channeling", "channelization"], "verb_forms": ["channelize", "channelise"], "adjective_forms": ["channelized"], "adverb_forms": ["channelwise"]}', '["The researcher channels data into a secure database.", "The tutor channels student questions to the expert panel."]', 'technology', '2', 388547, 837, NULL, 'opengloss-v1.1'),
('channel_noun_1', 'channel', 'noun', 1, 'A natural or artificial waterway that links two bodies of water.', '["waterway", "watercourse", "canal"]', '["land", "dry land"]', '["geographic feature"]', '["canal", "strait", "tidal channel"]', '["television channel", "radio channel", "water channel", "channel of communication", "distribution channel", "channel capacity"]', '{"noun_forms": ["channeler", "channeling", "channelization"], "verb_forms": ["channelize", "rechannel"], "adjective_forms": [], "adverb_forms": []}', '["The ship moved through the channel that connected the two seas.", "Ancient canals and channels improved irrigation for farms."]', 'technology', '2', 388547, 837, NULL, 'opengloss-v1.1'),
('channel_verb_1', 'channel', 'verb', 1, 'To broadcast or transmit through a channel or medium; to send information or signals via a specified medium.', '["transmit", "broadcast", "relay", "convey", "send"]', '["conceal", "withhold", "block", "receive"]', '["transmission", "communication", "distribution"]', '["telecast", "air", "stream"]', '["channel data", "channel energy", "channel information", "channel signals", "channel emotions", "channel a broadcast"]', '{"noun_forms": ["channeler", "channeling", "channelization"], "verb_forms": ["channelize", "channelise"], "adjective_forms": ["channelized"], "adverb_forms": ["channelwise"]}', '["The program channels the video feed to remote learners.", "The scientist channels signals through a fiber optic line."]', 'technology', '2', 388547, 837, NULL, 'opengloss-v1.1'),
('channel_noun_2', 'channel', 'noun', 2, 'An electronic or logical path that carries a signal or data.', '["pathway", "route", "lane"]', '["blockage", "obstruction"]', '["pathway", "passage", "route"]', '["data channel", "control channel", "broadcast channel"]', '["television channel", "radio channel", "water channel", "channel of communication", "distribution channel", "channel capacity"]', '{"noun_forms": ["channeler", "channeling", "channelization"], "verb_forms": ["channelize", "rechannel"], "adjective_forms": [], "adverb_forms": []}', '["WiFi uses multiple channels to avoid interference.", "The program assigns a channel to send data."]', 'technology', '2', 388547, 837, NULL, 'opengloss-v1.1')
