-- lexi ETL: engineering (2026-09-18T16:20:09Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('engineering_adjective_0', 'engineering', 'adjective', 0, 'Relating to the academic and practical work of engineers, including design, analysis, and testing.', '["technical", "applied", "practical"]', '[]', '["applied science", "design field", "science"]', '["mechanical engineering", "electrical engineering", "civil engineering"]', '["engineering design", "engineering drawing", "engineering principles", "engineering problem", "engineering project", "engineering challenge"]', '{"noun_forms": ["engineering", "engineer"], "verb_forms": ["engineer"], "adjective_forms": ["engineered"], "adverb_forms": []}', '["The engineering curriculum teaches students how to create safe structures.", "We studied engineering methods for measuring force and motion in experiments."]', 'science', 'BS', 378996, 855, NULL, 'opengloss-v1.1'),
('engineering_noun_0', 'engineering', 'noun', 0, 'Engineering as a school subject is the study of designing and testing tools structures and systems using math and science.', '["applied science", "technology", "technical field"]', '[]', '["technical subject", "applied science", "science"]', '["civil engineering", "mechanical engineering", "electrical engineering", "chemical engineering"]', '["engineering design", "civil engineering", "mechanical engineering", "engineering project", "engineering principles", "engineering workshop"]', '{"noun_forms": ["engineer", "engineering student"], "verb_forms": ["engineer"], "adjective_forms": ["engineered", "engineering"], "adverb_forms": []}', '["Our class studied engineering to learn how bridges carry weight safely.", "Engineering uses math and science to solve real world problems."]', 'science', 'BS', 378996, 855, NULL, 'opengloss-v1.1'),
('engineering_verb_0', 'engineering', 'verb', 0, 'To apply scientific and mathematical principles to design and build a device system or structure for a specific purpose.', '["design", "construct", "develop", "fabricate"]', '[]', '["design process", "technical work", "applied science"]', '["bridge design", "circuit design", "prototype testing"]', '["engineering design", "engineering problem", "engineering principle", "engineering process", "engineering team"]', '{"noun_forms": ["engineering", "engineer", "engineering design"], "verb_forms": [], "adjective_forms": ["engineered"], "adverb_forms": []}', '["Students engineered a small bridge model and measured load capacity during the lab.", "The class engineered a water filtration device using measured flow and material tests."]', 'science', 'BS', 378996, 855, NULL, 'opengloss-v1.1'),
('engineering_adjective_1', 'engineering', 'adjective', 1, 'Made or arranged using engineered methods or components intended for consistent performance.', '["engineered", "designed", "constructed", "fabricated"]', '[]', '["manufactured", "made", "created"]', '["engineered wood", "engineered system", "engineered part"]', '["engineering design", "engineering drawing", "engineering principles", "engineering problem", "engineering project", "engineering challenge"]', '{"noun_forms": ["engineering", "engineer"], "verb_forms": ["engineer"], "adjective_forms": ["engineered"], "adverb_forms": []}', '["The engineering bridge model used engineered joints to resist bending.", "Students built an engineering prototype that passed the load test."]', 'science', 'BS', 378996, 855, NULL, 'opengloss-v1.1'),
('engineering_noun_1', 'engineering', 'noun', 1, 'Engineering as a process means planning designing and building a thing or system to meet a specific need.', '["design", "construction", "system design"]', '[]', '["design activity", "technical practice", "process"]', '["bridge design", "robot design", "circuit design", "model building"]', '["engineering design", "civil engineering", "mechanical engineering", "engineering project", "engineering principles", "engineering workshop"]', '{"noun_forms": ["engineer", "engineering student"], "verb_forms": ["engineer"], "adjective_forms": ["engineered", "engineering"], "adverb_forms": []}', '["Design and engineering of the toy car involved drawing plans.", "Good engineering includes measuring materials and checking connections."]', 'science', 'BS', 378996, 855, NULL, 'opengloss-v1.1'),
('engineering_verb_1', 'engineering', 'verb', 1, 'To modify reconfigure or adapt an existing system or component to improve performance or meet new requirements.', '["modify", "reconfigure", "adapt", "retrofit"]', '[]', '["system modification", "technical change", "intervention"]', '["software refactor", "hardware retrofit", "parameter tuning"]', '["engineering design", "engineering problem", "engineering principle", "engineering process", "engineering team"]', '{"noun_forms": ["engineering", "engineer", "engineering design"], "verb_forms": [], "adjective_forms": ["engineered"], "adverb_forms": []}', '["Learners engineered the robot control code to increase sensor accuracy during trials.", "The team engineered the pump assembly to reduce energy consumption in experiments."]', 'science', 'BS', 378996, 855, NULL, 'opengloss-v1.1'),
('engineering_adjective_2', 'engineering', 'adjective', 2, 'Requiring engineering skill or focused on solving technical problems through systematic processes.', '["technical", "complex", "specialized", "systematic"]', '[]', '["problem solving", "skill based", "technical field"]', '["structural engineering", "systems engineering", "software engineering"]', '["engineering design", "engineering drawing", "engineering principles", "engineering problem", "engineering project", "engineering challenge"]', '{"noun_forms": ["engineering", "engineer"], "verb_forms": ["engineer"], "adjective_forms": ["engineered"], "adverb_forms": []}', '["This engineering task asks students to design a water filtration model.", "Engineering problems often require measurement calculation and careful testing."]', 'science', 'BS', 378996, 855, NULL, 'opengloss-v1.1'),
