('ships_noun_0', 'ships', 'noun', 0, 'Ships are large waterborne vessels designed for the transport of people, cargo, or military operations across seas and oceans.', '["vessel", "watercraft", "craft", "liner"]', '["land vehicle", "aircraft"]', '["vehicle", "craft", "vessel"]', '["cruise ship", "container ship", "bulk carrier", "ferry", "battleship"]', '["merchant ships", "naval ships", "container ships", "cargo ships", "tanker ships"]', '{"noun_forms": ["shipper", "shipping", "shipyard", "shipbuilding"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The merchant fleet comprised several ships operating along major trade routes.", "Historically ships powered by wind enabled global exploration."]', 'technology', '1', 364667, 891, NULL, 'opengloss-v1.1'),
('ships_verb_0', 'ships', 'verb', 0, 'To transport people or goods by sea using ships; to convey cargo across a body of water.', '["transport", "convey", "carry", "haul"]', '["unload", "receive", "disembark"]', '["transport", "move", "transfer", "convey"]', '["freighter", "liner", "cargo ship", "bulk carrier"]', '["shipping container", "freight rate", "cargo capacity", "ship date", "shipping lane", "logistics chain"]', '{"noun_forms": ["shipper", "shipment", "shipping"], "verb_forms": [], "adjective_forms": ["shippable"], "adverb_forms": []}', '["The fleet ships ore from the inland port to export terminals.", "International traders ship crude oil to refineries via tanker routes."]', 'technology', '1', 364667, 891, NULL, 'opengloss-v1.1'),
('ships_noun_1', 'ships', 'noun', 1, 'In fan studies ships refer to fan created romantic pairings of fictional characters, typically explored and circulated as fan fiction and discourse.', '["pairings", "couplings", "romances", "ships in fandom"]', '["canon pairings", "unship concept"]', '["fan culture", "narrative practice"]', '["slash pairings", "het pairings", "polyamorous ships"]', '["merchant ships", "naval ships", "container ships", "cargo ships", "tanker ships"]', '{"noun_forms": ["shipper", "shipping", "shipyard", "shipbuilding"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Scholars analyze how ships reflect audience negotiations of gender and desire.", "Popular ships can drive community activity and fan production."]', 'technology', '1', 364667, 891, NULL, 'opengloss-v1.1'),
('ships_verb_1', 'ships', 'verb', 1, 'To send or dispatch goods to a recipient, typically via a carrier; to ship items.', '["dispatch", "send", "forward", "deliver"]', '["receive", "collect", "retain"]', '["deliver", "distribute", "disburse"]', '["courier service", "parcel", "express shipment", "air freight"]', '["shipping container", "freight rate", "cargo capacity", "ship date", "shipping lane", "logistics chain"]', '{"noun_forms": ["shipper", "shipment", "shipping"], "verb_forms": [], "adjective_forms": ["shippable"], "adverb_forms": []}', '["The company ships orders the same day after payment.", "Automated fulfillment centers ship electronics worldwide via carriers."]', 'technology', '1', 364667, 891, NULL, 'opengloss-v1.1'),
('ships_verb_2', 'ships', 'verb', 2, 'To romantically support or endorse a fictional couple, commonly in fan communities.', '["support", "endorse", "root for", "back"]', '["oppose", "disapprove", "refuse to back"]', '["advocacy", "endorsement", "fandom practice"]', '["canon pairing", "fan pairing", "ship fiction"]', '["shipping container", "freight rate", "cargo capacity", "ship date", "shipping lane", "logistics chain"]', '{"noun_forms": ["shipper", "shipment", "shipping"], "verb_forms": [], "adjective_forms": ["shippable"], "adverb_forms": []}', '["Fans ship romantic pairings in fan fiction.", "Scholars analyze how fans ship characters to illustrate narrative desires."]', 'technology', '1', 364667, 891, NULL, 'opengloss-v1.1'),
('ships_verb_3', 'ships', 'verb', 3, 'To deliver a product or software to customers; to release a product into the market.', '["release", "launch", "deliver"]', '["delay", "withdraw", "pull"]', '["release", "deploy", "distribute"]', '["beta release", "stable release", "patch", "hotfix"]', '["shipping container", "freight rate", "cargo capacity", "ship date", "shipping lane", "logistics chain"]', '{"noun_forms": ["shipper", "shipment", "shipping"], "verb_forms": [], "adjective_forms": ["shippable"], "adverb_forms": []}', '["The company ships the latest update to customers next week.", "Software firms ship monthly releases after final quality checks."]', 'technology', '1', 364667, 891, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
