INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('silver_adjective_0', 'silver', 'adjective', 0, 'Of the color of polished silver; having a shiny metallic gray appearance.', '["silvery", "gray"]', '["dull", "matte"]', '["color", "appearance"]', '["silver-gray", "silver-white"]', '["silver color", "silver nitrate", "silver halide", "silver lining", "silverware"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": ["silvery", "silvered"], "adverb_forms": []}', '["The alloy displays a silver color that reflects light evenly.", "In cultural artifacts silver color signals high status."]', 'science', '2', 356434, 916, NULL, 'opengloss-v1.1'),
('silver_noun_0', 'silver', 'noun', 0, 'The chemical element with atomic number 47, symbol Ag, a soft, lustrous metal with high electrical and thermal conductivity; widely used in jewelry, electronics, and various industrial applications.', '["argentum", "silver metal"]', '["base metal"]', '["metal", "chemical element"]', '["fine silver", "silver ingot", "coin silver"]', '["silver medal", "silver lining", "silver coin", "silver jewelry", "silver price", "silver bullion"]', '{"noun_forms": ["silverware", "silversmith", "silversmithing"], "verb_forms": ["silvering", "silvered"], "adjective_forms": ["silvery"], "adverb_forms": []}', '["The jewelry contained pure silver.", "Refineries produce silver ingots from refined ore."]', 'science', '2', 356434, 916, NULL, 'opengloss-v1.1'),
('silver_verb_0', 'silver', 'verb', 0, 'To coat or plate with a thin layer of metallic silver on a surface, typically by electroplating or chemical deposition.', '["plate", "silverplate", "argentate"]', '["unplate", "deplate"]', '["coat", "surface treatment", "metal finishing"]', '["electroplating", "galvanic coating"]', '["silver plate", "silver plating", "silvered surface", "silver nitrate bath", "silver plating process"]', '{"noun_forms": ["silvering"], "verb_forms": ["silvered", "silvering"], "adjective_forms": [], "adverb_forms": []}', '["The substrate was silvered to increase reflectivity for spectroscopy.", "Researchers silverplate the sample surface to enhance corrosion resistance."]', 'science', '2', 356434, 916, NULL, 'opengloss-v1.1'),
('silver_adjective_1', 'silver', 'adjective', 1, 'Made of or coated with silver or containing silver metal; having a surface of silver.', '["silvered", "silver-plated", "metallic"]', '["nonmetallic"]', '["material", "metal"]', '["silverware", "silver jewelry", "silver coin"]', '["silver color", "silver nitrate", "silver halide", "silver lining", "silverware"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": ["silvery", "silvered"], "adverb_forms": []}', '["The vase was silvered to resist tarnish and enhance durability.", "A silver-plated spoon can deteriorate if improperly polished."]', 'science', '2', 356434, 916, NULL, 'opengloss-v1.1'),
('silver_noun_1', 'silver', 'noun', 1, 'A monetary metal or currency medium comprising silver; historically used in coins and bullion.', '["coinage metal", "monetary metal", "silver currency"]', '["fiat money"]', '["currency", "precious metal"]', '["silver coin", "silver bullion", "silver ingot"]', '["silver medal", "silver lining", "silver coin", "silver jewelry", "silver price", "silver bullion"]', '{"noun_forms": ["silverware", "silversmith", "silversmithing"], "verb_forms": ["silvering", "silvered"], "adjective_forms": ["silvery"], "adverb_forms": []}', '["Coins minted from silver circulated in ancient markets.", "Silver bullion served as reserves for national treasuries."]', 'science', '2', 356434, 916, NULL, 'opengloss-v1.1'),
('silver_verb_1', 'silver', 'verb', 1, 'To take on a silvery color or appearance, as a surface reflects light with a silvery sheen.', '["gleam", "glitter", "shine"]', '["dim", "dull"]', '["color change"]', '["silver-plate", "silver-coat", "frost"]', '["silver plate", "silver plating", "silvered surface", "silver nitrate bath", "silver plating process"]', '{"noun_forms": ["silvering"], "verb_forms": ["silvered", "silvering"], "adjective_forms": [], "adverb_forms": []}', '["The lake surface silvered under moonlight.", "Moonlight silvered the metal surface, yielding a reflective sheen."]', 'science', '2', 356434, 916, NULL, 'opengloss-v1.1'),
('silver_noun_2', 'silver', 'noun', 2, 'The color named silver; a light gray with metallic luster.', '["silvery color", "silvery white"]', '["dull color"]', '["color", "hue"]', '["silver gray", "metallic white"]', '["silver medal", "silver lining", "silver coin", "silver jewelry", "silver price", "silver bullion"]', '{"noun_forms": ["silverware", "silversmith", "silversmithing"], "verb_forms": ["silvering", "silvered"], "adjective_forms": ["silvery"], "adverb_forms": []}', '["The gown reflected a silvery color under stage lights.", "The car''s finish appeared metallic silver in sunlight."]', 'science', '2', 356434, 916, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
