('recording_noun_0', 'recording', 'noun', 0, 'The stored audio or visual content captured by a device, such as a sound file, video, or other perceptible trace of an event or performance.', '["audio", "tape", "video"]', '["silence", "live performance"]', '["media", "document"]', '["audio recording", "video recording"]', '["audio recording", "video recording", "field recording", "studio recording"]', '{"noun_forms": ["recordist", "recorder"], "verb_forms": ["record"], "adjective_forms": ["recorded", "recordable"], "adverb_forms": ["recordingly"]}', '["The lecture recording was uploaded to the course website for later review.", "Archival recording of the speech revealed several unscripted remarks."]', 'technology', '2', 338096, 979, NULL, 'opengloss-v1.1'),
('recording_verb_0', 'recording', 'verb', 0, 'Present participle of record: to capture and store audio, visual, or other data in a stable medium for later retrieval or analysis.', '["capturing", "registering", "documenting"]', '["erasing", "overwriting"]', '["saving", "storing"]', '["digitally recording", "audio recording"]', '["recording data", "recording observations", "recording interviews", "recording sessions"]', '{"noun_forms": ["record", "recording", "recorder", "recordist"], "verb_forms": ["re-record", "misrecord"], "adjective_forms": ["recorded", "recordable", "unrecorded"], "adverb_forms": ["recordingly"]}', '["The device is currently recording all incoming calls for quality assurance.", "Researchers are recording participants’ responses during the experiment."]', 'technology', '2', 338096, 979, NULL, 'opengloss-v1.1'),
('recording_noun_1', 'recording', 'noun', 1, 'The act or process of capturing, encoding, and storing information, especially sound or images, for later playback, analysis, or documentation.', '["documentation", "capturing", "registration"]', '["erasure", "deletion"]', '["documentation", "data collection"]', '["sound recording", "data recording"]', '["audio recording", "video recording", "field recording", "studio recording"]', '{"noun_forms": ["recordist", "recorder"], "verb_forms": ["record"], "adjective_forms": ["recorded", "recordable"], "adverb_forms": ["recordingly"]}', '["Accurate recording of field observations is essential in ethnographic research.", "The recording of interviews followed a standardized protocol."]', 'technology', '2', 338096, 979, NULL, 'opengloss-v1.1'),
('recording_verb_1', 'recording', 'verb', 1, 'Present participle of record: to make an official or systematic written, visual, or digital account of an event, measurement, or observation.', '["logging", "noting", "chronicling"]', '["omitting"]', '["documenting", "noting"]', '["video recording", "data recording"]', '["recording data", "recording observations", "recording interviews", "recording sessions"]', '{"noun_forms": ["record", "recording", "recorder", "recordist"], "verb_forms": ["re-record", "misrecord"], "adjective_forms": ["recorded", "recordable", "unrecorded"], "adverb_forms": ["recordingly"]}', '["The meteorological station is recording temperature changes every minute.", "The court clerk is recording the witness’s testimony in the official transcript."]', 'technology', '2', 338096, 979, NULL, 'opengloss-v1.1'),
('recording_noun_2', 'recording', 'noun', 2, 'A commercial or publishable audio product, typically a track, album, or performance released in a fixed medium or digital format.', '["track", "album", "release"]', '["manuscript"]', '["publication", "artwork"]', '["studio recording", "live recording"]', '["audio recording", "video recording", "field recording", "studio recording"]', '{"noun_forms": ["recordist", "recorder"], "verb_forms": ["record"], "adjective_forms": ["recorded", "recordable"], "adverb_forms": ["recordingly"]}', '["The ensemble’s latest recording received critical acclaim.", "She cited a historic jazz recording as a primary source in her paper."]', 'technology', '2', 338096, 979, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
