BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('highway_noun_0', 'highway', 'noun', 0, 'A major public road designed for through traffic between cities or regions, typically with multiple lanes and restricted access to support high-speed travel.', '["main road", "arterial road", "thoroughfare", "expressway"]', '["local road", "local street"]', '["road", "infrastructure"]', '["freeway", "interstate", "motorway", "tollway"]', '["highway system", "highway network", "limited access highway", "interstate highway", "urban highway", "highway maintenance"]', '{"noun_forms": ["highwayman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Urban planners evaluated highway capacity for regional traffic.", "The highway was widened to reduce congestion during peak hours."]', 'technology', '2', 331240, 1001, NULL, 'opengloss-v1.1'),
('highway_noun_1', 'highway', 'noun', 1, 'A publicly owned right‑of‑way reserved for vehicular traffic, maintained by government authorities as part of a national or regional road network; the term emphasizes governance and access rights.', '["public road", "state road", "public highway", "arterial route"]', '["private road", "private property road"]', '["infrastructure", "public works"]', '["state highway", "national highway", "federal highway", "tollway"]', '["highway system", "highway network", "limited access highway", "interstate highway", "urban highway", "highway maintenance"]', '{"noun_forms": ["highwayman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The highway network is financed through public funds and tolls.", "State highways connect rural places to urban centers."]', 'technology', '2', 331240, 1001, NULL, 'opengloss-v1.1'),
('highway_noun_2', 'highway', 'noun', 2, 'In metaphorical or colloquial usage, highway denotes a direct or rapid path to a goal, analogous to a route through life or career.', '["path", "course", "route", "pathway"]', '["detour", "dead end"]', '["pathway", "course"]', '["career path", "life route", "success trajectory"]', '["highway system", "highway network", "limited access highway", "interstate highway", "urban highway", "highway maintenance"]', '{"noun_forms": ["highwayman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["In literature, the highway motif represents freedom and escape.", "Scholars cite the highway as a metaphor for rapid advancement."]', 'technology', '2', 331240, 1001, NULL, 'opengloss-v1.1'),
('highway_noun_3', 'highway', 'noun', 3, 'A road type within national or regional transport networks characterized by limited access, grade-separated interchanges, and high-speed limits, commonly known as a limited-access highway.', '["limited access highway", "freeway", "expressway"]', '["at-grade road", "local road"]', '["road"]', '["tollway", "interstate"]', '["highway system", "highway network", "limited access highway", "interstate highway", "urban highway", "highway maintenance"]', '{"noun_forms": ["highwayman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The design of limited access highways reduces cross traffic.", "A tollway provides funding for maintenance and expansion."]', 'technology', '2', 331240, 1001, NULL, 'opengloss-v1.1')
