('digital_adjective_0', 'digital', 'adjective', 0, 'Relating to digits such as numbers or fingers.', '["numeric", "digit based"]', '["analog"]', '["mathematical term"]', '["binary digit", "decimal digit"]', '["digital classroom", "digital literacy", "digital device", "digital file", "digital camera"]', '{"noun_forms": ["digitalization", "digitization"], "verb_forms": ["digitize"], "adjective_forms": [], "adverb_forms": ["digitally"]}', '["The digital numbers on the board show the score.", "In early math digital means using digits instead of words."]', 'technology', '3', 320833, 1034, NULL, 'opengloss-v1.1'),
('digital_adjective_1', 'digital', 'adjective', 1, 'Relating to electronic technology and computers.', '["electronic", "computerized"]', '["analog"]', '["technology term"]', '["digital signal", "digital display"]', '["digital classroom", "digital literacy", "digital device", "digital file", "digital camera"]', '{"noun_forms": ["digitalization", "digitization"], "verb_forms": ["digitize"], "adjective_forms": [], "adverb_forms": ["digitally"]}', '["A digital classroom uses online software for lessons.", "Digital devices help students access information quickly."]', 'technology', '3', 320833, 1034, NULL, 'opengloss-v1.1'),
