INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('key_adjective_0', 'key', 'adjective', 0, 'In professional and technical usage, key describes a factor, feature, or attribute of central importance to an outcome, system, or analysis.', '["essential", "crucial", "critical", "pivotal"]', '["incidental", "minor", "trivial", "unimportant"]', '["importance", "attribute", "property"]', '["crucial factor", "essential variable", "critical parameter"]', '["key factor", "key variable", "key metric", "key parameter", "key findings", "key stakeholder"]', '{"noun_forms": ["keyness", "keyboard"], "verb_forms": ["keyed", "keying"], "adjective_forms": [], "adverb_forms": []}', '["The key factor in the experiment was data integrity.", "A key component determines overall system reliability."]', 'technology', 'K', 318596, 1042, NULL, 'opengloss-v1.1'),
('key_noun_0', 'key', 'noun', 0, 'A physical mechanical device consisting of a metal blade shaped to engage the pins of a lock, enabling operation of a lock and access to a secured area.', '["door key", "metal key", "lock key"]', '["unkeyed lock"]', '["device", "tool"]', '["master key", "skeleton key", "electronic key"]', '["security key", "master key", "skeleton key", "cryptographic key", "encryption key", "map key"]', '{"noun_forms": ["keyboard", "keyring", "keystone"], "verb_forms": ["keying", "keyed"], "adjective_forms": ["keyed", "keyless"], "adverb_forms": []}', '["The locksmith cataloged each physical key by lock.", "Security audits require keys to be tagged and tracked."]', 'technology', 'K', 318596, 1042, NULL, 'opengloss-v1.1'),
('key_verb_0', 'key', 'verb', 0, 'To input data into a computer system by keyboard, typically by typing characters.', '["input", "enter", "type"]', '["erase", "delete"]', '["data entry", "character input"]', '["text entry", "numeric entry"]', '["keyboard input", "keystroke", "key code", "key field", "key management"]', '{"noun_forms": ["keyboard", "keystroke", "keyer", "keying"], "verb_forms": ["keyed", "keys", "keying"], "adjective_forms": [], "adverb_forms": []}', '["Researchers key in experimental measurements from the field logs.", "The operator keyed the sensor readings into the database."]', 'technology', 'K', 318596, 1042, NULL, 'opengloss-v1.1'),
('key_adjective_1', 'key', 'adjective', 1, 'Relating to a cryptographic key or to key management; used to describe algorithms, protocols, or systems that employ keys for encryption or authentication.', '["cryptographic", "keyed"]', '["unsecured", "public"]', '["cryptographic property", "security attribute", "tech trait"]', '["secret key", "public key", "encryption key", "key exchange"]', '["key factor", "key variable", "key metric", "key parameter", "key findings", "key stakeholder"]', '{"noun_forms": ["keyness", "keyboard"], "verb_forms": ["keyed", "keying"], "adjective_forms": [], "adverb_forms": []}', '["Key management protocols govern how cryptographic keys are generated, stored, and rotated.", "Key length selection influences resistance to cryptanalytic attacks in symmetric ciphers."]', 'technology', 'K', 318596, 1042, NULL, 'opengloss-v1.1'),
('key_noun_1', 'key', 'noun', 1, 'In cryptography, a value used to perform encryption and decryption operations to control access to data.', '["encryption key", "secret key", "private key"]', '["plaintext"]', '["cryptographic concept", "security parameter"]', '["public key", "private key", "symmetric key"]', '["security key", "master key", "skeleton key", "cryptographic key", "encryption key", "map key"]', '{"noun_forms": ["keyboard", "keyring", "keystone"], "verb_forms": ["keying", "keyed"], "adjective_forms": ["keyed", "keyless"], "adverb_forms": []}', '["Public keys enable secure exchange in asymmetric cryptography.", "The secret key must be protected to maintain confidentiality."]', 'technology', 'K', 318596, 1042, NULL, 'opengloss-v1.1'),
('key_verb_1', 'key', 'verb', 1, 'To provision or initialize a cryptographic key within a system to enable its use for encryption or authentication.', '["provision", "initialize", "install"]', '["remove key", "clear key"]', '["cryptographic operation", "security procedure"]', '["key provisioning", "key installation"]', '["keyboard input", "keystroke", "key code", "key field", "key management"]', '{"noun_forms": ["keyboard", "keystroke", "keyer", "keying"], "verb_forms": ["keyed", "keys", "keying"], "adjective_forms": [], "adverb_forms": []}', '["Administrators key the device with a new encryption key during onboarding.", "The policy requires key provisioning before enabling secure communications."]', 'technology', 'K', 318596, 1042, NULL, 'opengloss-v1.1'),
('key_noun_2', 'key', 'noun', 2, 'A map key or legend describing symbols, colors, and abbreviations used on a map to facilitate interpretation.', '["legend", "map legend"]', '["no legend"]', '["cartographic element", "graphic element"]', '["color key", "symbol key", "legend entry"]', '["security key", "master key", "skeleton key", "cryptographic key", "encryption key", "map key"]', '{"noun_forms": ["keyboard", "keyring", "keystone"], "verb_forms": ["keying", "keyed"], "adjective_forms": ["keyed", "keyless"], "adverb_forms": []}', '["The map key clarifies the meaning of color codes.", "Researchers consulted the legend to interpret symbols in the study map."]', 'technology', 'K', 318596, 1042, NULL, 'opengloss-v1.1'),
('key_noun_3', 'key', 'noun', 3, 'An essential factor or determinant that explains or governs a process or outcome.', '["crucial factor", "essential element"]', '["nonessential element"]', '["conceptual element", "determinant"]', '["core variable", "driving factor"]', '["security key", "master key", "skeleton key", "cryptographic key", "encryption key", "map key"]', '{"noun_forms": ["keyboard", "keyring", "keystone"], "verb_forms": ["keying", "keyed"], "adjective_forms": ["keyed", "keyless"], "adverb_forms": []}', '["The key to the puzzle is identifying the underlying assumption.", "In predictive modeling, the key variable drives the outcome."]', 'technology', 'K', 318596, 1042, NULL, 'opengloss-v1.1')
