('structures_noun_0', 'structures', 'noun', 0, 'The way parts of something are arranged or connected, forming the framework that holds it together.', '["organization", "framework", "arrangement", "construction"]', '["disorder", "chaos"]', '["organization", "framework", "system"]', '["frame", "skeleton", "layout"]', '["cell structures", "social structures", "architectural structures", "economic structures", "data structures"]', '{"noun_forms": ["structure"], "verb_forms": ["structured", "structuring"], "adjective_forms": ["structural"], "adverb_forms": []}', '["The structure of a paragraph shows how ideas are arranged.", "A plant''s structure includes roots stems and leaves."]', 'science', '4', 311139, 1076, NULL, 'opengloss-v1.1'),
('structures_verb_0', 'structures', 'verb', 0, 'To arrange or organize elements in a coherent form according to a plan.', '["organize", "arrange", "design", "compose"]', '["disorganize", "disorder"]', '["organize", "form"]', '["frame", "layout", "system"]', '["lesson structure", "data structure", "sentence structure", "physical structure", "organizational structure", "frame structure"]', '{"noun_forms": ["structure"], "verb_forms": ["restructure"], "adjective_forms": ["structural"], "adverb_forms": ["structurally"]}', '["The teacher structures the lesson plan to build knowledge.", "Researchers structure the data to reveal trends."]', 'science', '4', 311139, 1076, NULL, 'opengloss-v1.1'),
('structures_noun_1', 'structures', 'noun', 1, 'A building or other constructed object such as a bridge or tower.', '["buildings", "edifices"]', '["ruins", "demolition"]', '["construction", "structure"]', '["house", "bridge", "skyscraper"]', '["cell structures", "social structures", "architectural structures", "economic structures", "data structures"]', '{"noun_forms": ["structure"], "verb_forms": ["structured", "structuring"], "adjective_forms": ["structural"], "adverb_forms": []}', '["The library is a simple structure.", "A bridge is a large structure."]', 'science', '4', 311139, 1076, NULL, 'opengloss-v1.1'),
('structures_verb_1', 'structures', 'verb', 1, 'To physically assemble or erect by joining parts; to build.', '["build", "assemble", "erect", "construct"]', '["demolish", "dismantle", "disassemble"]', '["construct", "build"]', '["frame", "assembly", "construction"]', '["lesson structure", "data structure", "sentence structure", "physical structure", "organizational structure", "frame structure"]', '{"noun_forms": ["structure"], "verb_forms": ["restructure"], "adjective_forms": ["structural"], "adverb_forms": ["structurally"]}', '["Engineers structure the steel frame to ensure stability.", "The crew structure the modular units on site."]', 'science', '4', 311139, 1076, NULL, 'opengloss-v1.1'),
