('operated_adjective_0', 'operated', 'adjective', 0, 'Having undergone a surgical operation; treated surgically.', '["postoperative", "surgical"]', '["unoperated", "nonoperative"]', '["medical descriptor"]', '["postoperative", "operated-on"]', '["operated device", "operated system", "operated valve", "operated limb", "operated patient", "operated group"]', '{"noun_forms": ["operation", "operator"], "verb_forms": ["operates", "operating", "operated"], "adjective_forms": ["operational"], "adverb_forms": ["operatively"]}', '["The operated group showed significant improvement after the intervention.", "The operated limb required extensive rehabilitation."]', 'technology', '2', 299562, 1108, NULL, 'opengloss-v1.1'),
('operated_verb_0', 'operated', 'verb', 0, 'To control the functioning of a device or system by using its controls.', '["run", "control", "pilot"]', '["stop", "idle", "cease"]', '["operation"]', '["crane operation", "machine operation", "vehicle operation"]', '["remote operation", "automated operation", "manual operation", "critical operation", "industrial operation"]', '{"noun_forms": ["operation", "operator", "operability"], "verb_forms": [], "adjective_forms": ["operable", "operational"], "adverb_forms": ["operationally"]}', '["The technician operated the centrifuge to separate samples.", "The device was operated under controlled laboratory conditions."]', 'technology', '2', 299562, 1108, NULL, 'opengloss-v1.1'),
('operated_adjective_1', 'operated', 'adjective', 1, 'Controlled or manipulated by a human operator; manual.', '["manual", "hand-operated", "human-operated"]', '["automatic", "self-operating"]', '["control method"]', '["hand-operated", "human-operated"]', '["operated device", "operated system", "operated valve", "operated limb", "operated patient", "operated group"]', '{"noun_forms": ["operation", "operator"], "verb_forms": ["operates", "operating", "operated"], "adjective_forms": ["operational"], "adverb_forms": ["operatively"]}', '["Manual valves require direct manipulation by an operator.", "The trial compared manual devices with autonomous systems."]', 'technology', '2', 299562, 1108, NULL, 'opengloss-v1.1'),
('operated_verb_1', 'operated', 'verb', 1, 'To perform a medical operation on a patient; to surgically intervene.', '["operate on", "perform surgery"]', '["avoid surgery"]', '["surgical procedure"]', '["appendectomy", "biopsy", "cesarean section"]', '["remote operation", "automated operation", "manual operation", "critical operation", "industrial operation"]', '{"noun_forms": ["operation", "operator", "operability"], "verb_forms": [], "adjective_forms": ["operable", "operational"], "adverb_forms": ["operationally"]}', '["The surgeon operated on the patient to remove the tumor.", "The team operated on the heart with a minimally invasive technique."]', 'technology', '2', 299562, 1108, NULL, 'opengloss-v1.1'),
('operated_adjective_2', 'operated', 'adjective', 2, 'In operation; currently functioning or being used.', '["operational", "functional"]', '["nonoperational", "offline", "idle"]', '["functional state"]', '["online", "live", "in-use"]', '["operated device", "operated system", "operated valve", "operated limb", "operated patient", "operated group"]', '{"noun_forms": ["operation", "operator"], "verb_forms": ["operates", "operating", "operated"], "adjective_forms": ["operational"], "adverb_forms": ["operatively"]}', '["The operated equipment remained operational during the test.", "The system remained in use during testing."]', 'technology', '2', 299562, 1108, NULL, 'opengloss-v1.1'),
