INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('train_noun_0', 'train', 'noun', 0, 'A railroad train is a connected line of railroad cars pulled by a locomotive that travels on tracks to transport people or goods.', '["railway train", "railroad train"]', '[]', '["vehicle"]', '["boxcar", "passenger car"]', '["train station", "train track", "train schedule", "train car", "train conductor", "train ride"]', '{"noun_forms": ["trainer", "training"], "verb_forms": [], "adjective_forms": ["untrained"], "adverb_forms": []}', '["A class compared a train with other forms of transport.", "A railroad train moves along tracks across the landscape."]', 'technology', 'K', 294309, 1133, NULL, 'opengloss-v1.1'),
('train_verb_0', 'train', 'verb', 0, 'To teach someone a skill or subject through instruction and practice.', '["educate", "instruct", "coach", "tutor"]', '["neglect", "ignore", "untrain"]', '["educate", "prepare"]', '["coach", "drill", "practice", "tutor"]', '["training program", "physical training", "skill training", "training data", "driver training", "animal training"]', '{"noun_forms": ["trainer", "retraining"], "verb_forms": ["retrain"], "adjective_forms": ["trainable"], "adverb_forms": []}', '["Teachers train students in problem solving through guided practice.", "Parents train children to recognize safety rules at home."]', 'technology', 'K', 294309, 1133, NULL, 'opengloss-v1.1'),
('train_noun_1', 'train', 'noun', 1, 'A sequence or line of objects, actions, or ideas; a chain; as in train of thought or train of events.', '["sequence", "line", "series", "progression"]', '["disorder", "randomness"]', '["order"]', '["string", "row", "chain"]', '["train station", "train track", "train schedule", "train car", "train conductor", "train ride"]', '{"noun_forms": ["trainer", "training"], "verb_forms": [], "adjective_forms": ["untrained"], "adverb_forms": []}', '["The teacher traced the train of thought to the answer.", "Researchers followed a train of events from cause to effect."]', 'technology', 'K', 294309, 1133, NULL, 'opengloss-v1.1'),
('train_verb_1', 'train', 'verb', 1, 'To exercise and practice to improve strength speed or skill.', '["practice", "drill", "workout", "rehearse"]', '["rest", "idle", "disuse"]', '["improve", "develop"]', '["workout", "drill", "conditioning", "practice"]', '["training program", "physical training", "skill training", "training data", "driver training", "animal training"]', '{"noun_forms": ["trainer", "retraining"], "verb_forms": ["retrain"], "adjective_forms": ["trainable"], "adverb_forms": []}', '["Athletes train daily to improve endurance and speed.", "Musicians train their fingers with scales and patterns."]', 'technology', 'K', 294309, 1133, NULL, 'opengloss-v1.1'),
('train_noun_2', 'train', 'noun', 2, 'The long trailing part of a dress or gown.', '["gown train", "dress train", "dress tail"]', '[]', '["garment"]', '["cathedral train", "chapel train"]', '["train station", "train track", "train schedule", "train car", "train conductor", "train ride"]', '{"noun_forms": ["trainer", "training"], "verb_forms": [], "adjective_forms": ["untrained"], "adverb_forms": []}', '["The bride''s train swept the floor as she entered.", "The wedding gown featured a dramatic cathedral train."]', 'technology', 'K', 294309, 1133, NULL, 'opengloss-v1.1'),
('train_verb_2', 'train', 'verb', 2, 'To teach or discipline an animal to behave in a desired way.', '["tame", "domesticate", "drill", "train"]', '["untrain", "neglect", "ignore"]', '["educate", "discipline"]', '["obedience", "agility", "housebreaking", "trick training"]', '["training program", "physical training", "skill training", "training data", "driver training", "animal training"]', '{"noun_forms": ["trainer", "retraining"], "verb_forms": ["retrain"], "adjective_forms": ["trainable"], "adverb_forms": []}', '["A dog is trained to sit on command.", "Pets learn to respond to cues through gentle training."]', 'technology', 'K', 294309, 1133, NULL, 'opengloss-v1.1'),
('train_verb_3', 'train', 'verb', 3, 'To direct one''s gaze or attention toward something.', '["focus", "direct", "concentrate"]', '["disregard", "ignore", "overlook"]', '["focus", "direct"]', '["gaze", "spotlight", "focus"]', '["training program", "physical training", "skill training", "training data", "driver training", "animal training"]', '{"noun_forms": ["trainer", "retraining"], "verb_forms": ["retrain"], "adjective_forms": ["trainable"], "adverb_forms": []}', '["The photographer trains the camera on the subject.", "The teacher trains focus on the main idea."]', 'technology', 'K', 294309, 1133, NULL, 'opengloss-v1.1')
