INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('broadcast_adjective_0', 'broadcast', 'adjective', 0, 'Broadcast describes content that is transmitted to a wide audience via radio or television, or content designed for such transmission.', '["televised", "aired"]', '["narrowcast"]', '["media term", "mass media", "communication term"]', '["television broadcast", "radio broadcast", "live broadcast"]', '["broadcast media", "televised program", "live broadcast", "radio broadcast", "broadcast schedule", "mass media"]', '{"noun_forms": ["broadcaster", "broadcasting"], "verb_forms": ["broadcast", "broadcasted", "broadcasting", "broadcasts"], "adjective_forms": ["broadcastable"], "adverb_forms": []}', '["The broadcast weather forecast helps students learn about climate.", "The broadcast schedule shows when the next science program airs."]', 'technology', '2', 276307, 1208, NULL, 'opengloss-v1.1'),
('broadcast_noun_0', 'broadcast', 'noun', 0, 'A radio or television program that is broadcast to an audience.', '["program", "telecast", "show", "airing"]', '["unbroadcast"]', '["media content", "broadcasting content"]', '["news broadcast", "sports broadcast", "educational program"]', '["broadcast schedule", "radio broadcast", "television broadcast", "live broadcast", "news broadcast", "educational broadcast"]', '{"noun_forms": ["broadcaster"], "verb_forms": ["broadcasting"], "adjective_forms": [], "adverb_forms": []}', '["Students watched the science broadcast in homeroom.", "The morning broadcast explained the new science topic."]', 'technology', '2', 276307, 1208, NULL, 'opengloss-v1.1'),
('broadcast_verb_0', 'broadcast', 'verb', 0, 'To send out a program, message, or signal to many listeners or viewers via radio, television, or the internet so that it can be received by a large audience.', '["telecast", "air", "transmit"]', '["conceal", "withhold", "hide"]', '["transmit", "disseminate"]', '["telecast", "webcast"]', '["live broadcast", "online broadcast", "television broadcast", "radio broadcast", "news broadcast", "school broadcast"]', '{"noun_forms": ["broadcaster", "broadcasting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The school will broadcast the science lesson live online.", "The city radio station broadcasts weather alerts during emergencies."]', 'technology', '2', 276307, 1208, NULL, 'opengloss-v1.1'),
('broadcast_noun_1', 'broadcast', 'noun', 1, 'The act of sending out messages or information to a large audience.', '["airing", "dissemination", "transmission"]', '["concealment", "withholding"]', '["communication", "information flow"]', '["live stream", "news bulletin"]', '["broadcast schedule", "radio broadcast", "television broadcast", "live broadcast", "news broadcast", "educational broadcast"]', '{"noun_forms": ["broadcaster"], "verb_forms": ["broadcasting"], "adjective_forms": [], "adverb_forms": []}', '["The broadcast of the announcements reached every classroom.", "A teacher explained how information spreads through dissemination."]', 'technology', '2', 276307, 1208, NULL, 'opengloss-v1.1'),
('broadcast_verb_1', 'broadcast', 'verb', 1, 'To make information, announcements, or opinions widely known or communicated to a broad audience, often through media or networks.', '["disseminate", "publicize", "spread"]', '["conceal", "withhold"]', '["inform", "publish", "disseminate information"]', '["press release", "newsletter"]', '["live broadcast", "online broadcast", "television broadcast", "radio broadcast", "news broadcast", "school broadcast"]', '{"noun_forms": ["broadcaster", "broadcasting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The principal broadcast the test results to all families.", "Scientists broadcast their findings through newsletters and the school website."]', 'technology', '2', 276307, 1208, NULL, 'opengloss-v1.1'),
('broadcast_noun_2', 'broadcast', 'noun', 2, 'The practice of scattering seeds over land to plant crops.', '["sowing", "seeding"]', '["row planting", "precise planting"]', '["agriculture practice", "crop production"]', '["hand sowing", "aerial seeding"]', '["broadcast schedule", "radio broadcast", "television broadcast", "live broadcast", "news broadcast", "educational broadcast"]', '{"noun_forms": ["broadcaster"], "verb_forms": ["broadcasting"], "adjective_forms": [], "adverb_forms": []}', '["Farmers use broadcast seeding to cover large fields.", "A seed broadcast covered the field with a uniform layer."]', 'technology', '2', 276307, 1208, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
