INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('charts_noun_0', 'charts', 'noun', 0, 'A graphic representation of data using bars, lines, or cells to show relationships and trends.', '["graph", "diagram", "table"]', '["text", "narrative"]', '["data visualization"]', '["bar chart", "line chart", "pie chart", "scatter chart"]', '["bar chart", "line chart", "pie chart", "attendance chart", "nautical chart"]', '{"noun_forms": ["charting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The science report included a chart showing temperature changes over a week.", "Experiments compared charts of growth rates across different trials."]', 'technology', '1', 252725, 1327, NULL, 'opengloss-v1.1'),
('charts_verb_0', 'charts', 'verb', 0, 'To create charts or graphs by representing data visually.', '["plot", "graph", "map", "record", "log"]', '["erase", "ignore", "conceal"]', '["verb", "action"]', '["plot data", "map region", "record trends"]', '["chart a course", "chart data", "chart progress", "chart a map", "chart trends", "chart results"]', '{"noun_forms": ["charting"], "verb_forms": ["rechart"], "adjective_forms": ["chartable"], "adverb_forms": []}', '["She charts the test scores in a bar graph.", "The class charts monthly progress to show improvement."]', 'technology', '1', 252725, 1327, NULL, 'opengloss-v1.1'),
('charts_noun_1', 'charts', 'noun', 1, 'A map used for navigation that shows coastlines, depths, hazards, and other features.', '["map", "nautical chart"]', '["verbal directions"]', '["map"]', '["nautical chart", "pilot chart", "maritime chart"]', '["bar chart", "line chart", "pie chart", "attendance chart", "nautical chart"]', '{"noun_forms": ["charting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The captain studied the nautical chart before entering the harbor.", "Geographers examine maritime charts to analyze coastal zones."]', 'technology', '1', 252725, 1327, NULL, 'opengloss-v1.1'),
('charts_verb_1', 'charts', 'verb', 1, 'To map or plan by marking positions on a chart or map; to chart a route or coastline.', '["map", "plot", "plan"]', '["erase", "omit", "discard"]', '["verb", "action"]', '["map region", "chart coastline", "plot route"]', '["chart a course", "chart data", "chart progress", "chart a map", "chart trends", "chart results"]', '{"noun_forms": ["charting"], "verb_forms": ["rechart"], "adjective_forms": ["chartable"], "adverb_forms": []}', '["Explorers charted the coastline to avoid reefs.", "The map team charts a new river route."]', 'technology', '1', 252725, 1327, NULL, 'opengloss-v1.1'),
('charts_noun_2', 'charts', 'noun', 2, 'A chart that lists tasks, events, or progress in a planned sequence.', '["schedule", "timetable", "plan"]', '["disorganization", "mess"]', '["planning tool"]', '["daily schedule", "class timetable", "attendance chart", "progress chart"]', '["bar chart", "line chart", "pie chart", "attendance chart", "nautical chart"]', '{"noun_forms": ["charting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The classroom uses a daily schedule chart showing activities.", "Students track homework on a progress chart."]', 'technology', '1', 252725, 1327, NULL, 'opengloss-v1.1'),
('charts_verb_2', 'charts', 'verb', 2, 'To record or document data or trends over time for analysis and tracking.', '["record", "log", "track"]', '["erase", "delete", "omit"]', '["verb", "action"]', '["record trends", "log measurements"]', '["chart a course", "chart data", "chart progress", "chart a map", "chart trends", "chart results"]', '{"noun_forms": ["charting"], "verb_forms": ["rechart"], "adjective_forms": ["chartable"], "adverb_forms": []}', '["The teacher charts reading pace across the semester.", "Scientists chart temperature changes year by year."]', 'technology', '1', 252725, 1327, NULL, 'opengloss-v1.1')
