('bronze_adjective_0', 'bronze', 'adjective', 0, 'Having the color of bronze; a reddish brown metallic color.', '["coppery", "bronze-toned", "reddish brown"]', '["silver", "pale"]', '["color"]', '["bronze hue", "bronze tint", "bronze shade"]', '["bronze color", "bronze medal", "bronze statue", "bronze coating", "bronze alloy", "bronze age"]', '{"noun_forms": ["bronze"], "verb_forms": ["bronze"], "adjective_forms": ["bronzed", "bronze-colored"], "adverb_forms": []}', '["The sculpture has a bronze color that catches the light.", "In the science project, students compare bronze color variations across samples."]', 'technology', '3', 252027, 1334, NULL, 'opengloss-v1.1'),
('bronze_noun_0', 'bronze', 'noun', 0, 'A yellow-brown metal alloy produced by combining copper with tin.', '["copper tin alloy", "metal alloy"]', '[]', '["alloy", "metal"]', '["bronze statue", "bronze coin", "bronze sculpture"]', '["bronze statue", "bronze coin", "bronze sculpture", "bronze age", "bronze medal", "bronze color"]', '{"noun_forms": ["bronzer"], "verb_forms": ["bronze", "bronzed", "bronzing", "bronzes"], "adjective_forms": ["bronzy"], "adverb_forms": []}', '["Bronze is an alloy of copper and tin used for statues.", "Ancient artisans forged bronze for durable tools and weapons."]', 'technology', '3', 252027, 1334, NULL, 'opengloss-v1.1'),
('bronze_verb_0', 'bronze', 'verb', 0, 'To coat or cover a surface with bronze or a bronze colored finish.', '["coat", "metalize", "finish", "treat"]', '["uncoat", "unbronze"]', '["surface coating", "finishing process", "metal finishing"]', '["bronze statue", "bronze coin", "bronze medal"]', '["bronze statue", "bronze medal", "bronze finish", "bronze coating", "bronze color"]', '{"noun_forms": ["bronzer"], "verb_forms": [], "adjective_forms": ["bronzy"], "adverb_forms": []}', '["The sculptor bronzed the statue for a durable finish.", "They bronzed the coin to imitate antique metal."]', 'technology', '3', 252027, 1334, NULL, 'opengloss-v1.1'),
('bronze_adjective_1', 'bronze', 'adjective', 1, 'Made of bronze or showing the metallic material of bronze.', '["bronze-coated", "bronze-plated", "metallic"]', '["wooden", "plastic"]', '["material", "metal"]', '["bronze statue", "bronze coin", "bronze bell"]', '["bronze color", "bronze medal", "bronze statue", "bronze coating", "bronze alloy", "bronze age"]', '{"noun_forms": ["bronze"], "verb_forms": ["bronze"], "adjective_forms": ["bronzed", "bronze-colored"], "adverb_forms": []}', '["The bronze sculpture survived the museum''s weathering tests.", "A bronze coin is often included in ancient trade studies."]', 'technology', '3', 252027, 1334, NULL, 'opengloss-v1.1'),
('bronze_noun_1', 'bronze', 'noun', 1, 'The bronze color, a warm brown shade with a metallic sheen.', '["bronze color", "metallic brown"]', '["silver", "gold"]', '["color", "hue"]', '["antique bronze", "dark bronze", "bronze patina"]', '["bronze statue", "bronze coin", "bronze sculpture", "bronze age", "bronze medal", "bronze color"]', '{"noun_forms": ["bronzer"], "verb_forms": ["bronze", "bronzed", "bronzing", "bronzes"], "adjective_forms": ["bronzy"], "adverb_forms": []}', '["The bronze color is a warm brown shade with a metallic look.", "The painter mixed pigments to achieve a bronze color."]', 'technology', '3', 252027, 1334, NULL, 'opengloss-v1.1'),
('bronze_verb_1', 'bronze', 'verb', 1, 'To tan or darken the skin to a bronze color, typically from sun exposure or a tanning product.', '["tan", "tint", "color", "darken"]', '["pale", "bleach"]', '["tanning", "coloring"]', '["bronze tan", "bronzed skin"]', '["bronze statue", "bronze medal", "bronze finish", "bronze coating", "bronze color"]', '{"noun_forms": ["bronzer"], "verb_forms": [], "adjective_forms": ["bronzy"], "adverb_forms": []}', '["She bronzed her skin after a sunny vacation.", "A spray tan can bronze quickly."]', 'technology', '3', 252027, 1334, NULL, 'opengloss-v1.1'),
