INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('mike_noun_0', 'mike', 'noun', 0, 'A microphone is an electroacoustic transducer that converts acoustic energy into an electrical signal for amplification, recording, or transmission in audio systems.', '["microphone", "mic"]', '["loudspeaker", "unamplified sound"]', '["device", "instrument", "equipment"]', '["dynamic microphone", "condenser microphone", "lavalier microphone", "boundary microphone"]', '["dynamic microphone", "condenser microphone", "handheld microphone", "wireless microphone", "microphone stand"]', '{"noun_forms": ["microphone"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The microphone array recorded the lecture for acoustic analysis.", "Researchers calibrated a microphone to ensure stable measurements across trials."]', 'technology', 'K', 240247, 1401, NULL, 'opengloss-v1.1'),
('mike_verb_0', 'mike', 'verb', 0, 'To place and arrange a microphone to capture audio for amplification or recording, typically in studio, stage, or film-set contexts.', '["mic"]', '["mute", "disconnect"]', '["sound recording"]', '["miking vocals", "miking drums"]', '["handheld microphone", "wireless microphone", "boom microphone", "microphone stand", "microphone cable"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The sound engineer miked the vocalist to ensure clear vocal capture.", "During the session, engineers miked every instrument for redundancy."]', 'technology', 'K', 240247, 1401, NULL, 'opengloss-v1.1'),
('mike_verb_1', 'mike', 'verb', 1, 'To speak into a microphone, i.e., to address an audience or participate in a broadcast or interview using a microphone.', '["talk", "speak", "address"]', '["mute", "ignore"]', '["verbal communication"]', '["interviewing", "live broadcast"]', '["handheld microphone", "wireless microphone", "boom microphone", "microphone stand", "microphone cable"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The host miked the guest for the live broadcast.", "The interviewee miked up and began the presentation."]', 'technology', 'K', 240247, 1401, NULL, 'opengloss-v1.1'),
('mike_verb_2', 'mike', 'verb', 2, 'To perform a microphone check to verify functionality and audio levels prior to a recording or broadcast.', '["test", "check"]', '["neglect"]', '["audio testing"]', '["soundcheck", "level check"]', '["handheld microphone", "wireless microphone", "boom microphone", "microphone stand", "microphone cable"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The crew conducted a final soundcheck before recording.", "A quick level check revealed fluctuating levels in the room."]', 'technology', 'K', 240247, 1401, NULL, 'opengloss-v1.1')
