('paper_adjective_0', 'paper', 'adjective', 0, 'Made from paper; composed of paper material.', '["papery", "paperlike", "papered"]', '["cloth", "plastic", "metal"]', '["material", "substance"]', '["paper product", "paper sheet", "paper notebook"]', '["on paper", "paper trail", "paper notebook", "paper towel", "paper bag", "paper clip"]', '{"noun_forms": ["paperwork", "paperweight", "paperboard"], "verb_forms": ["papering"], "adjective_forms": ["papery", "paperless"], "adverb_forms": []}', '["The paper cup dissolved in hot coffee.", "A paper notebook was issued to each student for note taking."]', 'technology', 'K', 239880, 1405, NULL, 'opengloss-v1.1'),
('paper_noun_0', 'paper', 'noun', 0, 'Paper is the thin material made from wood pulp used for writing, printing, drawing, and packaging.', '["sheet", "cardstock", "parchment", "writing material"]', '["digital media"]', '["material"]', '["printer paper", "copy paper", "newsprint"]', '["printer paper", "graph paper", "lined paper", "copy paper", "newsprint", "cardstock"]', '{"noun_forms": ["paperwork"], "verb_forms": [], "adjective_forms": ["papery", "paperless"], "adverb_forms": []}', '["Plain white paper helps students write legibly in exercises.", "Graph paper helps organize data and charts in science notebooks."]', 'technology', 'K', 239880, 1405, NULL, 'opengloss-v1.1'),
