('paper_adjective_1', 'paper', 'adjective', 1, 'Relating to or existing in written form; theoretical rather than practical.', '["theoretical", "documentary", "formal"]', '["practical", "hands-on", "real-world"]', '["theory", "documentation"]', '["written plan", "formal proposal"]', '["on paper", "paper trail", "paper notebook", "paper towel", "paper bag", "paper clip"]', '{"noun_forms": ["paperwork", "paperweight", "paperboard"], "verb_forms": ["papering"], "adjective_forms": ["papery", "paperless"], "adverb_forms": []}', '["The plan looked good on paper but failed in the field.", "The school required a paper proposal before starting the project."]', 'technology', 'K', 239880, 1405, NULL, 'opengloss-v1.1'),
('paper_noun_1', 'paper', 'noun', 1, 'A formal written assignment on a topic produced for school assessment.', '["essay", "report", "composition", "term paper"]', '["oral presentation"]', '["document", "written work"]', '["research paper", "lab report", "book report", "term paper"]', '["printer paper", "graph paper", "lined paper", "copy paper", "newsprint", "cardstock"]', '{"noun_forms": ["paperwork"], "verb_forms": [], "adjective_forms": ["papery", "paperless"], "adverb_forms": []}', '["The science project required a five paragraph essay.", "Students submit a research paper with sources and a bibliography."]', 'technology', 'K', 239880, 1405, NULL, 'opengloss-v1.1'),
