-- lexi ETL: publishing (2026-09-18T16:20:12Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('publishing_adjective_0', 'publishing', 'adjective', 0, 'The adjective publishing describes processes and practices related to the production and dissemination of literary, journalistic, or digital content, including editorial, production, distribution, and rights-management activities.', '["editorial", "production-related", "print-related"]', '["unpublished", "unpublishing"]', '["production", "media industry", "information industry"]', '["book publishing", "journal publishing", "digital publishing"]', '["publishing industry", "academic publishing", "publishing workflow", "digital publishing", "print publishing", "self publishing"]', '{"noun_forms": ["publisher", "publication"], "verb_forms": ["publish"], "adjective_forms": ["publishable"], "adverb_forms": []}', '["publishing workflow constraints influence editorial timelines", "institutions invest in publishing infrastructure to support open access"]', 'technology', '4', 233867, 1448, NULL, 'opengloss-v1.1'),
('publishing_noun_0', 'publishing', 'noun', 0, 'The activity and industry involved in producing, editing, licensing, and distributing printed or digital content such as books, journals, and magazines.', '["book publishing", "publishing industry", "the trade", "publishing sector"]', '["unpublication", "withholding", "suppression"]', '["industry", "activity", "economic sector"]', '["book publishing", "academic publishing", "digital publishing", "newspaper publishing"]', '["publishing industry", "academic publishing", "digital publishing", "book publishing", "publishing process", "open access publishing"]', '{"noun_forms": ["publisher", "publishability", "publishing house", "publishing company"], "verb_forms": ["publish"], "adjective_forms": ["publishable"], "adverb_forms": []}', '["The publishing industry has rapidly shifted toward digital distribution.", "Academic publishers compete in a global market for scholarly titles."]', 'technology', '4', 233867, 1448, NULL, 'opengloss-v1.1'),
('publishing_verb_0', 'publishing', 'verb', 0, 'To issue a work or material to the public through publication channels such as print, online platforms, or broadcast media.', '["issue", "release", "disseminate", "print"]', '["withhold", "conceal", "suppress"]', '["dissemination", "distribution"]', '["book publishing", "journal publishing", "open access publishing", "digital publishing"]', '["academic publishing", "book publishing", "journal publishing", "publishing workflow", "publishing house"]', '{"noun_forms": ["publication", "publisher", "publishing platform", "publishing house"], "verb_forms": ["publish"], "adjective_forms": ["publishable"], "adverb_forms": []}', '["The university press is publishing a new monograph this fall.", "Researchers are publishing their findings in a high impact journal."]', 'technology', '4', 233867, 1448, NULL, 'opengloss-v1.1'),
('publishing_adjective_1', 'publishing', 'adjective', 1, 'Of or relating to the publishing industry as an economic sector and to its business practices, including ownership, licensing, distribution, and market strategies.', '["industry-related", "publisher-focused", "commercial-level"]', '["unpublished", "nonpublishing"]', '["media industry", "creative industries", "information industry"]', '["book publishing", "journal publishing", "academic publishing", "self publishing"]', '["publishing industry", "academic publishing", "publishing workflow", "digital publishing", "print publishing", "self publishing"]', '{"noun_forms": ["publisher", "publication"], "verb_forms": ["publish"], "adjective_forms": ["publishable"], "adverb_forms": []}', '["the publishing industry faced consolidation amid digital disruption", "journals rely on publishing houses for distribution"]', 'technology', '4', 233867, 1448, NULL, 'opengloss-v1.1'),
('publishing_noun_1', 'publishing', 'noun', 1, 'The process of preparing and releasing content to the public, including editing, formatting, licensing, and distribution.', '["issuance", "dissemination", "release"]', '["suppression", "withholding", "withdrawal"]', '["process", "activity"]', '["editing", "typesetting", "layout design", "printing"]', '["publishing industry", "academic publishing", "digital publishing", "book publishing", "publishing process", "open access publishing"]', '{"noun_forms": ["publisher", "publishability", "publishing house", "publishing company"], "verb_forms": ["publish"], "adjective_forms": ["publishable"], "adverb_forms": []}', '["The publishing process begins with manuscript review and ends with distribution.", "Editing is a crucial step in the publishing process."]', 'technology', '4', 233867, 1448, NULL, 'opengloss-v1.1'),
('publishing_verb_1', 'publishing', 'verb', 1, 'To make data or information publicly accessible by depositing it in a repository, platform, or database.', '["deposit", "upload", "post"]', '["remove", "withdraw"]', '["data dissemination", "information publication"]', '["data publishing", "dataset publication", "repository deposition", "open data release"]', '["academic publishing", "book publishing", "journal publishing", "publishing workflow", "publishing house"]', '{"noun_forms": ["publication", "publisher", "publishing platform", "publishing house"], "verb_forms": ["publish"], "adjective_forms": ["publishable"], "adverb_forms": []}', '["Researchers are publishing their data in an open repository.", "The platform enables publishing datasets alongside manuscripts."]', 'technology', '4', 233867, 1448, NULL, 'opengloss-v1.1'),
('publishing_adjective_2', 'publishing', 'adjective', 2, 'Relating to content that is prepared or suitable for publication; intended for release to the public or for formal dissemination, often implying readiness for submission or printing.', '["publishable", "print-ready", "ready-for-publication"]', '["unpublishable", "unready-for-publication"]', '["text quality", "document readiness"]', '["peer reviewed publication", "open access article"]', '["publishing industry", "academic publishing", "publishing workflow", "digital publishing", "print publishing", "self publishing"]', '{"noun_forms": ["publisher", "publication"], "verb_forms": ["publish"], "adjective_forms": ["publishable"], "adverb_forms": []}', '["a publishable manuscript awaiting peer review", "the manuscript achieved publishing readiness after revisions"]', 'technology', '4', 233867, 1448, NULL, 'opengloss-v1.1'),
('publishing_noun_2', 'publishing', 'noun', 2, 'The professional or academic practice of producing and disseminating scholarly works, typically through journals and books.', '["academic publishing", "scholarly publishing", "journal publishing"]', '["self publishing", "indie publishing"]', '["discipline", "field", "industry"]', '["open access publishing", "subscription publishing", "print publishing", "digital publishing"]', '["publishing industry", "academic publishing", "digital publishing", "book publishing", "publishing process", "open access publishing"]', '{"noun_forms": ["publisher", "publishability", "publishing house", "publishing company"], "verb_forms": ["publish"], "adjective_forms": ["publishable"], "adverb_forms": []}', '["Academic publishing relies on peer review to validate findings.", "Open access publishing has altered incentives for researchers."]', 'technology', '4', 233867, 1448, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
