INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('sites_noun_0', 'sites', 'noun', 0, 'A place or position where something is located or occurs; in geographic, architectural, or functional contexts.', '["location", "place", "locality", "venue"]', '[]', '["location", "place", "geographic concept"]', '["archaeological site", "construction site", "industrial site", "residential site"]', '["archaeological site", "building site", "construction site", "web site", "site selection", "site visit"]', '{"noun_forms": ["site"], "verb_forms": ["sited", "siting", "sites"], "adjective_forms": [], "adverb_forms": []}', '["Fieldwork documented multiple field sites for spatial analysis.", "The study compared outcomes across urban and rural sites."]', 'geography', '3', 233255, 1455, NULL, 'opengloss-v1.1'),
('sites_verb_0', 'sites', 'verb', 0, 'To locate or place a building or facility at a chosen position, especially in planning, construction, or site assessment contexts.', '["locate", "situate", "place", "position"]', '["remove", "displace"]', '["transitive verb", "action verb", "verb"]', '["resite"]', '["site plan", "building site", "historic site", "site selection", "site location", "prime site"]', '{"noun_forms": ["siting"], "verb_forms": ["resite"], "adjective_forms": ["onsite"], "adverb_forms": ["onsite"]}', '["The city planner sites the new biology lab on the riverbank.", "The engineer sites the facility on elevated ground to reduce flood risk."]', 'geography', '3', 233255, 1455, NULL, 'opengloss-v1.1'),
('sites_noun_1', 'sites', 'noun', 1, 'A collection of web pages and related resources identified by a common domain, forming a digital location on the Internet.', '["web site", "online resource", "digital platform", "internet portal"]', '[]', '["digital location", "online resource", "internet domain"]', '["academic site", "government site", "ecommerce site", "news site"]', '["archaeological site", "building site", "construction site", "web site", "site selection", "site visit"]', '{"noun_forms": ["site"], "verb_forms": ["sited", "siting", "sites"], "adjective_forms": [], "adverb_forms": []}', '["The dataset was retrieved from multiple web sites.", "Scholarly results were cross validated using several academic sites."]', 'geography', '3', 233255, 1455, NULL, 'opengloss-v1.1'),
('sites_verb_1', 'sites', 'verb', 1, 'To determine or record the location of a feature within a geographic information system or map by assigning coordinates or reference to a geospatial framework.', '["georeference", "geocode", "geolocate"]', '[]', '["transitive verb", "mapping verb"]', '["georeference", "geocode", "geolocate"]', '["site plan", "building site", "historic site", "site selection", "site location", "prime site"]', '{"noun_forms": ["siting"], "verb_forms": ["resite"], "adjective_forms": ["onsite"], "adverb_forms": ["onsite"]}', '["The GIS analyst sites the feature at the specified coordinates.", "Researchers sites the watershed feature within the geodatabase after verification."]', 'geography', '3', 233255, 1455, NULL, 'opengloss-v1.1'),
('sites_noun_2', 'sites', 'noun', 2, 'An area of land or water that is the site of an archaeological investigation or excavation.', '["archaeological site", "excavation site", "dig site", "archaeology site"]', '[]', '["location", "place", "archaeology"]', '["excavation site", "field site", "prehistoric site", "ritual site"]', '["archaeological site", "building site", "construction site", "web site", "site selection", "site visit"]', '{"noun_forms": ["site"], "verb_forms": ["sited", "siting", "sites"], "adjective_forms": [], "adverb_forms": []}', '["Excavations at the site revealed stratified deposits.", "The survey mapped features across each site."]', 'geography', '3', 233255, 1455, NULL, 'opengloss-v1.1'),
('sites_noun_3', 'sites', 'noun', 3, 'A location designated for a particular activity or project.', '["place", "facility", "venue", "construction zone"]', '[]', '["location", "place", "designated space"]', '["building site", "construction site", "study site", "event site"]', '["archaeological site", "building site", "construction site", "web site", "site selection", "site visit"]', '{"noun_forms": ["site"], "verb_forms": ["sited", "siting", "sites"], "adjective_forms": [], "adverb_forms": []}', '["The building site is located adjacent to transit corridors.", "The study site provided controlled environmental conditions."]', 'geography', '3', 233255, 1455, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
