('metal_adjective_0', 'metal', 'adjective', 0, 'Adj. made of metal or relating to metal as a material.', '["metallic"]', '["nonmetallic"]', '["material adjective", "descriptive adjective"]', '["ferrous", "nonferrous"]', '["metal surface", "metal frame", "metal ruler", "metal finish", "metal alloy", "metal detector"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": ["metallic"], "adverb_forms": []}', '["The metal ruler withstood the bending test.", "Metal bolts should be tightened with a wrench."]', 'science', '2', 231232, 1469, NULL, 'opengloss-v1.1'),
('metal_noun_0', 'metal', 'noun', 0, 'A solid material that is typically hard, shiny, and a good conductor of heat and electricity.', '["metallic material", "metallic substance"]', '["nonmetal"]', '["material"]', '["iron", "copper", "aluminum"]', '["metal wire", "metal sheet", "metal detector", "recycled metal", "ferrous metal"]', '{"noun_forms": ["metallurgy", "metalwork", "metallurgist"], "verb_forms": [], "adjective_forms": ["metallic"], "adverb_forms": []}', '["Copper and iron are common metals used in classroom experiments.", "A metal can be shaped into wires and sheets."]', 'science', '2', 231232, 1469, NULL, 'opengloss-v1.1'),
