INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('web_noun_0', 'web', 'noun', 0, 'A network of interlacing filaments or threads forming a mesh, such as the silky structure produced by spiders to capture prey or to serve as a support in textiles.', '["network", "mesh", "lattice", "meshwork"]', '["solid mass", "unwoven sheet"]', '["structure", "network"]', '["spider web", "cobweb", "lattice"]', '["spider web", "cobweb", "world wide web", "web page", "web browser"]', '{"noun_forms": ["webbing"], "verb_forms": [], "adjective_forms": ["webbed"], "adverb_forms": []}', '["Spiders construct a radial web to entangle insects.", "In textile engineering a web is defined as a filamentary mesh material."]', 'technology', '2', 227055, 1481, NULL, 'opengloss-v1.1'),
('web_verb_0', 'web', 'verb', 0, 'To form or weave a spider''s web; to spin a silken structure produced by a spider to capture prey.', '["weave", "spin", "construct"]', '["unweave", "destroy"]', '["create", "build", "make"]', '["weave a web", "spin a web"]', '["World Wide Web", "web page", "web browser", "web service", "web host", "web design"]', '{"noun_forms": ["webbing"], "verb_forms": ["webbed", "webbing"], "adjective_forms": ["webbed"], "adverb_forms": []}', '["Spiders web delicate lines to capture prey.", "Construction of a spider web is a rapid, energy efficient process."]', 'technology', '2', 227055, 1481, NULL, 'opengloss-v1.1'),
('web_noun_1', 'web', 'noun', 1, 'The World Wide Web, the distributed information space of hyperlinked documents and resources accessible via the Internet.', '["world wide web", "hypertext system", "digital medium"]', '[]', '["information system", "digital medium"]', '["web page", "web site", "web portal", "web server"]', '["spider web", "cobweb", "world wide web", "web page", "web browser"]', '{"noun_forms": ["webbing"], "verb_forms": [], "adjective_forms": ["webbed"], "adverb_forms": []}', '["Researchers retrieved datasets from the world wide web to reproduce experiments.", "The web architecture enables hypertext navigation across documents."]', 'technology', '2', 227055, 1481, NULL, 'opengloss-v1.1'),
('web_verb_1', 'web', 'verb', 1, 'To publish on the World Wide Web; to place resources on the Web.', '["publish online", "post online", "upload"]', '["unpublish"]', '["publish", "disseminate"]', '["publish a page", "post a page", "upload image"]', '["World Wide Web", "web page", "web browser", "web service", "web host", "web design"]', '{"noun_forms": ["webbing"], "verb_forms": ["webbed", "webbing"], "adjective_forms": ["webbed"], "adverb_forms": []}', '["Researchers web their findings to the project site.", "Developers web the documentation to the online portal."]', 'technology', '2', 227055, 1481, NULL, 'opengloss-v1.1'),
('web_noun_2', 'web', 'noun', 2, 'A complex network of connective tissues or neural, vascular, or other structures forming a frame or conduits.', '["network", "mesh", "lattice", "meshwork"]', '["solid mass", "unwoven sheet"]', '["anatomical structure", "tissue network"]', '["nerve plexus", "vascular network", "capillary mesh"]', '["spider web", "cobweb", "world wide web", "web page", "web browser"]', '{"noun_forms": ["webbing"], "verb_forms": [], "adjective_forms": ["webbed"], "adverb_forms": []}', '["A web of capillaries distributes nutrients through the tissue.", "The cranial nerves form a web linking sensory and motor pathways."]', 'technology', '2', 227055, 1481, NULL, 'opengloss-v1.1'),
('web_noun_3', 'web', 'noun', 3, 'A metaphorical or functional network of relations, influences, or dependencies in social, organizational, or academic contexts.', '["network", "mesh", "matrix", "web of relationships"]', '["independence", "solitude"]', '["system", "complex"]', '["social network", "influence network", "information network"]', '["spider web", "cobweb", "world wide web", "web page", "web browser"]', '{"noun_forms": ["webbing"], "verb_forms": [], "adjective_forms": ["webbed"], "adverb_forms": []}', '["Policy analysis maps a web of stakeholder relationships.", "Research models a web of influences on outcome variables."]', 'technology', '2', 227055, 1481, NULL, 'opengloss-v1.1')
