('rail_noun_0', 'rail', 'noun', 0, 'A long steel or metal bar forming part of a railway or tram track, serving as the load bearing guide for wheels.', '["bar", "rod", "metal bar"]', '["gap", "opening"]', '["bar", "component", "construction material"]', '["handrail", "guard rail"]', '["rail track", "guard rail", "handrail", "rail system", "power rail"]', '{"noun_forms": ["railing", "railway"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Maintenance crews inspected the damaged rail for cracks.", "The rail alignment affects wheel wear on trains."]', 'technology', '3', 221992, 1518, NULL, 'opengloss-v1.1'),
('rail_verb_0', 'rail', 'verb', 0, 'To speak or write vehemently in criticism of someone or something; to rail against.', '["rant", "carp", "berate", "decry"]', '["praise", "applaud", "support"]', '["criticize"]', '["decry", "berate", "condemn", "denounce"]', '["rail against", "rail at", "rail network", "install rails", "by rail"]', '{"noun_forms": ["railer", "railing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Scholars rail against the simplistic interpretation of data.", "The author rails at policy failures and opacity."]', 'technology', '3', 221992, 1518, NULL, 'opengloss-v1.1'),
('rail_noun_1', 'rail', 'noun', 1, 'A bird of the family Rallidae, typically found in marshes and wetlands.', '["crake", "rallid", "rail bird"]', '[]', '["bird", "vertebrate", "animal"]', '["water rail", "sora"]', '["rail track", "guard rail", "handrail", "rail system", "power rail"]', '{"noun_forms": ["railing", "railway"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The water rail inhabits reed beds and marshes.", "Rails are often cryptic when foraging on the wetlands floor."]', 'technology', '3', 221992, 1518, NULL, 'opengloss-v1.1'),
('rail_verb_1', 'rail', 'verb', 1, 'To enclose or fence off by installing rails.', '["fence", "enclose", "bar"]', '["free", "open", "unblock"]', '["enclose"]', '["fence", "bar"]', '["rail against", "rail at", "rail network", "install rails", "by rail"]', '{"noun_forms": ["railer", "railing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The courtyard was railed off to deter unauthorized entry.", "A safety barrier railed off the construction site."]', 'technology', '3', 221992, 1518, NULL, 'opengloss-v1.1'),
('rail_noun_2', 'rail', 'noun', 2, 'An electrical conductor that provides a common potential to electrical circuits, serving as a power supply line in devices.', '["supply line", "voltage rail", "power line"]', '[]', '["conductor", "electrical conductor", "supply line"]', '["voltage rail", "supply rail"]', '["rail track", "guard rail", "handrail", "rail system", "power rail"]', '{"noun_forms": ["railing", "railway"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The circuit uses a 5 volt power rail.", "Ground and Vcc rails are common in PCB layouts."]', 'technology', '3', 221992, 1518, NULL, 'opengloss-v1.1')
