BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('listing_noun_0', 'listing', 'noun', 0, 'A single item or entry in a list, catalog, or directory.', '["entry", "item", "record", "catalog entry", "list item"]', '["omission", "deletion"]', '["record", "data entry"]', '["catalog entry", "inventory item", "roster entry"]', '["property listing", "real estate listing", "listing price", "house listing", "open listing"]', '{"noun_forms": [], "verb_forms": ["list"], "adjective_forms": [], "adverb_forms": []}', '["Each listing in the glossary shows the term and its definition.", "The catalog listing includes the term, part of speech, and example sentence."]', 'technology', '3', 220662, 1526, NULL, 'opengloss-v1.1'),
('listing_verb_0', 'listing', 'verb', 0, 'To write or say items in a sequence, naming each item one after another.', '["itemize", "enumerate", "catalog"]', '["omit", "exclude"]', '["action", "process"]', '["bullet list", "checklist", "ordered list"]', '["create a listing", "property listing", "real estate listing", "product listing", "online listing", "listing page"]', '{"noun_forms": ["listing"], "verb_forms": ["relist"], "adjective_forms": ["listable"], "adverb_forms": []}', '["The teacher listed the steps of the experiment on the board.", "Students list the key vocabulary words for review."]', 'technology', '3', 220662, 1526, NULL, 'opengloss-v1.1'),
('listing_noun_1', 'listing', 'noun', 1, 'The act of creating or enumerating items in a list.', '["enumeration", "cataloging", "recording"]', '["omission", "deletion"]', '["process", "activity", "procedure"]', '["alphabetical listing", "price listing", "inventory listing"]', '["property listing", "real estate listing", "listing price", "house listing", "open listing"]', '{"noun_forms": [], "verb_forms": ["list"], "adjective_forms": [], "adverb_forms": []}', '["Students practiced listing the steps of the procedure.", "The teacher asked for a clear listing of data values."]', 'technology', '3', 220662, 1526, NULL, 'opengloss-v1.1'),
('listing_verb_1', 'listing', 'verb', 1, 'To place entries into a directory or catalog so they can be found later.', '["catalog", "record", "log"]', '["erase", "omit"]', '["cataloging", "recording"]', '["inventory", "catalog"]', '["create a listing", "property listing", "real estate listing", "product listing", "online listing", "listing page"]', '{"noun_forms": ["listing"], "verb_forms": ["relist"], "adjective_forms": ["listable"], "adverb_forms": []}', '["The librarian is listing new titles in the library catalog.", "The teacher is listing student names for the field trip."]', 'technology', '3', 220662, 1526, NULL, 'opengloss-v1.1'),
('listing_noun_2', 'listing', 'noun', 2, 'A posted advertisement for a property offered for sale or rent.', '["advertisement", "notice", "posting"]', '["unlisted", "unadvertised"]', '["advertisement", "notice"]', '["for sale listing", "rent listing", "open house listing"]', '["property listing", "real estate listing", "listing price", "house listing", "open listing"]', '{"noun_forms": [], "verb_forms": ["list"], "adjective_forms": [], "adverb_forms": []}', '["The real estate agent posted a listing for a three bedroom home.", "Families compared open house listings to plan visits."]', 'technology', '3', 220662, 1526, NULL, 'opengloss-v1.1'),
('listing_verb_2', 'listing', 'verb', 2, 'To publish an item for sale by posting it on a listing service or marketplace.', '["advertise", "market", "post"]', '["delist", "withdraw"]', '["advertising", "marketing"]', '["online listing", "real estate listing", "product listing"]', '["create a listing", "property listing", "real estate listing", "product listing", "online listing", "listing page"]', '{"noun_forms": ["listing"], "verb_forms": ["relist"], "adjective_forms": ["listable"], "adverb_forms": []}', '["The real estate agent is listing the house for sale.", "The online store is listing several new products today."]', 'technology', '3', 220662, 1526, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
