('programming_noun_0', 'programming', 'noun', 0, 'The process of designing, writing, testing, and maintaining instructions for computers to perform tasks.', '["coding", "software development", "computer programming", "application development"]', '[]', '["computer science", "field", "discipline"]', '["procedural programming", "object oriented programming", "functional programming"]', '["computer programming", "programming language", "programming course", "visual programming", "block programming", "beginner programming"]', '{"noun_forms": ["programmer"], "verb_forms": ["program"], "adjective_forms": ["programmable", "programmatic"], "adverb_forms": []}', '["Many students learn programming by building simple games.", "In class, you will practice programming by solving puzzles."]', 'technology', 'BS', 219285, 1536, NULL, 'opengloss-v1.1'),
('programming_verb_0', 'programming', 'verb', 0, 'To create software by writing code that a computer can execute to perform tasks.', '["code", "script"]', '["unprogram", "deprogram"]', '["software development", "computer activity"]', '["coding", "scripting", "algorithm design"]', '["computer programming", "programming language", "programming assignment", "robotics programming", "block based programming", "visual programming"]', '{"noun_forms": ["programmer"], "verb_forms": ["reprogram"], "adjective_forms": ["programmable", "programmatic"], "adverb_forms": ["programmatically"]}', '["The student programs a calculator app in Python.", "The robotics club programs a robot to navigate mazes."]', 'technology', 'BS', 219285, 1536, NULL, 'opengloss-v1.1'),
