('format_noun_0', 'format', 'noun', 0, 'The arrangement or design of content and elements in a document or medium.', '["arrangement", "layout", "structure", "organization"]', '["disorder", "chaos", "mess"]', '["organization", "structure", "form"]', '["layout", "structure", "organization", "blueprint"]', '["page format", "document format", "file format", "format guidelines", "standard format"]', '{"noun_forms": ["formatting"], "verb_forms": ["reformat"], "adjective_forms": [], "adverb_forms": []}', '["The science report should follow a clear format with sections.", "A consistent format helps readers understand information quickly."]', 'technology', '1', 218366, 1546, NULL, 'opengloss-v1.1'),
('format_verb_0', 'format', 'verb', 0, 'To arrange or organize content into a specific layout or structure for readability and presentation.', '["arrange", "organize", "structure", "design"]', '["disorganize", "ruin"]', '["organization", "presentation"]', '["APA format", "MLA format", "academic paper format", "letter format"]', '["document format", "disk format", "page layout", "formatting guidelines", "APA style"]', '{"noun_forms": ["formatting"], "verb_forms": ["reformat"], "adjective_forms": [], "adverb_forms": []}', '["Students format essays to meet the teacher''s guidelines.", "Format a page with margins and a title."]', 'technology', '1', 218366, 1546, NULL, 'opengloss-v1.1'),
('format_noun_1', 'format', 'noun', 1, 'The size, dimensions, or shape of something, especially a page or screen.', '["size", "dimension", "dimensions"]', '["small format", "large format"]', '["size", "dimensions"]', '["page size", "paper size", "screen size", "dimension"]', '["page format", "document format", "file format", "format guidelines", "standard format"]', '{"noun_forms": ["formatting"], "verb_forms": ["reformat"], "adjective_forms": [], "adverb_forms": []}', '["The worksheet uses a standard page size.", "A4 format is common for school handouts."]', 'technology', '1', 218366, 1546, NULL, 'opengloss-v1.1'),
('format_verb_1', 'format', 'verb', 1, 'To prepare a storage device by erasing data and establishing a new file system.', '["initialize", "reformat", "prepare", "set up"]', '["preserve", "recover"]', '["data management", "system operation"]', '["disk format", "drive format", "hard drive format", "SSD format"]', '["document format", "disk format", "page layout", "formatting guidelines", "APA style"]', '{"noun_forms": ["formatting"], "verb_forms": ["reformat"], "adjective_forms": [], "adverb_forms": []}', '["The technician formatted the USB drive for class.", "Format the drive to create a clean file system."]', 'technology', '1', 218366, 1546, NULL, 'opengloss-v1.1'),
('format_noun_2', 'format', 'noun', 2, 'A preset template or model used as a guide for presenting information.', '["template", "blueprint", "model", "pattern"]', '["free form", "random layout"]', '["template", "model", "design"]', '["template", "blueprint", "model", "pattern"]', '["page format", "document format", "file format", "format guidelines", "standard format"]', '{"noun_forms": ["formatting"], "verb_forms": ["reformat"], "adjective_forms": [], "adverb_forms": []}', '["Use the provided format as a template for your report.", "This science poster follows a fixed format for titles and captions."]', 'technology', '1', 218366, 1546, NULL, 'opengloss-v1.1'),
('format_verb_2', 'format', 'verb', 2, 'To adapt or tailor the formatting or presentation of content to fit a specified medium or style guide.', '["adapt", "tailor", "adjust", "customize"]', '["ignore"]', '["style adjustment", "presentation design"]', '["APA style", "MLA style", "publisher format", "journal style"]', '["document format", "disk format", "page layout", "formatting guidelines", "APA style"]', '{"noun_forms": ["formatting"], "verb_forms": ["reformat"], "adjective_forms": [], "adverb_forms": []}', '["Format the report to APA style for submission.", "Format slides to match the school guidelines."]', 'technology', '1', 218366, 1546, NULL, 'opengloss-v1.1'),
('format_noun_3', 'format', 'noun', 3, 'A particular arrangement of data as recognized by a computer program; a file type.', '["file type", "data type", "file format"]', '["unformatted data", "no format"]', '["data type", "file type"]', '["PDF format", "DOCX format", "image format", "video format"]', '["page format", "document format", "file format", "format guidelines", "standard format"]', '{"noun_forms": ["formatting"], "verb_forms": ["reformat"], "adjective_forms": [], "adverb_forms": []}', '["Save your essay in PDF format to preserve layout.", "Images can be stored in multiple formats such as JPEG or PNG."]', 'technology', '1', 218366, 1546, NULL, 'opengloss-v1.1')
