-- lexi ETL: railroad (2026-09-18T16:20:12Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('railroad_adjective_0', 'railroad', 'adjective', 0, 'Of or relating to railroads and the railway system, including their construction, operation, and regulation.', '["railroad-related", "railway-related", "rail transport-related"]', '["nonrailroad", "nonrailway"]', '["infrastructure", "transportation system"]', '["railroad construction", "railroad operations", "railroad maintenance"]', '["railroad crossing", "railroad track", "railroad worker", "railroad financing", "railroad safety", "railroaded legislation"]', '{"noun_forms": ["railroading"], "verb_forms": ["railroad", "railroading"], "adjective_forms": ["railroad-like", "railroad-related"], "adverb_forms": []}', '["Railroad financing and investment influence urban transportation planning.", "Railroad safety standards govern track maintenance and signaling."]', 'technology', '2', 216712, 1560, NULL, 'opengloss-v1.1'),
('railroad_noun_0', 'railroad', 'noun', 0, 'The system of tracks, stations, and rolling stock that constitutes the physical network for land-based rail transport.', '["railway", "rail system", "rail network", "train system"]', '["highway", "road transport"]', '["infrastructure", "transportation network"]', '["heavy rail", "light rail"]', '["railroad track", "railroad car", "railroad station", "railroad network", "railroad history", "railroad industry"]', '{"noun_forms": ["railroader"], "verb_forms": ["railroad", "railroading", "railroaded"], "adjective_forms": [], "adverb_forms": []}', '["Expansion of the railroad network in the 19th century spurred industrial growth.", "Advances in scheduling and signaling improved railroad efficiency."]', 'technology', '2', 216712, 1560, NULL, 'opengloss-v1.1'),
('railroad_verb_0', 'railroad', 'verb', 0, 'To push or force a bill or decision through a legislative or administrative process by undue influence or procedural manipulation.', '["coerce", "force through", "push through", "sneak through"]', '["block", "obstruct", "stall"]', '["coercion", "pressure", "influence"]', '["railroading a bill", "speed through a bill"]', '["railroad a bill", "railroad through Congress", "railroading a bill", "railroad through the legislature", "railroad cargo", "railroad freight"]', '{"noun_forms": ["railroader"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The committee rushed the bill through without hearings.", "Opponents argued the vote was railroaded through the legislature."]', 'technology', '2', 216712, 1560, NULL, 'opengloss-v1.1'),
('railroad_adjective_1', 'railroad', 'adjective', 1, 'Of or relating to the rapid and coercive advancement of a proposal or policy through procedural channels, bypassing deliberation or due process.', '["fast-tracked", "expedited", "steamrolled"]', '["deliberate", "careful"]', '["policy process", "procedure"]', '["railroad passage", "fast-tracked approval"]', '["railroad crossing", "railroad track", "railroad worker", "railroad financing", "railroad safety", "railroaded legislation"]', '{"noun_forms": ["railroading"], "verb_forms": ["railroad", "railroading"], "adjective_forms": ["railroad-like", "railroad-related"], "adverb_forms": []}', '["The committee approved the measure in a railroad fashion, bypassing public input.", "Legislation was railroaded through the legislature with limited debate."]', 'technology', '2', 216712, 1560, NULL, 'opengloss-v1.1'),
('railroad_noun_1', 'railroad', 'noun', 1, 'The railroad industry comprising the companies, organizations, and labor involved in building, maintaining, and operating railroads as a transportation network.', '["railroad industry", "rail transport", "railway industry"]', '["nonrail transport", "air transport"]', '["industry", "transportation sector"]', '["class I railroad", "regional railroad", "shortline railroad"]', '["railroad track", "railroad car", "railroad station", "railroad network", "railroad history", "railroad industry"]', '{"noun_forms": ["railroader"], "verb_forms": ["railroad", "railroading", "railroaded"], "adjective_forms": [], "adverb_forms": []}', '["The railroad industry underwent deregulation in the late 20th century.", "Policy changes influenced the consolidation and investment patterns of the railroad industry."]', 'technology', '2', 216712, 1560, NULL, 'opengloss-v1.1'),
('railroad_verb_1', 'railroad', 'verb', 1, 'To transport goods, passengers, or freight by railroad.', '["transport by rail", "move by rail", "ship by rail", "haul by rail"]', '["move by road", "haul by road", "air transport"]', '["transport", "move", "logistics"]', '["freight by rail", "passenger by rail"]', '["railroad a bill", "railroad through Congress", "railroading a bill", "railroad through the legislature", "railroad cargo", "railroad freight"]', '{"noun_forms": ["railroader"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The company will railroad the freight to Chicago.", "The freight was railroaded along the main line."]', 'technology', '2', 216712, 1560, NULL, 'opengloss-v1.1')
