INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('iron_adjective_0', 'iron', 'adjective', 0, 'Of or relating to iron metal; composed of iron or containing iron; used to describe materials or objects made of iron or containing iron.', '["ferrous", "metallic"]', '["nonferrous", "nonmetallic"]', '["metal"]', '["cast iron", "wrought iron", "pig iron", "iron ore", "ironwork"]', '["iron-based", "iron-rich", "iron-containing", "ironclad", "iron ore", "ironwork"]', '{"noun_forms": ["ironwork", "ironstone", "iron ore", "ironiness"], "verb_forms": ["ironing"], "adjective_forms": ["ironlike", "iron-gray", "iron-based", "iron-containing", "iron-rich"], "adverb_forms": []}', '["an iron-based alloy was selected for the structural component", "the sample contained iron-containing ore material"]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_noun_0', 'iron', 'noun', 0, 'The chemical element with atomic number 26, symbol Fe, a dense, ferromagnetic metal widely used in alloys and structural applications.', '["Fe", "ferrum", "ferrous metal", "metal"]', '["nonmetal", "nonferrous metal"]', '["chemical element", "metal"]', '["cast iron", "pig iron", "wrought iron"]', '["cast iron", "iron ore", "iron deficiency", "iron supplement", "wrought iron", "ironwork"]', '{"noun_forms": ["ironware", "ironwork", "ironstone"], "verb_forms": ["ironed", "ironing"], "adjective_forms": ["iron-rich", "ironless"], "adverb_forms": []}', '["Iron forms the basis of steel alloys in modern industry.", "Iron ore deposits are mined for metallurgical use."]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_verb_0', 'iron', 'verb', 0, 'To press or smooth fabric or garments by means of a heated iron to remove wrinkles.', '["press", "smooth"]', '["crease"]', '["pressing", "fabric care"]', '["steam ironing", "dry ironing"]', '["iron clothes", "iron shirt", "steam ironing", "ironing board", "linen ironing", "cotton ironing"]', '{"noun_forms": ["ironing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The technician ironed the linen blazer to remove creases.", "Researchers standardized surface finish by ironing the textile sample."]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_adjective_1', 'iron', 'adjective', 1, 'Figurative usage meaning unyielding or strict in standards, discipline, or policy; applying to behavior or governance.', '["unyielding", "rigid", "ironclad"]', '["flexible", "lenient", "permissive"]', '["trait"]', '["ironclad logic", "iron-willed leadership"]', '["iron-based", "iron-rich", "iron-containing", "ironclad", "iron ore", "ironwork"]', '{"noun_forms": ["ironwork", "ironstone", "iron ore", "ironiness"], "verb_forms": ["ironing"], "adjective_forms": ["ironlike", "iron-gray", "iron-based", "iron-containing", "iron-rich"], "adverb_forms": []}', '["the organization enforces iron discipline across subcommittees", "the leader''s iron will sustained the research program"]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_noun_1', 'iron', 'noun', 1, 'A handheld appliance with a heated flat soleplate used to press fabrics and remove wrinkles.', '["pressing iron", "flat iron", "steam iron", "electric iron"]', '["unironed", "unpressed"]', '["household appliance", "appliance"]', '["steam iron", "electric iron", "travel iron"]', '["cast iron", "iron ore", "iron deficiency", "iron supplement", "wrought iron", "ironwork"]', '{"noun_forms": ["ironware", "ironwork", "ironstone"], "verb_forms": ["ironed", "ironing"], "adjective_forms": ["iron-rich", "ironless"], "adverb_forms": []}', '["She pressed the shirt with a hot iron.", "A steam iron smooths cotton efficiently."]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_verb_1', 'iron', 'verb', 1, 'To resolve minor inconsistencies or rough edges in a plan, document, or agreement by discussion and adjustment.', '["resolve", "finalize"]', '["prolong", "complicate"]', '["problem solving", "process improvement"]', '["settle terms", "finalize terms"]', '["iron clothes", "iron shirt", "steam ironing", "ironing board", "linen ironing", "cotton ironing"]', '{"noun_forms": ["ironing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The committee ironed out the differing terms before signing.", "Researchers ironed out methodological differences across sites."]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_adjective_2', 'iron', 'adjective', 2, 'Having a high iron content; describing foods or substances that are rich in iron.', '["iron-rich", "iron-containing"]', '["iron-poor", "low iron"]', '["nutritional property"]', '["heme iron", "nonheme iron"]', '["iron-based", "iron-rich", "iron-containing", "ironclad", "iron ore", "ironwork"]', '{"noun_forms": ["ironwork", "ironstone", "iron ore", "ironiness"], "verb_forms": ["ironing"], "adjective_forms": ["ironlike", "iron-gray", "iron-based", "iron-containing", "iron-rich"], "adverb_forms": []}', '["spinach is classified as iron-rich in dietary studies", "dietary plans emphasized iron-containing supplements"]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_noun_2', 'iron', 'noun', 2, 'A golf club made of iron used for mid to short range shots.', '["golf club", "iron club", "numbered iron", "iron type club"]', '["wood"]', '["golf equipment", "sports equipment"]', '["nine iron", "five iron", "pitching iron"]', '["cast iron", "iron ore", "iron deficiency", "iron supplement", "wrought iron", "ironwork"]', '{"noun_forms": ["ironware", "ironwork", "ironstone"], "verb_forms": ["ironed", "ironing"], "adjective_forms": ["iron-rich", "ironless"], "adverb_forms": []}', '["A nine iron is suitable for a medium approach.", "The five iron is favored for mid range shots."]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_adjective_3', 'iron', 'adjective', 3, 'Describing color resembling iron or steel gray; used to denote a metallic gray color.', '["steel-gray", "grayish metallic"]', '["colorful", "bright"]', '["color descriptor"]', '["steel-gray", "slate-gray"]', '["iron-based", "iron-rich", "iron-containing", "ironclad", "iron ore", "ironwork"]', '{"noun_forms": ["ironwork", "ironstone", "iron ore", "ironiness"], "verb_forms": ["ironing"], "adjective_forms": ["ironlike", "iron-gray", "iron-based", "iron-containing", "iron-rich"], "adverb_forms": []}', '["the specimen displayed iron-gray coloration under standard lighting", "the chart used iron-gray tones to convey a metallic texture"]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1'),
('iron_noun_3', 'iron', 'noun', 3, 'An essential trace mineral required for hemoglobin formation and oxygen transport; dietary iron.', '["dietary iron", "essential mineral", "iron nutrient", "Fe"]', '[]', '["mineral", "trace element", "nutrient"]', '["heme iron", "nonheme iron"]', '["cast iron", "iron ore", "iron deficiency", "iron supplement", "wrought iron", "ironwork"]', '{"noun_forms": ["ironware", "ironwork", "ironstone"], "verb_forms": ["ironed", "ironing"], "adjective_forms": ["iron-rich", "ironless"], "adverb_forms": []}', '["Dietary iron is necessary for healthy red blood cells.", "Iron deficiency can cause fatigue and cognitive impairment."]', 'science', '3', 215761, 1570, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
