INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('models_noun_0', 'models', 'noun', 0, 'A simplified or scaled representation of an object or system used for study, demonstration, or prediction.', '["representation", "example", "template", "specimen"]', '["reality", "the real thing"]', '["abstraction", "representation"]', '["scale model", "physical model", "conceptual model"]', '["scale model", "role model", "mathematical model", "scientific model", "fashion model", "best model"]', '{"noun_forms": ["modeler", "modeller", "modeling", "modelling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Students compare a scale model of a house to the real building.", "A weather model helps scientists predict storms."]', 'science', '4', 211144, 1609, NULL, 'opengloss-v1.1'),
('models_verb_0', 'models', 'verb', 0, 'To create a simplified representation or simulation of a real object or system for study, analysis, or teaching.', '["simulate", "represent", "build"]', '["ignore", "neglect"]', '["represent", "simulate"]', '["conceptual model", "mathematical model"]', '["scale model", "toy model", "data model", "mathematical model", "computer model", "conceptual model"]', '{"noun_forms": ["modeler"], "verb_forms": [], "adjective_forms": ["modelable"], "adverb_forms": []}', '["The scientist models climate patterns to predict outcomes.", "Students model a simple ecosystem using colored cards."]', 'science', '4', 211144, 1609, NULL, 'opengloss-v1.1'),
('models_noun_1', 'models', 'noun', 1, 'A person or thing regarded as an example to imitate or copy, especially as a standard of good behavior or achievement.', '["exemplar", "role model", "idol"]', '["bad example"]', '["example", "paradigm"]', '["hero", "idol"]', '["scale model", "role model", "mathematical model", "scientific model", "fashion model", "best model"]', '{"noun_forms": ["modeler", "modeller", "modeling", "modelling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Many students choose a role model to guide their choices.", "A good role model demonstrates responsibility and kindness."]', 'science', '4', 211144, 1609, NULL, 'opengloss-v1.1'),
('models_verb_1', 'models', 'verb', 1, 'To act as an example or standard for others to imitate or follow, especially in teaching or demonstrations.', '["emulate", "imitate", "pattern"]', '["deviate", "ignore"]', '["guide", "standard"]', '["archetype", "template", "example"]', '["scale model", "toy model", "data model", "mathematical model", "computer model", "conceptual model"]', '{"noun_forms": ["modeler"], "verb_forms": [], "adjective_forms": ["modelable"], "adverb_forms": []}', '["The teacher models proper lab safety for the class.", "The mentor models careful note taking for students to imitate."]', 'science', '4', 211144, 1609, NULL, 'opengloss-v1.1'),
('models_noun_2', 'models', 'noun', 2, 'A standard or typical example used for comparison or to set a standard for others to follow.', '["standard", "benchmark", "paradigm", "best practice"]', '["outlier", "anomaly", "exception"]', '["standard", "criterion"]', '["gold standard", "best practice", "benchmark"]', '["scale model", "role model", "mathematical model", "scientific model", "fashion model", "best model"]', '{"noun_forms": ["modeler", "modeller", "modeling", "modelling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The school uses a model of lessons as a guide for planning.", "This lesson plan is a model of best practice in science."]', 'science', '4', 211144, 1609, NULL, 'opengloss-v1.1'),
('models_noun_3', 'models', 'noun', 3, 'A person, typically a fashion model, who displays clothes or products in advertising or on a runway.', '["fashion model", "runway model", "advertising model"]', '[]', '["performer", "professional", "person"]', '["runway model", "print model", "commercial model"]', '["scale model", "role model", "mathematical model", "scientific model", "fashion model", "best model"]', '{"noun_forms": ["modeler", "modeller", "modeling", "modelling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The fashion model walked the runway for the new collection.", "Many fashion models work with photographers on shoots."]', 'science', '4', 211144, 1609, NULL, 'opengloss-v1.1')
