('gun_noun_0', 'gun', 'noun', 0, 'A firearm, a portable weapon that fires bullets.', '["firearm", "weapon", "handgun", "pistol"]', '["nonweapon"]', '["weapon", "armament"]', '["pistol", "rifle", "shotgun", "revolver", "machine gun"]', '["gun control", "gun safety", "gun range", "gun shop", "gun laws", "gun violence"]', '{"noun_forms": ["gunner", "gunpowder"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["A gun is a firearm used to shoot bullets.", "Historically muskets evolved into rifles and revolvers."]', 'technology', '2', 209884, 1620, NULL, 'opengloss-v1.1'),
('gun_verb_0', 'gun', 'verb', 0, 'To discharge a firearm or other projectile by pulling the trigger; to shoot at a target.', '["shoot", "fire", "discharge", "blast"]', '["refrain"]', '["shooting", "action"]', '["single shot", "rapid fire"]', '["gun the engine", "gun down", "gun for", "gunned for", "gun control", "gun safety"]', '{"noun_forms": ["gunner", "gunnery"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["During practice, the marksman gunned the silhouette target from fifty meters.", "The hunter gunned several shots at the target with careful aim."]', 'technology', '2', 209884, 1620, NULL, 'opengloss-v1.1'),
('gun_noun_1', 'gun', 'noun', 1, 'A small pistol used to signal the start of a race.', '["starter pistol", "starting pistol", "signal pistol"]', '[]', '["firearm", "device"]', '["starting pistol", "signal pistol"]', '["gun control", "gun safety", "gun range", "gun shop", "gun laws", "gun violence"]', '{"noun_forms": ["gunner", "gunpowder"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Officials use a starter pistol to signal the race start.", "Athletes listen for the starter pistol''s report to begin running."]', 'technology', '2', 209884, 1620, NULL, 'opengloss-v1.1'),
('gun_verb_1', 'gun', 'verb', 1, 'To accelerate a vehicle''s engine by pressing the accelerator to the floor; to cause the engine to rev and speed up.', '["accelerate", "rev", "speed up", "boost"]', '["decelerate"]', '["move", "drive"]', '["rapid acceleration", "high RPM"]', '["gun the engine", "gun down", "gun for", "gunned for", "gun control", "gun safety"]', '{"noun_forms": ["gunner", "gunnery"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The car gunned the engine to leap away from the stoplight.", "Racers gunned the engines and surged forward at the starting signal."]', 'technology', '2', 209884, 1620, NULL, 'opengloss-v1.1'),
('gun_verb_2', 'gun', 'verb', 2, 'To pursue another person or goal with persistent, aggressive effort; to press hard in a challenge.', '["pursue", "press", "go after"]', '["avoid"]', '["pursuit", "competition"]', '["intense pursuit", "aggressive campaign"]', '["gun the engine", "gun down", "gun for", "gunned for", "gun control", "gun safety"]', '{"noun_forms": ["gunner", "gunnery"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The political team gunned for the position with a bold outreach plan.", "The sales team gunned for the market share with a new campaign."]', 'technology', '2', 209884, 1620, NULL, 'opengloss-v1.1')
