-- lexi ETL: floor (2026-09-18T16:20:12Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('floor_noun_0', 'floor', 'noun', 0, 'The flat horizontal surface within a room or building on which occupants stand, place objects, or perform activities, typically finished with wood, tile, carpet, or other materials.', '["surface", "flooring"]', '["ceiling"]', '["surface"]', '["wood floor", "tile floor", "carpet floor", "marble floor"]', '["floor plan", "floor tile", "hardwood floor", "marble floor", "floor space", "floor level"]', '{"noun_forms": ["flooring", "floorboard"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The floor was swept clean before the performance.", "A marble floor reflected the chandelier''s light."]', 'technology', 'K', 209630, 1625, NULL, 'opengloss-v1.1'),
('floor_verb_0', 'floor', 'verb', 0, 'To cause someone to fall to the floor as a result of a physical strike, push, or other force; to overpower or immobilize by force.', '["flatten", "immobilize", "stun"]', '["raise", "lift", "support"]', '["physical act"]', '["takedown"]', '["floor the accelerator", "floor the gas pedal", "floor function", "hardwood floor", "wood flooring", "floor covering"]', '{"noun_forms": ["flooring"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The assailant floored the guard with a swift punch.", "The officer was floored when the suspect lunged forward, but recovered quickly."]', 'technology', 'K', 209630, 1625, NULL, 'opengloss-v1.1'),
('floor_noun_1', 'floor', 'noun', 1, 'A distinct horizontal level within a building used for occupancy or activity, including spaces such as ground floor and upper floors.', '["storey", "level", "story"]', '["basement"]', '["level"]', '["ground floor", "upper floor", "top floor", "penthouse floor"]', '["floor plan", "floor tile", "hardwood floor", "marble floor", "floor space", "floor level"]', '{"noun_forms": ["flooring", "floorboard"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The meeting took place on the third floor.", "Elevators connect all floors of the building."]', 'technology', 'K', 209630, 1625, NULL, 'opengloss-v1.1'),
('floor_verb_1', 'floor', 'verb', 1, 'To lay or install a floor surface or to cover a space with a floor material such as wood, tile, or carpet.', '["install", "lay", "cover"]', '["remove", "uncover"]', '["construction operation"]', '["tile", "carpet"]', '["floor the accelerator", "floor the gas pedal", "floor function", "hardwood floor", "wood flooring", "floor covering"]', '{"noun_forms": ["flooring"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Contractors floor the library with oak planks.", "We floor the dining hall using reclaimed wood."]', 'technology', 'K', 209630, 1625, NULL, 'opengloss-v1.1'),
('floor_noun_2', 'floor', 'noun', 2, 'The greatest integer less than or equal to a real number, a standard mathematical function that maps a real value to an integer.', '["greatest integer function"]', '["ceiling function"]', '["mathematical function"]', '["rounding down function", "truncation"]', '["floor plan", "floor tile", "hardwood floor", "marble floor", "floor space", "floor level"]', '{"noun_forms": ["flooring", "floorboard"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The floor of 3.7 is 3.", "For any real x, floor x is an integer."]', 'technology', 'K', 209630, 1625, NULL, 'opengloss-v1.1'),
('floor_verb_2', 'floor', 'verb', 2, 'To apply the floor function to a numeric value, yielding the greatest integer less than or equal to the value.', '["round down", "truncate"]', '["ceil", "round up"]', '["mathematical operation"]', '["downward rounding"]', '["floor the accelerator", "floor the gas pedal", "floor function", "hardwood floor", "wood flooring", "floor covering"]', '{"noun_forms": ["flooring"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The calculator floors 3.9 to 3.", "We floor a positive decimal to the floor value."]', 'technology', 'K', 209630, 1625, NULL, 'opengloss-v1.1'),
('floor_verb_3', 'floor', 'verb', 3, 'To press the accelerator pedal to the floor, maximizing engine power and speed.', '["gas it", "floor it", "accelerate fully"]', '["ease off", "take foot off"]', '["driving action"]', '["full throttle"]', '["floor the accelerator", "floor the gas pedal", "floor function", "hardwood floor", "wood flooring", "floor covering"]', '{"noun_forms": ["flooring"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The driver floors the accelerator to escape.", "During overtaking, floor the accelerator to gain speed."]', 'technology', 'K', 209630, 1625, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
