('image_noun_0', 'image', 'noun', 0, 'A visual representation such as a picture or photograph.', '["picture", "photograph", "drawing", "graphic"]', '["reality"]', '["visual representation"]', '["photograph", "drawing", "portrait"]', '["image file", "image processing", "image quality", "image size", "public image", "mental image"]', '{"noun_forms": ["imagery"], "verb_forms": ["image", "imagining", "imagined", "images"], "adjective_forms": ["imageable"], "adverb_forms": []}', '["The image on the chart shows the experiment results.", "Students compare the image to the original illustration."]', 'technology', 'K', 208622, 1631, NULL, 'opengloss-v1.1'),
('image_verb_0', 'image', 'verb', 0, 'To form or have a mental image of something in the mind.', '["imagine", "visualize", "picture"]', '["forget", "ignore"]', '["mental activity", "visualization"]', '["mental image", "visual scene"]', '["image file", "image processing", "image library", "image gallery", "image map"]', '{"noun_forms": ["imagery"], "verb_forms": [], "adjective_forms": ["imageable"], "adverb_forms": []}', '["She images the forest as she reads the story.", "The child images a dragon flying over the hills."]', 'technology', 'K', 208622, 1631, NULL, 'opengloss-v1.1'),
('image_noun_1', 'image', 'noun', 1, 'A mental picture or impression formed in the mind.', '["mental picture", "impression", "idea"]', '["forgetting"]', '["idea"]', '["vision", "scene"]', '["image file", "image processing", "image quality", "image size", "public image", "mental image"]', '{"noun_forms": ["imagery"], "verb_forms": ["image", "imagining", "imagined", "images"], "adjective_forms": ["imageable"], "adverb_forms": []}', '["She formed a mental image of the habitat from the written description.", "Readers create a mental image when imagining the scene."]', 'technology', 'K', 208622, 1631, NULL, 'opengloss-v1.1'),
('image_verb_1', 'image', 'verb', 1, 'To create a visual representation of something by drawing, rendering, or photographing it.', '["depict", "portray", "render"]', '["erase", "conceal"]', '["visual creation", "representation"]', '["line drawing", "photograph", "rendering"]', '["image file", "image processing", "image library", "image gallery", "image map"]', '{"noun_forms": ["imagery"], "verb_forms": [], "adjective_forms": ["imageable"], "adverb_forms": []}', '["The artist images a landscape by drawing and painting.", "The photographer images a still life to illustrate the lesson."]', 'technology', 'K', 208622, 1631, NULL, 'opengloss-v1.1'),
