BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('drive_noun_0', 'drive', 'noun', 0, 'a trip taken by car for travel or leisure, often for enjoyment or to reach a destination', '["trip", "ride", "outing", "journey"]', '["inactivity", "idleness"]', '["trip", "journey", "travel"]', '["short drive", "scenic drive"]', '["hard drive", "external drive", "internal drive", "long drive", "short drive", "family drive"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["We planned a weekend drive to the countryside.", "A sunrise drive can be a calm start to the day."]', 'technology', '2', 206358, 1647, NULL, 'opengloss-v1.1'),
('drive_verb_0', 'drive', 'verb', 0, 'To cause an object to move forward or in a chosen direction by applying force; to propel it.', '["propel", "push", "impel"]', '["halt", "stop"]', '["move"]', '["push", "shove"]', '["drive a car", "drive to school", "drive safely", "drive carefully", "drive at high speed", "drive with confidence"]', '{"noun_forms": ["driver", "driveway", "overdrive"], "verb_forms": [], "adjective_forms": ["drivable"], "adverb_forms": []}', '["In physics, engines drive wheels to propel vehicles.", "The bicycle chain drives the wheels when you pedal."]', 'technology', '2', 206358, 1647, NULL, 'opengloss-v1.1'),
('drive_noun_1', 'drive', 'noun', 1, 'a strong motivation or determination to achieve something such as a goal', '["motivation", "ambition", "determination", "initiative"]', '["laziness", "apathy", "disinterest"]', '["motivation", "incentive", "psychology concept"]', '["ambition", "determination"]', '["hard drive", "external drive", "internal drive", "long drive", "short drive", "family drive"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Her drive to learn math led to better grades.", "A strong drive to help others shapes her goals."]', 'technology', '2', 206358, 1647, NULL, 'opengloss-v1.1'),
('drive_verb_1', 'drive', 'verb', 1, 'To operate or control a vehicle or machine; to guide or pilot.', '["operate", "pilot"]', '["park", "stall"]', '["control"]', '["pilot", "steer"]', '["drive a car", "drive to school", "drive safely", "drive carefully", "drive at high speed", "drive with confidence"]', '{"noun_forms": ["driver", "driveway", "overdrive"], "verb_forms": [], "adjective_forms": ["drivable"], "adverb_forms": []}', '["She learned to drive a car in driver''s education.", "The bus instructor showed students how to drive safely."]', 'technology', '2', 206358, 1647, NULL, 'opengloss-v1.1'),
('drive_noun_2', 'drive', 'noun', 2, 'a data storage device used in computers', '["hard drive", "storage drive", "disk"]', '[]', '["computer hardware", "data storage device"]', '["solid state drive", "external drive", "internal drive"]', '["hard drive", "external drive", "internal drive", "long drive", "short drive", "family drive"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The laptop''s hard drive stores all documents.", "We upgraded the hard drive to increase space."]', 'technology', '2', 206358, 1647, NULL, 'opengloss-v1.1'),
('drive_verb_2', 'drive', 'verb', 2, 'To insert or embed by applying force, such as driving a nail into wood.', '["hammer", "pound", "embed"]', '["extract", "remove"]', '["insert"]', '["hammer", "pound"]', '["drive a car", "drive to school", "drive safely", "drive carefully", "drive at high speed", "drive with confidence"]', '{"noun_forms": ["driver", "driveway", "overdrive"], "verb_forms": [], "adjective_forms": ["drivable"], "adverb_forms": []}', '["The hammer drives a nail into the board.", "Stakes were driven into the ground to mark the boundary."]', 'technology', '2', 206358, 1647, NULL, 'opengloss-v1.1'),
('drive_verb_3', 'drive', 'verb', 3, 'To urge or motivate toward action; to cause progress or growth.', '["motivate", "inspire", "stimulate"]', '["discourage", "deter"]', '["influence"]', '["inspire", "encourage"]', '["drive a car", "drive to school", "drive safely", "drive carefully", "drive at high speed", "drive with confidence"]', '{"noun_forms": ["driver", "driveway", "overdrive"], "verb_forms": [], "adjective_forms": ["drivable"], "adverb_forms": []}', '["Curiosity drives students to explore new topics.", "Clear goals drive teams to finish projects on time."]', 'technology', '2', 206358, 1647, NULL, 'opengloss-v1.1')
