BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('windows_adjective_0', 'windows', 'adjective', 0, 'Relating to the Windows operating system or its ecosystem; used to describe software, hardware, or services designed for Microsoft Windows.', '["windows-based", "windows-compatible", "microsoft-windows", "os-specific"]', '["cross-platform"]', '["software-related"]', '["windows-native", "windows-embedded", "windows-portable"]', '["windows-based", "windows-compatible", "windowed interface", "casement windows", "double-hung windows", "fenestrated facade"]', '{"noun_forms": ["window"], "verb_forms": [], "adjective_forms": ["windowed"], "adverb_forms": []}', '["A windows-based deployment was evaluated under enterprise security policies.", "The windows-compatible driver suite improved interoperability across devices."]', 'technology', '1', 205485, 1655, NULL, 'opengloss-v1.1'),
('windows_noun_0', 'windows', 'noun', 0, 'A window is an opening in a building facade or roof that admits light and air and is typically fitted with glazing and a frame.', '["opening", "aperture", "fenestra"]', '["wall"]', '["opening"]', '["bay window", "sash window", "casement window", "sliding window"]', '["bay window", "sliding window", "energy efficient windows", "double glazed windows", "window frame"]', '{"noun_forms": ["windowpane"], "verb_forms": ["windowing", "windowed"], "adjective_forms": ["windowless"], "adverb_forms": []}', '["The facade uses large energy efficient windows.", "Proper glazing reduces heat transfer through exterior windows."]', 'technology', '1', 205485, 1655, NULL, 'opengloss-v1.1'),
('windows_verb_0', 'windows', 'verb', 0, 'To install or provide window openings by fitting windows in a building envelope, typically as part of construction or renovation.', '["install", "fit"]', '["remove", "seal"]', '["installation", "construction"]', '["casement window", "sliding window", "sash window"]', '["window frame", "window manager", "window size", "dialog window", "pop up window"]', '{"noun_forms": ["windowing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The contractor windowed the facade to accommodate casement units.", "Structural engineers windowed the exterior wall to improve daylighting."]', 'technology', '1', 205485, 1655, NULL, 'opengloss-v1.1'),
('windows_adjective_1', 'windows', 'adjective', 1, 'Relating to architectural fenestration; having multiple windows or a design emphasizing window placement.', '["fenestrated", "windowed", "sunlit"]', '["windowless"]', '["architectural feature", "building component"]', '["double-glazed windows", "casement windows", "vinyl windows"]', '["windows-based", "windows-compatible", "windowed interface", "casement windows", "double-hung windows", "fenestrated facade"]', '{"noun_forms": ["window"], "verb_forms": [], "adjective_forms": ["windowed"], "adverb_forms": []}', '["The windowed facade enabled daylight optimization without glare.", "Fenestrated elevations were evaluated for thermal performance."]', 'technology', '1', 205485, 1655, NULL, 'opengloss-v1.1'),
('windows_noun_1', 'windows', 'noun', 1, 'Windows is a family of graphical operating systems developed by Microsoft for personal computers and business devices.', '["MS Windows", "Windows OS"]', '["other OS"]', '["operating system"]', '["Windows 10", "Windows 11"]', '["bay window", "sliding window", "energy efficient windows", "double glazed windows", "window frame"]', '{"noun_forms": ["windowpane"], "verb_forms": ["windowing", "windowed"], "adjective_forms": ["windowless"], "adverb_forms": []}', '["The Windows OS provides a graphical interface.", "Organizations deploy Windows in enterprise networks."]', 'technology', '1', 205485, 1655, NULL, 'opengloss-v1.1'),
('windows_verb_1', 'windows', 'verb', 1, 'In signal processing, to apply a windowing operation by restricting a data stream to a finite segment for analysis, typically using sliding or tumbling windows.', '["frame", "segment"]', '["unwindowed data", "unframed data"]', '["data processing"]', '["sliding window", "tumbling window"]', '["window frame", "window manager", "window size", "dialog window", "pop up window"]', '{"noun_forms": ["windowing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The algorithm uses a sliding window to compute moving averages.", "Tumbling windows segment the stream into nonoverlapping frames."]', 'technology', '1', 205485, 1655, NULL, 'opengloss-v1.1'),
('windows_noun_2', 'windows', 'noun', 2, 'A time window is a contiguous time interval used for sampling aggregation or analysis in data processing and monitoring systems.', '["time interval", "time span", "temporal window"]', '["instant", "point in time"]', '["time interval"]', '["sliding window", "rolling window"]', '["bay window", "sliding window", "energy efficient windows", "double glazed windows", "window frame"]', '{"noun_forms": ["windowpane"], "verb_forms": ["windowing", "windowed"], "adjective_forms": ["windowless"], "adverb_forms": []}', '["The algorithm uses a one minute time window.", "A rolling window updates estimates with each new sample."]', 'technology', '1', 205485, 1655, NULL, 'opengloss-v1.1'),
('windows_verb_2', 'windows', 'verb', 2, 'In software engineering, to open or display a window object within a graphical user interface for presenting content and capturing input.', '["open", "launch"]', '["close", "minimize"]', '["window management"]', '["dialog window", "main window", "pop up window"]', '["window frame", "window manager", "window size", "dialog window", "pop up window"]', '{"noun_forms": ["windowing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The framework opens a new window to display settings.", "The UI toolkit manages window creation and destruction."]', 'technology', '1', 205485, 1655, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
