('box_noun_0', 'box', 'noun', 0, 'A rigid rectangular container with a lid, used to hold or transport items.', '["container", "receptacle"]', '[]', '["container", "object"]', '["cardboard box", "wooden box", "tin box"]', '["cardboard box", "storage box", "gift box", "shoe box", "theater box", "tool box"]', '{"noun_forms": ["boxer", "boxful", "boxiness"], "verb_forms": ["boxing"], "adjective_forms": ["boxy"], "adverb_forms": []}', '["Students packed science kits into a cardboard box.", "A shoe box can store small classroom items."]', 'technology', 'K', 205225, 1658, NULL, 'opengloss-v1.1'),
('box_verb_0', 'box', 'verb', 0, 'To place an object into a box or to enclose it within a container.', '["pack", "enclose", "wrap"]', '["unbox", "unpack"]', '["contain"]', '["gift-wrap", "crate-up", "carton"]', '["cardboard box", "box plot", "box score", "box office", "box cutter"]', '{"noun_forms": ["boxer", "boxiness"], "verb_forms": [], "adjective_forms": ["boxy", "boxlike"], "adverb_forms": []}', '["Students box the science materials for storage after the lab.", "The teacher asked learners to box the math manipulatives for neatness in the classroom brief."]', 'technology', 'K', 205225, 1658, NULL, 'opengloss-v1.1'),
('box_noun_1', 'box', 'noun', 1, 'A box plot is a graphical summary of a data set showing the median and quartiles.', '["box plot", "quartile plot"]', '["histogram"]', '["statistical chart"]', '["quartile plot", "five number plot"]', '["cardboard box", "storage box", "gift box", "shoe box", "theater box", "tool box"]', '{"noun_forms": ["boxer", "boxful", "boxiness"], "verb_forms": ["boxing"], "adjective_forms": ["boxy"], "adverb_forms": []}', '["A box plot displays the median and quartiles.", "Outliers may appear beyond whiskers on a box plot."]', 'technology', 'K', 205225, 1658, NULL, 'opengloss-v1.1'),
('box_verb_1', 'box', 'verb', 1, 'To confine or surround someone or something so that movement is restricted.', '["trap", "confine", "restrict"]', '["release", "liberate"]', '["restrict"]', '["box in", "box up", "box off"]', '["cardboard box", "box plot", "box score", "box office", "box cutter"]', '{"noun_forms": ["boxer", "boxiness"], "verb_forms": [], "adjective_forms": ["boxy", "boxlike"], "adverb_forms": []}', '["The security barriers boxed in the exhibit area to limit access during the exhibit.", "The suspect was boxed in by police barriers until interviews were completed."]', 'technology', 'K', 205225, 1658, NULL, 'opengloss-v1.1'),
('box_noun_2', 'box', 'noun', 2, 'A small private seating area in a theater or stadium.', '["private box"]', '[]', '["seating area"]', '["VIP box", "parlor box"]', '["cardboard box", "storage box", "gift box", "shoe box", "theater box", "tool box"]', '{"noun_forms": ["boxer", "boxful", "boxiness"], "verb_forms": ["boxing"], "adjective_forms": ["boxy"], "adverb_forms": []}', '["The actors waved from the theater box.", "Our family sat in a private box for the show."]', 'technology', 'K', 205225, 1658, NULL, 'opengloss-v1.1'),
