BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('bar_noun_0', 'bar', 'noun', 0, 'A rigid straight piece of material such as metal or wood used as a support or structural piece.', '["rod", "beam", "stick", "slat"]', '["hole", "gap", "opening"]', '["object", "material object", "piece"]', '["iron bar", "steel bar", "wood bar", "plastic bar"]', '["steel bar", "wooden bar", "candy bar", "bar graph", "bar chart", "bar magnet"]', '{"noun_forms": [], "verb_forms": ["bar", "barred", "barring", "bars"], "adjective_forms": ["barred"], "adverb_forms": []}', '["The engineer cut a steel bar to length for the experiment.", "A wooden bar spans the doorway to support the frame."]', 'technology', '3', 204799, 1664, NULL, 'opengloss-v1.1'),
('bar_verb_0', 'bar', 'verb', 0, 'To prevent someone from entering or participating in something, typically by authority or rule.', '["prohibit", "ban", "exclude"]', '["allow", "permit"]', '["restrict", "prevent"]', '["entry denial", "admission ban"]', '["bar the door", "bar the way", "bar entry", "bar access", "bar admission"]', '{"noun_forms": ["barrier"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The teacher bars students from using phones during class.", "The policy bars outsiders from entering the school building during recess."]', 'technology', '3', 204799, 1664, NULL, 'opengloss-v1.1'),
('bar_noun_1', 'bar', 'noun', 1, 'An obstacle that blocks or hinders movement or progress.', '["obstacle", "hindrance", "hurdle", "obstruction"]', '["opening", "passage"]', '["obstruction", "blockage"]', '["fence", "gate", "railing", "barrier"]', '["steel bar", "wooden bar", "candy bar", "bar graph", "bar chart", "bar magnet"]', '{"noun_forms": [], "verb_forms": ["bar", "barred", "barring", "bars"], "adjective_forms": ["barred"], "adverb_forms": []}', '["Construction tape formed a barrier around the site.", "A tall fence acted as a barrier to keep people out."]', 'technology', '3', 204799, 1664, NULL, 'opengloss-v1.1'),
('bar_verb_1', 'bar', 'verb', 1, 'To fasten or close a door, window, or passage by placing a rigid bar across it.', '["block", "secure"]', '["open", "unbar"]', '["block", "secure"]', '["door barricade", "window bar"]', '["bar the door", "bar the way", "bar entry", "bar access", "bar admission"]', '{"noun_forms": ["barrier"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["They bar the door with a metal bar.", "The gate is barred with a wooden bar."]', 'technology', '3', 204799, 1664, NULL, 'opengloss-v1.1'),
('bar_noun_2', 'bar', 'noun', 2, 'A musical bar or measure, a segment of time in music.', '["measure"]', '[]', '["musical unit", "time unit"]', '["bar line"]', '["steel bar", "wooden bar", "candy bar", "bar graph", "bar chart", "bar magnet"]', '{"noun_forms": [], "verb_forms": ["bar", "barred", "barring", "bars"], "adjective_forms": ["barred"], "adverb_forms": []}', '["The melody repeats every bar.", "In 4/4 time, each bar has four beats."]', 'technology', '3', 204799, 1664, NULL, 'opengloss-v1.1'),
('bar_verb_2', 'bar', 'verb', 2, 'To prohibit a person from practicing in a profession or from membership in a professional group; to disqualify by official action.', '["debar", "exclude", "disallow"]', '["admit", "enroll"]', '["exclude", "disallow"]', '["professional ban", "admission ban"]', '["bar the door", "bar the way", "bar entry", "bar access", "bar admission"]', '{"noun_forms": ["barrier"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The ethics board barred him from practicing law.", "The university barred her from enrollment in the program."]', 'technology', '3', 204799, 1664, NULL, 'opengloss-v1.1'),
('bar_noun_3', 'bar', 'noun', 3, 'A bar is a drinking establishment where beverages, especially alcoholic drinks, are served.', '["pub", "tavern", "inn"]', '[]', '["drinking place", "establishment", "business"]', '["sports bar", "wine bar", "neighborhood bar"]', '["steel bar", "wooden bar", "candy bar", "bar graph", "bar chart", "bar magnet"]', '{"noun_forms": [], "verb_forms": ["bar", "barred", "barring", "bars"], "adjective_forms": ["barred"], "adverb_forms": []}', '["The town features a bar that hosts community events.", "A bar is a licensed drinking establishment."]', 'technology', '3', 204799, 1664, NULL, 'opengloss-v1.1')
