('machine_noun_0', 'machine', 'noun', 0, 'A device that uses energy to perform work by moving parts or running components.', '["device", "apparatus", "instrument", "mechanism"]', '["humans", "person"]', '["device", "tool"]', '["computer", "robot", "engine"]', '["simple machine", "heavy machinery", "assembly line", "machine parts", "machine shop", "mechanical advantage"]', '{"noun_forms": ["machinery"], "verb_forms": ["mechanize"], "adjective_forms": ["mechanical"], "adverb_forms": ["mechanically"]}', '["A clock is a machine that uses gears to tell time.", "In science class, students study machines to understand how energy becomes motion."]', 'technology', '2', 203020, 1676, NULL, 'opengloss-v1.1'),
('machine_verb_0', 'machine', 'verb', 0, 'To operate or control a device or machine.', '["operate", "run", "control", "handle"]', '["stop", "disable", "deactivate"]', '["action verb", "transitive verb"]', '["calibrate", "adjust"]', '["machine parts", "machining process", "machine tools", "machine operator", "machine shop", "metal machining"]', '{"noun_forms": ["machining", "machinability", "machinery"], "verb_forms": [], "adjective_forms": ["machinable"], "adverb_forms": []}', '["The student will operate the classroom printer to print worksheets.", "During science class, she operates the lab computer for simulations."]', 'technology', '2', 203020, 1676, NULL, 'opengloss-v1.1'),
('machine_noun_1', 'machine', 'noun', 1, 'An organized system or organization that functions like a machine, performing tasks through standardized, impersonal processes.', '["system", "organization", "bureaucracy"]', '["humans", "person"]', '["structure", "organization"]', '["bureaucracy", "assembly line"]', '["simple machine", "heavy machinery", "assembly line", "machine parts", "machine shop", "mechanical advantage"]', '{"noun_forms": ["machinery"], "verb_forms": ["mechanize"], "adjective_forms": ["mechanical"], "adverb_forms": ["mechanically"]}', '["The factory operates as a machine, with every department following fixed rules.", "A school district can seem like a machine when schedules are perfectly timed."]', 'technology', '2', 203020, 1676, NULL, 'opengloss-v1.1'),
('machine_verb_1', 'machine', 'verb', 1, 'To shape or form a material by using a machine tool such as a drill, lathe, or mill.', '["shape", "form", "cut", "fabricate"]', '["handmade", "handcrafted"]', '["shape verb", "manufacture verb"]', '["drilling", "milling", "grinding"]', '["machine parts", "machining process", "machine tools", "machine operator", "machine shop", "metal machining"]', '{"noun_forms": ["machining", "machinability", "machinery"], "verb_forms": [], "adjective_forms": ["machinable"], "adverb_forms": []}', '["The craft project requires students to machine a metal bolt.", "They machine the metal block into a smooth rod."]', 'technology', '2', 203020, 1676, NULL, 'opengloss-v1.1'),
('machine_noun_2', 'machine', 'noun', 2, 'A person who works with steady, machine like efficiency.', '["workhorse", "robot", "diligent worker"]', '["slacker", "sluggard"]', '["person", "worker"]', '["technician", "laborer"]', '["simple machine", "heavy machinery", "assembly line", "machine parts", "machine shop", "mechanical advantage"]', '{"noun_forms": ["machinery"], "verb_forms": ["mechanize"], "adjective_forms": ["mechanical"], "adverb_forms": ["mechanically"]}', '["In class, she is a machine at solving problems, finishing worksheets quickly.", "He acts as a machine in the lab, recording data with precision."]', 'technology', '2', 203020, 1676, NULL, 'opengloss-v1.1')
