('internet_noun_0', 'internet', 'noun', 0, 'A global system of interconnected computer networks that enables communication and access to information.', '["global network", "digital network", "information network"]', '["offline", "no connection"]', '["computer network", "communication medium"]', '["World Wide Web", "email", "cloud service", "online forum"]', '["internet access", "internet speed", "internet safety", "internet search", "broadband internet", "secure internet connection"]', '{"noun_forms": ["internet user", "internet access", "internet connectivity", "internet literacy"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Students can research science topics on the internet for reliable sources.", "The internet enables families to use educational videos from home."]', 'technology', '2', 202372, 1681, NULL, 'opengloss-v1.1'),
('internet_noun_1', 'internet', 'noun', 1, 'The World Wide Web, a service on the internet consisting of linked documents and resources accessed through web browsers.', '["web", "world wide web", "the web"]', '["offline resources", "standalone documents"]', '["online service", "information resource"]', '["website", "webpage", "blog", "forum"]', '["internet access", "internet speed", "internet safety", "internet search", "broadband internet", "secure internet connection"]', '{"noun_forms": ["internet user", "internet access", "internet connectivity", "internet literacy"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The World Wide Web hosts websites with science tutorials.", "Students browse web pages to compare facts for a report."]', 'technology', '2', 202372, 1681, NULL, 'opengloss-v1.1'),
('internet_noun_2', 'internet', 'noun', 2, 'A digital medium for learning and communication that supports activities such as researching topics, emailing teachers, and collaborating online.', '["digital medium", "information medium"]', '["in person learning", "offline learning"]', '["digital medium", "communication medium"]', '["email", "video call", "cloud storage", "online chat"]', '["internet access", "internet speed", "internet safety", "internet search", "broadband internet", "secure internet connection"]', '{"noun_forms": ["internet user", "internet access", "internet connectivity", "internet literacy"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Educators use the internet to share assignments with students.", "The internet supports collaborative group projects through shared documents."]', 'technology', '2', 202372, 1681, NULL, 'opengloss-v1.1')
