BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('block_noun_0', 'block', 'noun', 0, 'A solid piece of material, usually rectangular or cuboid, that can be used for building, modeling, or stacking.', '["slab", "brick", "cube", "mass"]', '["hole", "gap", "void"]', '["object", "material"]', '["wood block", "ice block", "cinder block"]', '["wood block", "ice block", "cinder block", "block diagram", "block schedule", "time block"]', '{"noun_forms": ["blockage", "blocker"], "verb_forms": ["block"], "adjective_forms": ["blocky"], "adverb_forms": []}', '["The carpenter cut a block of wood.", "Children stacked wooden blocks to build a tower."]', 'technology', '1', 202157, 1684, NULL, 'opengloss-v1.1'),
('block_verb_0', 'block', 'verb', 0, 'To stop movement through a space or to prevent access.', '["obstruct", "hinder", "impede"]', '["unblock", "open", "allow"]', '["restrict"]', '["obstruction", "barrier"]', '["time block", "calendar block", "block party", "traffic block"]', '{"noun_forms": ["blockage", "blockade", "blocker"], "verb_forms": ["reblock"], "adjective_forms": ["blocked", "blocking"], "adverb_forms": []}', '["The locked gate blocks the hallway to the lab.", "Teacher policies block access to non educational sites during class."]', 'technology', '1', 202157, 1684, NULL, 'opengloss-v1.1'),
('block_noun_1', 'block', 'noun', 1, 'An obstruction or barrier that stops movement or passage.', '["barrier", "obstacle", "hindrance"]', '["opening", "passage", "clear way"]', '["obstruction"]', '["roadblock", "blockade", "traffic block"]', '["wood block", "ice block", "cinder block", "block diagram", "block schedule", "time block"]', '{"noun_forms": ["blockage", "blocker"], "verb_forms": ["block"], "adjective_forms": ["blocky"], "adverb_forms": []}', '["Police set up a roadblock on the highway.", "A temporary barrier blocked the doorway to prevent entry."]', 'technology', '1', 202157, 1684, NULL, 'opengloss-v1.1'),
('block_verb_1', 'block', 'verb', 1, 'To designate a fixed period on a schedule for a task; to reserve time on a calendar.', '["schedule", "reserve", "set aside"]', '["release", "free", "open"]', '["plan"]', '["time block"]', '["time block", "calendar block", "block party", "traffic block"]', '{"noun_forms": ["blockage", "blockade", "blocker"], "verb_forms": ["reblock"], "adjective_forms": ["blocked", "blocking"], "adverb_forms": []}', '["We block two hours after lunch for science experiments.", "Students block time on the calendar for study sessions."]', 'technology', '1', 202157, 1684, NULL, 'opengloss-v1.1'),
('block_noun_2', 'block', 'noun', 2, 'A contiguous period of time set aside for a specific activity.', '["time slot", "time period", "interval", "study block"]', '["unblocked time", "free time", "unstructured time"]', '["time interval", "time unit"]', '["class block", "math block", "reading block"]', '["wood block", "ice block", "cinder block", "block diagram", "block schedule", "time block"]', '{"noun_forms": ["blockage", "blocker"], "verb_forms": ["block"], "adjective_forms": ["blocky"], "adverb_forms": []}', '["We scheduled a math block from nine to ten.", "The teacher planned a reading block in the morning."]', 'technology', '1', 202157, 1684, NULL, 'opengloss-v1.1'),
('block_verb_2', 'block', 'verb', 2, 'To stop a ball or opponent from scoring or advancing by using the hands or body to hinder the play.', '["stop", "deflect", "thwart"]', '["advance", "permit", "allow"]', '["defend"]', '["block shot", "block pass"]', '["time block", "calendar block", "block party", "traffic block"]', '{"noun_forms": ["blockage", "blockade", "blocker"], "verb_forms": ["reblock"], "adjective_forms": ["blocked", "blocking"], "adverb_forms": []}', '["The defender blocks the shot to stop a goal.", "She blocks the pass and steals the ball."]', 'technology', '1', 202157, 1684, NULL, 'opengloss-v1.1')
