('flying_adjective_0', 'flying', 'adjective', 0, 'In the air; moving through the air; engaged in flight.', '["airborne", "winged"]', '["grounded", "earthbound"]', '["flight property", "airborne state"]', '["bird in flight", "aircraft in flight"]', '["flying buttress", "flying insect", "flying machine", "flying start", "flying fish"]', '{"noun_forms": ["flight"], "verb_forms": ["fly"], "adjective_forms": [], "adverb_forms": []}', '["A bird may be flying during migration.", "The aircraft is flying above the cloud layer."]', 'science', '1', 188038, 1798, NULL, 'opengloss-v1.1'),
('flying_noun_0', 'flying', 'noun', 0, 'The act or process of moving through air by means of wings or propulsion; the capacity for aerial motion by a living organism or mechanism.', '["flight", "air travel"]', '["landing", "grounding"]', '["movement"]', '["gliding", "soaring", "hovering"]', '["flying insect", "flying fish", "flying buttress", "flying colors", "flying squadron", "flying machine"]', '{"noun_forms": ["flight"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Birds achieve efficient flying during seasonal migrations.", "Powered flying is constrained by aerodynamic drag and lift."]', 'science', '1', 188038, 1798, NULL, 'opengloss-v1.1'),
('flying_verb_0', 'flying', 'verb', 0, 'To move through the air by means of wings.', '["soar", "glide", "flitter"]', '["land", "descend", "settle"]', '["locomotion"]', '["soar", "glide"]', '["flying insect", "flying colors", "flying saucer", "flying buttress", "flying drone"]', '{"noun_forms": ["flight", "flyer"], "verb_forms": [], "adjective_forms": ["flying"], "adverb_forms": []}', '["Flying requires lift generation via wingbeat frequency.", "In avian biomechanics, flying is modeled as a coupled interaction of wing kinematics and aerodynamic forces."]', 'science', '1', 188038, 1798, NULL, 'opengloss-v1.1'),
('flying_adjective_1', 'flying', 'adjective', 1, 'In architecture, a projecting buttress that channels lateral thrust from a vault to an exterior support.', '["buttress", "arc-boutant"]', '[]', '["architectural feature", "structural element"]', '["gothic flying buttress", "arc-boutant"]', '["flying buttress", "flying insect", "flying machine", "flying start", "flying fish"]', '{"noun_forms": ["flight"], "verb_forms": ["fly"], "adjective_forms": [], "adverb_forms": []}', '["The cathedral employs flying buttresses to counteract thrust.", "Flying buttresses distribute loads to exterior piers."]', 'science', '1', 188038, 1798, NULL, 'opengloss-v1.1'),
('flying_verb_1', 'flying', 'verb', 1, 'To operate or pilot an aircraft.', '["pilot", "operate", "steer"]', '["land", "ground", "stall"]', '["aviation"]', '["pilot"]', '["flying insect", "flying colors", "flying saucer", "flying buttress", "flying drone"]', '{"noun_forms": ["flight", "flyer"], "verb_forms": [], "adjective_forms": ["flying"], "adverb_forms": []}', '["Flying a plane requires certification and training.", "Researchers studied the safety of flying unmanned systems."]', 'science', '1', 188038, 1798, NULL, 'opengloss-v1.1'),
('flying_adjective_2', 'flying', 'adjective', 2, 'Very fast; unusually rapid; used especially to denote rapid progress or execution in ordinary or academic contexts.', '["rapid", "swift", "speedy"]', '["slow", "sluggish", "gradual"]', '["speed property", "motion property"]', '["fast pace", "rapid acceleration"]', '["flying buttress", "flying insect", "flying machine", "flying start", "flying fish"]', '{"noun_forms": ["flight"], "verb_forms": ["fly"], "adjective_forms": [], "adverb_forms": []}', '["The team opened the season with a flying start.", "Operations progressed at a flying pace after the reform."]', 'science', '1', 188038, 1798, NULL, 'opengloss-v1.1'),
('flying_verb_2', 'flying', 'verb', 2, 'To rise rapidly in price or quantity.', '["skyrocket", "surge", "spike"]', '["level off", "stabilize", "decrease"]', '["increase"]', '["skyrocket", "spike"]', '["flying insect", "flying colors", "flying saucer", "flying buttress", "flying drone"]', '{"noun_forms": ["flight", "flyer"], "verb_forms": [], "adjective_forms": ["flying"], "adverb_forms": []}', '["Prices are flying higher in the housing market.", "Stock prices are flying after the earnings report."]', 'science', '1', 188038, 1798, NULL, 'opengloss-v1.1')
