('reference_adjective_0', 'reference', 'adjective', 0, 'Relating to references or citations in scholarly writing or to sources used for citation.', '["referential", "cited", "relational"]', '["nonreferential"]', '["descriptor", "modifier"]', '["reference data", "reference material", "reference book"]', '["reference materials", "reference section", "reference book", "reference data", "reference guide", "reference point"]', '{"noun_forms": ["references"], "verb_forms": [], "adjective_forms": ["referential", "referenceable"], "adverb_forms": ["referentially"]}', '["The reference section lists dictionaries and encyclopedias for student use.", "Students consult reference materials to verify facts during research."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1'),
('reference_noun_0', 'reference', 'noun', 0, 'A source of information cited in a scholarly work to verify facts.', '["citation", "source", "reference text"]', '["no citation"]', '["information source"]', '["journal article", "web page", "textbook"]', '["reference book", "reference list", "reference page", "character reference", "academic reference"]', '{"noun_forms": ["referent"], "verb_forms": ["referencing", "referenced"], "adjective_forms": ["referential", "referable"], "adverb_forms": []}', '["The bibliography includes many references from peer reviewed journals.", "Cite all references in the Works Cited section."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1'),
('reference_verb_0', 'reference', 'verb', 0, 'To cite a source to support a statement in written work.', '["cite", "quote", "mention"]', '["ignore", "miscite"]', '["citation action"]', '["in text reference", "footnote reference", "endnote reference"]', '["reference book", "reference list", "bibliographic reference", "cross reference", "in text reference", "footnote reference"]', '{"noun_forms": ["referent"], "verb_forms": [], "adjective_forms": ["referenceable"], "adverb_forms": []}', '["The student references several studies to support the conclusion.", "The report references multiple sources to justify its claims."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1'),
('reference_adjective_1', 'reference', 'adjective', 1, 'Designated for reference use only; not available for loan.', '["reserved", "restricted"]', '["loanable", "circulating"]', '["designation"]', '["library reserve", "staff use only"]', '["reference materials", "reference section", "reference book", "reference data", "reference guide", "reference point"]', '{"noun_forms": ["references"], "verb_forms": [], "adjective_forms": ["referential", "referenceable"], "adverb_forms": ["referentially"]}', '["These reference books are kept on reserve and cannot be checked out.", "In the library, reference materials must be consulted on site."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1'),
('reference_noun_1', 'reference', 'noun', 1, 'The act of mentioning something in speaking or writing; a reference to something.', '["mention", "allusion", "note"]', '["no reference"]', '["communication act"]', '["in text reference", "footnote"]', '["reference book", "reference list", "reference page", "character reference", "academic reference"]', '{"noun_forms": ["referent"], "verb_forms": ["referencing", "referenced"], "adjective_forms": ["referential", "referable"], "adverb_forms": []}', '["The sentence contains a reference to Newtonian physics in the lesson.", "There is a reference to studies from the 1990s in this paragraph."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1'),
('reference_verb_1', 'reference', 'verb', 1, 'To mention or refer to something as a source or example during writing or discussion.', '["refer", "mention", "cite"]', '["conceal", "omit"]', '["verbal reference"]', '["parenthetical reference", "see also reference", "note reference"]', '["reference book", "reference list", "bibliographic reference", "cross reference", "in text reference", "footnote reference"]', '{"noun_forms": ["referent"], "verb_forms": [], "adjective_forms": ["referenceable"], "adverb_forms": []}', '["The teacher referenced a rule to explain the procedure.", "The author references a model example to illustrate the point."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1'),
('reference_noun_2', 'reference', 'noun', 2, 'A person who can attest to a student’s character or abilities, especially for a job or college application.', '["referee", "character witness", "employer"]', '["no reference"]', '["person"]', '["employer", "teacher", "professor"]', '["reference book", "reference list", "reference page", "character reference", "academic reference"]', '{"noun_forms": ["referent"], "verb_forms": ["referencing", "referenced"], "adjective_forms": ["referential", "referable"], "adverb_forms": []}', '["She asked her teacher to serve as a reference.", "Ask a supervisor to be your reference for college."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1'),
('reference_verb_2', 'reference', 'verb', 2, 'To cross-reference, i.e., to link to related content within a document or between documents.', '["cross reference", "link to"]', '["detach", "disconnect"]', '["document navigation"]', '["internal cross reference", "external cross reference", "index cross reference"]', '["reference book", "reference list", "bibliographic reference", "cross reference", "in text reference", "footnote reference"]', '{"noun_forms": ["referent"], "verb_forms": [], "adjective_forms": ["referenceable"], "adverb_forms": []}', '["The report cross references the appendix for details.", "The textbook cross references related topics in chapter two."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1'),
('reference_noun_3', 'reference', 'noun', 3, 'A standard or point of comparison used to judge or measure something.', '["benchmark", "standard", "yardstick"]', '["deviation"]', '["measurement"]', '["milestone", "reference standard", "frame of reference"]', '["reference book", "reference list", "reference page", "character reference", "academic reference"]', '{"noun_forms": ["referent"], "verb_forms": ["referencing", "referenced"], "adjective_forms": ["referential", "referable"], "adverb_forms": []}', '["Researchers compare results to a reference benchmark.", "The map uses a common reference for latitude."]', 'science', '4', 186054, 1817, NULL, 'opengloss-v1.1')
