-- lexi ETL: search (2026-09-18T16:20:13Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('search_noun_0', 'search', 'noun', 0, 'The act of looking for something; an attempt to locate a person, object, or information.', '["quest", "inquiry", "investigation"]', '["ignore", "disregard"]', '["activity", "process", "effort"]', '["online search", "field search", "library search"]', '["do a search", "make a search", "search results", "search engine", "search query", "search term"]', '{"noun_forms": ["searcher", "searchability"], "verb_forms": ["search", "searched", "searching"], "adjective_forms": ["searchable"], "adverb_forms": []}', '["Students conducted a search for credible sources on photosynthesis.", "The librarian supervised a search for missing textbooks."]', 'technology', '1', 184056, 1837, NULL, 'opengloss-v1.1'),
('search_verb_0', 'search', 'verb', 0, 'To try to locate something or someone by looking.', '["seek", "hunt", "scour", "investigate"]', '["overlook", "ignore", "miss"]', '["look", "seek"]', '["hunt", "scour", "probe"]', '["conduct a search", "search for information", "search the data", "web search", "library search"]', '{"noun_forms": ["searcher", "searchability"], "verb_forms": [], "adjective_forms": ["searchable", "unsearchable"], "adverb_forms": []}', '["They searched the attic for the missing keys.", "Students search the library catalog for sources."]', 'technology', '1', 184056, 1837, NULL, 'opengloss-v1.1'),
('search_noun_1', 'search', 'noun', 1, 'A systematic process used to locate data or items within a computer, database, or catalog.', '["query", "lookup", "retrieval"]', '["ignore", "hide"]', '["operation", "retrieval", "data access"]', '["keyword search", "filtered search", "advanced search"]', '["do a search", "make a search", "search results", "search engine", "search query", "search term"]', '{"noun_forms": ["searcher", "searchability"], "verb_forms": ["search", "searched", "searching"], "adjective_forms": ["searchable"], "adverb_forms": []}', '["A database search helps students locate articles on plant cells.", "Use a keyword search to locate chapters in the textbook."]', 'technology', '1', 184056, 1837, NULL, 'opengloss-v1.1'),
('search_verb_1', 'search', 'verb', 1, 'To examine a source or data carefully to locate information.', '["examine", "inspect", "peruse", "review"]', '["ignore", "overlook", "skip"]', '["investigate", "examine"]', '["scan", "peruse", "audit"]', '["conduct a search", "search for information", "search the data", "web search", "library search"]', '{"noun_forms": ["searcher", "searchability"], "verb_forms": [], "adjective_forms": ["searchable", "unsearchable"], "adverb_forms": []}', '["The student peruses the article to find key facts.", "Librarians ask learners to examine the report for errors."]', 'technology', '1', 184056, 1837, NULL, 'opengloss-v1.1'),
('search_noun_2', 'search', 'noun', 2, 'An organized group effort to locate a person or object, often outdoors.', '["search party", "expedition", "investigation team"]', '["inaction", "neglect"]', '["operation", "effort", "action"]', '["field search", "outdoor search", "door to door search"]', '["do a search", "make a search", "search results", "search engine", "search query", "search term"]', '{"noun_forms": ["searcher", "searchability"], "verb_forms": ["search", "searched", "searching"], "adjective_forms": ["searchable"], "adverb_forms": []}', '["A search party roamed the park in daylight.", "The field expedition joined volunteers for the search."]', 'technology', '1', 184056, 1837, NULL, 'opengloss-v1.1'),
('search_verb_2', 'search', 'verb', 2, 'To use a search engine to locate information on the internet.', '["browse", "query", "research"]', '["ignore", "avoid internet"]', '["obtain information", "learn"]', '["web search", "catalog search", "image search"]', '["conduct a search", "search for information", "search the data", "web search", "library search"]', '{"noun_forms": ["searcher", "searchability"], "verb_forms": [], "adjective_forms": ["searchable", "unsearchable"], "adverb_forms": []}', '["Students perform a web search to answer the question.", "The teacher trains how to search the web for reliable sources."]', 'technology', '1', 184056, 1837, NULL, 'opengloss-v1.1')
