-- lexi ETL: steel (2026-09-18T16:20:13Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('steel_adjective_0', 'steel', 'adjective', 0, 'Of or relating to steel; composed of steel or used in steel construction.', '["ferrous", "metallic"]', '["nonmetallic", "wooden"]', '["material", "substance"]', '["carbon steel", "stainless steel"]', '["steel frame", "steel beam", "steel plate", "steel alloy", "steel cable", "steel gray"]', '{"noun_forms": ["steeliness"], "verb_forms": [], "adjective_forms": ["steely"], "adverb_forms": []}', '["The steel framework provided structural integrity under load.", "Steel components were selected for their high yield strength."]', 'science', '3', 182792, 1846, NULL, 'opengloss-v1.1'),
('steel_noun_0', 'steel', 'noun', 0, 'A metal alloy primarily of iron with carbon, and often containing other elements, that is hard, strong, and widely used as a structural and functional material.', '["ferrous alloy", "metal alloy"]', '["wood", "plastic"]', '["metal", "alloy"]', '["carbon steel", "tool steel", "stainless steel"]', '["carbon steel", "stainless steel", "tool steel", "structural steel", "steel beam", "steel plate"]', '{"noun_forms": ["steelmaking", "steelworker", "steelwork", "steelworks", "steeliness"], "verb_forms": [], "adjective_forms": ["steely"], "adverb_forms": []}', '["Researchers used carbon steel for structural fasteners in tests.", "Stainless steel is widely used in medical instruments due to corrosion resistance."]', 'science', '3', 182792, 1846, NULL, 'opengloss-v1.1'),
('steel_verb_0', 'steel', 'verb', 0, 'To make oneself more mentally prepared or resistant to adversity; to brace one''s resolve to face a difficult situation.', '["brace", "harden", "prepare", "fortify", "arm"]', '["soften", "weaken", "demoralize", "deter"]', '["action", "preparation"]', '["brace", "harden", "fortify"]', '["steel oneself", "steeled nerves", "steel blade", "steel beam", "steel plate", "steel industry"]', '{"noun_forms": ["steeliness"], "verb_forms": [], "adjective_forms": ["steely"], "adverb_forms": []}', '["The researcher steeled herself for the forthcoming interview with skeptical reviewers.", "She steeled her nerves before presenting the controversial findings."]', 'science', '3', 182792, 1846, NULL, 'opengloss-v1.1'),
('steel_adjective_1', 'steel', 'adjective', 1, 'Having the qualities of steel; showing firm resolve or unyielding discipline.', '["steely", "unyielding", "ironclad"]', '["flexible", "yielding"]', '["quality", "attribute", "characteristic"]', '["iron will", "unyielding resolve", "steely nerve"]', '["steel frame", "steel beam", "steel plate", "steel alloy", "steel cable", "steel gray"]', '{"noun_forms": ["steeliness"], "verb_forms": [], "adjective_forms": ["steely"], "adverb_forms": []}', '["The negotiator maintained steely composure under pressure.", "Her steely resolve sustained the project through difficulties."]', 'science', '3', 182792, 1846, NULL, 'opengloss-v1.1'),
('steel_noun_1', 'steel', 'noun', 1, 'A category of steel designed for structural use in construction with standardized composition and mechanical properties.', '["construction steel"]', '["nonstructural metal"]', '["construction material", "metal"]', '["A36 steel", "I-beam steel"]', '["carbon steel", "stainless steel", "tool steel", "structural steel", "steel beam", "steel plate"]', '{"noun_forms": ["steelmaking", "steelworker", "steelwork", "steelworks", "steeliness"], "verb_forms": [], "adjective_forms": ["steely"], "adverb_forms": []}', '["Structural steel members are designed to satisfy load requirements.", "A36 steel is a common structural grade used in building frames."]', 'science', '3', 182792, 1846, NULL, 'opengloss-v1.1'),
('steel_verb_1', 'steel', 'verb', 1, 'To furnish or clad a material or object with steel, or to treat it with steel in order to improve durability or function; as in manufacturing or metalworking.', '["arm", "coat", "clad", "armor"]', '["uncoat", "bare", "unarm"]', '["manufacturing", "treatment"]', '["armoring", "cladding"]', '["steel oneself", "steeled nerves", "steel blade", "steel beam", "steel plate", "steel industry"]', '{"noun_forms": ["steeliness"], "verb_forms": [], "adjective_forms": ["steely"], "adverb_forms": []}', '["The blades were steeled with an additional steel edge to improve durability.", "The hull was steeled by applying steel reinforcement plates."]', 'science', '3', 182792, 1846, NULL, 'opengloss-v1.1'),
('steel_adjective_2', 'steel', 'adjective', 2, 'Of a color resembling steel; typically a gray metallic hue.', '["gray", "grayish"]', '["colorful", "bright"]', '["color", "hue"]', '["steel gray", "steel blue"]', '["steel frame", "steel beam", "steel plate", "steel alloy", "steel cable", "steel gray"]', '{"noun_forms": ["steeliness"], "verb_forms": [], "adjective_forms": ["steely"], "adverb_forms": []}', '["The specimen exhibited a steel gray finish.", "Steel blue accents provided a cut metallic contrast."]', 'science', '3', 182792, 1846, NULL, 'opengloss-v1.1'),
