INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('trains_noun_0', 'trains', 'noun', 0, 'A connected series of railroad cars drawn by a locomotive.', '["railroad train", "railway train", "locomotive train"]', '["bus", "car"]', '["vehicle", "means of transport", "mode of transport"]', '["freight train", "passenger train", "high speed train", "local train"]', '["train station", "train schedule", "train tracks", "train conductor", "passenger train", "freight train"]', '{"noun_forms": ["trainer", "training"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The freight train moved slowly through the valley.", "A passenger train connected distant towns during the field trip."]', 'technology', 'K', 182597, 1851, NULL, 'opengloss-v1.1'),
('trains_verb_0', 'trains', 'verb', 0, 'To teach someone a skill through instruction and practice so they can perform it well.', '["educate", "instruct", "coach", "teach"]', '["neglect", "ignore"]', '["teach", "education"]', '["drills", "coaching"]', '["dog training", "training data", "teacher training", "sports training", "training program", "career training"]', '{"noun_forms": ["trainer", "training"], "verb_forms": ["retrain"], "adjective_forms": ["trainable", "untrained"], "adverb_forms": []}', '["The physical education teacher trains students in proper running form.", "A coach trains new players after school to improve teamwork."]', 'technology', 'K', 182597, 1851, NULL, 'opengloss-v1.1'),
('trains_noun_1', 'trains', 'noun', 1, 'A sequence of thoughts or events that follow one another in a logical order.', '["sequence", "line", "progression"]', '["randomness", "disorder", "chaos"]', '["order", "structure"]', '["train of thought", "line of succession", "chain of events"]', '["train station", "train schedule", "train tracks", "train conductor", "passenger train", "freight train"]', '{"noun_forms": ["trainer", "training"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["A scientist traced a train of thought to a conclusion.", "Historians study a train of events to explain policy changes."]', 'technology', 'K', 182597, 1851, NULL, 'opengloss-v1.1'),
('trains_verb_1', 'trains', 'verb', 1, 'To train an animal, especially a dog, to perform commands or tasks.', '["dog training", "conditioning", "drilling"]', '["untrained", "inexperienced"]', '["training"]', '["dog obedience", "trick training", "agility training"]', '["dog training", "training data", "teacher training", "sports training", "training program", "career training"]', '{"noun_forms": ["trainer", "training"], "verb_forms": ["retrain"], "adjective_forms": ["trainable", "untrained"], "adverb_forms": []}', '["The trainer trains a dog to fetch on cue.", "Owners practice patience as the dog learns to sit."]', 'technology', 'K', 182597, 1851, NULL, 'opengloss-v1.1'),
('trains_noun_2', 'trains', 'noun', 2, 'The long trailing part of a dress or gown that forms a decorative extension at the back.', '["dress train", "gown train", "dress tail"]', '["short hem", "short front", "short hemline"]', '["garment feature", "dress detail"]', '["court train", "chapel train"]', '["train station", "train schedule", "train tracks", "train conductor", "passenger train", "freight train"]', '{"noun_forms": ["trainer", "training"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The wedding gown had a long dress train.", "Her dress train swept the floor as she walked."]', 'technology', 'K', 182597, 1851, NULL, 'opengloss-v1.1'),
('trains_verb_2', 'trains', 'verb', 2, 'To train a computer program or model by using data so it can perform a task.', '["program", "learn", "fit"]', '["untrain", "forget"]', '["machine learning", "data science"]', '["supervised training", "unsupervised training", "reinforcement training"]', '["dog training", "training data", "teacher training", "sports training", "training program", "career training"]', '{"noun_forms": ["trainer", "training"], "verb_forms": ["retrain"], "adjective_forms": ["trainable", "untrained"], "adverb_forms": []}', '["Scientists train a computer model with labeled data.", "Students learn how to train a robot to follow lines."]', 'technology', 'K', 182597, 1851, NULL, 'opengloss-v1.1'),
('trains_noun_3', 'trains', 'noun', 3, 'A line or sequence of travelers or animals moving together as a group, often for travel or ceremonial purposes.', '["caravan", "procession"]', '["solo travelers", "single riders"]', '["procession", "convoy"]', '["caravan", "pack train"]', '["train station", "train schedule", "train tracks", "train conductor", "passenger train", "freight train"]', '{"noun_forms": ["trainer", "training"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The desert caravan moved slowly with many camels.", "A pack train of mules followed the guide through the valley."]', 'technology', 'K', 182597, 1851, NULL, 'opengloss-v1.1')
