('versions_noun_0', 'versions', 'noun', 0, 'A particular form or variant of something, differing from others in content, design, or edition; a version of a document, product, or process.', '["edition", "variant", "form", "rendition"]', '["original"]', '["form"]', '["software version", "document version", "translated version", "beta version"]', '["new version", "latest version", "software version", "version history", "version control", "version number"]', '{"noun_forms": ["versioning"], "verb_forms": ["version", "versioned", "versioning"], "adjective_forms": ["versionable"], "adverb_forms": []}', '["The latest version of the dataset was released after peer review.", "Researchers compared the two versions of the protocol to assess reproducibility."]', 'technology', '3', 179564, 1883, NULL, 'opengloss-v1.1'),
('versions_verb_0', 'versions', 'verb', 0, 'To create a new edition or revision of an item such as a document, software, or dataset, typically updating content, features, or metadata.', '["revise", "update", "reissue"]', '["preserve", "maintain", "keep"]', '["edit", "modify"]', '["major version", "minor version", "release version"]', '["version control", "version number", "new version", "latest version", "version history", "software versioning"]', '{"noun_forms": ["versioning"], "verb_forms": [], "adjective_forms": ["versioned"], "adverb_forms": []}', '["The researchers version the dataset to reflect updated measurements.", "Software teams version the codebase after major milestones."]', 'technology', '3', 179564, 1883, NULL, 'opengloss-v1.1'),
('versions_noun_1', 'versions', 'noun', 1, 'In software and data management, a version is a specific revision identified by a version number, used to track changes and compatibility.', '["release", "build", "revision"]', '["original"]', '["revision"]', '["software version", "API version", "library version", "file version"]', '["new version", "latest version", "software version", "version history", "version control", "version number"]', '{"noun_forms": ["versioning"], "verb_forms": ["version", "versioned", "versioning"], "adjective_forms": ["versionable"], "adverb_forms": []}', '["The project uses semantic versioning to indicate compatibility changes.", "Version numbering allows automated dependency resolution in the build system."]', 'technology', '3', 179564, 1883, NULL, 'opengloss-v1.1'),
('versions_verb_1', 'versions', 'verb', 1, 'To apply a version label or number to an item, typically within a version control system, in order to distinguish revisions.', '["tag", "label", "mark"]', '["unversioned", "unlabeled", "unmarked"]', '["labeling", "tagging"]', '["version tag", "version label", "build label", "release tag"]', '["version control", "version number", "new version", "latest version", "version history", "software versioning"]', '{"noun_forms": ["versioning"], "verb_forms": [], "adjective_forms": ["versioned"], "adverb_forms": []}', '["The team assigned a version tag to mark the release.", "Each patch is versioned with a new version label."]', 'technology', '3', 179564, 1883, NULL, 'opengloss-v1.1'),
('versions_noun_2', 'versions', 'noun', 2, 'A retelling or interpretation of a text or events as presented by a particular author or source; an edition or wording of a narrative.', '["rendering", "edition", "interpretation", "retelling"]', '["original"]', '["textual form", "narrative form"]', '["paraphrased version", "abridged version", "annotated version", "unabridged version"]', '["new version", "latest version", "software version", "version history", "version control", "version number"]', '{"noun_forms": ["versioning"], "verb_forms": ["version", "versioned", "versioning"], "adjective_forms": ["versionable"], "adverb_forms": []}', '["The historian offered a more sympathetic version of events.", "The novel exists in several versions, each with different endings."]', 'technology', '3', 179564, 1883, NULL, 'opengloss-v1.1')
