BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('finish_noun_0', 'finish', 'noun', 0, 'A surface coating or treatment applied to a material to improve appearance and durability.', '["coating", "coat", "layer", "topcoat"]', '["uncoated", "unpainted"]', '["surface coating", "coating", "surface treatment"]', '["gloss finish", "matte finish", "satin finish", "oil finish", "urethane finish"]', '["wood finish", "paint finish", "matte finish", "gloss finish", "satin finish"]', '{"noun_forms": ["finisher", "finishing"], "verb_forms": ["finish"], "adjective_forms": ["finished", "unfinished"], "adverb_forms": []}', '["The wood cabinet has a matte finish that reduces glare.", "A gloss finish highlights the grain of the wood."]', 'technology', '2', 179294, 1884, NULL, 'opengloss-v1.1'),
('finish_verb_0', 'finish', 'verb', 0, 'To bring a task or activity to completion by finishing all required parts.', '["complete", "conclude", "finalize", "wrap up"]', '["begin", "start"]', '["accomplish task", "end process"]', '["finish homework", "finish project", "finish assignment"]', '["finish homework", "finish the assignment", "finish the project", "finish in time", "finish line", "finish up quickly"]', '{"noun_forms": ["finish", "finisher", "finishing"], "verb_forms": ["finishes", "finished", "finishing"], "adjective_forms": ["finished"], "adverb_forms": []}', '["Students should finish their math worksheet before lunch.", "We will finish the science project by Friday."]', 'technology', '2', 179294, 1884, NULL, 'opengloss-v1.1'),
('finish_noun_1', 'finish', 'noun', 1, 'The act of finishing or bringing something to completion; the end stage of a process.', '["completion", "conclusion", "end"]', '["start", "beginning"]', '["end", "outcome", "process result"]', '["race finish", "task completion", "project completion"]', '["wood finish", "paint finish", "matte finish", "gloss finish", "satin finish"]', '{"noun_forms": ["finisher", "finishing"], "verb_forms": ["finish"], "adjective_forms": ["finished", "unfinished"], "adverb_forms": []}', '["The finish of the science project required careful revisions.", "The finish of the math assignment came after extra practice."]', 'technology', '2', 179294, 1884, NULL, 'opengloss-v1.1'),
('finish_verb_1', 'finish', 'verb', 1, 'To come to an end or to stop; to be completed in duration or sequence.', '["end", "cease", "conclude"]', '["begin", "start"]', '["end"]', '["end the meeting", "conclude session"]', '["finish homework", "finish the assignment", "finish the project", "finish in time", "finish line", "finish up quickly"]', '{"noun_forms": ["finish", "finisher", "finishing"], "verb_forms": ["finishes", "finished", "finishing"], "adjective_forms": ["finished"], "adverb_forms": []}', '["The class finishes at 3:15.", "The movie finishes after ninety minutes."]', 'technology', '2', 179294, 1884, NULL, 'opengloss-v1.1'),
('finish_verb_2', 'finish', 'verb', 2, 'To apply a surface finish such as a coat or varnish to wood or metal.', '["coat", "varnish", "polish"]', '["strip", "remove"]', '["surface treatment", "coating"]', '["varnish table", "paint surface", "oil finish"]', '["finish homework", "finish the assignment", "finish the project", "finish in time", "finish line", "finish up quickly"]', '{"noun_forms": ["finish", "finisher", "finishing"], "verb_forms": ["finishes", "finished", "finishing"], "adjective_forms": ["finished"], "adverb_forms": []}', '["The carpenter finishes the table with polyurethane.", "The wood is finished with a clear varnish."]', 'technology', '2', 179294, 1884, NULL, 'opengloss-v1.1')
