INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('pilot_adjective_0', 'pilot', 'adjective', 0, 'Experimental or trial use designed to assess feasibility before full implementation.', '["experimental", "trial", "preliminary", "test"]', '["established", "final", "definitive"]', '["descriptive term", "modifier"]', '["pilot program", "pilot study"]', '["pilot program", "pilot study", "pilot episode", "pilot license", "pilot training"]', '{"noun_forms": ["pilotage", "piloting"], "verb_forms": ["pilot", "piloting"], "adjective_forms": ["pilotless"], "adverb_forms": []}', '["The school launched a pilot program to test a new math module.", "Researchers ran a pilot study with a small group of students."]', 'technology', '2', 175695, 1921, NULL, 'opengloss-v1.1'),
('pilot_noun_0', 'pilot', 'noun', 0, 'A person who operates and flies an aircraft such as a plane or helicopter.', '["aviator", "airman"]', '[]', '["person", "occupation"]', '["fighter pilot", "commercial pilot", "airline pilot", "helicopter pilot"]', '["pilot program", "pilot study", "pilot episode", "airline pilot", "pilot light", "pilot fish"]', '{"noun_forms": ["pilotage", "piloting"], "verb_forms": [], "adjective_forms": ["pilotless"], "adverb_forms": []}', '["The pilot studied the weather report before takeoff.", "A pilot must follow air traffic control instructions."]', 'technology', '2', 175695, 1921, NULL, 'opengloss-v1.1'),
('pilot_verb_0', 'pilot', 'verb', 0, 'To guide the movement of a vehicle by controlling its direction, especially an aircraft or ship.', '["steer", "navigate", "direct"]', '["misnavigate", "misdirect"]', '["vehicle operation"]', '["plane piloting", "boat piloting", "car piloting", "helicopter piloting"]', '["pilot a program", "pilot a study", "pilot test", "pilot project", "pilot a plane", "pilot lesson"]', '{"noun_forms": ["pilotage"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The captain will pilot the plane through the storm.", "Students learned to pilot a drone in a supervised session."]', 'technology', '2', 175695, 1921, NULL, 'opengloss-v1.1'),
('pilot_adjective_1', 'pilot', 'adjective', 1, 'Relating to piloting or operating a vehicle; able to be steered or controlled by a pilot.', '["steerable", "controllable", "maneuverable"]', '["unmanned", "autonomous", "automatic"]', '["descriptive term", "modifier"]', '["pilot controls", "cockpit instruments"]', '["pilot program", "pilot study", "pilot episode", "pilot license", "pilot training"]', '{"noun_forms": ["pilotage", "piloting"], "verb_forms": ["pilot", "piloting"], "adjective_forms": ["pilotless"], "adverb_forms": []}', '["Pilot controls are checked before every training flight.", "Flight simulators teach how cockpit instruments support safe piloting."]', 'technology', '2', 175695, 1921, NULL, 'opengloss-v1.1'),
('pilot_noun_1', 'pilot', 'noun', 1, 'An initial version of a project or program used to test feasibility and gather data.', '["trial version", "test run"]', '["full version", "complete release"]', '["prototype"]', '["pilot study", "pilot program", "pilot episode"]', '["pilot program", "pilot study", "pilot episode", "airline pilot", "pilot light", "pilot fish"]', '{"noun_forms": ["pilotage", "piloting"], "verb_forms": [], "adjective_forms": ["pilotless"], "adverb_forms": []}', '["The teacher started a pilot program to gather feedback.", "The team conducted a pilot study to assess feasibility."]', 'technology', '2', 175695, 1921, NULL, 'opengloss-v1.1'),
('pilot_verb_1', 'pilot', 'verb', 1, 'To conduct a small-scale test of a new idea or program before wider use.', '["test", "tryout", "experiment"]', '["full rollout", "wide deployment"]', '["testing"]', '["field test", "beta test", "pilot study"]', '["pilot a program", "pilot a study", "pilot test", "pilot project", "pilot a plane", "pilot lesson"]', '{"noun_forms": ["pilotage"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["We will pilot the new math app this week.", "Families will pilot the science kit in a small study."]', 'technology', '2', 175695, 1921, NULL, 'opengloss-v1.1'),
('pilot_noun_2', 'pilot', 'noun', 2, 'A small flame kept near a gas burner to ignite it.', '["flame", "ignition flame"]', '[]', '["flame", "ignition"]', '["pilot lamp", "pilot burner"]', '["pilot program", "pilot study", "pilot episode", "airline pilot", "pilot light", "pilot fish"]', '{"noun_forms": ["pilotage", "piloting"], "verb_forms": [], "adjective_forms": ["pilotless"], "adverb_forms": []}', '["Older stoves rely on a pilot light that stays lit.", "If the pilot flame goes out, gas will shut off."]', 'technology', '2', 175695, 1921, NULL, 'opengloss-v1.1'),
('pilot_noun_3', 'pilot', 'noun', 3, 'An expert navigator who guides ships through dangerous waters into port.', '["maritime pilot", "harbor pilot"]', '[]', '["navigator", "occupation"]', '["harbor pilot", "river pilot"]', '["pilot program", "pilot study", "pilot episode", "airline pilot", "pilot light", "pilot fish"]', '{"noun_forms": ["pilotage", "piloting"], "verb_forms": [], "adjective_forms": ["pilotless"], "adverb_forms": []}', '["A harbor pilot boarded the vessel for docking.", "River pilots guide ships through narrow channels."]', 'technology', '2', 175695, 1921, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
