('architect_noun_0', 'architect', 'noun', 0, 'An individual who designs and oversees the construction of buildings and related structures.', '["designer", "planner", "building designer"]', '["builder", "layperson"]', '["profession", "design professional"]', '["residential architect", "commercial architect", "historic preservation architect"]', '["architecture firm", "architectural drawing", "architectural plan", "residential architect", "building project", "city planning"]', '{"noun_forms": ["architecture"], "verb_forms": ["architect", "architected", "architecting", "architects"], "adjective_forms": ["architectural"], "adverb_forms": []}', '["The architect drafted a schematic design for the cultural center.", "The architect supervised construction phases and coordinated consultants."]', 'technology', '3', 175596, 1923, NULL, 'opengloss-v1.1'),
('architect_verb_0', 'architect', 'verb', 0, 'To plan, design, and oversee the construction or organization of a complex system or artifact.', '["design", "plan", "engineer"]', '["disassemble", "undo design", "disorganize"]', '["verb", "transitive verb"]', '["system architecture", "data pipeline", "software framework", "experimental protocol"]', '["data architecture", "software architecture", "cloud architecture", "architectural design", "governance architecture", "system design"]', '{"noun_forms": ["architecture"], "verb_forms": ["rearchitect"], "adjective_forms": ["architectural"], "adverb_forms": []}', '["The team architected a scalable data architecture.", "Researchers architect experimental protocols to minimize confounds."]', 'technology', '3', 175596, 1923, NULL, 'opengloss-v1.1'),
