('nuclear_adjective_0', 'nuclear', 'adjective', 0, 'In physics and chemistry, relating to the nucleus of an atom; used to describe processes such as fission, fusion, and radioactive decay.', '["atomic", "nucleonic", "subnuclear"]', '["molecular", "nonnuclear"]', '["physical property", "atomic science term"]', '["fission", "fusion", "radioactive decay"]', '["nuclear energy", "nuclear power", "nuclear weapons", "nuclear reactor", "nuclear family", "nuclear physics"]', '{"noun_forms": ["nuclearization"], "verb_forms": ["nuclearize"], "adjective_forms": ["nuclearized"], "adverb_forms": ["nuclearly"]}', '["Nuclear fission releases energy when heavy nuclei split.", "Nuclear models describe interactions within the atomic nucleus."]', 'science', '6', 174763, 1927, NULL, 'opengloss-v1.1'),
('nuclear_adjective_1', 'nuclear', 'adjective', 1, 'Relating to the nucleus of a cell; pertaining to cellular nucleus and its components.', '["intranuclear", "intracellular", "cellular"]', '["cytoplasmic", "extranuclear"]', '["cell biology term", "cellular structure"]', '["nuclear envelope", "chromatin", "nucleolus", "nuclear pore"]', '["nuclear energy", "nuclear power", "nuclear weapons", "nuclear reactor", "nuclear family", "nuclear physics"]', '{"noun_forms": ["nuclearization"], "verb_forms": ["nuclearize"], "adjective_forms": ["nuclearized"], "adverb_forms": ["nuclearly"]}', '["The nuclear envelope encloses the nucleus.", "Nuclear pores regulate traffic between nucleus and cytoplasm."]', 'science', '6', 174763, 1927, NULL, 'opengloss-v1.1'),
