('programme_noun_0', 'programme', 'noun', 0, 'A planned series of activities or events intended to achieve an objective; a structured outline of tasks and milestones.', '["plan", "schedule", "agenda", "course of study"]', '["unplanned", "disorganization", "spontaneity"]', '["plan", "scheme"]', '["research programme", "training programme", "project programme"]', '["academic programme", "degree programme", "research programme", "course programme", "programme committee", "conference programme"]', '{"noun_forms": ["programming", "programmability"], "verb_forms": [], "adjective_forms": ["programmable"], "adverb_forms": []}', '["The research team outlined a five year programme of fieldwork.", "The university approved a new teaching programme with milestones."]', 'technology', '2', 171645, 1958, NULL, 'opengloss-v1.1'),
('programme_verb_0', 'programme', 'verb', 0, 'To programme is to create and implement a computer program by writing code, configuring instructions, and integrating components so that a computer can execute a task.', '["code", "write software", "develop software", "build a program", "implement software"]', '[]', '["coding activity", "software development"]', '["computer program", "embedded script", "software module"]', '["course programme", "computer program", "software program", "program design", "programming language", "programmable device"]', '{"noun_forms": ["programmer", "programming", "programmability"], "verb_forms": [], "adjective_forms": ["programmable", "programmatic"], "adverb_forms": []}', '["The team programmed a data analysis pipeline.", "Researchers programmed a simulation to validate hypotheses."]', 'technology', '2', 171645, 1958, NULL, 'opengloss-v1.1'),
('programme_noun_1', 'programme', 'noun', 1, 'A published official list of events, talks, or performances for a conference, show, or broadcast.', '["agenda", "itinerary", "schedule"]', '["disarray", "uncertainty"]', '["schedule", "list"]', '["conference programme", "festival programme"]', '["academic programme", "degree programme", "research programme", "course programme", "programme committee", "conference programme"]', '{"noun_forms": ["programming", "programmability"], "verb_forms": [], "adjective_forms": ["programmable"], "adverb_forms": []}', '["The conference programme lists keynote talks and panel discussions.", "Students consult the programme to plan attendance."]', 'technology', '2', 171645, 1958, NULL, 'opengloss-v1.1'),
('programme_noun_2', 'programme', 'noun', 2, 'A software program; a complete set of instructions that a computer can execute.', '["software", "application", "app"]', '["hardware", "manual"]', '["software"]', '["word processor", "spreadsheet", "compiler", "graphics editor"]', '["academic programme", "degree programme", "research programme", "course programme", "programme committee", "conference programme"]', '{"noun_forms": ["programming", "programmability"], "verb_forms": [], "adjective_forms": ["programmable"], "adverb_forms": []}', '["The statistical programme handles large datasets efficiently.", "A reliable data analysis programme is essential for the lab."]', 'technology', '2', 171645, 1958, NULL, 'opengloss-v1.1'),
('programme_noun_3', 'programme', 'noun', 3, 'An organized set of courses offered by an institution to achieve a degree or qualification.', '["curriculum", "course of study", "degree programme"]', '["unstructured study"]', '["curriculum", "program"]', '["engineering programme", "biology programme", "medicine programme"]', '["academic programme", "degree programme", "research programme", "course programme", "programme committee", "conference programme"]', '{"noun_forms": ["programming", "programmability"], "verb_forms": [], "adjective_forms": ["programmable"], "adverb_forms": []}', '["Her degree programme includes modules in mathematics and statistics.", "The university redesigned its engineering programme to integrate software."]', 'technology', '2', 171645, 1958, NULL, 'opengloss-v1.1')
