('connected_adjective_0', 'connected', 'adjective', 0, 'Joined or linked together physically, logically, or conceptually so as to form a whole or a system', '["linked", "joined", "interrelated"]', '["separate", "disconnected"]', '["related", "associated"]', '["interconnected", "interlinked"]', '["closely connected", "connected to the internet", "socially connected", "connected with"]', '{"noun_forms": ["connection", "connectedness", "connectivity"], "verb_forms": ["connect", "reconnect", "interconnect"], "adjective_forms": ["disconnected", "interconnected", "unconnected"], "adverb_forms": ["connectedly"]}', '["The two buildings are connected by an underground tunnel.", "The chapters in this book are closely connected, each building on the previous one."]', 'technology', '3', 169310, 1988, NULL, 'opengloss-v1.1'),
('connected_verb_0', 'connected', 'verb', 0, 'Simple past and past participle of connect: to join or link things together physically, logically, or conceptually', '["linked", "joined", "united"]', '["separated", "disconnected"]', '["attached", "associated"]', '["wire-linked", "networked"]', '["connected devices", "connected systems", "connected via", "connected through"]', '{"noun_forms": ["connection", "connector", "connectedness", "connectivity"], "verb_forms": ["reconnect", "interconnect", "disconnect"], "adjective_forms": ["connected", "connecting", "connective"], "adverb_forms": ["connectively"]}', '["The engineer connected the sensors to the central control unit.", "In his lecture, he connected historical events to contemporary issues."]', 'technology', '3', 169310, 1988, NULL, 'opengloss-v1.1'),
('connected_adjective_1', 'connected', 'adjective', 1, 'Having established communication, especially by electronic or digital networks', '["online", "networked", "wired"]', '["offline", "unplugged"]', '["linked", "networked"]', '["internet-connected", "cloud-connected"]', '["closely connected", "connected to the internet", "socially connected", "connected with"]', '{"noun_forms": ["connection", "connectedness", "connectivity"], "verb_forms": ["connect", "reconnect", "interconnect"], "adjective_forms": ["disconnected", "interconnected", "unconnected"], "adverb_forms": ["connectedly"]}', '["Once the device is connected to the internet, the software will update automatically.", "Students remained connected through video conferencing during the campus closure."]', 'technology', '3', 169310, 1988, NULL, 'opengloss-v1.1'),
('connected_verb_1', 'connected', 'verb', 1, 'Simple past and past participle of connect: to establish communication between systems, devices, or people', '["linked", "networked", "hooked up"]', '["isolated", "cut off"]', '["linked", "associated"]', '["paired", "synchronized"]', '["connected devices", "connected systems", "connected via", "connected through"]', '{"noun_forms": ["connection", "connector", "connectedness", "connectivity"], "verb_forms": ["reconnect", "interconnect", "disconnect"], "adjective_forms": ["connected", "connecting", "connective"], "adverb_forms": ["connectively"]}', '["The technician connected the computers to the new server.", "The program successfully connected remote participants in real time."]', 'technology', '3', 169310, 1988, NULL, 'opengloss-v1.1'),
('connected_adjective_2', 'connected', 'adjective', 2, 'Associated or involved with particular people, groups, or institutions, often implying influence or affiliation', '["affiliated", "associated", "related"]', '["unaffiliated", "independent"]', '["associated", "aligned"]', '["politically connected", "socially connected"]', '["closely connected", "connected to the internet", "socially connected", "connected with"]', '{"noun_forms": ["connection", "connectedness", "connectivity"], "verb_forms": ["connect", "reconnect", "interconnect"], "adjective_forms": ["disconnected", "interconnected", "unconnected"], "adverb_forms": ["connectedly"]}', '["The researcher is connected with several international climate initiatives.", "The organization is closely connected to the local university."]', 'technology', '3', 169310, 1988, NULL, 'opengloss-v1.1')
