BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('phase_noun_0', 'phase', 'noun', 0, 'A phase is a defined stage in a process or cycle that occurs in sequence.', '["stage", "period", "step", "section"]', '["whole process", "entire process"]', '["segment", "portion"]', '["growth phase", "final phase"]', '["phase change", "phase diagram", "phase shift", "phase of matter", "growth phase", "final phase"]', '{"noun_forms": ["phasing", "phaseout"], "verb_forms": ["phases", "phased", "phasing"], "adjective_forms": [], "adverb_forms": []}', '["In science journaling, learners describe the growth phase of a plant.", "The timeline shows each phase from research to presentation."]', 'science', '3', 168379, 2000, NULL, 'opengloss-v1.1'),
('phase_verb_0', 'phase', 'verb', 0, 'to introduce or implement something gradually in stages', '["introduce", "implement"]', '["remove", "eliminate"]', '["change", "implementation"]', '["gradual rollout", "pilot rollout"]', '["phase in", "phase out", "phasing in", "phased in", "gradual phase-in", "phase-out policy"]', '{"noun_forms": ["phasing", "phase-out"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The district will phase in the new standards by fall.", "Teachers will phase in the curriculum gradually over several weeks."]', 'science', '3', 168379, 2000, NULL, 'opengloss-v1.1'),
