('count_noun_0', 'count', 'noun', 0, 'A measured tally of discrete items or events recorded during an experiment or engineering process.', '["tally", "total", "number", "quantity"]', '[]', '["measurement", "metric", "quantity"]', '["particle count", "event count", "error count"]', '["total count", "particle count", "error count", "sample count", "cycle count", "packet count"]', '{"noun_forms": ["countability", "counter"], "verb_forms": ["count", "counted", "counting"], "adjective_forms": ["countable"], "adverb_forms": []}', '["Record the particle count after each test run.", "The sensor logged the event count per minute."]', 'science', '1', 165849, 2025, NULL, 'opengloss-v1.1'),
('count_verb_0', 'count', 'verb', 0, 'Determine the number of discrete items or components in a set or assembly.', '["tally", "enumerate", "tabulate"]', '[]', '["measure", "determine"]', '["count components", "count parts", "skip count"]', '["count items", "count occurrences", "count cycles", "count errors", "count frequency", "count components"]', '{"noun_forms": ["count", "counter"], "verb_forms": ["recount", "miscount"], "adjective_forms": ["countable"], "adverb_forms": []}', '["Students counted the screws to match the parts list for the robot.", "Engineers counted test samples before starting the lab run."]', 'science', '1', 165849, 2025, NULL, 'opengloss-v1.1'),
('count_noun_1', 'count', 'noun', 1, 'A recorded reading used as a parameter or input value in calculations, controls, or algorithms.', '["reading", "value", "measurement", "datum"]', '[]', '["parameter", "metric", "measurement"]', '["packet count", "cycle count", "sample count"]', '["total count", "particle count", "error count", "sample count", "cycle count", "packet count"]', '{"noun_forms": ["countability", "counter"], "verb_forms": ["count", "counted", "counting"], "adjective_forms": ["countable"], "adverb_forms": []}', '["Use the packet count as a parameter for the routing algorithm.", "The cycle count determines wear in the battery test."]', 'science', '1', 165849, 2025, NULL, 'opengloss-v1.1'),
('count_verb_1', 'count', 'verb', 1, 'Compute how often a value or event occurs in data collected from tests or experiments.', '["tabulate", "compute", "tally"]', '[]', '["analyze", "process"]', '["count occurrences", "frequency count", "count frequency"]', '["count items", "count occurrences", "count cycles", "count errors", "count frequency", "count components"]', '{"noun_forms": ["count", "counter"], "verb_forms": ["recount", "miscount"], "adjective_forms": ["countable"], "adverb_forms": []}', '["We counted defects per batch to monitor manufacturing quality trends.", "The lab team counted occurrences of the signal above the threshold."]', 'science', '1', 165849, 2025, NULL, 'opengloss-v1.1'),
