-- lexi ETL: broadcasting (2026-09-18T16:20:14Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('broadcasting_adjective_0', 'broadcasting', 'adjective', 0, 'Relating to or used for the transmission of audio, visual, or data content to a mass audience via radio, television, or digital networks.', '["televised", "on-air", "transmitted"]', '["print", "offline"]', '["media related", "communicative"]', '["broadcasting regulatory", "broadcasting technical"]', '["broadcasting standards", "broadcasting equipment", "broadcasting technology", "broadcasting policy"]', '{"noun_forms": ["broadcast", "broadcaster", "broadcasting"], "verb_forms": ["broadcast"], "adjective_forms": ["broadcast", "broadcasting"], "adverb_forms": []}', '["The broadcasting schedule is revised every season to reflect audience preferences.", "New broadcasting technologies have lowered barriers to entry for small media organizations."]', 'technology', '2', 165628, 2031, NULL, 'opengloss-v1.1'),
('broadcasting_noun_0', 'broadcasting', 'noun', 0, 'The distribution of audio or visual content to a dispersed audience via any electronic mass communication medium, such as radio, television, or internet streams.', '["transmission", "telecast", "airing"]', '["reception"]', '["communication", "media", "distribution"]', '["radio broadcasting", "television broadcasting"]', '["public broadcasting", "broadcasting industry", "broadcasting system", "broadcasting rights"]', '{"noun_forms": ["broadcaster", "broadcast"], "verb_forms": ["broadcast"], "adjective_forms": ["broadcast"], "adverb_forms": []}', '["Public broadcasting plays a crucial role in providing educational content to citizens.", "Digital technologies have transformed the economics of broadcasting in the last two decades."]', 'technology', '2', 165628, 2031, NULL, 'opengloss-v1.1'),
('broadcasting_verb_0', 'broadcasting', 'verb', 0, 'Present participle of broadcast: to transmit audio, video, or data signals by radio waves, cable, satellite, or internet to a large and dispersed audience.', '["transmitting", "airing", "telecasting"]', '["receiving"]', '["communicating", "sending"]', '["live broadcasting", "simulcasting"]', '["broadcasting live", "broadcasting globally", "broadcasting simultaneously", "broadcasting information"]', '{"noun_forms": ["broadcast", "broadcaster", "broadcasting"], "verb_forms": ["rebroadcast", "simulcast"], "adjective_forms": ["broadcast"], "adverb_forms": []}', '["The station is currently broadcasting a live debate between the candidates.", "They are broadcasting the lecture simultaneously on radio and online platforms."]', 'technology', '2', 165628, 2031, NULL, 'opengloss-v1.1'),
('broadcasting_adjective_1', 'broadcasting', 'adjective', 1, 'In computing, denoting a mode of data transfer in which a message is sent from one node to all others within a network segment.', '["multinode", "network wide"]', '["unicast", "point to point"]', '["networking", "digital"]', '["IP broadcasting", "Ethernet broadcasting"]', '["broadcasting standards", "broadcasting equipment", "broadcasting technology", "broadcasting policy"]', '{"noun_forms": ["broadcast", "broadcaster", "broadcasting"], "verb_forms": ["broadcast"], "adjective_forms": ["broadcast", "broadcasting"], "adverb_forms": []}', '["Broadcasting traffic can cause congestion on large local area networks.", "The protocol includes mechanisms for limiting unnecessary broadcasting of packets."]', 'technology', '2', 165628, 2031, NULL, 'opengloss-v1.1'),
('broadcasting_noun_1', 'broadcasting', 'noun', 1, 'The institutional sector and professional activity concerned with producing, scheduling, and transmitting programs for radio, television, or online channels.', '["media industry", "programming", "television industry"]', '["print publishing"]', '["industry", "profession"]', '["public service broadcasting", "commercial broadcasting"]', '["public broadcasting", "broadcasting industry", "broadcasting system", "broadcasting rights"]', '{"noun_forms": ["broadcaster", "broadcast"], "verb_forms": ["broadcast"], "adjective_forms": ["broadcast"], "adverb_forms": []}', '["She has worked in broadcasting for more than twenty years.", "Regulation of broadcasting varies widely between democratic and authoritarian regimes."]', 'technology', '2', 165628, 2031, NULL, 'opengloss-v1.1'),
('broadcasting_verb_1', 'broadcasting', 'verb', 1, 'Present participle of broadcast: to widely disseminate information, opinions, or messages to the public or a large group.', '["circulating", "publicizing", "spreading"]', '["withholding", "concealing"]', '["disseminating", "announcing"]', '["news broadcasting", "political broadcasting"]', '["broadcasting live", "broadcasting globally", "broadcasting simultaneously", "broadcasting information"]', '{"noun_forms": ["broadcast", "broadcaster", "broadcasting"], "verb_forms": ["rebroadcast", "simulcast"], "adjective_forms": ["broadcast"], "adverb_forms": []}', '["By broadcasting misinformation, the group undermined public trust in health institutions.", "The university is broadcasting updates about the policy changes to all students."]', 'technology', '2', 165628, 2031, NULL, 'opengloss-v1.1'),
('broadcasting_noun_2', 'broadcasting', 'noun', 2, 'The act or process of disseminating information, signals, or data broadly and simultaneously to multiple recipients in communication networks.', '["signal dissemination", "data transmission"]', '["unicasting", "narrowcasting"]', '["signaling", "data transfer"]', '["network broadcasting", "wireless broadcasting"]', '["public broadcasting", "broadcasting industry", "broadcasting system", "broadcasting rights"]', '{"noun_forms": ["broadcaster", "broadcast"], "verb_forms": ["broadcast"], "adjective_forms": ["broadcast"], "adverb_forms": []}', '["In computer networks, broadcasting allows one node to send a packet to all others on the same subnet.", "Emergency alerts often rely on broadcasting to reach as many people as possible at once."]', 'technology', '2', 165628, 2031, NULL, 'opengloss-v1.1')
