('lists_verb_0', 'lists', 'verb', 0, 'To prepare a structured enumeration of items by naming them individually.', '["enumerate", "catalog", "itemize"]', '["omit", "exclude"]', '["record", "document"]', '["bulleted list", "checklist", "inventory list"]', '["grocery list", "master list", "checklist", "bulleted list", "inventory list", "alphabetical list"]', '{"noun_forms": ["listing"], "verb_forms": ["relist"], "adjective_forms": ["listed", "unlisted"], "adverb_forms": []}', '["Researchers list the variables in a structured table.", "The study lists key factors affecting climate change."]', 'technology', '4', 160774, 2081, NULL, 'opengloss-v1.1'),
('lists_noun_1', 'lists', 'noun', 1, 'In computer science, a list is an ordered collection of elements that supports indexing and traversal, often implemented as linked lists or arrays.', '["sequence", "array", "collection", "data structure"]', '["unordered collection", "random order"]', '["data structure", "ordered collection"]', '["linked list", "dynamic array", "vector"]', '["master list", "checklist", "shopping list", "grocery list", "inventory list", "price list"]', '{"noun_forms": ["listing"], "verb_forms": ["listed"], "adjective_forms": ["unlisted", "listable"], "adverb_forms": []}', '["In Python, lists are dynamic arrays that resize.", "A linked list stores elements with pointers to neighbors."]', 'technology', '4', 160774, 2081, NULL, 'opengloss-v1.1'),
('lists_verb_1', 'lists', 'verb', 1, 'To include as an item within a catalog, roster, or index.', '["include", "enroll", "register"]', '["exclude", "omit"]', '["catalog", "record"]', '["roster entry", "participant listing"]', '["grocery list", "master list", "checklist", "bulleted list", "inventory list", "alphabetical list"]', '{"noun_forms": ["listing"], "verb_forms": ["relist"], "adjective_forms": ["listed", "unlisted"], "adverb_forms": []}', '["The database lists eligible participants for enrollment.", "The directory lists cooperating institutions by country."]', 'technology', '4', 160774, 2081, NULL, 'opengloss-v1.1'),
('lists_verb_2', 'lists', 'verb', 2, 'To lean or tilt to one side, typically due to imbalance or wind.', '["tilt", "lean", "incline", "cant"]', '["straighten", "level"]', '["move", "motion", "displacement"]', '["cant", "heel"]', '["grocery list", "master list", "checklist", "bulleted list", "inventory list", "alphabetical list"]', '{"noun_forms": ["listing"], "verb_forms": ["relist"], "adjective_forms": ["listed", "unlisted"], "adverb_forms": []}', '["The ship began to list after ballast shifts.", "The vessel listed to port in heavy seas."]', 'technology', '4', 160774, 2081, NULL, 'opengloss-v1.1')
