('guns_noun_0', 'guns', 'noun', 0, 'A portable weapon that fires a projectile by explosive combustion and is designed to be carried and operated by an individual.', '["firearm", "weapon", "arms"]', '["unarmed"]', '["weapon"]', '["pistol", "rifle", "shotgun", "revolver", "machine gun"]', '["gun violence", "gun control", "firearm safety", "machine gun", "handgun", "rifle"]', '{"noun_forms": ["gunner", "gunship", "gunpowder", "gunpoint", "gunfight", "gunmetal"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The police collected guns from the crime scene.", "Comparative studies assess how gun laws affect violent crime rates."]', 'technology', '3', 160687, 2085, NULL, 'opengloss-v1.1'),
('guns_verb_0', 'guns', 'verb', 0, 'To discharge a firearm by pulling the trigger, typically at a target.', '["fire", "shoot", "discharge"]', '["cease fire", "decelerate"]', '["fire a weapon"]', '["shoot a target", "shoot to kill"]', '["gun down", "gun the engine", "gun it", "gun the throttle"]', '{"noun_forms": ["gunner"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The soldiers gun the target from the ridge during the exercise.", "Analysts document incidents where forces gunned down unarmed combatants."]', 'technology', '3', 160687, 2085, NULL, 'opengloss-v1.1'),
('guns_noun_1', 'guns', 'noun', 1, 'A slang term for the biceps or upper arm muscles.', '["biceps", "arm muscles", "upper arm muscles"]', '[]', '["limbs"]', '["biceps", "triceps", "deltoids"]', '["gun violence", "gun control", "firearm safety", "machine gun", "handgun", "rifle"]', '{"noun_forms": ["gunner", "gunship", "gunpowder", "gunpoint", "gunfight", "gunmetal"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["He flexed his guns to display well developed biceps.", "Weight lifters chase bigger guns through targeted training."]', 'technology', '3', 160687, 2085, NULL, 'opengloss-v1.1'),
('guns_verb_1', 'guns', 'verb', 1, 'To accelerate a vehicle by applying the throttle, especially to produce rapid increase in speed.', '["accelerate", "rev", "speed up"]', '["decelerate", "slow down"]', '["increase speed"]', '["rev the engine", "step on the gas"]', '["gun down", "gun the engine", "gun it", "gun the throttle"]', '{"noun_forms": ["gunner"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The driver guns the engine to overtake on the highway.", "Pilots may gun the engines to reach takeoff thrust."]', 'technology', '3', 160687, 2085, NULL, 'opengloss-v1.1')
