('communications_noun_0', 'communications', 'noun', 0, 'Messages or information that people send to others.', '["messages", "notes", "emails", "correspondence"]', '["silence", "miscommunication"]', '["communication"]', '["email", "text message", "letter", "note"]', '["mass communications", "communications technology", "communications plan", "communications skills", "public communications", "digital communications"]', '{"noun_forms": ["communicator"], "verb_forms": ["communicate", "communicated", "communicating"], "adjective_forms": ["communicative"], "adverb_forms": ["communicatively"]}', '["Class newsletters are a form of school communications.", "Parents receive communications about homework and events."]', 'technology', 'BS', 159760, 2098, NULL, 'opengloss-v1.1'),
('communications_noun_1', 'communications', 'noun', 1, 'The act of sharing information through speaking writing or signaling.', '["speaking", "writing", "signaling", "exchanging information"]', '["silence", "inactivity"]', '["process", "activity"]', '["oral communication", "written communication", "nonverbal communication"]', '["mass communications", "communications technology", "communications plan", "communications skills", "public communications", "digital communications"]', '{"noun_forms": ["communicator"], "verb_forms": ["communicate", "communicated", "communicating"], "adjective_forms": ["communicative"], "adverb_forms": ["communicatively"]}', '["Giving a presentation is a form of oral communication.", "Writing a letter is another form of communication."]', 'technology', 'BS', 159760, 2098, NULL, 'opengloss-v1.1'),
('communications_noun_2', 'communications', 'noun', 2, 'The academic field that studies how people share information through media and language.', '["field of study", "discipline", "academic field"]', '["ignorance", "disorganization"]', '["discipline", "academic field"]', '["mass communications", "digital communications", "corporate communications", "health communications"]', '["mass communications", "communications technology", "communications plan", "communications skills", "public communications", "digital communications"]', '{"noun_forms": ["communicator"], "verb_forms": ["communicate", "communicated", "communicating"], "adjective_forms": ["communicative"], "adverb_forms": ["communicatively"]}', '["The communications curriculum covers research methods.", "Hospitals use health communications to share patient information."]', 'technology', 'BS', 159760, 2098, NULL, 'opengloss-v1.1')
