('boat_noun_0', 'boat', 'noun', 0, 'The noun boat denotes a watercraft small to medium in size used for transport or recreation on inland or coastal waters; propulsion by oars, sails, or motor.', '["watercraft", "vessel", "craft"]', '["aircraft"]', '["watercraft", "vessel"]', '["rowboat", "dinghy", "canoe", "kayak", "sailboat"]', '["motor boat", "rowboat", "dinghy", "lifeboat", "houseboat", "boat ramp"]', '{"noun_forms": ["boater", "boatman", "boathouse"], "verb_forms": ["boat"], "adjective_forms": [], "adverb_forms": []}', '["Researchers used a small boat to collect water samples along the river.", "A motor boat ferries researchers between stations along the coastline."]', 'technology', 'K', 156502, 2133, NULL, 'opengloss-v1.1'),
('boat_verb_0', 'boat', 'verb', 0, 'To travel by boat; to move on water using a boat as the vehicle.', '["sail", "voyage", "cruise"]', '["land", "disembark"]', '["move"]', '["row", "sail", "cruise"]', '["boat ramp", "boat engine", "boat deck", "boathouse", "boat builder", "boat trip"]', '{"noun_forms": ["boater", "boatman", "boatyard"], "verb_forms": ["boating"], "adjective_forms": ["boatable"], "adverb_forms": []}', '["Field researchers boated along the river to sample sediments.", "The expedition team boated upstream to reach a sample site."]', 'technology', 'K', 156502, 2133, NULL, 'opengloss-v1.1'),
