('glass_adjective_0', 'glass', 'adjective', 0, 'Of or relating to glass; made of glass.', '["made of glass", "glass-made", "glass-based"]', '["plastic", "wooden"]', '["material", "substance"]', '["borosilicate glass", "soda lime glass"]', '["glass surface", "glass panel", "glass fiber", "glass window", "glass ceiling"]', '{"noun_forms": ["glassiness"], "verb_forms": [], "adjective_forms": ["glassy"], "adverb_forms": []}', '["The glass panel was used to enclose the optical chamber.", "Glass samples were prepared for spectroscopy and microstructural analysis."]', 'science', 'K', 156071, 2141, NULL, 'opengloss-v1.1'),
('glass_noun_0', 'glass', 'noun', 0, 'Glass is a noncrystalline amorphous solid formed by cooling molten silicate mixtures, typically composed of silicon dioxide with additives, and used as a ubiquitous material in architecture, containers, and optics.', '["silicate", "silicate glass", "glass material"]', '["plastic", "metal"]', '["material"]', '["soda lime glass", "borosilicate glass", "fused silica"]', '["window glass", "stained glass", "soda lime glass", "borosilicate glass", "glass sheet", "glass transition temperature"]', '{"noun_forms": ["glassware", "glassiness"], "verb_forms": [], "adjective_forms": ["glassy"], "adverb_forms": []}', '["Soda lime glass dominates architectural glazing and container applications.", "Borosilicate glass resists thermal shock in laboratory apparatus."]', 'science', 'K', 156071, 2141, NULL, 'opengloss-v1.1'),
('glass_verb_0', 'glass', 'verb', 0, 'To cover or enclose (a surface or structure) with glass, typically by installing glass panes.', '["glaze", "enclose", "coat"]', '["expose", "uncover"]', '["surface treatment", "enclosure"]', '["glazing", "glass paneling"]', '["glass pane", "glass window", "tempered glass", "glass ceiling", "glass fiber", "glass facade"]', '{"noun_forms": ["glassmaking", "glazing", "glassware", "glasswork"], "verb_forms": [], "adjective_forms": ["glassy"], "adverb_forms": []}', '["The contractor glassed the storefront by installing tempered glass panels.", "Architects glass the atrium roof to maximize daylight."]', 'science', 'K', 156071, 2141, NULL, 'opengloss-v1.1'),
('glass_adjective_1', 'glass', 'adjective', 1, 'Having a surface or appearance like glass; smooth, clear, and reflective.', '["glassy", "glasslike", "transparent"]', '["opaque", "dull"]', '["surface property", "optical property"]', '["crystal clear", "polished glass"]', '["glass surface", "glass panel", "glass fiber", "glass window", "glass ceiling"]', '{"noun_forms": ["glassiness"], "verb_forms": [], "adjective_forms": ["glassy"], "adverb_forms": []}', '["The glassy surface yielded high specular reflectance in measurements.", "A glassy coating contributed to improved optical clarity in the samples."]', 'science', 'K', 156071, 2141, NULL, 'opengloss-v1.1'),
('glass_noun_1', 'glass', 'noun', 1, 'A glass is a drinking vessel made of glass used to hold beverages.', '["tumbler", "drinking glass", "drinking vessel", "glassware"]', '[]', '["container"]', '["wine glass", "highball glass", "water glass"]', '["window glass", "stained glass", "soda lime glass", "borosilicate glass", "glass sheet", "glass transition temperature"]', '{"noun_forms": ["glassware", "glassiness"], "verb_forms": [], "adjective_forms": ["glassy"], "adverb_forms": []}', '["A wine glass is used for serving wine.", "Highball glass suits cocktails requiring tall narrow vessels."]', 'science', 'K', 156071, 2141, NULL, 'opengloss-v1.1'),
