('holds_noun_0', 'holds', 'noun', 0, 'The interior cargo compartments of a ship or aircraft used for storage of freight.', '["cargo space", "cargo bay", "storage compartment"]', '["exterior space"]', '["storage space", "compartment"]', '["forward hold", "aft hold", "bulk hold"]', '["cargo holds", "climbing holds", "handholds", "storage holds", "forward hold", "aft hold"]', '{"noun_forms": ["holding", "holder", "holdings"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The ship''s holds were inspected for grain.", "Cargo holds must be watertight to prevent contamination."]', 'technology', '2', 155659, 2148, NULL, 'opengloss-v1.1'),
('holds_verb_0', 'holds', 'verb', 0, 'To grasp, clasp, or retain an object with the hands or fingers.', '["grasp", "grip", "clasp", "seize"]', '["release", "free", "let go"]', '["physical action", "manual action"]', '["grip", "clasp"]', '["holds true", "holds steady", "holds memory", "holds the line", "holds up", "holds elections"]', '{"noun_forms": ["holding", "holder"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The analyst holds the sample securely during measurement.", "The technician holds the instrument with a firm grip."]', 'technology', '2', 155659, 2148, NULL, 'opengloss-v1.1'),
('holds_noun_1', 'holds', 'noun', 1, 'In climbing or mountaineering, holds are features on rock, a climbing wall, or an artificial surface that a climber can grip or stand on.', '["handholds", "grips", "grip points"]', '["slips"]', '["grip", "surface feature"]', '["edge hold", "crimp hold", "pocket hold", "jug", "pinch hold"]', '["cargo holds", "climbing holds", "handholds", "storage holds", "forward hold", "aft hold"]', '{"noun_forms": ["holding", "holder", "holdings"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Climbers test different holds to measure grip strength.", "The wall includes jugs and crimps as holds."]', 'technology', '2', 155659, 2148, NULL, 'opengloss-v1.1'),
