('launch_noun_0', 'launch', 'noun', 0, 'The act of starting or initiating something such as a project, program, or activity.', '["start", "initiation", "opening"]', '["end", "finish"]', '["event", "activity", "process"]', '["rocket launch", "product launch"]', '["launch date", "launch window", "launch party", "launch pad", "product launch", "software launch"]', '{"noun_forms": ["launchpad"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The school announced the launch of a new science curriculum.", "A careful plan helps the launch of a classroom project succeed."]', 'technology', '3', 154534, 2160, NULL, 'opengloss-v1.1'),
('launch_verb_0', 'launch', 'verb', 0, 'To begin or initiate something, especially a project, program, or activity.', '["begin", "start", "initiate", "inaugurate"]', '["end", "finish", "stop", "cease"]', '["initiation", "activity"]', '["project launch", "program initiation", "campaign kickoff"]', '["project launch", "program launch", "campaign launch", "rocket launch", "space launch", "launch date"]', '{"noun_forms": ["launcher", "launchpad", "launchable"], "verb_forms": ["relaunch"], "adjective_forms": ["launchable"], "adverb_forms": []}', '["The school will launch a reading program next semester.", "Researchers launched a study on climate effects this year."]', 'technology', '3', 154534, 2160, NULL, 'opengloss-v1.1'),
('launch_noun_1', 'launch', 'noun', 1, 'The act of sending a vehicle, missile, or spacecraft into flight.', '["liftoff", "blastoff", "takeoff"]', '["landing", "descent"]', '["flight start", "flight operation", "event"]', '["rocket liftoff", "missile launch"]', '["launch date", "launch window", "launch party", "launch pad", "product launch", "software launch"]', '{"noun_forms": ["launchpad"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The liftoff occurred on a clear morning.", "Missile liftoff was delayed by weather."]', 'technology', '3', 154534, 2160, NULL, 'opengloss-v1.1'),
('launch_verb_1', 'launch', 'verb', 1, 'To cause a rocket, spacecraft, or aircraft to leave the ground or to begin moving, typically by releasing thrust.', '["fire", "deploy", "send off", "set in motion"]', '["land", "abort", "ground", "stall"]', '["propulsion", "motion", "movement", "flight"]', '["rocket launch", "space launch", "satellite launch"]', '["project launch", "program launch", "campaign launch", "rocket launch", "space launch", "launch date"]', '{"noun_forms": ["launcher", "launchpad", "launchable"], "verb_forms": ["relaunch"], "adjective_forms": ["launchable"], "adverb_forms": []}', '["The first stage will launch the satellite into orbit.", "Engineers will launch the rocket after system checks."]', 'technology', '3', 154534, 2160, NULL, 'opengloss-v1.1'),
('launch_noun_2', 'launch', 'noun', 2, 'The public introduction or release of a product or service.', '["release", "introduction", "premiere"]', '["recall", "withdrawal"]', '["event", "release", "introduction"]', '["software launch", "hardware launch"]', '["launch date", "launch window", "launch party", "launch pad", "product launch", "software launch"]', '{"noun_forms": ["launchpad"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The software launch introduced new features to users.", "The product launch brought families to the local library demonstration."]', 'technology', '3', 154534, 2160, NULL, 'opengloss-v1.1')
