('visual_adjective_0', 'visual', 'adjective', 0, 'Relating to sight; able to be seen or observed.', '["optical", "ocular"]', '["invisible"]', '["perceptual term"]', '["visual cue", "visual diagram"]', '["visual aid", "visual representation", "visual data", "visual chart", "visual poster", "visual arts"]', '{"noun_forms": ["visuality", "visualization", "visualizer"], "verb_forms": ["visualize"], "adjective_forms": ["visualizable"], "adverb_forms": ["visually"]}', '["The diagram displayed a visual pattern that students could observe.", "A visual representation helps learners notice trends in the data."]', 'technology', '6', 151373, 2211, NULL, 'opengloss-v1.1'),
('visual_noun_0', 'visual', 'noun', 0, 'A visual is a picture or diagram used to convey information.', '["image", "picture", "diagram", "illustration"]', '["text", "audio"]', '["image", "representation"]', '["photograph", "diagram", "chart"]', '["visual aid", "visual display", "visual representation", "data visualization", "illustration set"]', '{"noun_forms": ["visualization"], "verb_forms": ["visualize"], "adjective_forms": ["visualizable"], "adverb_forms": ["visually"]}', '["The chart is a visual that helps students compare data.", "Science posters provide visuals to show cycles."]', 'technology', '6', 151373, 2211, NULL, 'opengloss-v1.1'),
('visual_adjective_1', 'visual', 'adjective', 1, 'Intended to be seen; used to show information rather than read or heard.', '["graphic", "pictorial"]', '["verbal"]', '["display term"]', '["visual poster", "visual chart"]', '["visual aid", "visual representation", "visual data", "visual chart", "visual poster", "visual arts"]', '{"noun_forms": ["visuality", "visualization", "visualizer"], "verb_forms": ["visualize"], "adjective_forms": ["visualizable"], "adverb_forms": ["visually"]}', '["The teacher used a visual poster to illustrate the steps.", "Visual charts summarize results for quick classroom reference."]', 'technology', '6', 151373, 2211, NULL, 'opengloss-v1.1'),
('visual_noun_1', 'visual', 'noun', 1, 'A visual aid is a graphic used to illustrate or support learning.', '["visual aid", "graphic", "illustration", "display"]', '["text", "sound"]', '["teaching tool", "instructional aid"]', '["poster", "diagram", "flashcard"]', '["visual aid", "visual display", "visual representation", "data visualization", "illustration set"]', '{"noun_forms": ["visualization"], "verb_forms": ["visualize"], "adjective_forms": ["visualizable"], "adverb_forms": ["visually"]}', '["The teacher used a visual aid for the water cycle.", "Students benefit when the visual aid accompanies the written text."]', 'technology', '6', 151373, 2211, NULL, 'opengloss-v1.1'),
('visual_adjective_2', 'visual', 'adjective', 2, 'Relating to learning through pictures and images; in education, favoring visual methods.', '["pictorial"]', '["verbal"]', '["educational descriptor"]', '["illustrative diagram", "illustrative graph"]', '["visual aid", "visual representation", "visual data", "visual chart", "visual poster", "visual arts"]', '{"noun_forms": ["visuality", "visualization", "visualizer"], "verb_forms": ["visualize"], "adjective_forms": ["visualizable"], "adverb_forms": ["visually"]}', '["Many science projects rely on visual diagrams to explain processes.", "A visual learner benefits from pictures and diagrams in notes."]', 'technology', '6', 151373, 2211, NULL, 'opengloss-v1.1'),
('visual_noun_2', 'visual', 'noun', 2, 'A visual is a mental image formed in the mind.', '["mental image", "picture"]', '["text", "sound"]', '["perception", "imagination"]', '["mind picture", "internal image"]', '["visual aid", "visual display", "visual representation", "data visualization", "illustration set"]', '{"noun_forms": ["visualization"], "verb_forms": ["visualize"], "adjective_forms": ["visualizable"], "adverb_forms": ["visually"]}', '["During recall, the student pictured a visual in the mind.", "A vivid visual helps remember a story."]', 'technology', '6', 151373, 2211, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
