-- lexi ETL: walls (2026-09-18T16:20:15Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('walls_noun_0', 'walls', 'noun', 0, 'A vertical architectural element that encloses or partitions space, forming a boundary between areas.', '["barrier", "partition", "enclosure"]', '["opening", "gap"]', '["structure", "architectural element"]', '["load bearing wall", "curtain wall"]', '["stone walls", "load bearing walls", "retaining walls", "internal walls", "outer walls", "wall thickness"]', '{"noun_forms": ["walling"], "verb_forms": ["wall", "walled", "walling"], "adjective_forms": ["wallless"], "adverb_forms": []}', '["Exterior walls delineate the enclosure of a building.", "The ancient city walls surrounded the fortress."]', 'technology', 'K', 148961, 2247, NULL, 'opengloss-v1.1'),
('walls_verb_0', 'walls', 'verb', 0, 'To construct a wall or barrier that encloses or surrounds a space by erecting masonry, a fence, or other enclosure material.', '["enclose", "surround"]', '["open", "expose"]', '["build", "enclose"]', '["brickwork", "masonry"]', '["wall construction", "brick wall", "masonry wall", "wall height", "wall thickness", "walling process"]', '{"noun_forms": ["walling"], "verb_forms": ["rewall"], "adjective_forms": ["wall-like"], "adverb_forms": []}', '["The city walls the fortress to secure the perimeter.", "Engineers wall the courtyard with reinforced masonry."]', 'technology', 'K', 148961, 2247, NULL, 'opengloss-v1.1'),
('walls_noun_1', 'walls', 'noun', 1, 'A wall that bears structural loads in a building, transferring weight to the foundation.', '["bearing wall", "structural wall"]', '["nonloadbearing wall"]', '["structural element", "building component"]', '["shear wall", "cavity wall", "fire wall"]', '["stone walls", "load bearing walls", "retaining walls", "internal walls", "outer walls", "wall thickness"]', '{"noun_forms": ["walling"], "verb_forms": ["wall", "walled", "walling"], "adjective_forms": ["wallless"], "adverb_forms": []}', '["The shear wall resists lateral seismic forces.", "The cavity wall provides insulation and drainage."]', 'technology', 'K', 148961, 2247, NULL, 'opengloss-v1.1'),
