('mill_noun_0', 'mill', 'noun', 0, 'A building or complex containing machinery for grinding grain into flour, typically including a milling apparatus and ancillary facilities.', '["flour mill", "gristmill"]', '[]', '["facility", "industrial facility"]', '["sawmill", "windmill", "wheat mill", "corn mill"]', '["grain mill", "flour mill", "windmill", "water mill", "sawmill", "milling industry"]', '{"noun_forms": ["miller", "millage"], "verb_forms": ["milling"], "adjective_forms": [], "adverb_forms": []}', '["The town''s flour mill processed locally grown grain using a water wheel.", "A restored gristmill now operates as a museum illustrating early milling technology."]', 'technology', '1', 147755, 2264, NULL, 'opengloss-v1.1'),
('mill_verb_0', 'mill', 'verb', 0, 'To grind or reduce to fine powder or meal by passing material through a mill; typically cereals or grains.', '["grind", "crush", "pulverize"]', '[]', '["processing"]', '["wheat milling", "corn milling"]', '["mill grain", "mill flour", "mill metal", "milling machine", "grain milling", "wheat milling"]', '{"noun_forms": ["miller", "milling"], "verb_forms": [], "adjective_forms": ["milled"], "adverb_forms": []}', '["Farmers milled the grain into flour.", "The old mill milled the wheat into flour."]', 'technology', '1', 147755, 2264, NULL, 'opengloss-v1.1'),
('mill_noun_1', 'mill', 'noun', 1, 'A machine or device used to grind or pulverize material in industrial processing, especially for ore or grain.', '["grinding mill", "milling machine"]', '[]', '["machinery", "instrument"]', '["ball mill", "roller mill"]', '["grain mill", "flour mill", "windmill", "water mill", "sawmill", "milling industry"]', '{"noun_forms": ["miller", "millage"], "verb_forms": ["milling"], "adjective_forms": [], "adverb_forms": []}', '["A ball mill was used to grind ceramic particles to submicron sizes.", "Industrial mills rely on synchronized rollers to achieve uniform particle size."]', 'technology', '1', 147755, 2264, NULL, 'opengloss-v1.1'),
('mill_verb_1', 'mill', 'verb', 1, 'To machine a workpiece by removing material with a rotating cutter, usually in a milling machine.', '["machine", "cut", "shape"]', '[]', '["machining"]', '["face milling", "slot milling"]', '["mill grain", "mill flour", "mill metal", "milling machine", "grain milling", "wheat milling"]', '{"noun_forms": ["miller", "milling"], "verb_forms": [], "adjective_forms": ["milled"], "adverb_forms": []}', '["The machinist milled a slot on the workpiece.", "CNC mills milled aluminum prototypes."]', 'technology', '1', 147755, 2264, NULL, 'opengloss-v1.1'),
('mill_noun_2', 'mill', 'noun', 2, 'A monetary unit equal to one thousandth of a basic currency unit, historically used in taxation and pricing, often described as one tenth of a cent.', '["thousandth of a dollar", "one mill"]', '["cent"]', '["currency unit", "monetary unit"]', '["mill rate", "millage"]', '["grain mill", "flour mill", "windmill", "water mill", "sawmill", "milling industry"]', '{"noun_forms": ["miller", "millage"], "verb_forms": ["milling"], "adjective_forms": [], "adverb_forms": []}', '["Prices were quoted in mills during the predecimal era.", "Tax rates were assessed in mills to fund municipal improvements."]', 'technology', '1', 147755, 2264, NULL, 'opengloss-v1.1'),
('mill_verb_2', 'mill', 'verb', 2, 'To move about in a crowd or group, typically in a restless, aimless fashion.', '["roam", "wander", "shuffle"]', '["stay", "settle"]', '["movement"]', '["crowd movement", "mass movement"]', '["mill grain", "mill flour", "mill metal", "milling machine", "grain milling", "wheat milling"]', '{"noun_forms": ["miller", "milling"], "verb_forms": [], "adjective_forms": ["milled"], "adverb_forms": []}', '["Visitors milled about the hall after the lecture.", "People milled around waiting for the entry gate."]', 'technology', '1', 147755, 2264, NULL, 'opengloss-v1.1')
