('motor_adjective_0', 'motor', 'adjective', 0, 'Relating to motion or to devices that produce motion.', '["powered", "driven", "kinetic"]', '["nonmotor", "static"]', '["motion"]', '["motorized", "engine powered"]', '["motor skills", "motor function", "motor vehicle", "motor oil", "motorized toy", "motor cortex"]', '{"noun_forms": ["motorization"], "verb_forms": ["motorize"], "adjective_forms": ["motorized"], "adverb_forms": []}', '["Students study how a powered device converts electricity to motion.", "A motorized cart demonstrates motion generated by a motor."]', 'technology', '3', 147239, 2269, NULL, 'opengloss-v1.1'),
('motor_noun_0', 'motor', 'noun', 0, 'A motor is a device that converts electrical energy into mechanical energy to produce motion.', '["engine", "machine"]', '["hand crank"]', '["machine", "device"]', '["electric motor", "dc motor", "brushless motor", "stepper motor"]', '["electric motor", "dc motor", "brushless motor", "stepper motor", "motor shaft", "motor oil"]', '{"noun_forms": ["motorization"], "verb_forms": ["motorize"], "adjective_forms": ["motorized"], "adverb_forms": []}', '["A small electric motor powers a toy car.", "Industrial fans use a powerful motor to move air."]', 'technology', '3', 147239, 2269, NULL, 'opengloss-v1.1'),
('motor_verb_0', 'motor', 'verb', 0, 'To travel in or by means of a motor vehicle such as a car, bus, or truck, typically for a short or routine journey.', '["drive", "travel"]', '["walk", "stroll"]', '["move", "travel"]', '["car travel", "road trip", "long drive"]', '["motor along", "motor down the road", "motor to school", "motor to town", "motor away"]', '{"noun_forms": ["motorist", "motorization"], "verb_forms": ["motorize"], "adjective_forms": ["motorized", "motorless"], "adverb_forms": []}', '["We motored to the library for a field trip.", "The bus motored along the highway during the field trip."]', 'technology', '3', 147239, 2269, NULL, 'opengloss-v1.1'),
('motor_adjective_1', 'motor', 'adjective', 1, 'In anatomy, relating to nerves that activate muscles.', '["neural"]', '["sensory"]', '["nervous system"]', '["motor neuron", "motor cortex"]', '["motor skills", "motor function", "motor vehicle", "motor oil", "motorized toy", "motor cortex"]', '{"noun_forms": ["motorization"], "verb_forms": ["motorize"], "adjective_forms": ["motorized"], "adverb_forms": []}', '["Motor nerves transmit commands from the brain to muscles.", "Tests assess motor pathways to diagnose neuromuscular issues."]', 'technology', '3', 147239, 2269, NULL, 'opengloss-v1.1'),
('motor_verb_1', 'motor', 'verb', 1, 'To operate or power a motor or engine, especially to cause a machine to run.', '["operate", "power up"]', '["disable", "stall"]', '["activate", "run"]', '["engine start", "motor startup"]', '["motor along", "motor down the road", "motor to school", "motor to town", "motor away"]', '{"noun_forms": ["motorist", "motorization"], "verb_forms": ["motorize"], "adjective_forms": ["motorized", "motorless"], "adverb_forms": []}', '["The technician motored the conveyor belt to start the line.", "We motored the backup generator to supply extra capacity."]', 'technology', '3', 147239, 2269, NULL, 'opengloss-v1.1')
