('images_noun_0', 'images', 'noun', 0, 'A two dimensional visual representation produced by light captured or created by photographic, artistic, or other visual media, typically used as a depiction of a scene or object.', '["picture", "depiction", "illustration", "graphic"]', '["reality", "actual scene"]', '["depiction", "visual representation", "picture"]', '["photograph", "drawing", "engraving", "icon"]', '["digital image", "image processing", "image file", "image dataset", "image quality", "medical images"]', '{"noun_forms": ["imagery", "imaging"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The images depict cellular morphology under microscopy.", "Historical images illustrate changes in urban form."]', 'arts', '3', 146888, 2277, NULL, 'opengloss-v1.1'),
('images_verb_0', 'images', 'verb', 0, 'To form a mental image of something; to visualize or imagine it in the mind.', '["visualize", "imagine", "picture"]', '["forget", "disregard", "ignore"]', '["mental process", "cognition"]', '["visualization", "mental image"]', '["image processing", "image file", "high resolution image", "medical imaging", "image dataset", "image quality"]', '{"noun_forms": ["imagery", "imaging"], "verb_forms": [], "adjective_forms": ["imageable"], "adverb_forms": []}', '["Participants image a calm scene to reduce stress.", "Researchers image a future scenario during planning tasks."]', 'arts', '3', 146888, 2277, NULL, 'opengloss-v1.1'),
('images_noun_1', 'images', 'noun', 1, 'A digital graphic stored as data for display or processing by computer systems, typically in a raster or vector format.', '["digital image", "bitmap", "raster image"]', '["nonimage data"]', '["digital representation", "data graphic"]', '["bitmap", "jpeg image", "png image", "vector graphic"]', '["digital image", "image processing", "image file", "image dataset", "image quality", "medical images"]', '{"noun_forms": ["imagery", "imaging"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["JPEG images are stored as compressed pixel data.", "The dataset includes thousands of images for training."]', 'arts', '3', 146888, 2277, NULL, 'opengloss-v1.1'),
('images_verb_1', 'images', 'verb', 1, 'To produce a visual representation of an object or scene by using imaging equipment or methods.', '["photograph", "capture", "record"]', '["erase", "destroy"]', '["visualization", "imaging"]', '["MRI imaging", "ultrasound imaging"]', '["image processing", "image file", "high resolution image", "medical imaging", "image dataset", "image quality"]', '{"noun_forms": ["imagery", "imaging"], "verb_forms": [], "adjective_forms": ["imageable"], "adverb_forms": []}', '["The MRI scanner images brain tissue to detect abnormalities.", "Satellite sensors image the land surface to monitor changes."]', 'arts', '3', 146888, 2277, NULL, 'opengloss-v1.1'),
('images_noun_2', 'images', 'noun', 2, 'A mental image or impression formed in the mind''s eye, representing a scene, object, or concept.', '["mental image", "visualization", "internal image"]', '["forgetting"]', '["cognitive representation", "mental concept"]', '["visual memory", "dream image"]', '["digital image", "image processing", "image file", "image dataset", "image quality", "medical images"]', '{"noun_forms": ["imagery", "imaging"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Participants reported vivid images during the task.", "Memory studies examine how images are recalled."]', 'arts', '3', 146888, 2277, NULL, 'opengloss-v1.1'),
('images_verb_2', 'images', 'verb', 2, 'To portray or project an image of something in order to convey a particular impression or interpretation.', '["depict", "portray", "represent", "project"]', '["conceal", "distort", "obscure"]', '["visual representation", "communication"]', '["figurative image", "symbolic depiction"]', '["image processing", "image file", "high resolution image", "medical imaging", "image dataset", "image quality"]', '{"noun_forms": ["imagery", "imaging"], "verb_forms": [], "adjective_forms": ["imageable"], "adverb_forms": []}', '["The campaign images the corporation as socially responsible.", "The film images urban life as chaotic and dynamic."]', 'arts', '3', 146888, 2277, NULL, 'opengloss-v1.1'),
('images_noun_3', 'images', 'noun', 3, 'A public or symbolic representation of a person, organization, or idea, as perceived or portrayed by others.', '["reputation", "persona", "public face"]', '["bad reputation"]', '["representation", "symbol"]', '["brand image", "corporate image", "personal image", "political image"]', '["digital image", "image processing", "image file", "image dataset", "image quality", "medical images"]', '{"noun_forms": ["imagery", "imaging"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The company manages its image through branding campaigns.", "Media coverage shapes the political candidate''s image."]', 'arts', '3', 146888, 2277, NULL, 'opengloss-v1.1')
