('applications_noun_0', 'applications', 'noun', 0, 'The action of putting something to use; the practical uses or purposes of a method, device, or theory in scholarly work.', '["uses", "utilizations", "employment"]', '["disuse", "nonuse"]', '["use", "function"]', '["data analysis", "experimental technique"]', '["practical applications", "medical applications", "industrial applications", "software applications", "fields of application"]', '{"noun_forms": ["applicability"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Examples of applications include data analysis and experimental design.", "In the course, we study applications of probability to experimental planning."]', 'science', '3', 146329, 2284, NULL, 'opengloss-v1.1'),
('applications_noun_1', 'applications', 'noun', 1, 'A software program or group of programs designed to perform a defined set of tasks for end users.', '["apps", "programs"]', '["system software"]', '["software", "computer program"]', '["word processor", "spreadsheet", "image editor", "presentation program"]', '["practical applications", "medical applications", "industrial applications", "software applications", "fields of application"]', '{"noun_forms": ["applicability"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Modern offices rely on applications for word processing and data analysis.", "Mobile devices run applications that support communication and productivity."]', 'science', '3', 146329, 2284, NULL, 'opengloss-v1.1'),
('applications_noun_2', 'applications', 'noun', 2, 'A formal request or submission to obtain something such as admission, funding, or endorsement.', '["request", "submission"]', '["rejection", "denial"]', '["request", "petition"]', '["admission application", "fellowship application", "grant application"]', '["practical applications", "medical applications", "industrial applications", "software applications", "fields of application"]', '{"noun_forms": ["applicability"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The committee evaluated every admission application.", "Grant applications require detailed budgets and justification."]', 'science', '3', 146329, 2284, NULL, 'opengloss-v1.1'),
('applications_noun_3', 'applications', 'noun', 3, 'The domains or contexts in which a method or theory can be used.', '["fields of use", "areas of use"]', '[]', '["contexts", "domains"]', '["clinical use", "industrial use", "educational use"]', '["practical applications", "medical applications", "industrial applications", "software applications", "fields of application"]', '{"noun_forms": ["applicability"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers assess the domains of use for the model across disciplines.", "Education and engineering illustrate different fields of use for simulation."]', 'science', '3', 146329, 2284, NULL, 'opengloss-v1.1')
