-- lexi ETL: mine (2026-09-18T16:20:16Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('mine_determiner_0', 'mine', 'determiner', 0, 'Archaic or literary form of "my," used before a word beginning with a vowel sound to indicate that something belongs or relates to the speaker.', '["my"]', '["thy", "your"]', '["possessive determiner"]', '["mine eyes", "mine own", "mine honor"]', '["mine own", "mine eyes", "mine enemy", "mine honor"]', '{"noun_forms": [], "verb_forms": ["mine"], "adjective_forms": [], "adverb_forms": []}', '["Mine enemy pursued me relentlessly in the tale.", "He listened to mine arguments with great patience."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1'),
('mine_noun_0', 'mine', 'noun', 0, 'An excavation in the earth from which minerals, ores, coal, precious stones, or other geological materials are extracted, typically involving shafts, tunnels, or open pits.', '["pit", "quarry", "excavation"]', '["surface", "dump"]', '["excavation", "industrial site"]', '["coal mine", "gold mine"]', '["coal mine", "gold mine", "mine shaft", "mine worker"]', '{"noun_forms": ["mining", "miner"], "verb_forms": ["mine"], "adjective_forms": ["mined"], "adverb_forms": []}', '["The gold mine brought rapid economic development to the remote region.", "Safety regulations in the coal mine were tightened after the accident."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1'),
('mine_pronoun_0', 'mine', 'pronoun', 0, 'A possessive pronoun used to indicate that something belongs or relates to the speaker, often replacing a noun phrase previously mentioned or understood from context.', '["my own", "belonging to me"]', '["yours", "theirs"]', '["possessive pronoun"]', '["mine alone", "all mine", "only mine"]', '["mine alone", "not mine", "mine and yours", "of mine"]', '{"noun_forms": [], "verb_forms": ["mine"], "adjective_forms": [], "adverb_forms": []}', '["This book is mine, not yours.", "The decision is mine to make."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1'),
('mine_verb_0', 'mine', 'verb', 0, 'To extract minerals, ores, or other geological materials from the earth, typically by digging, drilling, or blasting.', '["extract", "excavate", "dig"]', '["fill", "restore"]', '["extract", "harvest"]', '["strip mine", "surface mine"]', '["mine coal", "mine data", "mine resources", "mine the area"]', '{"noun_forms": ["miner", "mining", "minefield"], "verb_forms": ["undermine"], "adjective_forms": ["mined", "minable"], "adverb_forms": []}', '["The company plans to mine copper from the newly discovered deposit.", "Historically, many towns in the region relied on coal that was mined locally."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1'),
('mine_noun_1', 'mine', 'noun', 1, 'A rich or apparently inexhaustible source of something valuable, especially information, inspiration, or material for study.', '["treasure trove", "fount", "source"]', '["void", "scarcity"]', '["source", "resource"]', '["data mine", "information mine"]', '["coal mine", "gold mine", "mine shaft", "mine worker"]', '{"noun_forms": ["mining", "miner"], "verb_forms": ["mine"], "adjective_forms": ["mined"], "adverb_forms": []}', '["The archive proved to be a mine of information for the historian.", "The interviews were a mine of data for the social science research team."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1'),
('mine_pronoun_1', 'mine', 'pronoun', 1, 'In formal or archaic style, used with "of" before a noun beginning with a vowel sound, functioning like a possessive determiner meaning "my."', '["my"]', '["thy", "your"]', '["possessive pronoun"]', '["mine own", "mine eyes", "mine honour"]', '["mine alone", "not mine", "mine and yours", "of mine"]', '{"noun_forms": [], "verb_forms": ["mine"], "adjective_forms": [], "adverb_forms": []}', '["Mine eyes have seen the glory of the coming of the Lord.", "She spoke of mine honor and reputation."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1'),
('mine_verb_1', 'mine', 'verb', 1, 'To obtain or analyze large quantities of data in order to discover patterns, correlations, or useful information.', '["analyze", "exploit", "process"]', '["ignore"]', '["analyze", "process"]', '["data mine", "text mine"]', '["mine coal", "mine data", "mine resources", "mine the area"]', '{"noun_forms": ["miner", "mining", "minefield"], "verb_forms": ["undermine"], "adjective_forms": ["mined", "minable"], "adverb_forms": []}', '["Researchers mine social media data to study patterns of communication.", "The team used specialized software to mine the database for anomalies."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1'),
('mine_noun_2', 'mine', 'noun', 2, 'An explosive device placed underground, underwater, or on the surface, designed to detonate when triggered by contact, pressure, or proximity, often used in warfare.', '["landmine", "explosive", "bomb"]', '["dud"]', '["weapon", "explosive device"]', '["land mine", "naval mine"]', '["coal mine", "gold mine", "mine shaft", "mine worker"]', '{"noun_forms": ["mining", "miner"], "verb_forms": ["mine"], "adjective_forms": ["mined"], "adverb_forms": []}', '["The engineers carefully cleared the area of each mine before construction began.", "Stepping on a buried mine can have devastating consequences for civilians."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1'),
('mine_verb_2', 'mine', 'verb', 2, 'To place explosive mines in or under an area, structure, or route, usually for military purposes.', '["booby-trap", "seed", "plant"]', '["demine", "clear"]', '["arm", "rig"]', '["landmine", "sea-mine"]', '["mine coal", "mine data", "mine resources", "mine the area"]', '{"noun_forms": ["miner", "mining", "minefield"], "verb_forms": ["undermine"], "adjective_forms": ["mined", "minable"], "adverb_forms": []}', '["The retreating forces decided to mine the bridge to slow the enemy advance.", "Engineers were ordered to mine the harbor entrance before dawn."]', 'technology', 'K', 143571, 2324, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
