('stand_noun_0', 'stand', 'noun', 0, 'A stand is a piece of furniture or equipment used to hold or support objects, commonly placed on a desk, table, or floor.', '["rack", "holder", "pedestal", "support"]', '[]', '["object", "furniture", "equipment"]', '["book stand", "music stand", "laptop stand", "instrument stand"]', '["book stand", "music stand", "fruit stand", "ice cream stand", "firm stand"]', '{"noun_forms": ["standing"], "verb_forms": ["stand"], "adjective_forms": [], "adverb_forms": []}', '["In the science lab, place the beaker on a sturdy stand.", "The teacher displayed the poster on a portable stand during the lesson."]', 'technology', 'K', 142750, 2339, NULL, 'opengloss-v1.1'),
('stand_verb_0', 'stand', 'verb', 0, 'To assume an upright position on the feet, usually by rising from a seated or lying posture.', '["rise", "arise", "get up"]', '["sit", "lie", "collapse"]', '["action verb", "move"]', '["stand up", "stand tall"]', '["stand firm", "stand by", "stand for", "stand tall", "stand still", "stand up"]', '{"noun_forms": ["standstill", "standing"], "verb_forms": [], "adjective_forms": ["standing"], "adverb_forms": []}', '["Students should stand when the flag is raised.", "The teacher asked everyone to stand quietly during the pledge."]', 'technology', 'K', 142750, 2339, NULL, 'opengloss-v1.1'),
('stand_noun_1', 'stand', 'noun', 1, 'A stand is a small structure or stall where goods are sold, especially outdoors in markets or fairs.', '["stall", "booth"]', '[]', '["structure", "outlet"]', '["fruit stand", "ice cream stand", "hot dog stand", "lemonade stand"]', '["book stand", "music stand", "fruit stand", "ice cream stand", "firm stand"]', '{"noun_forms": ["standing"], "verb_forms": ["stand"], "adjective_forms": [], "adverb_forms": []}', '["The school fundraiser featured a lemonade stand near the gym.", "Visitors browsed the fruit stand near the market entrance."]', 'technology', 'K', 142750, 2339, NULL, 'opengloss-v1.1'),
('stand_verb_1', 'stand', 'verb', 1, 'To tolerate or endure something unpleasant or disliked.', '["tolerate", "endure", "bear", "withstand"]', '["enjoy", "love", "admire", "celebrate"]', '["emotive verb", "action verb"]', '["bear pain", "tolerate heat", "endure stress"]', '["stand firm", "stand by", "stand for", "stand tall", "stand still", "stand up"]', '{"noun_forms": ["standstill", "standing"], "verb_forms": [], "adjective_forms": ["standing"], "adverb_forms": []}', '["I can''t stand loud noises in the classroom.", "We cannot stand the heat during exams."]', 'technology', 'K', 142750, 2339, NULL, 'opengloss-v1.1'),
('stand_noun_2', 'stand', 'noun', 2, 'A stand is a position or attitude about an issue; the stance one takes in a discussion or debate.', '["stance", "position", "viewpoint", "attitude"]', '["opposite stance", "neutral position"]', '["viewpoint", "belief"]', '["moral stand", "political stance", "ethical position", "legal stance"]', '["book stand", "music stand", "fruit stand", "ice cream stand", "firm stand"]', '{"noun_forms": ["standing"], "verb_forms": ["stand"], "adjective_forms": [], "adverb_forms": []}', '["In social studies, students defend their stand with evidence.", "The debate required a clear stand on the issue."]', 'technology', 'K', 142750, 2339, NULL, 'opengloss-v1.1'),
