('screen_noun_0', 'screen', 'noun', 0, 'A flat panel that shows images or text from a computer, TV, or other device.', '["display", "monitor", "panel", "viewing surface"]', '["printout", "paper page"]', '["device", "technology"]', '["LCD screen", "LED screen", "touch screen"]', '["computer screen", "touch screen", "window screen", "insect screen", "screen door", "screen time"]', '{"noun_forms": ["screening", "screener"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The teacher showed the science video on the screen in class.", "Students read the math problem on the screen with large print."]', 'technology', '2', 142392, 2346, NULL, 'opengloss-v1.1'),
('screen_verb_0', 'screen', 'verb', 0, 'To show or project a film or video to an audience on a screen.', '["show", "display", "present", "project"]', '["conceal", "hide"]', '["display"]', '["movie screening", "video projection"]', '["screen for", "screen a film", "screen data", "screen patients", "screen candidates", "screening process"]', '{"noun_forms": ["screener", "screening"], "verb_forms": ["screens", "screened", "screening"], "adjective_forms": ["screenable"], "adverb_forms": []}', '["The class screens a short film for science.", "The school screens the film for the assembly."]', 'technology', '2', 142392, 2346, NULL, 'opengloss-v1.1'),
('screen_noun_1', 'screen', 'noun', 1, 'A mesh covering used to keep insects out and to separate spaces.', '["mesh", "netting", "grille", "mesh covering"]', '["open", "uncovered"]', '["barrier", "covering"]', '["window screen", "insect screen", "privacy screen"]', '["computer screen", "touch screen", "window screen", "insect screen", "screen door", "screen time"]', '{"noun_forms": ["screening", "screener"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["We installed a window screen to keep bugs out.", "The screen on the porch is made of metal mesh."]', 'technology', '2', 142392, 2346, NULL, 'opengloss-v1.1'),
