('engineers_noun_0', 'engineers', 'noun', 0, 'People who use science and math to create, build, and improve machines, systems, and structures.', '["designers", "technologists", "developers"]', '["nonengineers"]', '["professionals", "workers"]', '["mechanical engineers", "electrical engineers", "civil engineers"]', '["civil engineers", "electrical engineers", "mechanical engineers", "engineering team", "professional engineers", "engineering firm"]', '{"noun_forms": ["engineering"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Engineers design safer bridges for towns.", "Young students learn how engineers use math."]', 'technology', '4', 139506, 2400, NULL, 'opengloss-v1.1'),
('engineers_verb_0', 'engineers', 'verb', 0, 'To plan and build something with skill and careful design.', '["design", "plan", "devise", "construct"]', '["destroy", "ruin"]', '["design", "planning"]', '["bridge design", "robot design", "software design"]', '["engineer a plan", "engineer a solution", "engineer a model", "engineer software", "engineer a bridge", "engineer a device"]', '{"noun_forms": ["engineering"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The team engineers a new solar panel.", "They engineer a plan to test the hypothesis."]', 'technology', '4', 139506, 2400, NULL, 'opengloss-v1.1'),
('engineers_noun_1', 'engineers', 'noun', 1, 'A team or group of engineers who work together on a project.', '["engineering team", "design team", "project group"]', '["nonengineering team"]', '["teams", "groups"]', '["robotics team", "design team"]', '["civil engineers", "electrical engineers", "mechanical engineers", "engineering team", "professional engineers", "engineering firm"]', '{"noun_forms": ["engineering"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The engineers formed an engineering team to design a new playground.", "A small design team at the school built a solar car."]', 'technology', '4', 139506, 2400, NULL, 'opengloss-v1.1'),
('engineers_verb_1', 'engineers', 'verb', 1, 'To arrange or influence events or outcomes through careful planning.', '["plan", "design", "devise", "orchestrate"]', '["unplanned", "unscripted"]', '["planning", "management"]', '["classroom schedule", "event plan", "outreach program"]', '["engineer a plan", "engineer a solution", "engineer a model", "engineer software", "engineer a bridge", "engineer a device"]', '{"noun_forms": ["engineering"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The coach engineers a practice schedule to improve speed.", "Researchers engineer an experiment that shows the expected results."]', 'technology', '4', 139506, 2400, NULL, 'opengloss-v1.1'),
('engineers_verb_2', 'engineers', 'verb', 2, 'To arrange or alter data or results to achieve a desired outcome.', '["manipulate", "fabricate", "craft", "produce"]', '["unmanipulated", "genuine"]', '["manipulation", "deception"]', '["fabricated data", "staged scene", "manipulated results"]', '["engineer a plan", "engineer a solution", "engineer a model", "engineer software", "engineer a bridge", "engineer a device"]', '{"noun_forms": ["engineering"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The study was engineered to produce favorable results.", "Critics say the data were engineered to mislead."]', 'technology', '4', 139506, 2400, NULL, 'opengloss-v1.1')
