INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('scale_noun_0', 'scale', 'noun', 0, 'A set of evenly spaced marks and labels on a measuring tool or drawing that show units or values.', '["ruler", "graduation", "tick mark", "measurement scale"]', '[]', '["measuring device", "mathematical tool", "representation"]', '["ruler", "graduated ruler", "number line"]', '["scale factor", "scale drawing", "map scale", "axis scale", "number scale", "measurement scale"]', '{"noun_forms": ["scaling", "scaler"], "verb_forms": ["scale", "rescale"], "adjective_forms": ["scalable", "scaled"], "adverb_forms": []}', '["Mark centimeters on the ruler scale before measuring the wooden block.", "Use the scale on the number line to add distances accurately."]', 'science', '2', 138428, 2419, NULL, 'opengloss-v1.1'),
('scale_verb_0', 'scale', 'verb', 0, 'To multiply all linear measurements of a geometric figure by a constant factor to change its size while preserving its shape and proportions.', '["resize", "dilate", "enlarge", "shrink"]', '[]', '["transform", "operation", "change"]', '["scale up", "scale down", "scale by factor"]', '["scale factor", "scale drawing", "scale model", "scale up", "scale down"]', '{"noun_forms": ["scale", "scaling", "scale factor"], "verb_forms": [], "adjective_forms": ["scaled", "scalable"], "adverb_forms": []}', '["Scale the triangle by factor three to create a similar larger triangle.", "When you scale a rectangle by one half each side becomes half as long."]', 'science', '2', 138428, 2419, NULL, 'opengloss-v1.1'),
('scale_noun_1', 'scale', 'noun', 1, 'A ratio that compares the size of a drawing or model to the actual object used to enlarge or reduce lengths.', '["scale factor", "ratio", "proportion", "map scale"]', '[]', '["ratio", "multiplicative relation", "mathematical relationship"]', '["model scale", "drawing scale", "blueprint scale"]', '["scale factor", "scale drawing", "map scale", "axis scale", "number scale", "measurement scale"]', '{"noun_forms": ["scaling", "scaler"], "verb_forms": ["scale", "rescale"], "adjective_forms": ["scalable", "scaled"], "adverb_forms": []}', '["Apply the scale factor to every side to make the model larger.", "If the map scale is one to fifty convert map distance to real distance."]', 'science', '2', 138428, 2419, NULL, 'opengloss-v1.1'),
('scale_verb_1', 'scale', 'verb', 1, 'To change the numerical range or units of an axis or dataset so values compare correctly across different measures.', '["rescale", "adjust", "compress", "stretch"]', '[]', '["transform", "adjustment", "operation"]', '["rescale axis", "change units", "normalize data"]', '["scale factor", "scale drawing", "scale model", "scale up", "scale down"]', '{"noun_forms": ["scale", "scaling", "scale factor"], "verb_forms": [], "adjective_forms": ["scaled", "scalable"], "adverb_forms": []}', '["Rescale the vertical axis so the data points show variation clearly.", "When you scale the axis from meters to centimeters multiply all values by one hundred."]', 'science', '2', 138428, 2419, NULL, 'opengloss-v1.1'),
('scale_noun_2', 'scale', 'noun', 2, 'A labeled sequence of numbers on a graph axis that shows equal intervals for plotting values.', '["axis scale", "number scale", "value scale", "graph axis"]', '[]', '["graph feature", "coordinate component", "mathematical representation"]', '["x axis scale", "y axis scale", "equal interval scale"]', '["scale factor", "scale drawing", "map scale", "axis scale", "number scale", "measurement scale"]', '{"noun_forms": ["scaling", "scaler"], "verb_forms": ["scale", "rescale"], "adjective_forms": ["scalable", "scaled"], "adverb_forms": []}', '["Choose a clear axis scale so points spread evenly across the graph.", "Label the number scale using consistent intervals of two or five."]', 'science', '2', 138428, 2419, NULL, 'opengloss-v1.1')
