-- lexi ETL: mining (2026-09-18T16:20:16Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('mining_noun_0', 'mining', 'noun', 0, 'The industrial process or activity of extracting minerals, metals, or other geological materials from the earth, typically from ore bodies, lodes, seams, or reefs.', '["extraction", "excavation", "quarrying"]', '["reclamation", "conservation"]', '["industry", "resource_extraction"]', '["coal_mining", "gold_mining"]', '["mining_industry", "coal_mining", "mining_operations", "data_mining"]', '{"noun_forms": ["miner", "mineshaft"], "verb_forms": ["mine", "undermine"], "adjective_forms": ["mined_out", "mineral"], "adverb_forms": ["industrially"]}', '["Mining has historically played a central role in regional economic development.", "Open-pit mining can result in significant changes to local landscapes and ecosystems."]', 'science', '3', 138269, 2423, NULL, 'opengloss-v1.1'),
('mining_verb_0', 'mining', 'verb', 0, 'Present participle of mine: engaging in the act of extracting minerals or other geological materials from the earth.', '["extracting", "excavating", "quarrying"]', '["restoring", "rehabilitating"]', '["harvesting", "exploiting"]', '["strip_mining", "deep_mining"]', '["mining_for_data", "mining_resources", "mining_information", "mining_ore"]', '{"noun_forms": ["miner", "mining"], "verb_forms": ["undermine", "reopen_mine"], "adjective_forms": ["mined_out", "mineral"], "adverb_forms": ["minimally"]}', '["The company is currently mining in three adjacent valleys.", "By 2030, the consortium expects to be mining at greater ocean depths."]', 'science', '3', 138269, 2423, NULL, 'opengloss-v1.1'),
('mining_noun_1', 'mining', 'noun', 1, 'The commercial sector and institutions associated with the extraction and initial processing of mineral resources, including companies, regulatory bodies, and labor organizations.', '["mining_industry", "extractive_sector"]', '["service_sector"]', '["economic_sector", "primary_industry"]', '["artisanal_mining", "large_scale_mining"]', '["mining_industry", "coal_mining", "mining_operations", "data_mining"]', '{"noun_forms": ["miner", "mineshaft"], "verb_forms": ["mine", "undermine"], "adjective_forms": ["mined_out", "mineral"], "adverb_forms": ["industrially"]}', '["The mining of the region is dominated by multinational corporations.", "Regulatory reforms transformed the governance of mining in the late twentieth century."]', 'science', '3', 138269, 2423, NULL, 'opengloss-v1.1'),
('mining_verb_1', 'mining', 'verb', 1, 'Present participle of mine: systematically extracting useful information or patterns from a large collection of data, documents, or other materials.', '["analyzing", "scrutinizing", "probing"]', '["overlooking", "ignoring"]', '["processing", "researching"]', '["data_mining", "text_mining"]', '["mining_for_data", "mining_resources", "mining_information", "mining_ore"]', '{"noun_forms": ["miner", "mining"], "verb_forms": ["undermine", "reopen_mine"], "adjective_forms": ["mined_out", "mineral"], "adverb_forms": ["minimally"]}', '["Researchers are mining historical archives to reconstruct climate variability.", "The algorithm is continuously mining user data to optimize recommendations."]', 'science', '3', 138269, 2423, NULL, 'opengloss-v1.1'),
('mining_noun_2', 'mining', 'noun', 2, 'In data science and computer science, the systematic analysis of large datasets to discover patterns, correlations, or useful information, usually specified by a modifier such as data or text.', '["data_analysis", "pattern_discovery"]', '["data_ignorance"]', '["analysis", "information_extraction"]', '["data_mining", "text_mining"]', '["mining_industry", "coal_mining", "mining_operations", "data_mining"]', '{"noun_forms": ["miner", "mineshaft"], "verb_forms": ["mine", "undermine"], "adjective_forms": ["mined_out", "mineral"], "adverb_forms": ["industrially"]}', '["Data mining has become indispensable in contemporary marketing research.", "Text mining techniques were applied to a corpus of journal articles to identify emerging research trends."]', 'science', '3', 138269, 2423, NULL, 'opengloss-v1.1')
