('lane_noun_0', 'lane', 'noun', 0, 'A designated marked division of a road intended for vehicle traffic, typically narrower than the full roadway and bounded by lane markings or curbs.', '["passage", "track", "roadway", "driving lane"]', '["shoulder"]', '["road feature", "traffic feature"]', '["bus lane", "bike lane", "HOV lane", "turning lane", "passing lane"]', '["driving lane", "bike lane", "bus lane", "swimming lane", "starting lane", "bowling lane"]', '{"noun_forms": ["lanes"], "verb_forms": ["laned", "laning"], "adjective_forms": [], "adverb_forms": []}', '["Vehicles must merge into the left lane before the exit.", "The lane width on this highway is 3.75 meters."]', 'technology', '2', 136116, 2448, NULL, 'opengloss-v1.1'),
('lane_noun_1', 'lane', 'noun', 1, 'A designated strip on a track or pool reserved for a single competitor during a race or competition.', '["track", "strip"]', '[]', '["sports feature", "race facility"]', '["swimming lane", "starting lane", "competition lane"]', '["driving lane", "bike lane", "bus lane", "swimming lane", "starting lane", "bowling lane"]', '{"noun_forms": ["lanes"], "verb_forms": ["laned", "laning"], "adjective_forms": [], "adverb_forms": []}', '["Swimmers must stay within their lane during the relay.", "Starting lanes are assigned by seeding in the meet."]', 'technology', '2', 136116, 2448, NULL, 'opengloss-v1.1'),
