('fuel_noun_0', 'fuel', 'noun', 0, 'A substance that can be burned to release energy for engines or heating.', '["energy source", "propellant", "gas", "oil"]', '["drain"]', '["substance", "energy source"]', '["gasoline", "diesel", "coal", "wood"]', '["fossil fuel", "fuel efficiency", "fuel economy", "fuel source", "fuel pump", "fuel cell"]', '{"noun_forms": ["fueler"], "verb_forms": ["fuel", "fuels", "fueled", "fueling"], "adjective_forms": [], "adverb_forms": []}', '["A car uses fuel to power the engine.", "A furnace needs fuel to heat a room."]', 'science', '3', 135125, 2462, NULL, 'opengloss-v1.1'),
('fuel_verb_0', 'fuel', 'verb', 0, 'To supply fuel to an engine or machine so it can run.', '["energize", "power", "supply energy"]', '["starve", "deplete"]', '["provide energy"]', '["refuel", "gas up", "top up"]', '["fuel the engine", "fuel a fire", "fuel growth", "fuel demand", "fuel debate", "fuel curiosity"]', '{"noun_forms": ["fueler"], "verb_forms": ["refuel"], "adjective_forms": [], "adverb_forms": []}', '["Mechanics fueled the car''s engine to start.", "We fuel the bus''s engine for the field trip."]', 'science', '3', 135125, 2462, NULL, 'opengloss-v1.1'),
('fuel_noun_1', 'fuel', 'noun', 1, 'Something that provides energy or motivation for a process or idea.', '["inspiration", "stimulus", "motivation"]', '["drain", "disincentive"]', '["resource", "support"]', '["idea", "creativity", "planning"]', '["fossil fuel", "fuel efficiency", "fuel economy", "fuel source", "fuel pump", "fuel cell"]', '{"noun_forms": ["fueler"], "verb_forms": ["fuel", "fuels", "fueled", "fueling"], "adjective_forms": [], "adverb_forms": []}', '["Curiosity is fuel for learning.", "Regular study sessions fuel progress in math."]', 'science', '3', 135125, 2462, NULL, 'opengloss-v1.1'),
