('dvd_noun_0', 'dvd', 'noun', 0, 'A digital optical storage medium standardized for data and video, commonly storing 4.7 GB on a single layer and up to 8.5 GB on a dual layer, used for media distribution and data archival.', '["digital video disc", "digital versatile disc"]', '["cd"]', '["optical disc", "storage medium"]', '["DVD-ROM", "DVD-R", "DVD-RW", "DVD+R", "DVD+RW"]', '["dvd player", "dvd drive", "dvd rom", "dual layer dvd", "region code", "copy protection"]', '{"noun_forms": ["digital versatile disc", "digital video disc"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Datasets were archived on a DVD for distribution among researchers.", "Course materials were provided on a single DVD to participants."]', 'technology', '3', 133663, 2489, NULL, 'opengloss-v1.1'),
('dvd_noun_1', 'dvd', 'noun', 1, 'A format within the DVD family for packaging consumer video content on discs, featuring interactive menus, multiple audio tracks, subtitles, and region coding.', '["dvd video", "dvd-Video"]', '["streaming video"]', '["video format", "disc format", "optical disc format"]', '["dvd-menu", "audio track", "subtitle track"]', '["dvd player", "dvd drive", "dvd rom", "dual layer dvd", "region code", "copy protection"]', '{"noun_forms": ["digital versatile disc", "digital video disc"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The DVD-Video specification supports interactive menus and multiple audio streams.", "Lectures were released on DVD-Video discs with multilingual subtitles."]', 'technology', '3', 133663, 2489, NULL, 'opengloss-v1.1')
