BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('manufacturing_noun_0', 'manufacturing', 'noun', 0, 'The industrial process of transforming raw materials, components, or parts into finished goods using machinery, tools, labor, and standardized procedures, typically on a large scale.', '["production", "fabrication", "industrial processing"]', '["consumption", "disposal"]', '["production", "industry"]', '["lean manufacturing", "additive manufacturing"]', '["advanced manufacturing", "manufacturing sector", "manufacturing process", "manufacturing industry"]', '{"noun_forms": ["manufacture", "manufacturer", "manufacturability"], "verb_forms": ["manufacture"], "adjective_forms": ["manufactured", "manufacturable", "manufacturing"], "adverb_forms": ["industrially"]}', '["Manufacturing plays a central role in the economic development of many countries.", "Advances in automation have significantly increased the efficiency of modern manufacturing."]', 'technology', '7', 133587, 2493, NULL, 'opengloss-v1.1'),
('manufacturing_verb_0', 'manufacturing', 'verb', 0, 'Present participle of manufacture: engaging in the process of producing goods from raw materials or components, especially in a systematic, industrial manner.', '["producing", "fabricating", "processing"]', '["consuming", "destroying"]', '["making", "creating"]', '["mass producing", "handcrafting"]', '["manufacturing goods", "manufacturing products", "manufacturing evidence", "manufacturing components"]', '{"noun_forms": ["manufacturing", "manufacture", "manufacturer"], "verb_forms": ["remanufacture"], "adjective_forms": ["manufactured", "manufacturing"], "adverb_forms": ["industrially"]}', '["The company is currently manufacturing parts for several major automobile brands.", "Firms manufacturing medical equipment must comply with strict regulatory standards."]', 'technology', '7', 133587, 2493, NULL, 'opengloss-v1.1'),
('manufacturing_noun_1', 'manufacturing', 'noun', 1, 'The specific sector of the economy composed of organizations whose primary activity is the large-scale production of tangible goods rather than services.', '["manufacturing sector", "industrial sector", "factory industry"]', '["service sector", "agriculture"]', '["economic sector", "secondary sector"]', '["automotive manufacturing", "electronics manufacturing"]', '["advanced manufacturing", "manufacturing sector", "manufacturing process", "manufacturing industry"]', '{"noun_forms": ["manufacture", "manufacturer", "manufacturability"], "verb_forms": ["manufacture"], "adjective_forms": ["manufactured", "manufacturable", "manufacturing"], "adverb_forms": ["industrially"]}', '["Employment in manufacturing has declined in some regions due to globalization and offshoring.", "Government policies can significantly affect the competitiveness of domestic manufacturing."]', 'technology', '7', 133587, 2493, NULL, 'opengloss-v1.1'),
('manufacturing_verb_1', 'manufacturing', 'verb', 1, 'Present participle of manufacture: creating or generating something that is not genuine, often with the implication of deception or artificiality.', '["faking", "forging", "inventing"]', '["authenticating", "verifying"]', '["creating", "generating"]', '["forging documents", "fabricating data"]', '["manufacturing goods", "manufacturing products", "manufacturing evidence", "manufacturing components"]', '{"noun_forms": ["manufacturing", "manufacture", "manufacturer"], "verb_forms": ["remanufacture"], "adjective_forms": ["manufactured", "manufacturing"], "adverb_forms": ["industrially"]}', '["The committee accused the group of manufacturing evidence to support its claims.", "Some media outlets were criticized for manufacturing outrage to attract viewers."]', 'technology', '7', 133587, 2493, NULL, 'opengloss-v1.1'),
('manufacturing_noun_2', 'manufacturing', 'noun', 2, 'The act or activity of making something by hand or by mechanical means, especially when emphasizing the method, quality, or scale of production.', '["making", "crafting", "construction"]', '["neglect", "nonproduction"]', '["creation", "construction"]', '["mass manufacturing", "custom manufacturing"]', '["advanced manufacturing", "manufacturing sector", "manufacturing process", "manufacturing industry"]', '{"noun_forms": ["manufacture", "manufacturer", "manufacturability"], "verb_forms": ["manufacture"], "adjective_forms": ["manufactured", "manufacturable", "manufacturing"], "adverb_forms": ["industrially"]}', '["The study compares traditional manufacturing with digital fabrication techniques.", "High-precision manufacturing is essential for the aerospace industry."]', 'technology', '7', 133587, 2493, NULL, 'opengloss-v1.1')
