BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('signal_adjective_0', 'signal', 'adjective', 0, 'easily seen or noticed; obvious or important; standing out in a way that attracts attention.', '["evident", "conspicuous", "notable", "apparent", "clear"]', '["insignificant", "unremarkable", "minor"]', '["descriptor", "quality"]', '["conspicuous", "evident"]', '["signal processing", "signal strength", "signal detection", "signal integrity", "signal cue", "signal indicator"]', '{"noun_forms": ["signaler", "signalization"], "verb_forms": ["signalize", "signalized", "signaling"], "adjective_forms": ["signalable"], "adverb_forms": []}', '["The data showed a signal improvement in test scores.", "The chart revealed a signal difference between groups."]', 'science', '4', 133339, 2497, NULL, 'opengloss-v1.1'),
('signal_noun_0', 'signal', 'noun', 0, 'A sign or cue that conveys information about a situation or outcome.', '["indicator", "cue", "sign", "token"]', '[]', '["information", "indicator"]', '["traffic signal", "alarm signal", "smoke signal"]', '["traffic signal", "signal strength", "signal word", "emergency signal", "signal processing"]', '{"noun_forms": ["signaler", "signaling"], "verb_forms": ["signals", "signalized", "signaling"], "adjective_forms": ["signal-based"], "adverb_forms": ["signal-wise"]}', '["The flag raised at noon is a signal to begin class.", "A rising grade on the test acts as a signal that understanding grows."]', 'science', '4', 133339, 2497, NULL, 'opengloss-v1.1'),
('signal_verb_0', 'signal', 'verb', 0, 'To convey information or a message to others by signs or actions.', '["inform", "convey", "indicate"]', '["conceal", "hide", "ignore"]', '["inform", "communicate"]', '["gesture", "smile"]', '["signal strength", "signal device", "signal flag", "signal light", "signaling device", "signal processing"]', '{"noun_forms": ["signaler", "signaling"], "verb_forms": ["signalize"], "adjective_forms": [], "adverb_forms": []}', '["The teacher signaled understanding with a nod.", "A green light signals that the crossing is safe."]', 'science', '4', 133339, 2497, NULL, 'opengloss-v1.1'),
('signal_adjective_1', 'signal', 'adjective', 1, 'relating to or used to convey a signal; designed to indicate or transmit information.', '["indicative", "informative", "transmitting"]', '["uninformative", "undetectable"]', '["descriptor", "quality"]', '["indicating", "transmitting"]', '["signal processing", "signal strength", "signal detection", "signal integrity", "signal cue", "signal indicator"]', '{"noun_forms": ["signaler", "signalization"], "verb_forms": ["signalize", "signalized", "signaling"], "adjective_forms": ["signalable"], "adverb_forms": []}', '["The red light is a signal cue indicating when to stop.", "A clear signal indicating the system status was recorded in logs."]', 'science', '4', 133339, 2497, NULL, 'opengloss-v1.1'),
('signal_noun_1', 'signal', 'noun', 1, 'A device that conveys information by emitting light, sound, or other signals.', '["device", "instrument", "apparatus"]', '[]', '["device", "instrument", "means of communication"]', '["traffic signal", "alarm signal", "radio signal"]', '["traffic signal", "signal strength", "signal word", "emergency signal", "signal processing"]', '{"noun_forms": ["signaler", "signaling"], "verb_forms": ["signals", "signalized", "signaling"], "adjective_forms": ["signal-based"], "adverb_forms": ["signal-wise"]}', '["Solar lights function as a signal device for warning.", "A loud alarm is an emergency signal to evacuate."]', 'science', '4', 133339, 2497, NULL, 'opengloss-v1.1'),
('signal_verb_1', 'signal', 'verb', 1, 'To prompt or guide someone to take a course of action by a sign or cue.', '["cue", "prompt", "trigger"]', '["ignore", "disregard", "overlook"]', '["inform", "communicate", "prompt"]', '["cue", "prompt"]', '["signal strength", "signal device", "signal flag", "signal light", "signaling device", "signal processing"]', '{"noun_forms": ["signaler", "signaling"], "verb_forms": ["signalize"], "adjective_forms": [], "adverb_forms": []}', '["The coach signaled the players to start.", "The teacher signaled the class to quiet down."]', 'science', '4', 133339, 2497, NULL, 'opengloss-v1.1'),
('signal_noun_2', 'signal', 'noun', 2, 'In data analysis, a detectable pattern that stands out from background noise and carries information.', '["pattern", "trace", "indicator"]', '["noise"]', '["data pattern", "information"]', '["digital signal", "analog signal"]', '["traffic signal", "signal strength", "signal word", "emergency signal", "signal processing"]', '{"noun_forms": ["signaler", "signaling"], "verb_forms": ["signals", "signalized", "signaling"], "adjective_forms": ["signal-based"], "adverb_forms": ["signal-wise"]}', '["Researchers try to separate the signal from the noise in the data.", "A clear signal shows the trend despite random fluctuations."]', 'science', '4', 133339, 2497, NULL, 'opengloss-v1.1'),
('signal_verb_2', 'signal', 'verb', 2, 'To indicate the status or presence of something via a device or indicator.', '["indicate", "show", "signal"]', '["conceal", "mask", "hide"]', '["inform", "indicate"]', '["alarm", "indicator"]', '["signal strength", "signal device", "signal flag", "signal light", "signaling device", "signal processing"]', '{"noun_forms": ["signaler", "signaling"], "verb_forms": ["signalize"], "adjective_forms": [], "adverb_forms": []}', '["The warning light signals an error on the panel.", "The beeping sound signals low battery."]', 'science', '4', 133339, 2497, NULL, 'opengloss-v1.1')
