BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('joining_noun_0', 'joining', 'noun', 0, 'The act or process of connecting or bringing two or more things together so that they form a whole or are in contact.', '["connection", "linking", "union"]', '["separation", "division"]', '["combination", "attachment"]', '["welding", "splicing"]', '["joining process", "joining technique", "joining of materials", "joining point"]', '{"noun_forms": ["joint", "junction"], "verb_forms": ["join", "rejoin"], "adjective_forms": ["joint", "joined"], "adverb_forms": ["jointly"]}', '["The careful joining of the metal parts ensured the structure would withstand heavy loads.", "In sociology, the joining of different social groups can create new cultural patterns."]', 'technology', '1', 131716, 2525, NULL, 'opengloss-v1.1'),
('joining_verb_0', 'joining', 'verb', 0, 'Present participle of join: to connect or fasten things together so that they form a continuous whole or are in contact.', '["connecting", "linking", "attaching"]', '["separating", "disconnecting"]', '["combining", "uniting"]', '["welding", "soldering"]', '["joining together", "joining forces", "joining a group", "joining data"]', '{"noun_forms": ["joining", "joint", "junction"], "verb_forms": ["rejoin", "join up"], "adjective_forms": ["joined", "joint"], "adverb_forms": ["jointly"]}', '["The researcher is joining the data sets to create a comprehensive database.", "By joining the two pipes, the technician restored the flow of water."]', 'technology', '1', 131716, 2525, NULL, 'opengloss-v1.1'),
('joining_noun_1', 'joining', 'noun', 1, 'A place, point, or line at which two or more things are connected or meet.', '["junction", "joint", "seam"]', '["gap"]', '["intersection", "interface"]', '["butt joint", "lap joint"]', '["joining process", "joining technique", "joining of materials", "joining point"]', '{"noun_forms": ["joint", "junction"], "verb_forms": ["join", "rejoin"], "adjective_forms": ["joint", "joined"], "adverb_forms": ["jointly"]}', '["Moisture often seeps in at the joining between the window frame and the wall.", "Engineers inspected each joining of the bridge segments for signs of stress."]', 'technology', '1', 131716, 2525, NULL, 'opengloss-v1.1'),
('joining_verb_1', 'joining', 'verb', 1, 'Present participle of join: to become a member of a group, organization, or activity.', '["enrolling", "entering", "participating"]', '["leaving", "resigning"]', '["engaging", "associating"]', '["enlisting", "subscribing"]', '["joining together", "joining forces", "joining a group", "joining data"]', '{"noun_forms": ["joining", "joint", "junction"], "verb_forms": ["rejoin", "join up"], "adjective_forms": ["joined", "joint"], "adverb_forms": ["jointly"]}', '["Many students are joining the seminar to deepen their understanding of ethics.", "She is joining the committee to contribute her expertise in public policy."]', 'technology', '1', 131716, 2525, NULL, 'opengloss-v1.1'),
