('documents_noun_0', 'documents', 'noun', 0, 'A written or printed record that provides information or proof; a document such as a form, certificate, or report.', '["record", "paper", "certificate", "deed"]', '["verbal account", "oral record"]', '["record"]', '["birth certificate", "deed", "license", "passport", "invoice"]', '["official documents", "legal documents", "research documents", "student documents", "confidential documents", "document folder"]', '{"noun_forms": ["documentation", "documentarian"], "verb_forms": ["document", "documented", "documenting"], "adjective_forms": ["documentary"], "adverb_forms": []}', '["The clerk filed the consent document for the school trip.", "A birth certificate is a common personal document used for identification."]', 'technology', '2', 129267, 2573, NULL, 'opengloss-v1.1'),
('documents_verb_0', 'documents', 'verb', 0, 'To put information, events, or facts into written or electronic form for others to study.', '["record", "log", "file"]', '["erase", "omit", "delete"]', '["recording", "logging"]', '["lab note", "lab report", "journal entry"]', '["document facts", "document sources", "document evidence", "document findings", "document records", "document process"]', '{"noun_forms": ["documentation"], "verb_forms": ["documenting"], "adjective_forms": ["documented"], "adverb_forms": ["documentedly"]}', '["The scientist documents observations in a lab notebook.", "Students document the steps of their experiment in a science journal."]', 'technology', '2', 129267, 2573, NULL, 'opengloss-v1.1'),
('documents_noun_1', 'documents', 'noun', 1, 'An official legal paper that proves ownership or a right, or status; such as a deed or contract.', '["deed", "title", "contract", "instrument", "certificate"]', '["oral word", "informal note"]', '["record", "paper"]', '["birth certificate", "will", "lease agreement", "power of attorney"]', '["official documents", "legal documents", "research documents", "student documents", "confidential documents", "document folder"]', '{"noun_forms": ["documentation", "documentarian"], "verb_forms": ["document", "documented", "documenting"], "adjective_forms": ["documentary"], "adverb_forms": []}', '["The title is the document that proves ownership of the car.", "A contract is a document that binds two parties."]', 'technology', '2', 129267, 2573, NULL, 'opengloss-v1.1'),
('documents_verb_1', 'documents', 'verb', 1, 'To provide documents or other written proof that support a claim or requirement.', '["provide", "furnish", "supply"]', '["withhold", "conceal", "destroy"]', '["provide materials", "documentation"]', '["signed form", "certificate", "receipt"]', '["document facts", "document sources", "document evidence", "document findings", "document records", "document process"]', '{"noun_forms": ["documentation"], "verb_forms": ["documenting"], "adjective_forms": ["documented"], "adverb_forms": ["documentedly"]}', '["The applicant documents their income with pay stubs.", "The librarian documents the loan with a signed form."]', 'technology', '2', 129267, 2573, NULL, 'opengloss-v1.1'),
('documents_noun_2', 'documents', 'noun', 2, 'An electronic file that contains text, images, or data; a digital document.', '["file", "PDF", "text document", "word document"]', '["paper document"]', '["record", "information"]', '["PDF file", "Word document", "Google document", "Excel file"]', '["official documents", "legal documents", "research documents", "student documents", "confidential documents", "document folder"]', '{"noun_forms": ["documentation", "documentarian"], "verb_forms": ["document", "documented", "documenting"], "adjective_forms": ["documentary"], "adverb_forms": []}', '["Students save their science report as a PDF document.", "The teacher shared the assignment as a Word document."]', 'technology', '2', 129267, 2573, NULL, 'opengloss-v1.1'),
