BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('disc_noun_0', 'disc', 'noun', 0, 'A flat circular object or surface; a thin, flat, circular plate used in mechanical, electrical, and manufacturing contexts.', '["disk", "plate", "wafer"]', '["solid"]', '["flat object", "object"]', '["brake disc", "flywheel disc", "optical disc"]', '["disc brake", "optical disc", "compact disc", "galactic disc", "intervertebral disc", "disc drive"]', '{"noun_forms": ["disk"], "verb_forms": [], "adjective_forms": ["discoid"], "adverb_forms": []}', '["A metal disc was machined to precise diameter.", "The sensor used a ceramic disc as its dielectric element."]', 'technology', '1', 126025, 2628, NULL, 'opengloss-v1.1'),
('disc_verb_0', 'disc', 'verb', 0, 'In agriculture, to disc is to till or turn over soil by passing a disc harrow over a field, breaking up clods, improving aeration and drainage to prepare a seedbed.', '["till", "cultivate", "harrow"]', '["compact", "compress"]', '["soil tillage", "agricultural operation", "soil preparation"]', '["deep tillage", "field tillage", "disc harrowing"]', '["soil tillage", "disc harrow", "field tillage", "seedbed preparation", "loosen soil", "crop residue management"]', '{"noun_forms": [], "verb_forms": ["discing"], "adjective_forms": [], "adverb_forms": []}', '["Farmers disc the field after harvest to prepare the seedbed for planting.", "The operator disced the soil to reduce clod formation and promote drainage."]', 'technology', '1', 126025, 2628, NULL, 'opengloss-v1.1'),
('disc_noun_1', 'disc', 'noun', 1, 'An anatomical fibrocartilaginous cushion between adjacent vertebrae.', '["vertebral disc", "spinal disc"]', '["bone"]', '["anatomical structure"]', '["cervical disc", "lumbar disc"]', '["disc brake", "optical disc", "compact disc", "galactic disc", "intervertebral disc", "disc drive"]', '{"noun_forms": ["disk"], "verb_forms": [], "adjective_forms": ["discoid"], "adverb_forms": []}', '["Degenerative disc disease can reduce intervertebral height.", "An herniated intervertebral disc compresses nearby nerves."]', 'technology', '1', 126025, 2628, NULL, 'opengloss-v1.1'),
('disc_noun_2', 'disc', 'noun', 2, 'A circular data storage medium read by laser, used for information and media storage.', '["CD", "DVD", "Blu-ray"]', '[]', '["data storage medium"]', '["compact disc", "digital versatile disc", "blu ray disc"]', '["disc brake", "optical disc", "compact disc", "galactic disc", "intervertebral disc", "disc drive"]', '{"noun_forms": ["disk"], "verb_forms": [], "adjective_forms": ["discoid"], "adverb_forms": []}', '["CDs and DVDs are optical discs used for data storage.", "The optical disc read head detects microscopic pits and lands."]', 'technology', '1', 126025, 2628, NULL, 'opengloss-v1.1'),
('disc_noun_3', 'disc', 'noun', 3, 'The planar, rotating component of a spiral galaxy, consisting of stars and interstellar material.', '["galaxy disc", "stellar disc"]', '["galactic halo"]', '["galactic structure"]', '["stellar disc", "gas disc", "dust disc"]', '["disc brake", "optical disc", "compact disc", "galactic disc", "intervertebral disc", "disc drive"]', '{"noun_forms": ["disk"], "verb_forms": [], "adjective_forms": ["discoid"], "adverb_forms": []}', '["The Milky Way’s disc contains most of its stars and gas.", "Thin and thick discs show different kinematic properties."]', 'technology', '1', 126025, 2628, NULL, 'opengloss-v1.1')
