('net_adjective_0', 'net', 'adjective', 0, 'In accounting and finance, the net amount is the final value remaining after deductions such as taxes, returns, and allowances have been subtracted from the gross amount.', '["take-home", "after deductions"]', '["gross"]', '["financial measure", "economic quantity"]', '["net income", "net profit", "net revenue", "net weight"]', '["net income", "net profit", "net revenue", "net weight", "net cash flow", "net fabric"]', '{"noun_forms": ["netting"], "verb_forms": ["net", "nets", "netted", "netting"], "adjective_forms": ["netlike"], "adverb_forms": []}', '["Net income rose after all operating costs were accounted.", "The net cash flow indicates liquidity after debt payments."]', 'technology', '3', 125345, 2639, NULL, 'opengloss-v1.1'),
('net_noun_0', 'net', 'noun', 0, 'In information technology and computer networks, net is a system of interconnected computing devices and pathways enabling communication and resource sharing within a defined scope.', '["network"]', '["isolation", "disconnection"]', '["system", "infrastructure"]', '["LAN", "WAN", "intranet", "VPN"]', '["net income", "net profit", "net loss", "net neutrality", "fishing net", "gillnet"]', '{"noun_forms": ["netter", "netting"], "verb_forms": ["netted", "netting", "nets"], "adjective_forms": ["netlike"], "adverb_forms": ["netwise"]}', '["The net interconnects servers across the data center.", "Researchers study net topology to optimize reliability and throughput."]', 'technology', '3', 125345, 2639, NULL, 'opengloss-v1.1'),
('net_verb_0', 'net', 'verb', 0, 'To catch or capture (an animal or object) using a net, typically in wildlife study, fisheries, or experimental contexts.', '["catch", "capture", "ensnare", "trap"]', '["release", "free"]', '["capture"]', '["snare", "trapping"]', '["net profit", "net income", "net revenue", "net gain", "net earnings"]', '{"noun_forms": ["netting", "netter"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The researchers netted specimens in a mangrove habitat during the field study.", "The survey netted data from 12 sites across three regions."]', 'technology', '3', 125345, 2639, NULL, 'opengloss-v1.1'),
('net_adjective_1', 'net', 'adjective', 1, 'Mesh-like; having an open weave or structure resembling a net, typically applied to fabrics or materials.', '["mesh", "mesh fabric", "netting", "lattice"]', '["solid", "dense"]', '["fabric type", "material property"]', '["netting", "mesh fabric", "open mesh"]', '["net income", "net profit", "net revenue", "net weight", "net cash flow", "net fabric"]', '{"noun_forms": ["netting"], "verb_forms": ["net", "nets", "netted", "netting"], "adjective_forms": ["netlike"], "adverb_forms": []}', '["The sample employed a net fabric suitable for lightweight filtration.", "Net-like materials offer high porosity for airflow."]', 'technology', '3', 125345, 2639, NULL, 'opengloss-v1.1'),
('net_noun_1', 'net', 'noun', 1, 'Net income is the amount of earnings remaining after deductions, taxes, and other expenses are subtracted from gross income.', '["profit", "earnings"]', '["gross", "loss"]', '["income", "profit"]', '["net profit", "net earnings", "net revenue"]', '["net income", "net profit", "net loss", "net neutrality", "fishing net", "gillnet"]', '{"noun_forms": ["netter", "netting"], "verb_forms": ["netted", "netting", "nets"], "adjective_forms": ["netlike"], "adverb_forms": ["netwise"]}', '["The firm reported net income after depreciation.", "Net income rose despite higher operating costs."]', 'technology', '3', 125345, 2639, NULL, 'opengloss-v1.1'),
('net_verb_1', 'net', 'verb', 1, 'To yield a net amount after deductions and expenses; to result in a net profit, net income, or net gain.', '["earn", "realize", "generate", "accrue"]', '["lose"]', '["obtain"]', '["profit", "revenue", "gain"]', '["net profit", "net income", "net revenue", "net gain", "net earnings"]', '{"noun_forms": ["netting", "netter"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The project netted a profit of 2 million after expenses.", "Policy reforms netted significant savings for the department."]', 'technology', '3', 125345, 2639, NULL, 'opengloss-v1.1'),
('net_noun_2', 'net', 'noun', 2, 'A mesh or fabric device used to catch fish, birds, or other animals.', '["fishing net", "mesh"]', '["hook and line", "netless"]', '["fishing gear", "catching device"]', '["gillnet", "seine", "driftnet"]', '["net income", "net profit", "net loss", "net neutrality", "fishing net", "gillnet"]', '{"noun_forms": ["netter", "netting"], "verb_forms": ["netted", "netting", "nets"], "adjective_forms": ["netlike"], "adverb_forms": ["netwise"]}', '["Gillnets are deployed to harvest migratory fish.", "The seine is a type of fishing net used in coastal operations."]', 'technology', '3', 125345, 2639, NULL, 'opengloss-v1.1')
