-- lexi ETL: tank (2026-09-18T16:20:18Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('tank_noun_0', 'tank', 'noun', 0, 'A large container designed to hold liquids or gases for storage and distribution.', '["container", "vessel", "receptacle", "holding tank"]', '["uncontained", "unfilled"]', '["container", "vessel", "receptacle"]', '["water tank", "fuel tank", "storage tank"]', '["fuel tank", "water tank", "storage tank", "battle tank", "main battle tank", "tank crew"]', '{"noun_forms": ["tankage", "tankful"], "verb_forms": [], "adjective_forms": ["tanklike", "tanky"], "adverb_forms": []}', '["The water tank supplies the greenhouse irrigation system.", "Aircraft fuel tanks must meet safety standards for aviation."]', 'technology', '2', 124257, 2659, NULL, 'opengloss-v1.1'),
('tank_verb_0', 'tank', 'verb', 0, 'To fill, load, or stock a tank or reservoir with a liquid or other material.', '["fill", "load", "charge", "stock"]', '["empty", "drain"]', '["store verb"]', '["fuel", "water"]', '["fuel tank", "water tank", "gas tank", "oil tank", "tank capacity", "tank pressure"]', '{"noun_forms": ["tankage", "tankful"], "verb_forms": [], "adjective_forms": ["tanklike"], "adverb_forms": []}', '["Researchers tank the reactor with cooling water.", "Laboratory staff tank the storage tank with saline solution."]', 'technology', '2', 124257, 2659, NULL, 'opengloss-v1.1'),
('tank_noun_1', 'tank', 'noun', 1, 'A tracked armored combat vehicle designed to engage enemy forces and support infantry.', '["armored vehicle", "battle tank", "combat tank"]', '["soft skinned vehicle", "unarmored vehicle", "noncombat vehicle"]', '["military vehicle", "land vehicle", "combat vehicle"]', '["main battle tank", "light tank", "heavy tank"]', '["fuel tank", "water tank", "storage tank", "battle tank", "main battle tank", "tank crew"]', '{"noun_forms": ["tankage", "tankful"], "verb_forms": [], "adjective_forms": ["tanklike", "tanky"], "adverb_forms": []}', '["Tanks rolled across the valley during the offensive.", "The main battle tank led the assault with heavy armor."]', 'technology', '2', 124257, 2659, NULL, 'opengloss-v1.1'),
('tank_verb_1', 'tank', 'verb', 1, 'To perform very poorly or fail in a game, test, or competition, often despite prior preparation.', '["bomb", "flop", "fail", "underperform"]', '["excel", "shine", "perform well"]', '["fail"]', '["bomb", "flop", "crash"]', '["fuel tank", "water tank", "gas tank", "oil tank", "tank capacity", "tank pressure"]', '{"noun_forms": ["tankage", "tankful"], "verb_forms": [], "adjective_forms": ["tanklike"], "adverb_forms": []}', '["The team tanked the game after a rough start.", "She tanked the exam due to time constraints."]', 'technology', '2', 124257, 2659, NULL, 'opengloss-v1.1'),
('tank_noun_2', 'tank', 'noun', 2, 'In multiplayer video games, a frontline role characterized by high durability and threat generation.', '["defender", "frontline tank", "meat shield"]', '["glass cannon", "damage dealer", "fragile target"]', '["game role", "character class"]', '["aggro tank", "meat shield", "shield bearer"]', '["fuel tank", "water tank", "storage tank", "battle tank", "main battle tank", "tank crew"]', '{"noun_forms": ["tankage", "tankful"], "verb_forms": [], "adjective_forms": ["tanklike", "tanky"], "adverb_forms": []}', '["In team based games the tank absorbs damage and draws aggro.", "Players select the tank role to protect ranged allies."]', 'technology', '2', 124257, 2659, NULL, 'opengloss-v1.1'),
('tank_verb_2', 'tank', 'verb', 2, 'To fall sharply in value or level, especially of stock prices or assets.', '["plunge", "crash", "dive", "drop"]', '["rise", "increase", "recover"]', '["decline"]', '["plunge", "crash", "dive"]', '["fuel tank", "water tank", "gas tank", "oil tank", "tank capacity", "tank pressure"]', '{"noun_forms": ["tankage", "tankful"], "verb_forms": [], "adjective_forms": ["tanklike"], "adverb_forms": []}', '["The stock tanked after the earnings miss.", "Oil prices tanked following the supply news."]', 'technology', '2', 124257, 2659, NULL, 'opengloss-v1.1')
