('designer_adjective_0', 'designer', 'adjective', 0, 'Of clothing or other items made by a famous designer or brand, usually expensive and fashionable.', '["fashionable", "stylish", "branded", "premium"]', '["plain", "ordinary", "mass market", "cheap"]', '["style descriptor", "brand descriptor"]', '["couture", "haute couture"]', '["designer clothes", "designer brand", "designer furniture", "designer fabrics", "designer shoes", "designer labels"]', '{"noun_forms": ["design"], "verb_forms": ["design"], "adjective_forms": ["designable", "designerly"], "adverb_forms": ["designably"]}', '["Designer clothes often cost more than plain garments.", "Students compare designer brands with mass market items."]', 'arts', '3', 121427, 2708, NULL, 'opengloss-v1.1'),
('designer_noun_0', 'designer', 'noun', 0, 'A person who plans and creates the design of something, drawing plans or sketches to guide production or construction.', '["creator", "architect", "planner", "maker"]', '[]', '["profession", "occupation", "role"]', '["fashion designer", "graphic designer", "interior designer", "industrial designer"]', '["fashion designer", "graphic designer", "interior designer", "industrial designer", "designer label", "designer bag"]', '{"noun_forms": ["design"], "verb_forms": [], "adjective_forms": ["designerly"], "adverb_forms": []}', '["The designer drew a plan for the new classroom furniture.", "A product designer sketches prototypes before building a model."]', 'arts', '3', 121427, 2708, NULL, 'opengloss-v1.1'),
('designer_adjective_1', 'designer', 'adjective', 1, 'Relating to design or deliberate planning; crafted with careful taste and arrangement.', '["crafted", "engineered", "curated"]', '["careless", "unplanned", "rough"]', '["design quality", "aesthetic quality"]', '["ergonomic", "user friendly"]', '["designer clothes", "designer brand", "designer furniture", "designer fabrics", "designer shoes", "designer labels"]', '{"noun_forms": ["design"], "verb_forms": ["design"], "adjective_forms": ["designable", "designerly"], "adverb_forms": ["designably"]}', '["The classroom layout uses a designer arrangement for clarity.", "A designer approach improves poster design and readability."]', 'arts', '3', 121427, 2708, NULL, 'opengloss-v1.1'),
('designer_noun_1', 'designer', 'noun', 1, 'A designer is a person who creates or selects a distinctive style, especially in clothing or consumer goods.', '["stylist", "fashioner"]', '[]', '["profession", "occupation"]', '["couturier", "visual designer", "web designer"]', '["fashion designer", "graphic designer", "interior designer", "industrial designer", "designer label", "designer bag"]', '{"noun_forms": ["design"], "verb_forms": [], "adjective_forms": ["designerly"], "adverb_forms": []}', '["She is a designer known for bold patterns.", "Designer bags often show the brand''s signature style."]', 'arts', '3', 121427, 2708, NULL, 'opengloss-v1.1')
