-- lexi ETL: audio (2026-09-18T16:20:18Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('audio_adjective_0', 'audio', 'adjective', 0, 'Relating to sound, hearing, or the audible, especially as used in scientific or technical contexts.', '["auditory", "sonic", "acoustic"]', '["silent", "inaudible"]', '["sound property"]', '["audio signal", "audio recording", "audio device"]', '["audio signal", "audio equipment", "audio recording", "audio processing", "audio quality", "audio bandwidth"]', '{"noun_forms": ["audiophile"], "verb_forms": [], "adjective_forms": ["auditory", "audio based"], "adverb_forms": []}', '["The study evaluated audio perception in humans.", "Participants were exposed to audio stimuli presented via headphones."]', 'technology', '2', 120540, 2723, NULL, 'opengloss-v1.1'),
('audio_noun_0', 'audio', 'noun', 0, 'The audible component of a multimedia signal that can be perceived by listeners, comprising speech, music, and other sounds, as distinct from visual content.', '["sound", "audio content", "recording"]', '["silence"]', '["signal", "media_content", "communication"]', '["background_audio", "voiceover", "soundtrack"]', '["audio signal", "audio recording", "audio file", "audio equipment", "audio processing", "audio quality"]', '{"noun_forms": ["audiophile", "audiology", "audiofile", "audibility"], "verb_forms": [], "adjective_forms": ["auditory"], "adverb_forms": []}', '["The audio track contains the speech portion of the recording.", "Researchers analyze the audio for phonetic features."]', 'technology', '2', 120540, 2723, NULL, 'opengloss-v1.1'),
('audio_adjective_1', 'audio', 'adjective', 1, 'Relating to equipment, media, and processes that produce, transmit, or reproduce sound, including hardware and software components used in audio workflows.', '["audio related", "audio oriented", "sonic"]', '["visual only", "non audio"]', '["audio technology"]', '["audio interface", "audio processor", "audio mixer"]', '["audio signal", "audio equipment", "audio recording", "audio processing", "audio quality", "audio bandwidth"]', '{"noun_forms": ["audiophile"], "verb_forms": [], "adjective_forms": ["auditory", "audio based"], "adverb_forms": []}', '["The lab compared audio interfaces and signal chains.", "Software tools enable high fidelity audio processing for experiments."]', 'technology', '2', 120540, 2723, NULL, 'opengloss-v1.1'),
('audio_noun_1', 'audio', 'noun', 1, 'The technology and practice of capturing, processing, transmitting, and reproducing sound, including hardware, software, and workflows used in recording and playback.', '["audio engineering", "sound engineering", "audio technology"]', '["visual engineering", "video engineering"]', '["engineering", "technology", "field of study"]', '["audio processing", "signal processing", "sound recording"]', '["audio signal", "audio recording", "audio file", "audio equipment", "audio processing", "audio quality"]', '{"noun_forms": ["audiophile", "audiology", "audiofile", "audibility"], "verb_forms": [], "adjective_forms": ["auditory"], "adverb_forms": []}', '["The course covers audio engineering principles and practice.", "Advances in audio processing improve speech intelligibility in mobile devices."]', 'technology', '2', 120540, 2723, NULL, 'opengloss-v1.1'),
('audio_noun_2', 'audio', 'noun', 2, 'A discrete audio recording or file, usually stored digitally, intended for playback or analysis; for example an audio file of a lecture.', '["audio file", "sound file", "recording"]', '["silence", "no recording"]', '["media file", "digital asset", "recording"]', '["podcast", "lecture audio", "interview recording"]', '["audio signal", "audio recording", "audio file", "audio equipment", "audio processing", "audio quality"]', '{"noun_forms": ["audiophile", "audiology", "audiofile", "audibility"], "verb_forms": [], "adjective_forms": ["auditory"], "adverb_forms": []}', '["The audio file was downloaded from the repository.", "Archived audio files include lecture recordings and podcasts."]', 'technology', '2', 120540, 2723, NULL, 'opengloss-v1.1')
