('driving_adjective_0', 'driving', 'adjective', 0, 'Relating to the operation or use of a motor vehicle; pertaining to driving actions and vehicle systems.', '["vehicular", "motoring", "automotive"]', '["stationary", "immobile"]', '["modifier", "descriptor"]', '["automatic driving", "manual driving"]', '["driving force", "driving rain", "driving wind", "driving license", "driving test", "driving habit"]', '{"noun_forms": ["driver"], "verb_forms": ["drive"], "adjective_forms": ["drivable"], "adverb_forms": []}', '["Vehicular design research emphasizes driving ergonomics.", "Motoring data analysis informs driving safety models."]', 'technology', '1', 117680, 2781, NULL, 'opengloss-v1.1'),
('driving_noun_0', 'driving', 'noun', 0, 'The act of controlling and operating a motor vehicle to move oneself or goods.', '["drive", "motoring", "operation"]', '["idling", "parking"]', '["activity", "transportation"]', '["manual driving", "automatic driving"]', '["driving force", "driving seat", "driving license", "driving test", "driving range", "driving habit"]', '{"noun_forms": ["driver", "drivability"], "verb_forms": ["drive"], "adjective_forms": [], "adverb_forms": []}', '["Road safety studies assess driving performance under cognitive load.", "New drivers must demonstrate proficient driving in real traffic."]', 'technology', '1', 117680, 2781, NULL, 'opengloss-v1.1'),
('driving_verb_0', 'driving', 'verb', 0, 'To operate or control a motor vehicle, typically a car, by steering, accelerating, and braking.', '["operate", "pilot", "steer"]', '["park", "stall"]', '["operation", "activity"]', '["car driving", "truck driving"]', '["driving force", "driving test", "driving license", "driving behavior", "driving record"]', '{"noun_forms": ["driver", "drivability"], "verb_forms": [], "adjective_forms": ["driving"], "adverb_forms": []}', '["Researchers assessed driving behavior under variable traffic density.", "The experiment compared driving performance across vehicle types."]', 'technology', '1', 117680, 2781, NULL, 'opengloss-v1.1'),
('driving_adjective_1', 'driving', 'adjective', 1, 'Of or relating to propulsion by energy or motive force; producing drive or impetus.', '["propulsive", "motivational"]', '["passive", "inhibiting"]', '["modifier", "descriptor"]', '["driving force", "driving factor"]', '["driving force", "driving rain", "driving wind", "driving license", "driving test", "driving habit"]', '{"noun_forms": ["driver"], "verb_forms": ["drive"], "adjective_forms": ["drivable"], "adverb_forms": []}', '["A driving factor behind the project is cost efficiency.", "Policy research identifies the driving force behind consumer adoption."]', 'technology', '1', 117680, 2781, NULL, 'opengloss-v1.1'),
('driving_noun_1', 'driving', 'noun', 1, 'A motive or stimulus that directs behavior or progress.', '["motive", "impetus", "incentive", "stimulus"]', '["demotivation", "discouragement"]', '["motivation", "psychological force"]', '["ambition", "goal"]', '["driving force", "driving seat", "driving license", "driving test", "driving range", "driving habit"]', '{"noun_forms": ["driver", "drivability"], "verb_forms": ["drive"], "adjective_forms": [], "adverb_forms": []}', '["Intrinsic motivation is a principal driving factor in scholarly performance.", "External incentives can enhance the driving force behind collaboration."]', 'technology', '1', 117680, 2781, NULL, 'opengloss-v1.1'),
('driving_verb_1', 'driving', 'verb', 1, 'To influence the development or progress of something by providing impetus, motivation, or direction; to propel forward a process or outcome.', '["propel", "spur", "stimulate"]', '["inhibit", "deter"]', '["influence"]', '["boost profits", "advance goals"]', '["driving force", "driving test", "driving license", "driving behavior", "driving record"]', '{"noun_forms": ["driver", "drivability"], "verb_forms": [], "adjective_forms": ["driving"], "adverb_forms": []}', '["Driving innovation requires sustained investment and cross sector collaboration.", "Driving market adoption depended on incentives and trust."]', 'technology', '1', 117680, 2781, NULL, 'opengloss-v1.1'),
