('designs_noun_0', 'designs', 'noun', 0, 'A plan or drawing that shows how something will look or work when it is built.', '["plans", "drawings", "schematics", "layouts"]', '["disorder", "improvisation"]', '["visual representations", "plans", "drawings"]', '["blueprints", "diagrams", "sketches"]', '["architectural designs", "fashion designs", "house designs", "floral designs", "portfolio of designs"]', '{"noun_forms": ["designer"], "verb_forms": ["designing"], "adjective_forms": ["designable"], "adverb_forms": []}', '["The architect shared the designs for the new classroom.", "Students studied the designs to plan their science fair model."]', 'technology', '3', 117552, 2786, NULL, 'opengloss-v1.1'),
('designs_verb_0', 'designs', 'verb', 0, 'To create a plan or drawing that shows how something will look or work.', '["plan", "create", "devise", "engineer"]', '["disassemble", "destroy", "neglect"]', '["create"]', '["blueprint", "layout", "prototype"]', '["design plan", "design process", "design brief", "design criteria", "design project", "design thinking"]', '{"noun_forms": ["designer"], "verb_forms": ["redesign"], "adjective_forms": ["designable"], "adverb_forms": []}', '["The engineer designs a new bicycle frame.", "She designs a classroom activity to teach measurement."]', 'technology', '3', 117552, 2786, NULL, 'opengloss-v1.1'),
('designs_noun_1', 'designs', 'noun', 1, 'A plan or intention to do something; a goal or aim.', '["intent", "aim", "goal", "purpose"]', '["accident", "disorganization"]', '["intentions", "goals"]', '["ambitions", "targets", "objectives"]', '["architectural designs", "fashion designs", "house designs", "floral designs", "portfolio of designs"]', '{"noun_forms": ["designer"], "verb_forms": ["designing"], "adjective_forms": ["designable"], "adverb_forms": []}', '["Her designs for a class project show careful planning.", "The team revised their designs after new evidence."]', 'technology', '3', 117552, 2786, NULL, 'opengloss-v1.1'),
('designs_verb_1', 'designs', 'verb', 1, 'To arrange parts of something to meet a purpose or constraints.', '["organize", "craft", "coordinate", "arrange"]', '["disorganize", "ignore", "neglect"]', '["organize"]', '["layout", "specification"]', '["design plan", "design process", "design brief", "design criteria", "design project", "design thinking"]', '{"noun_forms": ["designer"], "verb_forms": ["redesign"], "adjective_forms": ["designable"], "adverb_forms": []}', '["The teacher designs a unit that matches standards.", "The builder designs a safety checklist for a project."]', 'technology', '3', 117552, 2786, NULL, 'opengloss-v1.1'),
('designs_noun_2', 'designs', 'noun', 2, 'A decorative pattern or motif used in art, fabric, or objects.', '["patterns", "motifs", "ornaments", "embellishments"]', '["plainness", "monotony"]', '["patterns", "decorations"]', '["floral designs", "geometric designs", "paisley designs"]', '["architectural designs", "fashion designs", "house designs", "floral designs", "portfolio of designs"]', '{"noun_forms": ["designer"], "verb_forms": ["designing"], "adjective_forms": ["designable"], "adverb_forms": []}', '["The fabrics show bright floral designs.", "Traditional quilts feature intricate geometric designs."]', 'technology', '3', 117552, 2786, NULL, 'opengloss-v1.1'),
