-- lexi ETL: bridges (2026-09-18T16:20:18Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('bridges_noun_0', 'bridges', 'noun', 0, 'Physical structures that span a gap, enabling passage over an obstacle such as a river or valley.', '["structure", "construction", "viaduct"]', '["barrier", "obstacle", "chasm"]', '["structure", "infrastructure"]', '["arch bridge", "beam bridge", "suspension bridge"]', '["concrete bridges", "steel bridges", "suspension bridges", "pedestrian bridges", "bridges between cultures", "bridges across rivers"]', '{"noun_forms": ["bridgework"], "verb_forms": ["bridging", "bridged"], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["The city plans new bridges to improve regional mobility.", "Ancient bridges illustrate early engineering and urban planning."]', 'technology', '1', 116413, 2805, NULL, 'opengloss-v1.1'),
('bridges_verb_0', 'bridges', 'verb', 0, 'To construct or place a structure that spans a physical obstacle, enabling passage between two points.', '["span", "connect", "link", "overpass"]', '["dismantle", "disconnect", "block"]', '["build", "construct"]', '["span a river", "link two banks", "overpass a road", "connect a rail line"]', '["bridge the gap", "bridge the divide", "bridge loan", "bridge across", "bridge construction", "bridging the gap"]', '{"noun_forms": ["bridging", "bridge"], "verb_forms": ["rebridge"], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["Engineers bridge a river with a reinforced arch.", "A new span will bridge two urban districts."]', 'technology', '1', 116413, 2805, NULL, 'opengloss-v1.1'),
('bridges_noun_1', 'bridges', 'noun', 1, 'A means of connection between two domains or ideas, especially used metaphorically to describe linking disparate groups or disciplines.', '["link", "connection", "connector"]', '["separation", "disconnection", "divergence"]', '["link", "connection"]', '["cultural bridge", "educational bridge", "economic bridge"]', '["concrete bridges", "steel bridges", "suspension bridges", "pedestrian bridges", "bridges between cultures", "bridges across rivers"]', '{"noun_forms": ["bridgework"], "verb_forms": ["bridging", "bridged"], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["Bridges between cultures facilitate cross cultural understanding.", "Educational programs build bridges between theory and practice."]', 'technology', '1', 116413, 2805, NULL, 'opengloss-v1.1'),
('bridges_verb_1', 'bridges', 'verb', 1, 'To connect or reconcile differences between ideas, groups, or periods, often by synthesis or mediation.', '["connect", "link", "reconcile", "integrate"]', '["segregate", "polarize", "isolate"]', '["connect"]', '["gap closure", "disciplinary bridging"]', '["bridge the gap", "bridge the divide", "bridge loan", "bridge across", "bridge construction", "bridging the gap"]', '{"noun_forms": ["bridging", "bridge"], "verb_forms": ["rebridge"], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["Research in interdisciplinary teams bridges conceptual gaps.", "Education policies bridge the gap between theory and practice."]', 'technology', '1', 116413, 2805, NULL, 'opengloss-v1.1'),
('bridges_noun_2', 'bridges', 'noun', 2, 'In computer networking, a device that connects two or more network segments at the data link layer to regulate traffic and extend network reach.', '["bridge device", "network bridge", "LAN bridge"]', '["switch", "router", "isolation"]', '["network device", "communications equipment"]', '["wireless bridge", "LAN bridge", "bridge router"]', '["concrete bridges", "steel bridges", "suspension bridges", "pedestrian bridges", "bridges between cultures", "bridges across rivers"]', '{"noun_forms": ["bridgework"], "verb_forms": ["bridging", "bridged"], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["Network administrators deploy network bridges to segment collision domains.", "Bridging functions simplify interconnectivity between disparate LANs."]', 'technology', '1', 116413, 2805, NULL, 'opengloss-v1.1'),
('bridges_verb_2', 'bridges', 'verb', 2, 'In computer networking, to join two or more network segments by using a bridging device.', '["interconnect", "connect", "link"]', '["isolate networks", "segment"]', '["interconnect"]', '["LAN bridging", "wireless bridging"]', '["bridge the gap", "bridge the divide", "bridge loan", "bridge across", "bridge construction", "bridging the gap"]', '{"noun_forms": ["bridging", "bridge"], "verb_forms": ["rebridge"], "adjective_forms": ["bridgeable"], "adverb_forms": []}', '["A network bridge interconnects two LAN segments to manage traffic.", "Bridging two networks reduces broadcast domains and improves performance."]', 'technology', '1', 116413, 2805, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
