-- lexi ETL: instruments (2026-09-18T16:20:18Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('instruments_noun_0', 'instruments', 'noun', 0, 'An object or device used to perform a task, typically a manual hand tool or mechanical device.', '["tool", "implement", "device", "appliance"]', '[]', '["object", "device", "artifact"]', '["hammer", "screwdriver", "wrench", "pliers", "measuring tool"]', '["musical instrument", "measuring instrument", "surgical instrument", "medical instrument", "instrument panel", "precision instrument"]', '{"noun_forms": ["instrumentation", "instrumentalist", "instrumentality"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": ["instrumentally"]}', '["The carpenter chose a hammer as a primary tool.", "Screwdrivers pliers and wrenches are common instruments for repairs."]', 'technology', '1', 115670, 2818, NULL, 'opengloss-v1.1'),
('instruments_verb_0', 'instruments', 'verb', 0, 'To furnish or equip with instruments or tools necessary to perform a task, often in laboratory, field, or workshop settings.', '["equip", "furnish", "outfit"]', '["unfurnish", "deequip"]', '["provide", "supply"]', '["install sensors", "fit meters"]', '["instrument study", "instrument data", "instrument variables", "instrument sensors", "instrument measurement"]', '{"noun_forms": ["instrumentation", "instrumenter"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": ["instrumentally"]}', '["The technician instruments the field station with data loggers.", "The team instruments the laboratory bench to support experiments."]', 'technology', '1', 115670, 2818, NULL, 'opengloss-v1.1'),
('instruments_noun_1', 'instruments', 'noun', 1, 'An object designed to produce musical sounds when played.', '["musical instrument", "sound-producing device", "instrument of music"]', '[]', '["sound producing device", "art object"]', '["violin", "piano", "flute", "guitar", "trumpet"]', '["musical instrument", "measuring instrument", "surgical instrument", "medical instrument", "instrument panel", "precision instrument"]', '{"noun_forms": ["instrumentation", "instrumentalist", "instrumentality"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": ["instrumentally"]}', '["The violin, flute, and piano are common musical instruments.", "She learned to play the guitar, a popular musical instrument."]', 'technology', '1', 115670, 2818, NULL, 'opengloss-v1.1'),
('instruments_verb_1', 'instruments', 'verb', 1, 'To deploy measurement devices or sensors on a system, process, or environment in order to collect data or monitor conditions as part of an experimental or observational protocol.', '["measure", "monitor"]', '[]', '["instrumentation", "data collection"]', '["attach sensors", "install meters"]', '["instrument study", "instrument data", "instrument variables", "instrument sensors", "instrument measurement"]', '{"noun_forms": ["instrumentation", "instrumenter"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": ["instrumentally"]}', '["Researchers instrument the wind tunnel to record pressure changes.", "Clinicians instrument the patient with monitoring devices during evaluation."]', 'technology', '1', 115670, 2818, NULL, 'opengloss-v1.1'),
