INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('watch_noun_0', 'watch', 'noun', 0, 'A portable timekeeping device worn on the body, typically on the wrist, or carried as a pocket timepiece, used to display and measure time.', '["timepiece", "timekeeper", "wristwatch"]', '[]', '["timekeeping device", "device", "instrument"]', '["analog watch", "digital watch", "pocket watch", "smartwatch"]', '["wristwatch", "watch face", "watch band", "pocket watch", "analog watch", "smartwatch"]', '{"noun_forms": ["watchfulness", "watchman", "watchmaker", "watchmaking", "watchband"], "verb_forms": ["watching"], "adjective_forms": ["watchful"], "adverb_forms": ["watchfully"]}', '["The wristwatch enables field researchers to synchronize tasks with local time.", "A digital watch may be used in experiments requiring precise timing."]', 'technology', 'K', 115093, 2827, NULL, 'opengloss-v1.1'),
('watch_verb_0', 'watch', 'verb', 0, 'To look at or perceive with the eyes, often with deliberate attention, in order to gain information or understanding.', '["observe", "see", "perceive", "watch"]', '["ignore", "disregard", "overlook"]', '["perceive"]', '["gaze", "glance", "peer", "stare"]', '["watchtower", "watchman", "watchdog", "watchlist", "watchword", "watchband"]', '{"noun_forms": ["watcher", "watchfulness"], "verb_forms": [], "adjective_forms": ["watchful", "watchable"], "adverb_forms": ["watchfully"]}', '["Researchers watched the participants in a controlled setting to record behavioral responses.", "The analyst watched satellite feeds to detect anomalies in real time."]', 'technology', 'K', 115093, 2827, NULL, 'opengloss-v1.1'),
('watch_noun_1', 'watch', 'noun', 1, 'A period of duty or shift during which a person or group is responsible for observation, monitoring, or guarding a location or activity.', '["guard duty", "lookout", "sentry duty"]', '["off duty", "idle period", "vacation period"]', '["duty", "assignment", "shift"]', '["night watch", "sentry duty", "lookout duty"]', '["wristwatch", "watch face", "watch band", "pocket watch", "analog watch", "smartwatch"]', '{"noun_forms": ["watchfulness", "watchman", "watchmaker", "watchmaking", "watchband"], "verb_forms": ["watching"], "adjective_forms": ["watchful"], "adverb_forms": ["watchfully"]}', '["The night watch maintained surveillance over the perimeter.", "During the shift, personnel remain on watch to detect anomalies."]', 'technology', 'K', 115093, 2827, NULL, 'opengloss-v1.1'),
('watch_verb_1', 'watch', 'verb', 1, 'To maintain continuous observation of a person, place, or thing for safety, security, or supervisory purposes.', '["monitor", "surveil", "supervise", "guard"]', '["neglect", "disregard", "ignore"]', '["observe"]', '["surveil", "oversee", "guard", "screen"]', '["watchtower", "watchman", "watchdog", "watchlist", "watchword", "watchband"]', '{"noun_forms": ["watcher", "watchfulness"], "verb_forms": [], "adjective_forms": ["watchful", "watchable"], "adverb_forms": ["watchfully"]}', '["Security personnel surveilled the corridor during the transfer to prevent unauthorized access.", "The system monitors patient data and alerts staff when anomalies are detected."]', 'technology', 'K', 115093, 2827, NULL, 'opengloss-v1.1'),
('watch_verb_2', 'watch', 'verb', 2, 'To measure the duration of an event or interval using a watch as a timing device.', '["time", "measure", "clock"]', '["untimed", "unmeasured", "delayed"]', '["timekeeping"]', '["timing", "clocking"]', '["watchtower", "watchman", "watchdog", "watchlist", "watchword", "watchband"]', '{"noun_forms": ["watcher", "watchfulness"], "verb_forms": [], "adjective_forms": ["watchful", "watchable"], "adverb_forms": ["watchfully"]}', '["Researchers timed the reaction using a precision watch.", "The clock measured duration with a synchronized watch."]', 'technology', 'K', 115093, 2827, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
