('ranking_adjective_0', 'ranking', 'adjective', 0, 'Relating to rank or order in a list or scale.', '["hierarchical", "graded", "ordered"]', '["unordered", "random", "unranked"]', '["ordering", "classification"]', '["alphabetical ranking", "numerical ranking", "global ranking"]', '["ranking system", "ranking criteria", "global ranking", "numerical ranking", "alphabetical ranking", "local ranking"]', '{"noun_forms": ["ranking"], "verb_forms": ["rank"], "adjective_forms": ["ranked"], "adverb_forms": ["rankingly"]}', '["The ranking criteria guide how students are placed.", "A ranking system shows the order of options."]', 'mathematics', '5', 113657, 2873, NULL, 'opengloss-v1.1'),
('ranking_noun_0', 'ranking', 'noun', 0, 'The act or process of placing items in order according to a criterion, and the resulting list that shows that order.', '["order", "rating", "placement", "classification"]', '["disorder", "randomness"]', '["order", "system of evaluation"]', '["academic ranking", "sports ranking", "national ranking"]', '["ranking system", "class ranking", "world ranking", "sports ranking", "national ranking", "academic ranking"]', '{"noun_forms": [], "verb_forms": ["rank"], "adjective_forms": [], "adverb_forms": []}', '["The school''s ranking was determined by test scores.", "A class ranking lists students from highest to lowest."]', 'mathematics', '5', 113657, 2873, NULL, 'opengloss-v1.1'),
('ranking_verb_0', 'ranking', 'verb', 0, 'To arrange people or things in an order according to quality, importance, or another criterion.', '["classify", "order", "grade"]', '["disorder", "unranked"]', '["evaluate", "organize"]', '["tier", "grade"]', '["rank order", "high ranking", "top ranking", "ranking system", "ranking criteria", "ranked list"]', '{"noun_forms": ["ranker", "ranking"], "verb_forms": ["rerank"], "adjective_forms": [], "adverb_forms": []}', '["The teacher ranks students by test scores.", "The app ranks pages by relevance."]', 'mathematics', '5', 113657, 2873, NULL, 'opengloss-v1.1'),
('ranking_adjective_1', 'ranking', 'adjective', 1, 'Describing something or someone with a high position in a hierarchy; having a high status.', '["high ranking", "top ranking", "elite"]', '["low ranking", "unranked"]', '["status", "standing"]', '["national ranking", "regional ranking"]', '["ranking system", "ranking criteria", "global ranking", "numerical ranking", "alphabetical ranking", "local ranking"]', '{"noun_forms": ["ranking"], "verb_forms": ["rank"], "adjective_forms": ["ranked"], "adverb_forms": ["rankingly"]}', '["The top ranking student earned a scholarship.", "This school has a high ranking in the state."]', 'mathematics', '5', 113657, 2873, NULL, 'opengloss-v1.1'),
('ranking_noun_1', 'ranking', 'noun', 1, 'The position or standing of a person or thing within a ranking; the place they occupy on the list.', '["place", "standing", "position", "tier"]', '["last place", "bottom tier"]', '["position", "status"]', '["top tier", "mid tier", "bottom tier"]', '["ranking system", "class ranking", "world ranking", "sports ranking", "national ranking", "academic ranking"]', '{"noun_forms": [], "verb_forms": ["rank"], "adjective_forms": [], "adverb_forms": []}', '["Her ranking in the class improved after the science test.", "This week his ranking moved from mid tier to top tier."]', 'mathematics', '5', 113657, 2873, NULL, 'opengloss-v1.1'),
('ranking_verb_1', 'ranking', 'verb', 1, 'To hold a position of authority or status within a group or hierarchy; to be placed in a particular rank.', '["occupy", "hold", "belong"]', '["unranked", "demote"]', '["evaluate", "classify", "arrange"]', '["top tier", "mid tier"]', '["rank order", "high ranking", "top ranking", "ranking system", "ranking criteria", "ranked list"]', '{"noun_forms": ["ranker", "ranking"], "verb_forms": ["rerank"], "adjective_forms": [], "adverb_forms": []}', '["She ranks among the top students in the class.", "He ranks as a senior member of the team."]', 'mathematics', '5', 113657, 2873, NULL, 'opengloss-v1.1'),
('ranking_noun_2', 'ranking', 'noun', 2, 'A method for ordering items by a criterion, often used to compare products or data; a system of ranking.', '["sorting", "rating", "prioritization"]', '["unranking", "disorder"]', '["ordering method"]', '["score ranking", "merit ranking", "alphabetical ranking"]', '["ranking system", "class ranking", "world ranking", "sports ranking", "national ranking", "academic ranking"]', '{"noun_forms": [], "verb_forms": ["rank"], "adjective_forms": [], "adverb_forms": []}', '["Shopping sites use ranking to show best products first.", "Search engines rely on ranking to present relevant results."]', 'mathematics', '5', 113657, 2873, NULL, 'opengloss-v1.1'),
('ranking_verb_2', 'ranking', 'verb', 2, 'To evaluate or score something so that it can be compared with others; to assign a ranking score.', '["score", "assess", "evaluate"]', '["ignore", "neglect"]', '["evaluate", "assess"]', '["relevance score"]', '["rank order", "high ranking", "top ranking", "ranking system", "ranking criteria", "ranked list"]', '{"noun_forms": ["ranker", "ranking"], "verb_forms": ["rerank"], "adjective_forms": [], "adverb_forms": []}', '["The program ranks results by relevance score.", "The system ranks candidates by merit."]', 'mathematics', '5', 113657, 2873, NULL, 'opengloss-v1.1')
