('stands_noun_0', 'stands', 'noun', 0, 'A stand is a rigid support or frame used to hold, elevate, or display an object such as a lamp, instrument, or display item.', '["pedestal", "holder", "rack", "support"]', '["collapse", "topple"]', '["furniture", "equipment"]', '["lamp stand", "music stand", "book stand", "display stand"]', '["display stand", "lamp stand", "music stand", "book stand", "fruit stand", "newsstand"]', '{"noun_forms": ["standing"], "verb_forms": [], "adjective_forms": ["standing"], "adverb_forms": []}', '["Exhibit panels rested on metal stands during the demonstration.", "A lamp stand supports the light at the study desk."]', 'technology', '1', 110336, 2934, NULL, 'opengloss-v1.1'),
('stands_verb_0', 'stands', 'verb', 0, 'To be in an upright position or to remain erect.', '["be erect", "be upright", "stand erect", "stand tall"]', '["sit", "lie", "crouch"]', '["occupy a position"]', '["stand upright", "stand straight"]', '["stand up", "stand for", "stand by", "stand firm", "stand out", "stand tall"]', '{"noun_forms": ["stander", "standing", "standpoint", "standout"], "verb_forms": ["stand"], "adjective_forms": ["standable"], "adverb_forms": []}', '["The lamp stands on the desk.", "The statue stands at the center of the plaza."]', 'technology', '1', 110336, 2934, NULL, 'opengloss-v1.1'),
('stands_noun_1', 'stands', 'noun', 1, 'A stand is a small stall or booth at a market or fair used to sell goods.', '["booth", "stall", "kiosk", "vendor stand"]', '["store", "shop"]', '["retail location"]', '["food stand", "fruit stand", "newsstand", "book stand"]', '["display stand", "lamp stand", "music stand", "book stand", "fruit stand", "newsstand"]', '{"noun_forms": ["standing"], "verb_forms": [], "adjective_forms": ["standing"], "adverb_forms": []}', '["Street vendors operated fruit stands along the square.", "Students bought newspapers at the campus newsstand."]', 'technology', '1', 110336, 2934, NULL, 'opengloss-v1.1'),
('stands_verb_1', 'stands', 'verb', 1, 'To endure or tolerate a condition or circumstance.', '["endure", "tolerate", "bear", "withstand", "abide"]', '["give in", "succumb", "yield", "break down"]', '["withstand stress", "bear up under pressure"]', '["bear pain", "withstand heat", "endure stress"]', '["stand up", "stand for", "stand by", "stand firm", "stand out", "stand tall"]', '{"noun_forms": ["stander", "standing", "standpoint", "standout"], "verb_forms": ["stand"], "adjective_forms": ["standable"], "adverb_forms": []}', '["The structure stands up to the wind.", "The policy stands up to rigorous scrutiny."]', 'technology', '1', 110336, 2934, NULL, 'opengloss-v1.1'),
('stands_noun_2', 'stands', 'noun', 2, 'A stand is a position or attitude taken on an issue; a stance.', '["stance", "position", "viewpoint", "attitude"]', '["neutrality", "indifference", "ambivalence"]', '["opinion", "attitude"]', '["moral stand", "legal stand", "economic stand", "political stand"]', '["display stand", "lamp stand", "music stand", "book stand", "fruit stand", "newsstand"]', '{"noun_forms": ["standing"], "verb_forms": [], "adjective_forms": ["standing"], "adverb_forms": []}', '["Scholars presented their stands on the ethical implications.", "Public health officials defended their stands on vaccination policy."]', 'technology', '1', 110336, 2934, NULL, 'opengloss-v1.1'),
