INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('window_noun_0', 'window', 'noun', 0, 'An opening in a wall or vehicle fitted with glass to admit light and provide a view.', '["opening", "aperture", "fenestra"]', '["solid wall", "opaque barrier"]', '["architectural feature", "opening"]', '["casement window", "sliding window", "double-hung window", "picture window"]', '["window frame", "window pane", "sliding window", "double-hung window", "time window", "window of opportunity"]', '{"noun_forms": ["windowing"], "verb_forms": ["windowed", "windowing"], "adjective_forms": ["windowed"], "adverb_forms": []}', '["The kitchen window admitted bright morning light.", "A large window framed the view of the courtyard."]', 'technology', 'K', 109008, 2967, NULL, 'opengloss-v1.1'),
('window_verb_0', 'window', 'verb', 0, 'To insert or fit a window into a wall or barrier, creating an opening for light, view, or ventilation.', '["fit", "install", "set"]', '["seal", "close"]', '["modification", "construction", "alteration"]', '["casement installation", "sliding window installation"]', '["install window", "fit window", "window installation", "casement installation", "sliding window installation", "open window"]', '{"noun_forms": ["windowing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The contractor windowed the exterior wall to install a sash.", "A windowed opening improved daylight in the room."]', 'technology', 'K', 109008, 2967, NULL, 'opengloss-v1.1'),
('window_noun_1', 'window', 'noun', 1, 'A framed area on a computer display that presents information or a user interface separate from the main application.', '["frame", "panel"]', '["fullscreen"]', '["interface element"]', '["dialog box", "modal window", "pop-up window", "notification window"]', '["window frame", "window pane", "sliding window", "double-hung window", "time window", "window of opportunity"]', '{"noun_forms": ["windowing"], "verb_forms": ["windowed", "windowing"], "adjective_forms": ["windowed"], "adverb_forms": []}', '["The user opened a new window to compare results.", "Modal windows require user interaction before continuing."]', 'technology', 'K', 109008, 2967, NULL, 'opengloss-v1.1'),
('window_verb_1', 'window', 'verb', 1, 'To display software, data, or a user interface element within a separate on-screen window or dialog, or to open a new window in a graphical user interface.', '["open", "display", "spawn"]', '["close", "minimize", "hide"]', '["GUI operation"]', '["open window", "maximize window", "dialog window"]', '["install window", "fit window", "window installation", "casement installation", "sliding window installation", "open window"]', '{"noun_forms": ["windowing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The application windows a help dialog when the user requests assistance.", "Users can window new results in a separate panel."]', 'technology', 'K', 109008, 2967, NULL, 'opengloss-v1.1'),
('window_noun_2', 'window', 'noun', 2, 'A finite interval during which a condition holds or an action can be taken.', '["interval", "timeframe"]', '["indefinite interval"]', '["time interval"]', '["observation window", "measurement window", "data window", "eligibility window"]', '["window frame", "window pane", "sliding window", "double-hung window", "time window", "window of opportunity"]', '{"noun_forms": ["windowing"], "verb_forms": ["windowed", "windowing"], "adjective_forms": ["windowed"], "adverb_forms": []}', '["The observable data must fall within the time window.", "There is a narrow observation window for detecting signals."]', 'technology', 'K', 109008, 2967, NULL, 'opengloss-v1.1'),
('window_noun_3', 'window', 'noun', 3, 'A favorable period for undertaking a task or seizing an opportunity.', '["opportunity", "opening"]', '["closed period"]', '["period"]', '["opportunity window", "seasonal window", "market window", "business window"]', '["window frame", "window pane", "sliding window", "double-hung window", "time window", "window of opportunity"]', '{"noun_forms": ["windowing"], "verb_forms": ["windowed", "windowing"], "adjective_forms": ["windowed"], "adverb_forms": []}', '["There is a window of opportunity for advancing this research.", "Companies seek to exploit the market window before demand wanes."]', 'technology', 'K', 109008, 2967, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
