('user_adjective_0', 'user', 'adjective', 0, 'Relating to the user or users; used in contexts involving human factors in design, evaluation, or analytics.', '["user-related", "user-specific", "user-centered", "user-facing"]', '["nonuser", "system-related"]', '["descriptor", "modifier", "adjective"]', '["user-facing", "user-centered", "user-specific", "user-oriented"]', '["user experience", "user interface", "user data", "user needs", "user consent", "user feedback"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": ["user-centered", "user-friendly", "user-facing", "user-oriented"], "adverb_forms": []}', '["User-related factors should be considered in requirement analysis.", "The design emphasizes user-centered outcomes in evaluation."]', 'technology', '1', 107617, 2996, NULL, 'opengloss-v1.1'),
('user_noun_0', 'user', 'noun', 0, 'A person who ultimately uses a product or service, particularly a software application or hardware device, rather than its developer or administrator.', '["consumer", "customer", "client", "recipient"]', '["nonuser"]', '["person", "individual", "agent"]', '["power user", "guest user"]', '["end user", "system user", "user interface", "user account", "user experience", "power user"]', '{"noun_forms": ["userhood", "usership"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers interviewed the end users to validate the interface.", "The system logs each user action for audit."]', 'technology', '1', 107617, 2996, NULL, 'opengloss-v1.1'),
('user_adjective_1', 'user', 'adjective', 1, 'Relating to data or input provided directly by the user; used to distinguish content originated from the user from system generated content.', '["user-provided", "user-supplied"]', '["system-provided", "machine-generated"]', '["data attribute", "input type"]', '["user-provided data", "user-provided input", "user-supplied credentials", "user-input data"]', '["user experience", "user interface", "user data", "user needs", "user consent", "user feedback"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": ["user-centered", "user-friendly", "user-facing", "user-oriented"], "adverb_forms": []}', '["User-provided credentials must be authenticated.", "User-supplied content is stored for moderation."]', 'technology', '1', 107617, 2996, NULL, 'opengloss-v1.1'),
