('fan_noun_0', 'fan', 'noun', 0, 'A device with rotating blades driven by a motor used to move air for cooling, ventilation, or environmental air distribution.', '["ventilator", "air mover", "air circulator", "blower"]', '["airless room", "no airflow"]', '["device", "apparatus"]', '["ceiling fan", "table fan", "box fan", "tower fan"]', '["electric fan", "ceiling fan", "table fan", "box fan", "tower fan", "hand fan"]', '{"noun_forms": ["fanbase", "fanship", "fandom", "fangirl"], "verb_forms": [], "adjective_forms": ["fannish"], "adverb_forms": []}', '["A compact electric fan circulated air to prevent heat buildup in the experimental chamber.", "Industrial ventilation may rely on a large tower fan to move air through the facility."]', 'technology', 'K', 104995, 3082, NULL, 'opengloss-v1.1'),
('fan_verb_0', 'fan', 'verb', 0, 'To cause air to move or circulate by means of a fan, thereby ventilating or cooling a space.', '["ventilate", "aerate", "circulate"]', '["stifle", "block", "insulate"]', '["ventilation", "air movement"]', '["air circulation", "air exchange"]', '["ceiling fan", "electric fan", "desk fan", "pedestal fan", "oscillating fan", "handheld fan"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Engineers fanned the room to reduce heat.", "The turbine''s cooling system fanned air across the chamber."]', 'technology', 'K', 104995, 3082, NULL, 'opengloss-v1.1'),
('fan_noun_1', 'fan', 'noun', 1, 'A person who is an enthusiastic admirer or devotee of a subject, person, or cultural work.', '["admirer", "enthusiast", "supporter", "follower"]', '["critic", "opponent"]', '["person", "individual"]', '["superfan", "diehard"]', '["electric fan", "ceiling fan", "table fan", "box fan", "tower fan", "hand fan"]', '{"noun_forms": ["fanbase", "fanship", "fandom", "fangirl"], "verb_forms": [], "adjective_forms": ["fannish"], "adverb_forms": []}', '["The film''s fans attended the premiere.", "Sports fans debated the statistics on social media."]', 'technology', 'K', 104995, 3082, NULL, 'opengloss-v1.1'),
('fan_verb_1', 'fan', 'verb', 1, 'To distribute or extend outward in a fan-shaped pattern.', '["disperse", "spread", "radiate"]', '["concentrate", "cluster"]', '["dispersal"]', '["radial spread", "fan shaped distribution"]', '["ceiling fan", "electric fan", "desk fan", "pedestal fan", "oscillating fan", "handheld fan"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Survey teams fanned out across the region to collect data.", "Researchers fanned out along the coast to sample data."]', 'technology', 'K', 104995, 3082, NULL, 'opengloss-v1.1'),
('fan_noun_2', 'fan', 'noun', 2, 'A portable hand held fan operated by manual motion to create airflow; typically folding or collapsible.', '["hand fan", "folding fan", "paper fan", "feather fan"]', '[]', '["device", "artifact"]', '["folding fan", "silk fan", "peacock feather fan"]', '["electric fan", "ceiling fan", "table fan", "box fan", "tower fan", "hand fan"]', '{"noun_forms": ["fanbase", "fanship", "fandom", "fangirl"], "verb_forms": [], "adjective_forms": ["fannish"], "adverb_forms": []}', '["The dancer used a folding fan as part of the traditional costume.", "A silk fan was used by attendees to cool themselves at the ceremony."]', 'technology', 'K', 104995, 3082, NULL, 'opengloss-v1.1'),
('fan_verb_2', 'fan', 'verb', 2, 'To intensify or provoke a response or emotion; to inflame or aggravate a controversy.', '["intensify", "inflame", "aggravate"]', '["dampen", "calm", "mitigate"]', '["agitation"]', '["emotional escalation", "public outrage", "social tension"]', '["ceiling fan", "electric fan", "desk fan", "pedestal fan", "oscillating fan", "handheld fan"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Editorials fanned the flames of public outrage.", "Rhetoric can easily fan controversy into violence."]', 'technology', 'K', 104995, 3082, NULL, 'opengloss-v1.1')
