INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('sc_noun_0', 'sc', 'noun', 0, 'An abbreviation whose meaning depends on context; in academic and technical usage, often standing for terms such as small caps, subcutaneous, silicon carbide, or single cell, among others.', '["abbreviation", "short form", "initialism"]', '["full form"]', '["abbreviation", "symbol"]', '["scientific abbreviation", "medical abbreviation"]', '["sc abbreviation", "sc notation", "set in sc", "typed in sc"]', '{"noun_forms": ["small caps", "silicon carbide", "single cell"], "verb_forms": ["subcategorize"], "adjective_forms": ["sc based"], "adverb_forms": []}', '["The notation sc must be clearly defined the first time it appears in the article.", "Because sc can represent several different technical terms, the author included a list of abbreviations."]', 'language', 'BS', 104385, 3097, NULL, 'opengloss-v1.1'),
('sc_noun_1', 'sc', 'noun', 1, 'In typography and publishing, sc is commonly used as a short form for small caps, a style of capital letters reduced to the height of lowercase letters.', '["small caps", "small capitals"]', '["full capitals"]', '["typographic style", "font style"]', '["title small caps", "text small caps"]', '["sc abbreviation", "sc notation", "set in sc", "typed in sc"]', '{"noun_forms": ["small caps", "silicon carbide", "single cell"], "verb_forms": ["subcategorize"], "adjective_forms": ["sc based"], "adverb_forms": []}', '["The style guide recommends setting acronyms in sc for emphasis.", "In the layout file, the designer marked section headings with the code sc to indicate small caps."]', 'language', 'BS', 104385, 3097, NULL, 'opengloss-v1.1'),
('sc_noun_2', 'sc', 'noun', 2, 'In certain scientific and technical contexts, sc functions as a conventional symbol or abbreviation, for example for silicon carbide in materials science or single cell in biology, where its interpretation is domain specific.', '["technical symbol", "domain abbreviation"]', '[]', '["symbol", "notation"]', '["chemical symbol", "biological notation"]', '["sc abbreviation", "sc notation", "set in sc", "typed in sc"]', '{"noun_forms": ["small caps", "silicon carbide", "single cell"], "verb_forms": ["subcategorize"], "adjective_forms": ["sc based"], "adverb_forms": []}', '["In this experiment, sc nanowires were grown on a conductive substrate.", "The protocol describes sc sequencing of immune cells to capture transcriptional diversity."]', 'language', 'BS', 104385, 3097, NULL, 'opengloss-v1.1')
