('filmed_adjective_0', 'filmed', 'adjective', 0, 'Having been recorded on film or another motion-image medium.', '["recorded", "cinematographed", "captured"]', '["unrecorded", "unfilmed"]', '["recorded media", "visual media"]', '["filmed interview", "filmed scene", "filmed footage"]', '["filmed interview", "filmed scene", "filmed footage", "filmed sequence", "filmed material"]', '{"noun_forms": ["film"], "verb_forms": ["film", "films", "filmed", "filming"], "adjective_forms": ["filmed"], "adverb_forms": []}', '["The filmed interviews were transcribed for qualitative analysis.", "Researchers compared filmed sequences to archival records."]', 'arts', '3', 103582, 3116, NULL, 'opengloss-v1.1'),
('filmed_verb_0', 'filmed', 'verb', 0, 'To record moving images with a camera for the purpose of creating a film, television program, or video.', '["shoot", "record", "capture"]', '["unfilmed", "unrecorded"]', '["recording", "motion picture production"]', '["on location filming", "studio filming", "documentary filming", "live filming"]', '["filmed on location", "filmed in color", "filmed footage", "filmed interview", "filmed scene", "filmed documentary"]', '{"noun_forms": ["filmmaker", "filmmaking", "filmography"], "verb_forms": ["refilm"], "adjective_forms": ["filmic"], "adverb_forms": ["cinematically"]}', '["The director filmed the chase sequence over two nights.", "Researchers filmed the lab experiment to document outcomes."]', 'arts', '3', 103582, 3116, NULL, 'opengloss-v1.1'),
('filmed_verb_1', 'filmed', 'verb', 1, 'To capture events or subjects with a camera for documentation, journalism, or archival purposes.', '["shoot", "record", "document"]', '["unfilmed", "unrecorded"]', '["recording", "videography"]', '["news filming", "documentary filming"]', '["filmed on location", "filmed in color", "filmed footage", "filmed interview", "filmed scene", "filmed documentary"]', '{"noun_forms": ["filmmaker", "filmmaking", "filmography"], "verb_forms": ["refilm"], "adjective_forms": ["filmic"], "adverb_forms": ["cinematically"]}', '["The protest was filmed by journalists for later verification.", "Security footage was filmed to provide evidence during the trial."]', 'arts', '3', 103582, 3116, NULL, 'opengloss-v1.1'),
('filmed_verb_2', 'filmed', 'verb', 2, 'Used as a past participle adjective describing something that has been captured on film or video.', '["recorded", "shot", "captured"]', '["unfilmed", "unrecorded"]', '["recorded material", "visual media"]', '["filmed interview", "filmed scene"]', '["filmed on location", "filmed in color", "filmed footage", "filmed interview", "filmed scene", "filmed documentary"]', '{"noun_forms": ["filmmaker", "filmmaking", "filmography"], "verb_forms": ["refilm"], "adjective_forms": ["filmic"], "adverb_forms": ["cinematically"]}', '["A filmed interview can be edited for clarity.", "The filmed sequence provided essential context."]', 'arts', '3', 103582, 3116, NULL, 'opengloss-v1.1')
