('database_noun_0', 'database', 'noun', 0, 'A structured collection of related data stored electronically and accessible by computer programs.', '["data bank", "data store", "information base", "data repository"]', '["disorganization", "chaos"]', '["information system", "storage system"]', '["relational database", "graph database", "NoSQL database", "time-series database"]', '["school database", "student database", "homeschool database", "classroom database", "online database", "secure database"]', '{"noun_forms": ["database system", "data repository", "information store"], "verb_forms": ["databasing"], "adjective_forms": ["database oriented", "database related"], "adverb_forms": []}', '["The school''s student records are kept in a secure database for analysis.", "Researchers compile experimental results into a database to compare outcomes."]', 'technology', 'BS', 103281, 3122, NULL, 'opengloss-v1.1'),
('database_verb_0', 'database', 'verb', 0, 'To enter or record data into a database so information can be stored, searched, and retrieved.', '["record", "input", "log"]', '["erase", "delete", "remove"]', '["store data", "record information"]', '["input data", "append record"]', '["create database", "populate database", "query database", "database schema", "database system", "relational database"]', '{"noun_forms": ["databaser"], "verb_forms": ["databasing"], "adjective_forms": ["databased"], "adverb_forms": []}', '["We database the survey responses to compile a class report.", "The teacher databases attendance and scores to monitor progress."]', 'technology', 'BS', 103281, 3122, NULL, 'opengloss-v1.1'),
('database_noun_1', 'database', 'noun', 1, 'A software system designed to create, read, update, and delete data stored in a database.', '["database software", "DBMS", "data management system"]', '["manual record keeping", "paper ledger"]', '["information system"]', '["relational DBMS", "NoSQL DBMS", "graph DBMS"]', '["school database", "student database", "homeschool database", "classroom database", "online database", "secure database"]', '{"noun_forms": ["database system", "data repository", "information store"], "verb_forms": ["databasing"], "adjective_forms": ["database oriented", "database related"], "adverb_forms": []}', '["The DBMS supports multiple users editing grades at once.", "Teachers use database software to organize assignments and attendance."]', 'technology', 'BS', 103281, 3122, NULL, 'opengloss-v1.1'),
('database_verb_1', 'database', 'verb', 1, 'To create and configure a database by designing its structure including tables and relationships.', '["build", "set up", "design", "create"]', '["delete", "erase", "decommission"]', '["build data structure", "establish data system"]', '["design schema", "define tables", "create relations"]', '["create database", "populate database", "query database", "database schema", "database system", "relational database"]', '{"noun_forms": ["databaser"], "verb_forms": ["databasing"], "adjective_forms": ["databased"], "adverb_forms": []}', '["The team databases a new database to manage student records.", "Students learn how to database a simple database structure in class."]', 'technology', 'BS', 103281, 3122, NULL, 'opengloss-v1.1'),
('database_noun_2', 'database', 'noun', 2, 'A topic specific collection of data organized for a class or project used for teaching or research.', '["topic database", "class database", "project database", "topic data store"]', '["unorganized notes", "disorganized records"]', '["data collection"]', '["biology database", "history database", "math database"]', '["school database", "student database", "homeschool database", "classroom database", "online database", "secure database"]', '{"noun_forms": ["database system", "data repository", "information store"], "verb_forms": ["databasing"], "adjective_forms": ["database oriented", "database related"], "adverb_forms": []}', '["The science project used a biology database to track plant growth.", "Students built a history database of famous explorers."]', 'technology', 'BS', 103281, 3122, NULL, 'opengloss-v1.1')
