-- lexi ETL: filed (2026-09-18T16:20:19Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('filed_adjective_0', 'filed', 'adjective', 0, 'In law and public administration, described as filed when a document or item has been officially submitted to an authority and entered into the official record.', '["recorded", "documented", "submitted", "registered"]', '["unfiled", "unrecorded", "unsubmitted"]', '["document status", "record status"]', '["complaint", "petition", "motion", "application"]', '["filed document", "filed complaint", "filed motion", "filed patent", "filed application"]', '{"noun_forms": ["filing"], "verb_forms": ["file", "files", "filing", "filed"], "adjective_forms": ["filed"], "adverb_forms": []}', '["The complaint was filed with the court for review.", "All supporting documents were filed before the deadline."]', 'technology', '3', 102842, 3136, NULL, 'opengloss-v1.1'),
('filed_verb_0', 'filed', 'verb', 0, 'To place documents, data, or records into a file or folder for storage or organization, typically in a digital or physical filing system.', '["store", "archive", "save", "record"]', '["delete", "erase", "discard"]', '["data storage", "document management"]', '["digital filing", "physical filing"]', '["filing deadline", "filing system", "filing cabinet", "court filing", "lawsuit filing", "tax filing"]', '{"noun_forms": ["filing", "filings"], "verb_forms": ["refile"], "adjective_forms": [], "adverb_forms": []}', '["The dataset was filed in the institutional repository.", "Project records were filed under year and author IDs."]', 'technology', '3', 102842, 3136, NULL, 'opengloss-v1.1'),
('filed_adjective_1', 'filed', 'adjective', 1, 'Of a material or object, having surfaces shaped or smoothed by the use of a file.', '["smoothed", "shaped", "ground", "trimmed"]', '["rough", "untouched", "unpolished"]', '["finishing", "surface finish"]', '["nail", "edge", "surface"]', '["filed document", "filed complaint", "filed motion", "filed patent", "filed application"]', '{"noun_forms": ["filing"], "verb_forms": ["file", "files", "filing", "filed"], "adjective_forms": ["filed"], "adverb_forms": []}', '["The filed metal edge was prepared for final assembly.", "The wooden dowel was filed to size."]', 'technology', '3', 102842, 3136, NULL, 'opengloss-v1.1'),
('filed_verb_1', 'filed', 'verb', 1, 'To officially submit documents or applications to an authority or court for consideration or action.', '["submit", "present", "file"]', '["withdraw", "dismiss"]', '["legal action", "official filing"]', '["lawsuit filing", "patent filing", "tax filing", "court filing"]', '["filing deadline", "filing system", "filing cabinet", "court filing", "lawsuit filing", "tax filing"]', '{"noun_forms": ["filing", "filings"], "verb_forms": ["refile"], "adjective_forms": [], "adverb_forms": []}', '["The plaintiff filed a complaint with the court.", "The company filed a patent application with the patent office."]', 'technology', '3', 102842, 3136, NULL, 'opengloss-v1.1'),
('filed_verb_2', 'filed', 'verb', 2, 'To smooth or shape a workpiece by means of a file or similar abrasive tool, removing burrs or excess material.', '["smooth", "shape", "abrade"]', '["roughen", "coarsen"]', '["machining", "material processing"]', '["metal filing", "wood filing"]', '["filing deadline", "filing system", "filing cabinet", "court filing", "lawsuit filing", "tax filing"]', '{"noun_forms": ["filing", "filings"], "verb_forms": ["refile"], "adjective_forms": [], "adverb_forms": []}', '["The technician filed the metal surface to remove burrs.", "The craftsman filed the wooden dowel to a precise diameter."]', 'technology', '3', 102842, 3136, NULL, 'opengloss-v1.1')
