INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('linked_adjective_0', 'linked', 'adjective', 0, 'Having a physical connection or being joined to another object.', '["connected", "attached", "joined"]', '["disconnected", "unattached", "loose"]', '["connection"]', '["interlinked", "interconnected"]', '["closely linked", "highly linked", "directly linked", "interlinked", "hyperlinked"]', '{"noun_forms": ["linkage", "linker"], "verb_forms": ["linking"], "adjective_forms": ["linkable", "linkless"], "adverb_forms": ["linkably"]}', '["The rings are physically linked by a short chain.", "The bolts are linked to the plate with a pin."]', 'technology', '4', 100587, 3186, NULL, 'opengloss-v1.1'),
('linked_verb_0', 'linked', 'verb', 0, 'To join or fasten one object to another so that they become physically connected.', '["connect", "join", "attach", "couple", "tie"]', '["disconnect", "detach", "separate"]', '["connect"]', '["join", "attach", "couple", "tie", "affix"]', '["linked to", "linked with", "linked together", "closely linked", "strongly linked", "linked data"]', '{"noun_forms": ["linkage", "linker"], "verb_forms": ["relink"], "adjective_forms": ["linkable"], "adverb_forms": []}', '["The teacher linked two magnets with a string to show magnetic attraction.", "A chain linked the two fences together so the area was secure."]', 'technology', '4', 100587, 3186, NULL, 'opengloss-v1.1'),
('linked_adjective_1', 'linked', 'adjective', 1, 'Having a hyperlink to another online resource that can be clicked.', '["hyperlinked", "connected", "linked"]', '["unlinked", "unconnected"]', '["link"]', '["anchor link", "external link", "internal link"]', '["closely linked", "highly linked", "directly linked", "interlinked", "hyperlinked"]', '{"noun_forms": ["linkage", "linker"], "verb_forms": ["linking"], "adjective_forms": ["linkable", "linkless"], "adverb_forms": ["linkably"]}', '["The cited source is linked in the bibliography.", "Click the linked citation to view the original study."]', 'technology', '4', 100587, 3186, NULL, 'opengloss-v1.1'),
('linked_verb_1', 'linked', 'verb', 1, 'To show a relationship between two ideas, events, or pieces of information.', '["relate", "associate", "connect", "correlate", "link"]', '["ignore", "disconnect", "separate"]', '["relate", "connect"]', '["correlate", "associate", "compare"]', '["linked to", "linked with", "linked together", "closely linked", "strongly linked", "linked data"]', '{"noun_forms": ["linkage", "linker"], "verb_forms": ["relink"], "adjective_forms": ["linkable"], "adverb_forms": []}', '["Scientists linked the data points to reveal a pattern between temperature and growth.", "The author linked the main idea to the supporting details in the paragraph."]', 'technology', '4', 100587, 3186, NULL, 'opengloss-v1.1'),
('linked_adjective_2', 'linked', 'adjective', 2, 'Conceptually related or associated; connected in meaning or cause.', '["related", "connected", "associated"]', '["unrelated", "unconnected", "disconnected"]', '["relation"]', '["correlated", "interrelated"]', '["closely linked", "highly linked", "directly linked", "interlinked", "hyperlinked"]', '{"noun_forms": ["linkage", "linker"], "verb_forms": ["linking"], "adjective_forms": ["linkable", "linkless"], "adverb_forms": ["linkably"]}', '["These findings are linked to the prior theory.", "The variables are linked in a causal model."]', 'technology', '4', 100587, 3186, NULL, 'opengloss-v1.1'),
('linked_verb_2', 'linked', 'verb', 2, 'In a digital context, to create a clickable path from one document or page to another.', '["hyperlink", "connect", "link"]', '["unlink", "disconnect", "detach"]', '["connect", "link"]', '["hyperlink", "hotlink", "anchor"]', '["linked to", "linked with", "linked together", "closely linked", "strongly linked", "linked data"]', '{"noun_forms": ["linkage", "linker"], "verb_forms": ["relink"], "adjective_forms": ["linkable"], "adverb_forms": []}', '["The web page linked to the science article for extra reading.", "The teacher linked the homework help site as a resource."]', 'technology', '4', 100587, 3186, NULL, 'opengloss-v1.1')
