INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('demolished_adjective_0', 'demolished', 'adjective', 0, 'Destroyed or torn down; in a state resulting from demolition, typically referring to structures or objects.', '["ruined", "wrecked", "obliterated", "razed"]', '["intact", "undamaged", "whole"]', '["destruction", "damage", "ruination"]', '["razed house", "ruined storefront", "demolished warehouse"]', '["demolished building", "demolished structure", "demolished site", "demolished facade", "demolished wall", "demolished room"]', '{"noun_forms": ["demolition", "demolisher"], "verb_forms": ["demolish"], "adjective_forms": ["demolishable"], "adverb_forms": []}', '["The building was demolished in 2023 to make way for a park.", "A demolished warehouse stood as a vacant lot."]', 'technology', '4', 100571, 3187, NULL, 'opengloss-v1.1'),
