INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('channels_noun_0', 'channels', 'noun', 0, 'A channel is a path or medium for transmitting information, signals, or goods; a TV or radio channel is a particular broadcast frequency or program.', '["means", "medium", "avenue", "route"]', '["blockage", "barrier"]', '["path"]', '["television channel", "radio channel", "news channel"]', '["distribution channel", "sales channel", "online channel", "television channel", "water channel", "channel of communication"]', '{"noun_forms": ["channeling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["She changed to a different channel on the TV.", "Students learn how channels carry messages in class discussions."]', 'technology', '3', 99407, 3217, NULL, 'opengloss-v1.1'),
('channels_verb_0', 'channels', 'verb', 0, 'To direct something along a path or through a medium so that it reaches a destination.', '["direct", "guide", "funnel", "transmit"]', '["divert", "block", "scatter", "dissipate"]', '["direct action"]', '["route data", "funnel funds"]', '["channel information", "channel energy", "channel emotions", "channel data", "channel resources"]', '{"noun_forms": ["channeler", "channelization"], "verb_forms": ["rechannel"], "adjective_forms": [], "adverb_forms": []}', '["The charity channels funds to classroom projects.", "Rivers channel water into a manmade canal."]', 'technology', '3', 99407, 3217, NULL, 'opengloss-v1.1'),
('channels_noun_1', 'channels', 'noun', 1, 'A water channel is a natural or artificial passage for water between bodies of water or along coastlines.', '["waterway", "canal", "watercourse", "passage"]', '["land", "dry land"]', '["geographic feature", "waterway"]', '["canal", "river channel", "tidal channel"]', '["distribution channel", "sales channel", "online channel", "television channel", "water channel", "channel of communication"]', '{"noun_forms": ["channeling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The channel between the islands guides boat traffic.", "Water flows through a shallow channel after rain."]', 'technology', '3', 99407, 3217, NULL, 'opengloss-v1.1'),
('channels_verb_1', 'channels', 'verb', 1, 'To focus or direct energy, attention, or emotion into a productive activity or outcome.', '["focus", "concentrate", "direct"]', '["scatter", "ignore", "waste"]', '["focus action"]', '["focus energy", "redirect energy"]', '["channel information", "channel energy", "channel emotions", "channel data", "channel resources"]', '{"noun_forms": ["channeler", "channelization"], "verb_forms": ["rechannel"], "adjective_forms": [], "adverb_forms": []}', '["She channels her energy into her homework.", "Students channel curiosity toward a science project."]', 'technology', '3', 99407, 3217, NULL, 'opengloss-v1.1'),
('channels_noun_2', 'channels', 'noun', 2, 'In business, a distribution channel is the path that goods or services travel through to reach customers.', '["network", "pipeline", "route", "means"]', '["direct sales", "no intermediary"]', '["sales channel", "distribution method"]', '["retailer channel", "online channel", "direct channel"]', '["distribution channel", "sales channel", "online channel", "television channel", "water channel", "channel of communication"]', '{"noun_forms": ["channeling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Online channels help students access learning materials.", "Retail channels bring products to homes and stores."]', 'technology', '3', 99407, 3217, NULL, 'opengloss-v1.1'),
('channels_verb_2', 'channels', 'verb', 2, 'To transmit information, signals, or data through a defined channel or medium.', '["transmit", "send", "relay"]', '["store", "block", "withhold"]', '["transmit"]', '["channel data", "channel signals"]', '["channel information", "channel energy", "channel emotions", "channel data", "channel resources"]', '{"noun_forms": ["channeler", "channelization"], "verb_forms": ["rechannel"], "adjective_forms": [], "adverb_forms": []}', '["The network channels data securely to the server.", "Researchers channel survey results through the school''s database."]', 'technology', '3', 99407, 3217, NULL, 'opengloss-v1.1')
