('brick_noun_0', 'brick', 'noun', 0, 'A rectangular block of fired or sun-dried clay used in construction and masonry to form walls, pavements, or facades.', '["block", "masonry unit", "clay brick"]', '["stone", "steel", "timber"]', '["building material", "construction material", "structural material"]', '["fired brick", "clay brick", "refractory brick"]', '["brick wall", "red brick", "clay brick", "bricklaying", "brickmaking", "brick and mortar"]', '{"noun_forms": ["brickwork", "bricklayer", "brickmaking"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The wall was built with standard red bricks.", "Clay bricks are fired at high temperatures to achieve strength."]', 'technology', '1', 98870, 3235, NULL, 'opengloss-v1.1'),
('brick_verb_0', 'brick', 'verb', 0, 'To construct a wall or other structure by laying bricks in mortar; to cover a surface with bricks as a construction activity.', '["bricklay"]', '["dismantle", "demolish"]', '["build", "construct", "masonry"]', '["bricklaying", "brickwork"]', '["brick wall", "brick oven", "brickwork", "bricklaying", "bricked device", "brick facade"]', '{"noun_forms": ["bricklayer", "bricklaying", "brickwork"], "verb_forms": ["unbrick"], "adjective_forms": [], "adverb_forms": []}', '["The contractor bricked the exterior walls of the library using standard red bricks.", "Bricklaying techniques described in the report improved moisture resistance in historic masonry."]', 'technology', '1', 98870, 3235, NULL, 'opengloss-v1.1'),
('brick_noun_1', 'brick', 'noun', 1, 'A nonfunctional electronic device, typically a smartphone or tablet, that has been rendered inoperable by a failed software update or hardware fault.', '["dead device", "unusable device", "bricked device"]', '["operational device", "functional device", "working device"]', '["electronic device", "consumer electronics"]', '["smartphone", "tablet", "laptop"]', '["brick wall", "red brick", "clay brick", "bricklaying", "brickmaking", "brick and mortar"]', '{"noun_forms": ["brickwork", "bricklayer", "brickmaking"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["After the firmware crash the phone became a brick.", "A bricked tablet cannot boot and is unusable."]', 'technology', '1', 98870, 3235, NULL, 'opengloss-v1.1'),
('brick_verb_1', 'brick', 'verb', 1, 'To cause a device or system to become inoperable, typically as a result of a failed firmware or software update or improper manipulation, thereby rendering it unusable.', '["disable", "cripple"]', '["unbrick", "restore"]', '["damage", "deactivation"]', '["soft brick", "hard brick"]', '["brick wall", "brick oven", "brickwork", "bricklaying", "bricked device", "brick facade"]', '{"noun_forms": ["bricklayer", "bricklaying", "brickwork"], "verb_forms": ["unbrick"], "adjective_forms": [], "adverb_forms": []}', '["A failed firmware update bricked the smartphone, rendering it nonfunctional.", "The router became bricked after the power outage, necessitating replacement."]', 'technology', '1', 98870, 3235, NULL, 'opengloss-v1.1'),
('brick_noun_2', 'brick', 'noun', 2, 'A large bundle of banknotes bound together and treated as a single negotiable unit, commonly referred to as a brick of cash in slang.', '["bundle", "cash bundle", "money stack"]', '["single bill", "single note", "loose cash"]', '["money", "currency"]', '["thousand dollar brick", "five thousand dollar brick"]', '["brick wall", "red brick", "clay brick", "bricklaying", "brickmaking", "brick and mortar"]', '{"noun_forms": ["brickwork", "bricklayer", "brickmaking"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The ransom was paid in a brick of cash.", "Investigators found a brick of cash concealed in the car glovebox."]', 'technology', '1', 98870, 3235, NULL, 'opengloss-v1.1')
