('representation_noun_0', 'representation', 'noun', 0, 'An image or sign that stands for something else, used to depict or illustrate a concept.', '["depiction", "portrayal", "image", "likeness"]', '["reality", "fact"]', '["communication", "concept"]', '["graphic representation", "pictorial representation", "diagrammatic depiction", "iconic depiction"]', '["data representation", "visual representation", "symbolic representation", "mathematical representation", "graphic representation"]', '{"noun_forms": ["representative"], "verb_forms": ["represent"], "adjective_forms": ["representational"], "adverb_forms": []}', '["The map is a graphic representation of the terrain.", "Portraits are representations of people in art class."]', 'philosophy', '5', 98753, 3238, NULL, 'opengloss-v1.1'),
('representation_noun_1', 'representation', 'noun', 1, 'A systematic way of presenting information or ideas, such as charts, diagrams, or models.', '["model", "diagram", "chart", "schema"]', '[]', '["method", "system"]', '["data chart", "statistical graph", "flow diagram", "scale model"]', '["data representation", "visual representation", "symbolic representation", "mathematical representation", "graphic representation"]', '{"noun_forms": ["representative"], "verb_forms": ["represent"], "adjective_forms": ["representational"], "adverb_forms": []}', '["A line chart is a data representation of temperature over time.", "Teachers use a diagram as a representation of the water cycle."]', 'philosophy', '5', 98753, 3238, NULL, 'opengloss-v1.1'),
('representation_noun_2', 'representation', 'noun', 2, 'The act of representing or speaking for a person or group, such as in government, school, or classroom.', '["delegation", "spokesmanship", "advocacy", "proxy"]', '[]', '["role", "function"]', '["proxy", "spokesperson", "class representative", "delegate"]', '["data representation", "visual representation", "symbolic representation", "mathematical representation", "graphic representation"]', '{"noun_forms": ["representative"], "verb_forms": ["represent"], "adjective_forms": ["representational"], "adverb_forms": []}', '["The class representative spoke for classmates in the meeting.", "Citizens elect representatives to voice their concerns in government."]', 'philosophy', '5', 98753, 3238, NULL, 'opengloss-v1.1'),
('representation_noun_3', 'representation', 'noun', 3, 'In mathematics or logic, a notation or model that expresses a quantity, relationship, or rule.', '["notation", "symbolization", "formula"]', '[]', '["sign system", "notation"]', '["equation", "graph", "table", "formula"]', '["data representation", "visual representation", "symbolic representation", "mathematical representation", "graphic representation"]', '{"noun_forms": ["representative"], "verb_forms": ["represent"], "adjective_forms": ["representational"], "adverb_forms": []}', '["A linear equation is a representation of the relation y equals mx plus b.", "A graph is a representation of how a variable changes."]', 'philosophy', '5', 98753, 3238, NULL, 'opengloss-v1.1')
