('processes_noun_0', 'processes', 'noun', 0, 'A series of actions or steps designed to achieve a particular result.', '["procedure", "method", "operation"]', '["stasis", "randomness", "chaos"]', '["action", "activity", "operation"]', '["manufacturing process", "digestive process", "photosynthesis"]', '["chemical processes", "biological processes", "industrial processes", "cognitive processes", "data processing", "computer processes"]', '{"noun_forms": ["processor", "processing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers follow a step by step process to test ideas.", "The cooking process shows how heat changes food."]', 'technology', '4', 98415, 3255, NULL, 'opengloss-v1.1'),
('processes_verb_0', 'processes', 'verb', 0, 'To perform a series of actions or steps in order to transform something or prepare something for use.', '["handle", "treat", "perform"]', '["ignore", "neglect"]', '["operation"]', '["cook", "sort", "mix"]', '["process data", "process information", "process steps", "process materials", "process samples", "process foods"]', '{"noun_forms": ["processor", "processing"], "verb_forms": ["processed", "processing", "processes"], "adjective_forms": ["processable", "unprocessed"], "adverb_forms": []}', '["The scientist processes samples for analysis.", "The factory processes metal parts from ore."]', 'technology', '4', 98415, 3255, NULL, 'opengloss-v1.1'),
('processes_noun_1', 'processes', 'noun', 1, 'A natural or mechanical sequence of changes that leads to a result.', '["development", "progression", "transformation"]', '["stasis", "chaos", "randomness"]', '["change", "development", "transformation"]', '["digestion", "respiration", "evaporation"]', '["chemical processes", "biological processes", "industrial processes", "cognitive processes", "data processing", "computer processes"]', '{"noun_forms": ["processor", "processing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Digestion is a biological process that breaks down food.", "Photosynthesis is a natural process by which plants convert light into sugar."]', 'technology', '4', 98415, 3255, NULL, 'opengloss-v1.1'),
('processes_verb_1', 'processes', 'verb', 1, 'To deal with information or data by applying steps to organize, analyze, or transform it.', '["analyze", "summarize", "organize"]', '["ignore", "disregard"]', '["procedure", "routine"]', '["data entry", "data analysis", "data formatting"]', '["process data", "process information", "process steps", "process materials", "process samples", "process foods"]', '{"noun_forms": ["processor", "processing"], "verb_forms": ["processed", "processing", "processes"], "adjective_forms": ["processable", "unprocessed"], "adverb_forms": []}', '["Students learn to process data from experiments.", "The computer processes information quickly."]', 'technology', '4', 98415, 3255, NULL, 'opengloss-v1.1'),
('processes_noun_2', 'processes', 'noun', 2, 'A program or set of tasks that a computer executes.', '["program", "task", "job"]', '["idle", "stopped", "paused"]', '["operation", "execution", "activity"]', '["background process", "foreground process", "system process"]', '["chemical processes", "biological processes", "industrial processes", "cognitive processes", "data processing", "computer processes"]', '{"noun_forms": ["processor", "processing"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Several processes run at once in a modern computer.", "The operating system manages multiple processes to keep programs responsive."]', 'technology', '4', 98415, 3255, NULL, 'opengloss-v1.1')
