INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('flows_noun_0', 'flows', 'noun', 0, 'The continuous movement of a liquid or gas within a medium, driven by pressure differences or other forces.', '["stream", "current", "flux"]', '["stagnation", "stasis"]', '["movement", "physical process"]', '["laminar flow", "turbulent flow"]', '["cash flow", "flow rate", "blood flow", "flow diagram", "laminar flow", "turbulent flow"]', '{"noun_forms": ["flowage", "flowability", "workflow"], "verb_forms": ["flowed", "flowing", "flows"], "adjective_forms": ["flowing"], "adverb_forms": ["flowingly"]}', '["The flow of saline through the catheter was carefully controlled.", "Laminar flow was observed in the microfluidic channel."]', 'science', '2', 98316, 3256, NULL, 'opengloss-v1.1'),
('flows_verb_0', 'flows', 'verb', 0, 'To move along or out in a steady, streamlike motion, typically of a liquid, gas, or other material.', '["move", "circulate", "stream"]', '["stagnate", "stop"]', '["move", "circulate"]', '["gush", "drip"]', '["flow rate", "laminar flow", "turbulent flow", "data flow", "flow of information", "blood flow"]', '{"noun_forms": ["flowage", "workflow", "flowchart", "inflow", "outflow"], "verb_forms": ["reflow"], "adjective_forms": ["flowable"], "adverb_forms": ["flowingly"]}', '["Water flows down the slope under gravity.", "The river flows into the estuary after the rain."]', 'science', '2', 98316, 3256, NULL, 'opengloss-v1.1'),
('flows_noun_1', 'flows', 'noun', 1, 'The movement of people, goods, or information through a system or network, typically to describe throughput or efficiency.', '["throughput", "circulation"]', '["gridlock", "stagnation"]', '["movement", "distribution"]', '["pedestrian flow", "vehicular flow"]', '["cash flow", "flow rate", "blood flow", "flow diagram", "laminar flow", "turbulent flow"]', '{"noun_forms": ["flowage", "flowability", "workflow"], "verb_forms": ["flowed", "flowing", "flows"], "adjective_forms": ["flowing"], "adverb_forms": ["flowingly"]}', '["Urban planners study traffic flow to optimize signal timing.", "Data flow through the network was analyzed for bottlenecks."]', 'science', '2', 98316, 3256, NULL, 'opengloss-v1.1'),
('flows_verb_1', 'flows', 'verb', 1, 'To move through a system or channel in a continuous stream, particularly information, data, funds, or signals.', '["transmit", "circulate", "convey"]', '["block", "interrupt", "halt"]', '["move", "transmit"]', '["data flow", "signal flow"]', '["flow rate", "laminar flow", "turbulent flow", "data flow", "flow of information", "blood flow"]', '{"noun_forms": ["flowage", "workflow", "flowchart", "inflow", "outflow"], "verb_forms": ["reflow"], "adjective_forms": ["flowable"], "adverb_forms": ["flowingly"]}', '["Data flows through the network according to routing policies.", "Funds flow through the banking system during quarterly adjustments."]', 'science', '2', 98316, 3256, NULL, 'opengloss-v1.1'),
('flows_noun_2', 'flows', 'noun', 2, 'The rate of transfer of a quantity through a cross section or boundary, such as mass or energy flow, usually expressed per unit time.', '["throughput", "flux"]', '["blockage", "impedance"]', '["transfer", "flux"]', '["mass flow", "heat flow"]', '["cash flow", "flow rate", "blood flow", "flow diagram", "laminar flow", "turbulent flow"]', '{"noun_forms": ["flowage", "flowability", "workflow"], "verb_forms": ["flowed", "flowing", "flows"], "adjective_forms": ["flowing"], "adverb_forms": ["flowingly"]}', '["Mass flow rate was measured by a differential pressure sensor.", "Energy flow through the channel increased with temperature difference."]', 'science', '2', 98316, 3256, NULL, 'opengloss-v1.1'),
('flows_verb_2', 'flows', 'verb', 2, 'To proceed smoothly and coherently in a sequence of actions, events, or a discourse.', '["proceed"]', '["stall", "disrupt"]', '["move", "progress"]', '["narrative flow", "process flow", "argument flow"]', '["flow rate", "laminar flow", "turbulent flow", "data flow", "flow of information", "blood flow"]', '{"noun_forms": ["flowage", "workflow", "flowchart", "inflow", "outflow"], "verb_forms": ["reflow"], "adjective_forms": ["flowable"], "adverb_forms": ["flowingly"]}', '["The lecture flows from theory to empirical results.", "The discussion flows well during the seminar."]', 'science', '2', 98316, 3256, NULL, 'opengloss-v1.1'),
('flows_noun_3', 'flows', 'noun', 3, 'The psychological state of complete immersion and focused engagement in an activity, often producing high performance and enjoyment.', '["absorption", "immersion", "engagement"]', '["boredom", "distraction"]', '["psychological state", "mental state"]', '["flow state", "creative flow"]', '["cash flow", "flow rate", "blood flow", "flow diagram", "laminar flow", "turbulent flow"]', '{"noun_forms": ["flowage", "flowability", "workflow"], "verb_forms": ["flowed", "flowing", "flows"], "adjective_forms": ["flowing"], "adverb_forms": ["flowingly"]}', '["The athlete experienced flow during the race.", "Flow occurs when skill matches challenge level."]', 'science', '2', 98316, 3256, NULL, 'opengloss-v1.1')
