BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('file_noun_0', 'file', 'noun', 0, 'A named collection of data stored on a storage medium, representing a discrete unit for storage and retrieval in computing.', '["document", "record", "data item", "data object"]', '["directory", "folder"]', '["data object", "digital unit"]', '["text file", "binary file", "image file", "executable file", "log file"]', '["data file", "log file", "text file", "source file", "configuration file", "file extension"]', '{"noun_forms": ["filing", "filesystem"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The dataset was saved as a single data file.", "Each user task creates a new data file in the repository."]', 'technology', '4', 97283, 3280, NULL, 'opengloss-v1.1'),
('file_verb_0', 'file', 'verb', 0, 'To place a document or data item into a storage location within a filing system, physical or digital, for organization and later retrieval.', '["store", "archive", "record"]', '["retrieve", "delete"]', '["document storage"]', '["archive", "index", "classify"]', '["file a patent", "file a patent application", "file a lawsuit", "file a tax return", "file an application", "file a report"]', '{"noun_forms": ["filing"], "verb_forms": ["refile"], "adjective_forms": [], "adverb_forms": []}', '["The technician filed the quality assurance report into the project directory.", "Researchers filed the data into the central repository."]', 'technology', '4', 97283, 3280, NULL, 'opengloss-v1.1'),
('file_noun_1', 'file', 'noun', 1, 'A physical or electronic container for documents about a matter, typically kept in an organized filing system.', '["document folder", "case file", "records file"]', '["unfiled documents"]', '["records", "archive"]', '["case file", "customer file", "personnel file", "project file"]', '["data file", "log file", "text file", "source file", "configuration file", "file extension"]', '{"noun_forms": ["filing", "filesystem"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The case file was retrieved from the archives for review.", "Personnel files are stored under strict confidentiality."]', 'technology', '4', 97283, 3280, NULL, 'opengloss-v1.1'),
('file_verb_1', 'file', 'verb', 1, 'To submit documents or applications to an official body for formal processing.', '["submit", "present", "register"]', '["withdraw", "reject"]', '["legal procedure"]', '["patent filing", "lawsuit filing", "tax filing"]', '["file a patent", "file a patent application", "file a lawsuit", "file a tax return", "file an application", "file a report"]', '{"noun_forms": ["filing"], "verb_forms": ["refile"], "adjective_forms": [], "adverb_forms": []}', '["The inventor filed a patent with the patent office.", "The plaintiff filed a complaint in district court."]', 'technology', '4', 97283, 3280, NULL, 'opengloss-v1.1'),
('file_noun_2', 'file', 'noun', 2, 'A file containing source code for a program in a given programming language.', '["source file", "code file", "program file"]', '["executable file"]', '["text file", "data file"]', '["Java source file", "Python source file", "C source file"]', '["data file", "log file", "text file", "source file", "configuration file", "file extension"]', '{"noun_forms": ["filing", "filesystem"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The Java source file defines classes used in compilation.", "Developers modify Python source files before committing."]', 'technology', '4', 97283, 3280, NULL, 'opengloss-v1.1'),
('file_verb_2', 'file', 'verb', 2, 'To write data to a storage file on a computer system for persistence and later retrieval.', '["write", "save", "persist"]', '["erase", "delete"]', '["file operation"]', '["disk write", "file write", "append operation"]', '["file a patent", "file a patent application", "file a lawsuit", "file a tax return", "file an application", "file a report"]', '{"noun_forms": ["filing"], "verb_forms": ["refile"], "adjective_forms": [], "adverb_forms": []}', '["The software writes the results to a log file.", "The program saves intermediate data to disk file."]', 'technology', '4', 97283, 3280, NULL, 'opengloss-v1.1'),
('file_noun_3', 'file', 'noun', 3, 'An executable file is a compiled or binary that can be executed by a computer to run a program.', '["binary", "program file"]', '["source file"]', '["data file", "computer file"]', '["Windows executable", "ELF executable", "PE executable"]', '["data file", "log file", "text file", "source file", "configuration file", "file extension"]', '{"noun_forms": ["filing", "filesystem"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The installer launches from the Windows executable.", "An unsigned executable may be blocked by security policies."]', 'technology', '4', 97283, 3280, NULL, 'opengloss-v1.1')
