INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('cable_noun_0', 'cable', 'noun', 0, 'A cable is a thick rope made of braided or twisted metal wires or strong fibers used to lift, tow, or secure heavy loads.', '["rope", "line"]', '["wire"]', '["rope"]', '["wire rope", "steel cable", "manila rope"]', '["power cable", "electrical cable", "HDMI cable", "Ethernet cable", "coaxial cable", "fiber optic cable"]', '{"noun_forms": ["cabling"], "verb_forms": ["cable", "cables", "cabled", "cabling"], "adjective_forms": [], "adverb_forms": []}', '["The crane hoisted the crate using a steel cable.", "They secured the heavy load with a strong metal cable."]', 'technology', '3', 93996, 3382, NULL, 'opengloss-v1.1'),
('cable_verb_0', 'cable', 'verb', 0, 'To install electrical or communications cables in a building or space to provide power, data, or connectivity.', '["wire", "connect", "install"]', '["detach", "disconnect", "unwire"]', '["connect"]', '["wiring", "cabling"]', '["power cable", "fiber optic cable", "undersea cable", "coaxial cable", "cable TV", "cable management"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The technician cables the classroom for high speed internet.", "We will cable the lab with new data cables."]', 'technology', '3', 93996, 3382, NULL, 'opengloss-v1.1'),
('cable_noun_1', 'cable', 'noun', 1, 'A cable is a bundle of insulated conductors wrapped in a protective sheath used to transmit electricity or signals.', '["wire", "conductor"]', '["wireless"]', '["electrical component"]', '["HDMI cable", "Ethernet cable", "coaxial cable"]', '["power cable", "electrical cable", "HDMI cable", "Ethernet cable", "coaxial cable", "fiber optic cable"]', '{"noun_forms": ["cabling"], "verb_forms": ["cable", "cables", "cabled", "cabling"], "adjective_forms": [], "adverb_forms": []}', '["Plug the power cable into the outlet.", "The HDMI cable carries video and audio signals."]', 'technology', '3', 93996, 3382, NULL, 'opengloss-v1.1'),
('cable_verb_1', 'cable', 'verb', 1, 'To transmit a message or information by telegraph or cable, typically over long distances.', '["telegraph", "transmit"]', '["receive", "obtain"]', '["transmit"]', '["telegraph"]', '["power cable", "fiber optic cable", "undersea cable", "coaxial cable", "cable TV", "cable management"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The newsroom cabled the story from overseas.", "Officials cabled the findings to headquarters."]', 'technology', '3', 93996, 3382, NULL, 'opengloss-v1.1'),
('cable_verb_2', 'cable', 'verb', 2, 'To secure or fasten with a cable or wire rope to prevent movement or shifting.', '["lash", "tie"]', '["loosen", "unfasten"]', '["secure"]', '["lash", "tie"]', '["power cable", "fiber optic cable", "undersea cable", "coaxial cable", "cable TV", "cable management"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The crate was cabled to the deck to prevent movement.", "The ship was cabled to the pier with steel lines."]', 'technology', '3', 93996, 3382, NULL, 'opengloss-v1.1')
