('keyboards_noun_0', 'keyboards', 'noun', 0, 'A hardware input device consisting of a panel of keys used to input text and commands to a computer or other electronic device.', '["input device", "typing device", "peripheral"]', '["mouse"]', '["computer peripheral"]', '["gaming keyboard", "mechanical keyboard", "ergonomic keyboard"]', '["computer keyboards", "mechanical keyboard", "keyboard shortcuts", "keyboard layout", "ergonomic keyboard", "piano keyboard"]', '{"noun_forms": ["keyboarding", "keyboardist"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '[]', 'technology', '2', 93872, 3383, NULL, 'opengloss-v1.1'),
('keyboards_verb_0', 'keyboards', 'verb', 0, 'To type text or commands on a keyboard, thereby inputting data or instructions into a computer or digital system.', '["type", "input", "enter"]', '["erase", "delete", "undo"]', '["data entry action"]', '["typing", "keying"]', '["keyboard input", "keyboard layout", "keyboard shortcut", "keyboard data entry", "keyboard interface", "keyboard controller"]', '{"noun_forms": ["keyboarder", "keyboarding"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Participants keyboarded their responses into the computer survey.", "Researchers keyboarded textual data during the study session."]', 'technology', '2', 93872, 3383, NULL, 'opengloss-v1.1'),
('keyboards_noun_1', 'keyboards', 'noun', 1, 'The set of keys on a piano or other keyboard instrument, used to produce musical pitches when pressed.', '["piano keyboard", "keyboard instrument", "music keyboard"]', '["string instrument"]', '["musical instrument"]', '["piano", "organ"]', '["computer keyboards", "mechanical keyboard", "keyboard shortcuts", "keyboard layout", "ergonomic keyboard", "piano keyboard"]', '{"noun_forms": ["keyboarding", "keyboardist"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '[]', 'technology', '2', 93872, 3383, NULL, 'opengloss-v1.1'),
('keyboards_verb_1', 'keyboards', 'verb', 1, 'To configure or customize a keyboard''s mappings and shortcuts by defining key bindings on a device, typically in order to optimize workflow or accessibility.', '["configure", "remap", "customize"]', '["reset", "undo"]', '["device configuration"]', '["keyboard remapping", "layout customization", "shortcut definitions"]', '["keyboard input", "keyboard layout", "keyboard shortcut", "keyboard data entry", "keyboard interface", "keyboard controller"]', '{"noun_forms": ["keyboarder", "keyboarding"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers customized the keyboard layout to support bilingual input.", "The software permits key remapping to define shortcuts for efficient data entry."]', 'technology', '2', 93872, 3383, NULL, 'opengloss-v1.1'),
('keyboards_noun_2', 'keyboards', 'noun', 2, 'A software interface that presents a keyboard layout on a display for input without a physical keyboard.', '["on screen keyboard", "soft keyboard", "virtual keyboard"]', '["physical keyboard"]', '["input method"]', '["emoji keyboard", "gesture keyboard", "predictive keyboard"]', '["computer keyboards", "mechanical keyboard", "keyboard shortcuts", "keyboard layout", "ergonomic keyboard", "piano keyboard"]', '{"noun_forms": ["keyboarding", "keyboardist"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '[]', 'technology', '2', 93872, 3383, NULL, 'opengloss-v1.1')
