INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('platforms_noun_0', 'platforms', 'noun', 0, 'A raised flat surface used for people or items to stand on, or to display demonstrations in a classroom or stage setting.', '["dais", "stage", "podium"]', '["ground", "floor"]', '["surface", "structure"]', '["dais", "stage", "podium"]', '["software platform", "development platform", "mobile platform", "web platform", "educational platform"]', '{"noun_forms": ["platformer"], "verb_forms": ["platforming"], "adjective_forms": ["platformed"], "adverb_forms": []}', '["The raised platform held the science demonstration for the class.", "Students stood on the platform to measure the pendulum swing."]', 'technology', '2', 93693, 3388, NULL, 'opengloss-v1.1'),
('platforms_verb_0', 'platforms', 'verb', 0, 'To provide or present as a platform for someone to speak, perform, or share ideas.', '["host", "showcase", "present"]', '["silence", "suppress", "exclude"]', '["transitive verb"]', '["guest talk", "panel discussion", "assembly"]', '["platforms a speaker", "platforms a debate", "platforms an online service", "platforms a show", "platform-based curriculum", "platforms the audience"]', '{"noun_forms": ["platformer"], "verb_forms": ["platforming", "platformed"], "adjective_forms": ["platform-based"], "adverb_forms": []}', '["The school platformed a guest scientist to speak about ecosystems.", "The online show platformed multiple student voices during the science week."]', 'technology', '2', 93693, 3388, NULL, 'opengloss-v1.1'),
('platforms_noun_1', 'platforms', 'noun', 1, 'A declared set of goals, principles, and policies that a person or group supports.', '["agenda", "stance", "policies"]', '["opposition"]', '["policy", "program"]', '["party platform", "campaign platform", "policy platform"]', '["software platform", "development platform", "mobile platform", "web platform", "educational platform"]', '{"noun_forms": ["platformer"], "verb_forms": ["platforming"], "adjective_forms": ["platformed"], "adverb_forms": []}', '["The candidate outlined her platform during the debate to attract voters.", "Voters compared each party''s platform before casting ballots."]', 'technology', '2', 93693, 3388, NULL, 'opengloss-v1.1'),
('platforms_verb_1', 'platforms', 'verb', 1, 'To base, establish, or provide as a platform for a program, service, or media.', '["base", "establish", "deploy"]', '["detach", "remove", "disconnect"]', '["transitive verb"]', '["deploy app", "launch service", "offer platform"]', '["platforms a speaker", "platforms a debate", "platforms an online service", "platforms a show", "platform-based curriculum", "platforms the audience"]', '{"noun_forms": ["platformer"], "verb_forms": ["platforming", "platformed"], "adjective_forms": ["platform-based"], "adverb_forms": []}', '["The curriculum platformed the new science app across tablets.", "The company platformed its service on multiple operating systems."]', 'technology', '2', 93693, 3388, NULL, 'opengloss-v1.1'),
('platforms_noun_2', 'platforms', 'noun', 2, 'A software or hardware environment that enables software applications to run or be built upon.', '["environment", "framework", "system"]', '["standalone"]', '["software system", "operating system"]', '["web platform", "mobile platform", "gaming platform"]', '["software platform", "development platform", "mobile platform", "web platform", "educational platform"]', '{"noun_forms": ["platformer"], "verb_forms": ["platforming"], "adjective_forms": ["platformed"], "adverb_forms": []}', '["Developers publish apps on a platform that supports multiple devices.", "The platform provides APIs and tools for developers."]', 'technology', '2', 93693, 3388, NULL, 'opengloss-v1.1')
