INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('crash_adjective_0', 'crash', 'adjective', 0, 'Describes something done quickly and intensely to achieve rapid understanding or results.', '["intensive", "rapid", "urgent"]', '["gradual", "slow", "extended"]', '["modifier", "descriptive word", "adjective"]', '["crash course", "crash diet", "crash program"]', '["crash course", "crash diet", "crash program", "crash test", "crash landing", "crash scene"]', '{"noun_forms": ["crashworthiness", "crashness"], "verb_forms": [], "adjective_forms": ["crashproof"], "adverb_forms": []}', '["Students take a crash course in algebra before the test.", "Teachers offer a crash program to cover topics quickly."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1'),
('crash_noun_0', 'crash', 'noun', 0, 'A sudden collision between two or more vehicles or objects that causes damage.', '["collision", "accident", "wreck", "impact"]', '["smooth ride", "safe travel"]', '["event", "incident"]', '["car crash", "bus crash", "plane crash"]', '["car crash", "computer crash", "crash course", "crash site", "plane crash", "data crash"]', '{"noun_forms": ["crashiness", "crasher"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The car crash disrupted traffic near the school.", "Emergency crews arrived after the crash in town."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1'),
('crash_verb_0', 'crash', 'verb', 0, 'To hit something or someone with force, often causing damage or stopping movement.', '["collide", "ram", "smash"]', '["avoid", "miss", "misses"]', '["collision", "impact"]', '["car crash", "bus crash", "bike crash"]', '["car crash", "computer crash", "crash course", "crash site", "crash test", "crash report"]', '{"noun_forms": ["crasher", "crash course", "crash test", "crash report", "crashworthiness"], "verb_forms": [], "adjective_forms": ["crashy", "crashworthy"], "adverb_forms": []}', '["The car crashed into the tree after skidding on the wet road.", "Two cars crashed at the busy intersection during rush hour."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1'),
('crash_adjective_1', 'crash', 'adjective', 1, 'Relating to or caused by a collision or crash; used to describe events or items connected to a crash.', '["accident related", "collision related"]', '[]', '["descriptor", "modifier", "adjective"]', '["crash report", "crash site", "crash data", "crash scene"]', '["crash course", "crash diet", "crash program", "crash test", "crash landing", "crash scene"]', '{"noun_forms": ["crashworthiness", "crashness"], "verb_forms": [], "adjective_forms": ["crashproof"], "adverb_forms": []}', '["The crash report listed injuries and vehicle damage.", "Investigators studied crash scene photographs."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1'),
('crash_noun_1', 'crash', 'noun', 1, 'A sudden malfunction or shutdown of a computer or software program.', '["system failure", "malfunction", "shutdown"]', '["stable operation", "normal operation"]', '["failure", "error"]', '["blue screen", "kernel panic"]', '["car crash", "computer crash", "crash course", "crash site", "plane crash", "data crash"]', '{"noun_forms": ["crashiness", "crasher"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The classroom computer crashed during the test.", "Students saved work before the crash occurred."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1'),
('crash_verb_1', 'crash', 'verb', 1, 'To stop functioning or work suddenly, especially a computer program or device.', '["fail", "freeze", "collapse", "break down"]', '["run", "work", "function"]', '["malfunction"]', '["computer crash", "software crash", "app crash", "phone crash"]', '["car crash", "computer crash", "crash course", "crash site", "crash test", "crash report"]', '{"noun_forms": ["crasher", "crash course", "crash test", "crash report", "crashworthiness"], "verb_forms": [], "adjective_forms": ["crashy", "crashworthy"], "adverb_forms": []}', '["The tablet crashed in the middle of the online test and needed a restart.", "The software crashed when she tried to save her report."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1'),
('crash_adjective_2', 'crash', 'adjective', 2, 'Used in compound forms to indicate protection against or resistance to impacts; describing equipment intended to withstand crashes.', '["protective", "impact resistant", "shock absorbing"]', '[]', '["modifier", "descriptive term", "adjective"]', '["crash-resistant", "crash-proof", "crash-rated"]', '["crash course", "crash diet", "crash program", "crash test", "crash landing", "crash scene"]', '{"noun_forms": ["crashworthiness", "crashness"], "verb_forms": [], "adjective_forms": ["crashproof"], "adverb_forms": []}', '["A crash resistant bumper helps cars absorb impact.", "A crash proof case protects the device during drops."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1'),
('crash_noun_2', 'crash', 'noun', 2, 'A rapid large decline in prices or market value.', '["collapse", "slump", "downturn"]', '["boom", "recovery"]', '["economic event", "market change"]', '["stock market crash", "housing crash"]', '["car crash", "computer crash", "crash course", "crash site", "plane crash", "data crash"]', '{"noun_forms": ["crashiness", "crasher"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Investors feared a stock market crash today.", "A crash in prices affected family budgets."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1'),
('crash_noun_3', 'crash', 'noun', 3, 'A short intensive course of study designed to teach a topic quickly.', '["intensive course", "short course", "crash course"]', '["long course", "extended program"]', '["education program", "course"]', '["math crash course", "science crash course"]', '["car crash", "computer crash", "crash course", "crash site", "plane crash", "data crash"]', '{"noun_forms": ["crashiness", "crasher"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Parents enrolled their child in a math crash course.", "The science class joined a crash course in algebra."]', 'technology', '2', 93367, 3392, NULL, 'opengloss-v1.1')
