('panel_adjective_0', 'panel', 'adjective', 0, 'Relating to or decided by a panel of experts, typically involving evaluation by a small group.', '["panel-based", "expert-led", "juried"]', '["individual-based", "unreviewed"]', '["qualitative descriptor", "adjective"]', '["expert-led", "jury-based"]', '["panel-based assessment", "panel discussion", "paneled walls", "paneled room", "paneled doors", "panel of experts"]', '{"noun_forms": ["paneling", "panelist"], "verb_forms": [], "adjective_forms": ["paneled"], "adverb_forms": []}', '["The panel-based assessment will determine whether students meet the standards.", "A panel-based interview helps teachers select reading materials."]', 'technology', '4', 92849, 3408, NULL, 'opengloss-v1.1'),
('panel_noun_0', 'panel', 'noun', 0, 'A flat piece forming part of a surface such as a wall or door, often rectangular and used to cover or decorate.', '["board", "slab"]', '["uncovered surface", "open area"]', '["flat object", "surface piece"]', '["wood panel", "metal panel", "decorative panel"]', '["solar panel", "panel discussion", "electrical panel", "wooden panel", "panel of experts", "decorative panel"]', '{"noun_forms": ["paneling", "panelist"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The wall panel adds color to the classroom.", "We replaced the door panel to refresh the entryway."]', 'technology', '4', 92849, 3408, NULL, 'opengloss-v1.1'),
('panel_verb_0', 'panel', 'verb', 0, 'To cover or clad a surface such as a wall or door with flat panels.', '["cover", "coat", "clad"]', '["uncover", "expose"]', '["surface finishing", "decorate action"]', '["wood panel", "glass panel"]', '["panel walls", "wood paneling", "decorative paneling", "panel discussion", "panel of experts", "interior paneling"]', '{"noun_forms": ["panelist", "paneling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The carpenter panel walls with oak panels.", "They will panel the hallway using plywood panels."]', 'technology', '4', 92849, 3408, NULL, 'opengloss-v1.1'),
('panel_adjective_1', 'panel', 'adjective', 1, 'Paneled: having panels or divided into sections by panels on surfaces such as walls and furniture.', '["paneled", "panelled"]', '["unpaneled", "bare"]', '["architectural feature", "surfacial design"]', '["wood-paneled", "metal-paneled"]', '["panel-based assessment", "panel discussion", "paneled walls", "paneled room", "paneled doors", "panel of experts"]', '{"noun_forms": ["paneling", "panelist"], "verb_forms": [], "adjective_forms": ["paneled"], "adverb_forms": []}', '["The paneled walls in the classroom reduce echo and soften sound.", "A paneled cabinet hides wires and adds warmth to the room."]', 'technology', '4', 92849, 3408, NULL, 'opengloss-v1.1'),
('panel_noun_1', 'panel', 'noun', 1, 'A panel is a group of people chosen to discuss or judge a matter, such as a panel of experts.', '["committee", "expert panel"]', '["one person", "single judge"]', '["group", "body"]', '["expert panel", "jury panel", "advisory panel"]', '["solar panel", "panel discussion", "electrical panel", "wooden panel", "panel of experts", "decorative panel"]', '{"noun_forms": ["paneling", "panelist"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The university formed a panel to review the proposal.", "A panel of experts presented the study findings."]', 'technology', '4', 92849, 3408, NULL, 'opengloss-v1.1'),
('panel_verb_1', 'panel', 'verb', 1, 'To appoint as a panel or to assemble a panel of experts for a meeting or review.', '["appoint", "assemble", "select"]', '["disband", "dissolve"]', '["form a committee", "select a group"]', '["panel a jury", "panel an advisory board"]', '["panel walls", "wood paneling", "decorative paneling", "panel discussion", "panel of experts", "interior paneling"]', '{"noun_forms": ["panelist", "paneling"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The committee panels four scientists to judge proposals.", "A panel of experts was assembled to review the project."]', 'technology', '4', 92849, 3408, NULL, 'opengloss-v1.1'),
('panel_noun_2', 'panel', 'noun', 2, 'An electrical enclosure that houses breakers or fuses to control circuits.', '["breaker box", "service panel"]', '["open circuit"]', '["electrical equipment", "control device"]', '["breaker panel", "service panel", "distribution panel"]', '["solar panel", "panel discussion", "electrical panel", "wooden panel", "panel of experts", "decorative panel"]', '{"noun_forms": ["paneling", "panelist"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The breaker panel is located in the basement.", "The service panel houses the main breakers."]', 'technology', '4', 92849, 3408, NULL, 'opengloss-v1.1'),
('panel_noun_3', 'panel', 'noun', 3, 'A rectangular frame presenting a single scene in a comic, graphic novel, or storyboard.', '["frame", "cell"]', '["full page"]', '["layout element", "page element"]', '["comic panel", "storyboard panel"]', '["solar panel", "panel discussion", "electrical panel", "wooden panel", "panel of experts", "decorative panel"]', '{"noun_forms": ["paneling", "panelist"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The first panel shows the hero arriving.", "In the storyboard, a panel depicts the cliff scene."]', 'technology', '4', 92849, 3408, NULL, 'opengloss-v1.1')
