BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('bomb_noun_0', 'bomb', 'noun', 0, 'A device that contains explosive material and is designed to explode to cause damage.', '["explosive", "explosive device", "weapon"]', '["harmless object", "nonlethal device"]', '["weapon"]', '["grenade", "car bomb"]', '["bomb squad", "bomb blast", "bomb threat", "bomb shelter", "atomic bomb", "nuclear bomb"]', '{"noun_forms": [], "verb_forms": ["bombing", "bombed"], "adjective_forms": ["bombproof"], "adverb_forms": []}', '["The science unit explains how an explosive device releases energy.", "Safety education explains why such devices are strictly regulated."]', 'technology', '4', 90063, 3486, NULL, 'opengloss-v1.1'),
('bomb_verb_0', 'bomb', 'verb', 0, 'To drop explosive devices onto a target as a military attack.', '["bombard", "attack", "strike"]', '["defuse", "protect"]', '["attack verb"]', '["airstrike", "bombing"]', '["airstrike", "bombing campaign", "aerial attack", "mass bombing", "detonation charge"]', '{"noun_forms": ["bombing", "bombardment", "bombproofing"], "verb_forms": [], "adjective_forms": ["bombproof"], "adverb_forms": []}', '["The air force bombed the harbor last night.", "Officials decided to bomb the target to disrupt supply lines."]', 'technology', '4', 90063, 3486, NULL, 'opengloss-v1.1'),
('bomb_noun_1', 'bomb', 'noun', 1, 'A failure or disaster, especially in a performance or plan.', '["flop", "disaster", "dud"]', '["success"]', '["failure"]', '["fiasco", "flop"]', '["bomb squad", "bomb blast", "bomb threat", "bomb shelter", "atomic bomb", "nuclear bomb"]', '{"noun_forms": [], "verb_forms": ["bombing", "bombed"], "adjective_forms": ["bombproof"], "adverb_forms": []}', '["The science fair project turned out to be a bomb due to poor planning.", "The group presentation bombed after failing to cite sources."]', 'technology', '4', 90063, 3486, NULL, 'opengloss-v1.1'),
('bomb_verb_1', 'bomb', 'verb', 1, 'To perform very poorly, especially on a test or presentation.', '["fail", "flop"]', '["ace", "excel", "succeed"]', '["informal verb"]', '["flop", "tank"]', '["airstrike", "bombing campaign", "aerial attack", "mass bombing", "detonation charge"]', '{"noun_forms": ["bombing", "bombardment", "bombproofing"], "verb_forms": [], "adjective_forms": ["bombproof"], "adverb_forms": []}', '["The math test bombed, and she earned a low score.", "Her science presentation bombed with the audience."]', 'technology', '4', 90063, 3486, NULL, 'opengloss-v1.1'),
('bomb_verb_2', 'bomb', 'verb', 2, 'To cause an explosive device to explode.', '["detonate"]', '["defuse", "disarm"]', '["explode"]', '["ignite", "trigger"]', '["airstrike", "bombing campaign", "aerial attack", "mass bombing", "detonation charge"]', '{"noun_forms": ["bombing", "bombardment", "bombproofing"], "verb_forms": [], "adjective_forms": ["bombproof"], "adverb_forms": []}', '["The manual explains how detonation occurs in a controlled setting.", "Experts discuss detonation as the rapid release of energy."]', 'technology', '4', 90063, 3486, NULL, 'opengloss-v1.1')
