-- lexi ETL: hull (2026-09-18T16:20:22Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('hull_noun_0', 'hull', 'noun', 0, 'The main body of a watercraft that provides buoyancy and structural integrity, forming the watertight envelope of the vessel.', '["ship body", "vessel body", "main body"]', '["superstructure"]', '["ship component", "vessel part"]', '["monohull", "displacement hull", "planing hull"]', '["ship hull", "hull thickness", "hull form", "hull integrity", "hull material", "seed hull"]', '{"noun_forms": ["huller"], "verb_forms": ["hulling"], "adjective_forms": ["hulled"], "adverb_forms": []}', '["The hull form governs buoyancy and stability.", "Researchers compare hull geometry to optimize seakeeping and efficiency."]', 'technology', '5', 88901, 3534, NULL, 'opengloss-v1.1'),
('hull_verb_0', 'hull', 'verb', 0, 'To remove the hull from a seed or fruit as part of processing, exposing the edible kernel or inner material, typically in agricultural or food processing contexts.', '["dehull", "shell"]', '[]', '["seed processing", "food processing", "agricultural processing"]', '["dehulling", "shelling", "husking"]', '["hull grain", "hull seeds", "hull corn", "hulled grains", "dehulling rice", "dehulling oats"]', '{"noun_forms": ["huller"], "verb_forms": ["dehull"], "adjective_forms": ["hulled"], "adverb_forms": []}', '["The dehulling stage increases kernel yield in rice processing.", "The oatmeal production line includes a step to hull the kernels before milling."]', 'technology', '5', 88901, 3534, NULL, 'opengloss-v1.1'),
('hull_noun_1', 'hull', 'noun', 1, 'The protective outer covering of seeds and some fruits, comprising the seed coat or pericarp.', '["seed coat", "husk", "pericarp"]', '["kernel"]', '["seed covering", "protective layer"]', '["rice hull", "barley hull", "corn hull"]', '["ship hull", "hull thickness", "hull form", "hull integrity", "hull material", "seed hull"]', '{"noun_forms": ["huller"], "verb_forms": ["hulling"], "adjective_forms": ["hulled"], "adverb_forms": []}', '["Rice hulls are removed during milling.", "Hull thickness influences milling yield and grain protection."]', 'technology', '5', 88901, 3534, NULL, 'opengloss-v1.1'),
('hull_noun_2', 'hull', 'noun', 2, 'In geometry and related fields, hull denotes the smallest convex set containing a given set of points, commonly called the convex hull.', '["envelope", "enclosure"]', '["interior"]', '["geometric construct", "enclosing set"]', '["convex hull", "affine hull"]', '["ship hull", "hull thickness", "hull form", "hull integrity", "hull material", "seed hull"]', '{"noun_forms": ["huller"], "verb_forms": ["hulling"], "adjective_forms": ["hulled"], "adverb_forms": []}', '["The convex hull of the points forms a polygon.", "Algorithms compute hulls efficiently in higher dimensions."]', 'technology', '5', 88901, 3534, NULL, 'opengloss-v1.1')
