INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('phone_noun_0', 'phone', 'noun', 0, 'A device for voice communication that transmits and receives audio over a distance, typically consisting of a microphone, speaker, and network interface.', '["telephone", "landline", "handset"]', '[]', '["telecommunication device", "communication device"]', '["landline", "cellphone", "smartphone"]', '["phone number", "phone call", "phone charger", "landline phone", "cellphone", "phone book"]', '{"noun_forms": ["phonebook", "phonecard", "smartphone"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Classrooms often deploy desk phones connected to a campus telephony system.", "The emergence of digital networks transformed traditional telephone devices in scholarly communication contexts."]', 'technology', '1', 88832, 3536, NULL, 'opengloss-v1.1'),
('phone_verb_0', 'phone', 'verb', 0, 'To contact someone by telephone by dialing their number in order to convey information or request information, typically within an academic or professional setting.', '["call", "telephone", "ring up", "dial"]', '["text", "email"]', '["contact", "communicate"]', '["dial", "ring"]', '["make a phone call", "phone number", "phone line", "phone system", "phone service", "phone a colleague"]', '{"noun_forms": ["phoner", "phone call"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers phoned participants to verify consent.", "The principal investigator phoned the lab to report results."]', 'technology', '1', 88832, 3536, NULL, 'opengloss-v1.1'),
('phone_noun_1', 'phone', 'noun', 1, 'A mobile telecommunication device with computing capabilities that provides voice communication, data services, and access to applications.', '["smartphone", "handheld computer", "mobile phone"]', '["basic phone", "dumbphone"]', '["mobile device", "communication device"]', '["phablet", "camera phone", "gaming phone"]', '["phone number", "phone call", "phone charger", "landline phone", "cellphone", "phone book"]', '{"noun_forms": ["phonebook", "phonecard", "smartphone"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["University researchers frequently collect data using smartphones in fieldwork.", "Smartphones enable rapid dissemination of scholarly materials and collaborative tools in education."]', 'technology', '1', 88832, 3536, NULL, 'opengloss-v1.1'),
('phone_verb_1', 'phone', 'verb', 1, 'To submit information or commentary by telephone to a program or organization, typically as a remote contribution during a broadcast or meeting.', '["inform", "contribute", "report"]', '["text", "email"]', '["inform", "contribute"]', '["call in", "ring in", "phone in"]', '["make a phone call", "phone number", "phone line", "phone system", "phone service", "phone a colleague"]', '{"noun_forms": ["phoner", "phone call"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The witness phoned in his testimony.", "Audience members phoned in questions during the session."]', 'technology', '1', 88832, 3536, NULL, 'opengloss-v1.1'),
('phone_noun_2', 'phone', 'noun', 2, 'The handheld component of a telephone that contains the earpiece and mouthpiece and connects to the base unit via a cord or wireless link.', '["handset", "receiver"]', '[]', '["telephone component", "device component"]', '["earpiece", "mouthpiece"]', '["phone number", "phone call", "phone charger", "landline phone", "cellphone", "phone book"]', '{"noun_forms": ["phonebook", "phonecard", "smartphone"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The handset connects to the base unit by a coiled cord in classic telephone systems.", "Older models rely on a corded handset to transmit and receive audio."]', 'technology', '1', 88832, 3536, NULL, 'opengloss-v1.1')
