INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('photographs_noun_0', 'photographs', 'noun', 0, 'Images produced by the action of light or other radiation on a light-sensitive surface, especially those created using a camera and preserved on a physical or digital medium.', '["pictures", "images"]', '["drawings", "illustrations"]', '["images", "visual_media"]', '["portrait_photographs", "aerial_photographs"]', '["old_photographs", "family_photographs", "aerial_photographs", "archival_photographs"]', '{"noun_forms": ["photographer", "photography"], "verb_forms": ["photograph", "rephotograph"], "adjective_forms": ["photographic", "photographed"], "adverb_forms": ["photographically"]}', '["The archive contains thousands of photographs documenting urban life in the early twentieth century.", "Researchers analyzed aerial photographs to track changes in the coastline over several decades."]', 'arts', '3', 88127, 3559, NULL, 'opengloss-v1.1'),
('photographs_verb_0', 'photographs', 'verb', 0, 'To record an image of a person, object, or scene using a camera or other image-capturing device.', '["shoot", "capture"]', '["erase", "omit"]', '["record", "image"]', '["rephotograph", "overphotograph"]', '["photographs_subjects", "photographs_well", "photographs_poorly", "photographs_scenes"]', '{"noun_forms": ["photographer", "photography"], "verb_forms": ["rephotograph"], "adjective_forms": ["photographic", "photographed"], "adverb_forms": ["photographically"]}', '["The scientist photographed the specimens at regular intervals to document their development.", "Tourists are not allowed to photograph certain religious sites."]', 'arts', '3', 88127, 3559, NULL, 'opengloss-v1.1'),
('photographs_noun_1', 'photographs', 'noun', 1, 'Printed or developed copies of such images on paper or other tangible materials, as distinct from their negatives or digital files.', '["prints", "hard_copies"]', '["negatives", "digital_files"]', '["prints", "artifacts"]', '["album_photographs", "archival_photographs"]', '["old_photographs", "family_photographs", "aerial_photographs", "archival_photographs"]', '{"noun_forms": ["photographer", "photography"], "verb_forms": ["photograph", "rephotograph"], "adjective_forms": ["photographic", "photographed"], "adverb_forms": ["photographically"]}', '["Family photographs were stored in albums on the living room shelf.", "The original photographs have faded, so the museum commissioned high-quality reproductions."]', 'arts', '3', 88127, 3559, NULL, 'opengloss-v1.1'),
('photographs_verb_1', 'photographs', 'verb', 1, 'To appear in a particular way when captured in a photograph, especially with reference to attractiveness or clarity.', '["appear", "register"]', '["distort"]', '["appear", "present"]', '["photograph_poorly", "photograph_well"]', '["photographs_subjects", "photographs_well", "photographs_poorly", "photographs_scenes"]', '{"noun_forms": ["photographer", "photography"], "verb_forms": ["rephotograph"], "adjective_forms": ["photographic", "photographed"], "adverb_forms": ["photographically"]}', '["The sculpture photographs well from a distance but loses detail in close-up shots.", "She does not think she photographs accurately under fluorescent lighting."]', 'arts', '3', 88127, 3559, NULL, 'opengloss-v1.1')
