('equipped_adjective_0', 'equipped', 'adjective', 0, 'An object or space that has been supplied with the instruments, gear, or features necessary for its function.', '["outfitted", "furnished", "supplied", "provided"]', '["unfurnished", "unprovided"]', '["state", "condition", "preparedness"]', '["lab equipment", "military equipment", "field equipment", "construction equipment"]', '["lab equipment", "military equipment", "field equipment", "construction equipment", "trained staff", "qualified personnel"]', '{"noun_forms": ["equipment"], "verb_forms": ["equip", "equipping", "equipped"], "adjective_forms": ["equipped", "equipable"], "adverb_forms": []}', '["The laboratory is equipped with centrifuges and spectrometers.", "Classrooms are equipped with digital projectors and audio systems to support interactive learning."]', 'technology', '5', 87894, 3566, NULL, 'opengloss-v1.1'),
('equipped_verb_0', 'equipped', 'verb', 0, 'To provide with the necessary tools or equipment to carry out a task.', '["furnish", "outfit", "arm", "supply"]', '["deequip", "unfurnish"]', '["supply"]', '["toolkit", "equipment set", "safety gear"]', '["fully equipped", "well equipped", "equipped with", "equipped to handle", "equipped for"]', '{"noun_forms": ["equipment"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The laboratory was equipped with state of the art spectrometers.", "The crew was equipped to handle emergencies."]', 'technology', '5', 87894, 3566, NULL, 'opengloss-v1.1'),
('equipped_adjective_1', 'equipped', 'adjective', 1, 'Having the necessary skills, resources, or personnel to undertake a task; prepared or capable.', '["prepared", "capable", "ready", "competent"]', '["unprepared", "underequipped", "incompetent"]', '["state", "condition", "preparedness"]', '["trained staff", "skilled technicians", "expert researchers", "qualified personnel"]', '["lab equipment", "military equipment", "field equipment", "construction equipment", "trained staff", "qualified personnel"]', '{"noun_forms": ["equipment"], "verb_forms": ["equip", "equipping", "equipped"], "adjective_forms": ["equipped", "equipable"], "adverb_forms": []}', '["The research team is equipped to analyze longitudinal data.", "The department is equipped with trained staff for clinical trials."]', 'technology', '5', 87894, 3566, NULL, 'opengloss-v1.1'),
('equipped_verb_1', 'equipped', 'verb', 1, 'To prepare or furnish someone or a group with resources or capabilities necessary to perform a task, often through training or qualification.', '["train", "prepare", "qualify", "endow"]', '["untrain", "unprepare", "disqualify"]', '["training"]', '["training", "mentoring", "skill development"]', '["fully equipped", "well equipped", "equipped with", "equipped to handle", "equipped for"]', '{"noun_forms": ["equipment"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The program equips students with analytical skills for research.", "The course equips individuals to assess complex data."]', 'technology', '5', 87894, 3566, NULL, 'opengloss-v1.1'),
