('tech_adjective_0', 'tech', 'adjective', 0, 'Relating to technology; pertaining to the use, development, or study of equipment, systems, and processes in science and industry.', '["technological", "tech-based", "digital", "engineering-related"]', '["nontechnical", "low-tech"]', '["adjective", "descriptor", "modifier"]', '["high-tech", "state-of-the-art", "tech-enabled", "tech-driven"]', '["tech sector", "tech industry", "tech startup", "tech policy", "tech infrastructure", "tech ecosystem"]', '{"noun_forms": ["techness"], "verb_forms": [], "adjective_forms": ["techy"], "adverb_forms": []}', '["tech policy requires cybersecurity investments in research facilities.", "tech infrastructure upgrades influence information processing capacity in laboratories."]', 'technology', '4', 87750, 3571, NULL, 'opengloss-v1.1'),
('tech_noun_0', 'tech', 'noun', 0, 'The concept of technology; the practical application of scientific knowledge to create tools, systems, and processes.', '["technology"]', '["manual methods", "low tech"]', '["applied science", "engineering"]', '["biotech", "fintech", "edtech", "cleantech"]', '["tech industry", "tech policy", "tech startup", "tech support", "tech transfer", "tech ecosystem"]', '{"noun_forms": ["techie", "techy"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The rapid development of new tech raises ethical questions.", "Scholars analyze the diffusion of tech in public administration."]', 'technology', '4', 87750, 3571, NULL, 'opengloss-v1.1'),
('tech_adjective_1', 'tech', 'adjective', 1, 'Used as a modifier to indicate technology-based or technology-driven activity within a domain; common in industry and business contexts.', '["tech-enabled", "tech-driven", "tech-based", "tech-oriented"]', '["nontech", "manual"]', '["modifier", "descriptor", "adjective"]', '["high-tech", "tech-enabled", "tech-oriented", "tech-forward"]', '["tech sector", "tech industry", "tech startup", "tech policy", "tech infrastructure", "tech ecosystem"]', '{"noun_forms": ["techness"], "verb_forms": [], "adjective_forms": ["techy"], "adverb_forms": []}', '["tech startups shape regional innovation ecosystems.", "tech transfer programs link universities with industry partners."]', 'technology', '4', 87750, 3571, NULL, 'opengloss-v1.1'),
('tech_noun_1', 'tech', 'noun', 1, 'The technology industry; the part of the economy focused on developing and delivering technology-based products and services.', '["tech industry", "technology sector"]', '["old economy", "nontech sector"]', '["industrial sector", "economic sector"]', '["software industry", "hardware industry", "semiconductor industry", "fintech sector"]', '["tech industry", "tech policy", "tech startup", "tech support", "tech transfer", "tech ecosystem"]', '{"noun_forms": ["techie", "techy"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers track VC investment trends in the tech industry.", "Policy reforms influence the growth of the tech sector globally."]', 'technology', '4', 87750, 3571, NULL, 'opengloss-v1.1'),
('tech_adjective_2', 'tech', 'adjective', 2, 'In informal or marketing usage, a shortened form indicating technology-centric or technology-forward orientation; used to label products, policies, or cultures that emphasize digital capabilities.', '["tech-centric", "tech-forward"]', '["nontech", "manual"]', '["modifier", "descriptor", "adjective"]', '["tech-centric", "tech-forward"]', '["tech sector", "tech industry", "tech startup", "tech policy", "tech infrastructure", "tech ecosystem"]', '{"noun_forms": ["techness"], "verb_forms": [], "adjective_forms": ["techy"], "adverb_forms": []}', '["the campus adopts a tech-centric curriculum.", "a tech-forward policy aims to digitize services."]', 'technology', '4', 87750, 3571, NULL, 'opengloss-v1.1'),
('tech_noun_2', 'tech', 'noun', 2, 'A person who works with or provides technical services, often abbreviated from technician; a tech in informal usage.', '["technician", "technologist"]', '["engineer", "administrator"]', '["worker", "profession"]', '["lab technician", "IT technician", "electronics technician"]', '["tech industry", "tech policy", "tech startup", "tech support", "tech transfer", "tech ecosystem"]', '{"noun_forms": ["techie", "techy"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The lab tech calibrated the spectrometer before the experiment.", "Clinical tech staff monitor patient data during procedures."]', 'technology', '4', 87750, 3571, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
