('turning_adjective_0', 'turning', 'adjective', 0, 'Undergoing rotation or movement around an axis or point.', '["rotating", "spinning", "revolving"]', '["stationary", "motionless"]', '["moving", "rotational"]', '["slow_turning", "fast_turning"]', '["turning wheels", "turning object", "turning trend", "turning moment"]', '{"noun_forms": ["turn", "turning_point"], "verb_forms": ["turn"], "adjective_forms": ["turning", "turnable"], "adverb_forms": ["turningly"]}', '["The turning wheels generated enough friction to heat the metal.", "The model illustrates the behavior of a turning object in a vacuum."]', 'science', '1', 86451, 3623, NULL, 'opengloss-v1.1'),
('turning_noun_0', 'turning', 'noun', 0, 'The act or process of rotating or causing something to rotate around an axis or point.', '["rotation", "revolution", "twisting"]', '["stillness", "immobility"]', '["movement", "motion"]', '["spinning", "swiveling"]', '["sharp turning", "road turning", "metal turnings", "precision turning"]', '{"noun_forms": ["turn"], "verb_forms": ["turn"], "adjective_forms": ["turning_point"], "adverb_forms": []}', '["The turning of the gears drove the entire mechanism.", "The steady turning of the Earth creates the cycle of day and night."]', 'science', '1', 86451, 3623, NULL, 'opengloss-v1.1'),
('turning_verb_0', 'turning', 'verb', 0, 'Present participle of turn: to move or cause to move around an axis or point.', '["rotating", "revolving", "twisting"]', '["stopping", "freezing"]', '["moving", "spinning"]', '["whirling", "swiveling"]', '["turning around", "turning into", "turning over", "turning toward"]', '{"noun_forms": ["turn", "turning", "turnaround"], "verb_forms": ["overturn", "return"], "adjective_forms": ["turning", "turnable"], "adverb_forms": ["turningly"]}', '["The turbine is turning at a constant speed.", "She watched the wheels turning slowly in the distance."]', 'science', '1', 86451, 3623, NULL, 'opengloss-v1.1'),
('turning_adjective_1', 'turning', 'adjective', 1, 'Relating to or constituting a point at which a significant change in direction, development, or condition occurs, often in the phrase turning point.', '["pivotal", "decisive", "critical"]', '["insignificant", "trivial"]', '["important", "significant"]', '["historic_turning", "strategic_turning"]', '["turning wheels", "turning object", "turning trend", "turning moment"]', '{"noun_forms": ["turn", "turning_point"], "verb_forms": ["turn"], "adjective_forms": ["turning", "turnable"], "adverb_forms": ["turningly"]}', '["This was a turning moment in the history of the discipline.", "The data indicate a turning trend in public opinion."]', 'science', '1', 86451, 3623, NULL, 'opengloss-v1.1'),
('turning_noun_1', 'turning', 'noun', 1, 'A place or point at which a route, path, or course changes direction, especially on a road or in a river.', '["bend", "curve", "junction"]', '["straightaway"]', '["intersection", "change_of_direction"]', '["hairpin_turn", "crossroads"]', '["sharp turning", "road turning", "metal turnings", "precision turning"]', '{"noun_forms": ["turn"], "verb_forms": ["turn"], "adjective_forms": ["turning_point"], "adverb_forms": []}', '["Take the second turning on the left after the library.", "The boat slowed as it approached a sharp turning in the river."]', 'science', '1', 86451, 3623, NULL, 'opengloss-v1.1'),
