BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('blocks_noun_0', 'blocks', 'noun', 0, 'A solid piece with flat faces used for building or stacking.', '["brick", "slab", "cube", "piece", "chunk"]', '["void", "air"]', '["physical object", "material object"]', '["cinder block", "wood block", "foam block", "ice block"]', '["building blocks", "block of time", "city block", "wooden blocks", "cinder block", "block party"]', '{"noun_forms": ["blockade", "blockage", "blocker"], "verb_forms": ["block", "blocking", "blocked"], "adjective_forms": ["blocked", "blocky"], "adverb_forms": []}', '["The student stacked blocks to form a tower in math time.", "A concrete block is used to create a sturdy wall."]', 'technology', 'K', 86448, 3624, NULL, 'opengloss-v1.1'),
('blocks_verb_0', 'blocks', 'verb', 0, 'To obstruct movement or passage by placing a barrier or by taking action that prevents passage or entry.', '["obstruct", "impede", "hinder"]', '["unblock", "open", "permit"]', '["stop action", "restrain movement"]', '["block a road", "block a doorway", "block a path"]', '["block traffic", "block a road", "block a shot", "block access", "block a path", "block the doorway"]', '{"noun_forms": ["blockage", "blocker", "blockade"], "verb_forms": ["blockade"], "adjective_forms": [], "adverb_forms": []}', '["Construction cones blocked the street, forcing buses to detour.", "The gate blocks the doorway, making it difficult to enter the classroom."]', 'technology', 'K', 86448, 3624, NULL, 'opengloss-v1.1'),
('blocks_noun_1', 'blocks', 'noun', 1, 'Toy blocks are small interlocking pieces used by children to build models.', '["toy blocks", "wooden blocks", "construction blocks", "stacking blocks"]', '[]', '["toys", "playthings"]', '["wooden block set", "alphabet blocks", "colorful blocks", "stacking blocks"]', '["building blocks", "block of time", "city block", "wooden blocks", "cinder block", "block party"]', '{"noun_forms": ["blockade", "blockage", "blocker"], "verb_forms": ["block", "blocking", "blocked"], "adjective_forms": ["blocked", "blocky"], "adverb_forms": []}', '["Children learn balance by stacking blocks.", "Alphabet blocks help teach letters and sounds."]', 'technology', 'K', 86448, 3624, NULL, 'opengloss-v1.1'),
('blocks_verb_1', 'blocks', 'verb', 1, 'To prevent a ball, puck, or other object from entering a goal or target by stopping or catching it.', '["deflect", "intercept", "stop"]', '["allow", "let through", "miss"]', '["stop action", "interception"]', '["block a shot", "block a pass", "block a goal"]', '["block traffic", "block a road", "block a shot", "block access", "block a path", "block the doorway"]', '{"noun_forms": ["blockage", "blocker", "blockade"], "verb_forms": ["blockade"], "adjective_forms": [], "adverb_forms": []}', '["The goalie blocks the puck with his glove.", "The defender blocks the shot to prevent a score."]', 'technology', 'K', 86448, 3624, NULL, 'opengloss-v1.1'),
('blocks_noun_2', 'blocks', 'noun', 2, 'A city block is the built area between two crossing streets.', '["city block", "urban block", "block of buildings"]', '[]', '["street segment", "geographic unit"]', '["residential block", "business block", "mixed use block", "apartment block"]', '["building blocks", "block of time", "city block", "wooden blocks", "cinder block", "block party"]', '{"noun_forms": ["blockade", "blockage", "blocker"], "verb_forms": ["block", "blocking", "blocked"], "adjective_forms": ["blocked", "blocky"], "adverb_forms": []}', '["The school is on the next city block.", "A block of shops surrounds the town plaza."]', 'technology', 'K', 86448, 3624, NULL, 'opengloss-v1.1'),
('blocks_verb_2', 'blocks', 'verb', 2, 'To prevent someone from contacting or viewing by restricting access to a person or account.', '["restrict", "deny", "ban"]', '["allow", "permit", "unblock"]', '["restrict communication", "control access"]', '["block a caller", "block messages", "block a user"]', '["block traffic", "block a road", "block a shot", "block access", "block a path", "block the doorway"]', '{"noun_forms": ["blockage", "blocker", "blockade"], "verb_forms": ["blockade"], "adjective_forms": [], "adverb_forms": []}', '["She blocks messages from unknown numbers on her phone.", "He blocks access to his profile during school hours."]', 'technology', 'K', 86448, 3624, NULL, 'opengloss-v1.1'),
('blocks_noun_3', 'blocks', 'noun', 3, 'A block of code is a group of programming statements treated as a unit.', '["code block", "block of code", "code segment", "section of code"]', '[]', '["code unit", "program unit"]', '["if block", "loop block", "function block", "class block"]', '["building blocks", "block of time", "city block", "wooden blocks", "cinder block", "block party"]', '{"noun_forms": ["blockade", "blockage", "blocker"], "verb_forms": ["block", "blocking", "blocked"], "adjective_forms": ["blocked", "blocky"], "adverb_forms": []}', '["In Scratch, programs are built from code blocks.", "Loop blocks repeat a set of steps until finished."]', 'technology', 'K', 86448, 3624, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
