('boats_noun_0', 'boats', 'noun', 0, 'A small to medium-sized watercraft typically used for inland or nearshore transport and recreation, powered by oars, sails, or an engine.', '["boat", "watercraft", "craft", "vessel"]', '["aircraft", "land vehicle"]', '["watercraft", "vessel"]', '["dinghy", "rowboat", "skiff", "launch"]', '["rowboat", "lifeboat", "ferry boat", "cargo boat", "river boat"]', '{"noun_forms": ["boater", "boathouse"], "verb_forms": ["boating", "boated"], "adjective_forms": ["boaty"], "adverb_forms": []}', '["Field observations assessed stability and handling of small boats.", "Engineering analyses compared hull forms of boats in shallow water."]', 'technology', '1', 85849, 3643, NULL, 'opengloss-v1.1'),
('boats_verb_0', 'boats', 'verb', 0, 'To travel by boat; to move across a body of water using a watercraft, typically for transport or recreation.', '["sail", "cruise", "voyage"]', '["land", "disembark"]', '["motion verb", "travel verb"]', '["row", "sail", "motor", "paddle"]', '["boats along", "boats across", "boats downstream", "boats upstream", "boats on water", "boated supplies"]', '{"noun_forms": ["boater"], "verb_forms": [], "adjective_forms": ["boatable"], "adverb_forms": []}', '["Researchers boat along the estuary to collect salinity data.", "Field crews boat along sheltered bays to sample water quality."]', 'technology', '1', 85849, 3643, NULL, 'opengloss-v1.1'),
('boats_noun_1', 'boats', 'noun', 1, 'A larger watercraft used for passenger or cargo transport, typically serving coastal, riverine, or inland waterways.', '["vessel", "craft"]', '["aircraft", "land vehicle"]', '["watercraft", "vessel"]', '["ferry", "barge", "cargo boat", "fishing boat"]', '["rowboat", "lifeboat", "ferry boat", "cargo boat", "river boat"]', '{"noun_forms": ["boater", "boathouse"], "verb_forms": ["boating", "boated"], "adjective_forms": ["boaty"], "adverb_forms": []}', '["In the 19th century, ferry boats connected remote islands.", "Cargo boats transported commodities along major rivers during industrial expansion."]', 'technology', '1', 85849, 3643, NULL, 'opengloss-v1.1'),
('boats_verb_1', 'boats', 'verb', 1, 'To transport or convey people or goods by water using a vessel; used in logistics, field deployment, or supply chains.', '["ship", "ferry"]', '["land", "disembark"]', '["move by water", "logistical action"]', '["barge", "ferry", "ship", "cargo boat"]', '["boats along", "boats across", "boats downstream", "boats upstream", "boats on water", "boated supplies"]', '{"noun_forms": ["boater"], "verb_forms": [], "adjective_forms": ["boatable"], "adverb_forms": []}', '["Relief teams boated the medical supplies to the island after the cyclone.", "Researchers boated equipment to the field site across the harbor."]', 'technology', '1', 85849, 3643, NULL, 'opengloss-v1.1')
