('electricity_noun_0', 'electricity', 'noun', 0, 'A form of energy produced by the movement of charged particles that powers machines and lights.', '["energy", "power"]', '[]', '["energy"]', '["direct current", "alternating current"]', '["electric circuit", "electrical outlet", "electrical current", "household electricity", "electric power", "electric bill"]', '{"noun_forms": ["electrification"], "verb_forms": ["electrify", "electrified", "electrifying"], "adjective_forms": ["electrical"], "adverb_forms": ["electrically"]}', '["Electricity powers the lights in the classroom.", "Scientists study electricity to learn how circuits work."]', 'science', '4', 85017, 3674, NULL, 'opengloss-v1.1'),
('electricity_noun_1', 'electricity', 'noun', 1, 'The continuous flow of electric charges through a conductor, such as a wire.', '["current"]', '[]', '["electricity"]', '["direct current", "alternating current"]', '["electric circuit", "electrical outlet", "electrical current", "household electricity", "electric power", "electric bill"]', '{"noun_forms": ["electrification"], "verb_forms": ["electrify", "electrified", "electrifying"], "adjective_forms": ["electrical"], "adverb_forms": ["electrically"]}', '["An electric current travels through a wire when a switch is closed.", "We measure current to see how circuits work."]', 'science', '4', 85017, 3674, NULL, 'opengloss-v1.1'),
