-- lexi ETL: breaking (2026-09-18T16:20:22Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('breaking_adjective_0', 'breaking', 'adjective', 0, 'Pertaining to information or events that have just occurred and are being reported with urgency; used to label news items that are considered current and developing.', '["current", "urgent", "new"]', '["old", "stale", "expired"]', '["information", "news", "reporting", "current events"]', '["breaking story", "breaking alert", "breaking update"]', '["breaking news", "breaking waves", "breaking point", "breaking change", "breaking ground", "breaking load"]', '{"noun_forms": ["breakage", "breakdown", "breaker"], "verb_forms": ["break"], "adjective_forms": ["breakable"], "adverb_forms": []}', '["The breaking news item dominated the conference schedule.", "Scholars reported breaking findings in an online briefing."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_noun_0', 'breaking', 'noun', 0, 'The act or process of separating into pieces or losing integrity through rupture or fracture of a material or object.', '["rupture", "fracture", "breakage", "disintegration"]', '["intactness", "structural integrity"]', '["action", "process", "event", "rupture"]', '["fracture", "delamination", "breach"]', '["breaking point", "breaking news", "breaking wave", "breaking strength", "breaking load"]', '{"noun_forms": ["breakage", "breaker"], "verb_forms": ["break"], "adjective_forms": ["breakable", "unbreakable"], "adverb_forms": ["unbreakably"]}', '["The breaking of the ceramic specimen occurred under increased stress.", "The sample showed microscale breaking events that preceded crack growth."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_verb_0', 'breaking', 'verb', 0, 'To cause to separate into pieces by applying force; to cause material to fracture or divide.', '["crack", "fracture", "shatter", "smash"]', '["repair", "mend", "restore"]', '["transitive verb", "action verb"]', '["crack", "split", "fracture", "shatter"]', '["breaking point", "breaking news", "breaking dawn", "breaking glass", "breaking the law", "breaking with tradition"]', '{"noun_forms": ["breakage", "breakdown"], "verb_forms": ["breaking", "broke", "broken", "breaks"], "adjective_forms": ["breakable", "unbreakable"], "adverb_forms": []}', '["Researchers are breaking the sample under controlled pressure.", "The glass is breaking during the thermal cycle."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_adjective_1', 'breaking', 'adjective', 1, 'In oceanography, describing a surface wave that crest and breaks, dissipating energy; a regime of wave dynamics near shore.', '["crashing", "surging", "collapsing"]', '["calm water", "nonbreaking"]', '["wave", "ocean wave", "wave phenomenon"]', '["plunging breaker", "spilling breaker"]', '["breaking news", "breaking waves", "breaking point", "breaking change", "breaking ground", "breaking load"]', '{"noun_forms": ["breakage", "breakdown", "breaker"], "verb_forms": ["break"], "adjective_forms": ["breakable"], "adverb_forms": []}', '["Breaking waves were observed during the storm near the reef.", "Field measurements captured breaking waves dissipating energy at the beach."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_noun_1', 'breaking', 'noun', 1, 'The process by which a surface ocean wave becomes unstable and collapses near the shoreline, forming foam and breaking toward the shore.', '["breaker", "surf", "wave collapse"]', '["calm water", "still water"]', '["wave dynamics", "hydrodynamics"]', '["shorebreak", "surging breaker"]', '["breaking point", "breaking news", "breaking wave", "breaking strength", "breaking load"]', '{"noun_forms": ["breakage", "breaker"], "verb_forms": ["break"], "adjective_forms": ["breakable", "unbreakable"], "adverb_forms": ["unbreakably"]}', '["Breaking waves contribute to coastal erosion and sediment transport.", "The rate of breaking is influenced by wind speed and fetch."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_verb_1', 'breaking', 'verb', 1, 'To become damaged or fail as a mechanism or system due to fatigue or stress; to break down.', '["fail", "malfunction", "collapse", "degrade"]', '["function", "operate", "work", "perform"]', '["intransitive verb", "process verb"]', '["malfunction", "degrade", "wear", "deteriorate"]', '["breaking point", "breaking news", "breaking dawn", "breaking glass", "breaking the law", "breaking with tradition"]', '{"noun_forms": ["breakage", "breakdown"], "verb_forms": ["breaking", "broke", "broken", "breaks"], "adjective_forms": ["breakable", "unbreakable"], "adverb_forms": []}', '["The device is breaking due to repeated mechanical stress.", "Ice on the lake is breaking apart under wind."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_adjective_2', 'breaking', 'adjective', 2, 'In software engineering, describing a change that breaks backward compatibility in a software interface or API.', '["incompatible change", "disruptive change", "breaking modification"]', '["backward compatible change", "nonbreaking update"]', '["software change", "versioning rule"]', '["backward incompatible change", "breaking API change"]', '["breaking news", "breaking waves", "breaking point", "breaking change", "breaking ground", "breaking load"]', '{"noun_forms": ["breakage", "breakdown", "breaker"], "verb_forms": ["break"], "adjective_forms": ["breakable"], "adverb_forms": []}', '["The release notes warned of a breaking change.", "Developers must adapt code for breaking changes."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_noun_2', 'breaking', 'noun', 2, 'An item of urgent news reported by media organizations, typically designated and disseminated as breaking news.', '["newsflash", "bulletin"]', '["old news", "background information"]', '["news item", "report"]', '["newsflash", "bulletin"]', '["breaking point", "breaking news", "breaking wave", "breaking strength", "breaking load"]', '{"noun_forms": ["breakage", "breaker"], "verb_forms": ["break"], "adjective_forms": ["breakable", "unbreakable"], "adverb_forms": ["unbreakably"]}', '["News outlets issue breaking updates during live events.", "Breaking reports shaped the market response within minutes."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_verb_2', 'breaking', 'verb', 2, 'To violate or contravene a rule, law, or agreement; to infringe.', '["violate", "breach", "transgress", "infringe"]', '["obey", "comply", "adhere", "honor"]', '["illegal act", "violation"]', '["breach", "infraction", "noncompliance", "transgression"]', '["breaking point", "breaking news", "breaking dawn", "breaking glass", "breaking the law", "breaking with tradition"]', '{"noun_forms": ["breakage", "breakdown"], "verb_forms": ["breaking", "broke", "broken", "breaks"], "adjective_forms": ["breakable", "unbreakable"], "adverb_forms": []}', '["Breaking the law carries penalties in many jurisdictions.", "Breaking the contract terms may result in remedies."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1'),
('breaking_adjective_3', 'breaking', 'adjective', 3, 'Describing a material property or condition that makes a component liable to fracture under applied stress; used in mechanical and materials contexts.', '["fragile", "brittle", "breakable"]', '["tough", "sturdy", "robust"]', '["material property", "mechanical property"]', '["brittleness", "fracture toughness", "tensile strength"]', '["breaking news", "breaking waves", "breaking point", "breaking change", "breaking ground", "breaking load"]', '{"noun_forms": ["breakage", "breakdown", "breaker"], "verb_forms": ["break"], "adjective_forms": ["breakable"], "adverb_forms": []}', '["The material exhibited breaking strength under tensile load.", "Fragile alloys showed premature breaking under stress testing."]', 'science', '4', 84311, 3695, NULL, 'opengloss-v1.1')
