INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('mines_noun_0', 'mines', 'noun', 0, 'A mine is a site from which ore minerals are extracted, typically by underground or open-pit methods.', '["quarry", "pit", "lode", "deposit"]', '["unmined area"]', '["mining site"]', '["coal mine", "gold mine", "open pit mine", "underground mine"]', '["coal mine", "gold mine", "open pit mine", "underground mine", "mining operation", "mineral deposit"]', '{"noun_forms": ["miner", "mining"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Geologists mapped ore bodies within the coal mine to estimate reserves.", "Historical mining research shows multiple ore horizons exploited in ancient mines."]', 'technology', '2', 83752, 3707, NULL, 'opengloss-v1.1'),
('mines_verb_0', 'mines', 'verb', 0, 'To extract ore or minerals from a deposit by digging, blasting, or other excavation activities.', '["extract", "excavate", "quarry", "mine"]', '["unmined", "unextracted"]', '["extraction", "mining"]', '["open pit mining", "shaft mining"]', '["open pit mining", "strip mining", "shaft mining", "data mining", "mining operation", "mineral extraction"]', '{"noun_forms": ["mining"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The ore body was mined using open pit techniques.", "Underground deposits were mined by room and pillar methods."]', 'technology', '2', 83752, 3707, NULL, 'opengloss-v1.1'),
('mines_noun_1', 'mines', 'noun', 1, 'A mine is an explosive device concealed in the ground or sea to detonate by contact, proximity, or pressure.', '["landmine", "explosive device"]', '[]', '["explosive device"]', '["landmine", "naval mine"]', '["coal mine", "gold mine", "open pit mine", "underground mine", "mining operation", "mineral deposit"]', '{"noun_forms": ["miner", "mining"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The field survey identified several active landmines near the border.", "Demining teams cleared naval mines in harbor approaches."]', 'technology', '2', 83752, 3707, NULL, 'opengloss-v1.1'),
('mines_verb_1', 'mines', 'verb', 1, 'To lay land mines as a defensive or offensive measure by deploying explosive devices to create a minefield.', '["lay mines", "deploy mines", "mine"]', '["unmined", "unlaid"]', '["military action", "defense measure"]', '["naval mine laying", "field obstacle creation"]', '["open pit mining", "strip mining", "shaft mining", "data mining", "mining operation", "mineral extraction"]', '{"noun_forms": ["mining"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Coastal defenses were strengthened by laying mines.", "Military engineers laid mines along the river to deter crossings."]', 'technology', '2', 83752, 3707, NULL, 'opengloss-v1.1'),
