('spoke_noun_0', 'spoke', 'noun', 0, 'A slender rod radiating from the hub to the rim of a wheel, forming part of the wheel''s structural network and carrying tension to maintain wheel integrity.', '["rod", "arm", "spindle", "bar"]', '["solid wheel"]', '["wheel component", "mechanical part"]', '["radial spoke", "laced spoke"]', '["spoked wheel", "wheel spoke", "spoke length", "spoke tension", "spoke pattern", "tensioned spoke"]', '{"noun_forms": [], "verb_forms": ["speak", "speaks", "spoke", "spoken", "speaking"], "adjective_forms": ["spoked"], "adverb_forms": []}', '["The bicycle wheel alignment depended on even spoke tension.", "Engineering tests measured spoke length to assess wheel stiffness."]', 'technology', '1', 81983, 3764, NULL, 'opengloss-v1.1'),
('spoke_verb_0', 'spoke', 'verb', 0, 'Past tense of speak; to utter words or statements by means of spoken language.', '["talk", "utter"]', '["listen"]', '["verbal communication", "oral expression"]', '["lecture", "address"]', '["public speaking", "spoken language", "speech delivery", "oral presentation", "conversational speech", "debate participation"]', '{"noun_forms": ["speech", "speaker"], "verb_forms": ["speak"], "adjective_forms": [], "adverb_forms": []}', '["The researcher spoke clearly during the protocol demonstration.", "Participants spoke with precision about methodological details."]', 'technology', '1', 81983, 3764, NULL, 'opengloss-v1.1'),
('spoke_verb_1', 'spoke', 'verb', 1, 'To mention or refer to a subject within discourse; to talk about something.', '["mention", "refer to"]', '["omit", "ignore"]', '["reference", "mentioning"]', '["cite", "refer to"]', '["public speaking", "spoken language", "speech delivery", "oral presentation", "conversational speech", "debate participation"]', '{"noun_forms": ["speech", "speaker"], "verb_forms": ["speak"], "adjective_forms": [], "adverb_forms": []}', '["The author spoke of demographic trends in the sample.", "The panelist spoke of limitations in the methodology."]', 'technology', '1', 81983, 3764, NULL, 'opengloss-v1.1'),
('spoke_verb_2', 'spoke', 'verb', 2, 'To deliver a talk or address to an audience; to give a formal public discourse.', '["address", "lecture"]', '["listen", "remain silent"]', '["public speaking", "oral communication"]', '["informative talk", "persuasive address"]', '["public speaking", "spoken language", "speech delivery", "oral presentation", "conversational speech", "debate participation"]', '{"noun_forms": ["speech", "speaker"], "verb_forms": ["speak"], "adjective_forms": [], "adverb_forms": []}', '["He spoke at the regional conference on data ethics.", "The chair spoke for forty minutes on research priorities."]', 'technology', '1', 81983, 3764, NULL, 'opengloss-v1.1')
