('instrument_noun_0', 'instrument', 'noun', 0, 'A device or tool designed to perform a specific function or set of functions in science, engineering, or daily tasks.', '["device", "tool", "implement"]', '["obstacle", "hindrance"]', '["tool"]', '["scalpel", "microscope", "thermometer"]', '["musical instrument", "medical instrument", "scientific instrument", "precision instrument", "instrument panel"]', '{"noun_forms": ["instrumentation"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": []}', '["The scientist used the instrument to collect data.", "A thermometer is a common measuring instrument in labs."]', 'technology', '4', 81407, 3777, NULL, 'opengloss-v1.1'),
('instrument_verb_0', 'instrument', 'verb', 0, 'To equip or supply with instruments or tools to perform a task.', '["equip", "outfit", "furnish"]', '["disarm", "unfurnish"]', '["transitive verb", "verb"]', '["equip", "outfit", "furnish"]', '["measuring instrument", "lab instrument", "scientific instrument", "musical instrument", "precision instrument", "data logger"]', '{"noun_forms": ["instrumentation"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": ["instrumentally"]}', '["The science lab is instrumented with digital thermometers.", "The teacher instruments the science kit with data loggers."]', 'technology', '4', 81407, 3777, NULL, 'opengloss-v1.1'),
('instrument_noun_1', 'instrument', 'noun', 1, 'A musical device used to produce musical sounds and compose melodies.', '["musical tool", "sound producing device", "musical instrument"]', '["silence", "noise"]', '["tool", "device"]', '["piano", "violin", "drums"]', '["musical instrument", "medical instrument", "scientific instrument", "precision instrument", "instrument panel"]', '{"noun_forms": ["instrumentation"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": []}', '["A piano is a popular musical instrument for beginners.", "The violin is a common musical instrument in string ensembles."]', 'technology', '4', 81407, 3777, NULL, 'opengloss-v1.1'),
('instrument_verb_1', 'instrument', 'verb', 1, 'To install devices or sensors to measure or monitor conditions or data.', '["measure", "monitor", "gauge"]', '[]', '["transitive verb", "verb"]', '["sensor", "thermometer", "data logger", "gauge"]', '["measuring instrument", "lab instrument", "scientific instrument", "musical instrument", "precision instrument", "data logger"]', '{"noun_forms": ["instrumentation"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": ["instrumentally"]}', '["The researchers instrument the weather station to record humidity.", "Engineers instrument the car with accelerometers to study vibration."]', 'technology', '4', 81407, 3777, NULL, 'opengloss-v1.1'),
('instrument_noun_2', 'instrument', 'noun', 2, 'A formal written document that records a transaction, agreement, or deed.', '["deed", "contract", "document"]', '["oral agreement", "unwritten contract"]', '["document", "record"]', '["deed", "contract", "will", "lease"]', '["musical instrument", "medical instrument", "scientific instrument", "precision instrument", "instrument panel"]', '{"noun_forms": ["instrumentation"], "verb_forms": [], "adjective_forms": ["instrumental"], "adverb_forms": []}', '["The deed is a legal instrument that transfers ownership.", "A contract is a common legal instrument used in business deals."]', 'technology', '4', 81407, 3777, NULL, 'opengloss-v1.1')
