('truck_noun_0', 'truck', 'noun', 0, 'A motor vehicle designed to transport goods, typically larger than a passenger car and used in commerce and logistics to move cargo.', '["lorry", "freight vehicle"]', '["car"]', '["vehicle"]', '["box truck", "dump truck", "flatbed truck", "pickup truck", "semi truck"]', '["delivery truck", "box truck", "pickup truck", "dump truck", "flatbed truck", "semi truck"]', '{"noun_forms": ["trucker", "truckage", "truckload", "truckstop", "truckyard"], "verb_forms": ["trucking"], "adjective_forms": [], "adverb_forms": []}', '["Local logistics firms rely on a box truck for deliveries.", "A semi truck hauls freight across state lines daily."]', 'technology', 'K', 80523, 3806, NULL, 'opengloss-v1.1'),
('truck_verb_0', 'truck', 'verb', 0, 'To convey or move goods or passengers by means of a truck, typically within a logistics framework.', '["haul", "transport", "cart"]', '["unload", "offload"]', '["transportation"]', '["hauling", "freighting"]', '["truckload", "truck driver", "delivery truck", "truck chassis", "trucking industry", "truck route"]', '{"noun_forms": ["trucker"], "verb_forms": [], "adjective_forms": ["truckable"], "adverb_forms": []}', '["The company trucks cargo from the factory to the warehouse.", "Regional distributors truck goods to retailers to shorten delivery times."]', 'technology', 'K', 80523, 3806, NULL, 'opengloss-v1.1'),
('truck_verb_1', 'truck', 'verb', 1, 'To barter or trade, especially in historical or regional usage, or to deal with others by exchange.', '["barter", "trade", "deal"]', '["nontrading"]', '["commerce"]', '["barter", "trade", "deal"]', '["truckload", "truck driver", "delivery truck", "truck chassis", "trucking industry", "truck route"]', '{"noun_forms": ["trucker"], "verb_forms": [], "adjective_forms": ["truckable"], "adverb_forms": []}', '["Merchants trucked with farmers to exchange crops.", "Local traders trucked with neighbors to settle terms."]', 'technology', 'K', 80523, 3806, NULL, 'opengloss-v1.1')
