-- lexi ETL: component (2026-09-18T16:20:23Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('component_adjective_0', 'component', 'adjective', 0, 'Of or relating to a component; forming part of a larger whole.', '["constituent", "elemental", "componential"]', '["entire", "whole", "global"]', '["descriptor"]', '["subcomponent", "component part"]', '["component parts", "component design", "component form", "component video", "component quality"]', '{"noun_forms": ["componentry", "componentization"], "verb_forms": ["componentize"], "adjective_forms": ["componential", "componental"], "adverb_forms": ["componently"]}', '["The constituent parts of the machine were examined in class.", "Identify each constituent part to understand the system."]', 'technology', '5', 78334, 3900, NULL, 'opengloss-v1.1'),
('component_noun_0', 'component', 'noun', 0, 'A part that forms a larger whole, such as a piece that makes up a machine or system.', '["part", "piece", "section", "element"]', '["whole", "entirety"]', '["part", "piece", "unit", "section"]', '["module", "subassembly", "block", "piece"]', '["main component", "electrical component", "computer component", "structural component", "key component", "core component"]', '{"noun_forms": ["componentry"], "verb_forms": ["componentize"], "adjective_forms": ["componential"], "adverb_forms": []}', '["A wheel is a component of the bicycle.", "Each component helps the machine run smoothly."]', 'technology', '5', 78334, 3900, NULL, 'opengloss-v1.1'),
('component_adjective_1', 'component', 'adjective', 1, 'Relating to modules or parts that can be separated and replaced in a system.', '["modular", "composite", "componential"]', '["holistic", "systemwide", "overall"]', '["descriptor"]', '["module", "submodule"]', '["component parts", "component design", "component form", "component video", "component quality"]', '{"noun_forms": ["componentry", "componentization"], "verb_forms": ["componentize"], "adjective_forms": ["componential", "componental"], "adverb_forms": ["componently"]}', '["A modular design breaks the program into interchangeable modules.", "Software is built from component parts that can be swapped."]', 'technology', '5', 78334, 3900, NULL, 'opengloss-v1.1'),
