('carrier_noun_0', 'carrier', 'noun', 0, 'A person or thing that carries or conveys something from one place to another.', '["transporter", "bearer", "conveyor"]', '["receiver", "recipient"]', '["entity"]', '["courier", "bearer", "messenger"]', '[]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Logistics analyses treat the carrier as the entity responsible for transport.", "The courier acts as the carrier in regional freight networks."]', 'technology', '3', 76913, 3954, NULL, 'opengloss-v1.1'),
('carrier_noun_1', 'carrier', 'noun', 1, 'An organization that provides a service such as transportation or telecommunications.', '["service provider", "network operator", "telecom company"]', '["end user", "customer"]', '["organization", "business"]', '["airline", "rail operator", "telecom operator"]', '[]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The telecom carrier announced a new 5G plan.", "Shipping carriers compete on delivery reliability."]', 'technology', '3', 76913, 3954, NULL, 'opengloss-v1.1'),
('carrier_noun_2', 'carrier', 'noun', 2, 'An organism that harbors a non-expressed allele for a trait and can pass it on to offspring.', '["heterozygote", "asymptomatic host"]', '["noncarrier"]', '["genotype"]', '["recessive carrier", "dominant carrier"]', '[]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The patient is a carrier of the recessive allele but shows no symptoms.", "Carriers can transmit the allele to offspring even when unaffected."]', 'technology', '3', 76913, 3954, NULL, 'opengloss-v1.1'),
('carrier_noun_3', 'carrier', 'noun', 3, 'A signal used to convey information in a modulated communication system.', '["carrier signal", "carrier wave"]', '["baseband signal", "demodulated signal"]', '["signal"]', '["AM carrier", "FM carrier"]', '[]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["In AM radio, the carrier frequency dictates the transmitted bandwidth.", "The receiver demodulates the carrier to recover the audio signal."]', 'technology', '3', 76913, 3954, NULL, 'opengloss-v1.1')
