('clock_noun_0', 'clock', 'noun', 0, 'A timekeeping device that displays the current time, typically consisting of hours, minutes, and sometimes seconds.', '["timepiece", "timekeeper", "horologe"]', '[]', '["device", "instrument", "timekeeping device"]', '["grandfather clock", "mantel clock", "wall clock", "alarm clock"]', '["wall clock", "grandfather clock", "mantel clock", "alarm clock", "digital clock", "clock rate"]', '{"noun_forms": ["clockwork"], "verb_forms": [], "adjective_forms": ["clocklike"], "adverb_forms": ["clockwise"]}', '["Researchers synchronized the laboratory clock with the master clock.", "Students used the clock to measure durations of experiments."]', 'technology', 'K', 73539, 4095, NULL, 'opengloss-v1.1'),
('clock_verb_0', 'clock', 'verb', 0, 'In general academic use, to measure the duration of an event or process by means of a clock, thereby recording elapsed time.', '["time", "measure"]', '["delay", "stall"]', '["time measurement"]', '["record elapsed time"]', '["clock speed", "clock cycle", "clock time", "clock face", "time clock"]', '{"noun_forms": ["clockwork"], "verb_forms": [], "adjective_forms": ["clocklike"], "adverb_forms": []}', '["The researchers clocked the reaction at 2.3 seconds.", "We clocked the cyclist''s lap time to evaluate performance."]', 'technology', 'K', 73539, 4095, NULL, 'opengloss-v1.1'),
('clock_noun_1', 'clock', 'noun', 1, 'In electronics and computing, a clock is a periodic timing signal that coordinates the actions of synchronous digital circuits.', '["timing signal", "clock pulse", "clock signal"]', '[]', '["signal", "electronic signal", "control signal"]', '["cpu clock", "system clock", "clock generator"]', '["wall clock", "grandfather clock", "mantel clock", "alarm clock", "digital clock", "clock rate"]', '{"noun_forms": ["clockwork"], "verb_forms": [], "adjective_forms": ["clocklike"], "adverb_forms": ["clockwise"]}', '["The processor relies on the clock signal for synchronization.", "Increasing the clock rate can improve throughput but raises heat."]', 'technology', 'K', 73539, 4095, NULL, 'opengloss-v1.1'),
('clock_verb_1', 'clock', 'verb', 1, 'To register the start or end of a work period by using a clock or timekeeping system, thereby recording attendance or hours worked.', '["punch in", "log hours"]', '["clock out", "log off"]', '["timekeeping"]', '["start time recording", "time entry"]', '["clock speed", "clock cycle", "clock time", "clock face", "time clock"]', '{"noun_forms": ["clockwork"], "verb_forms": [], "adjective_forms": ["clocklike"], "adverb_forms": []}', '["Workers clocked in at 9 a.m.", "Employees clocked out after the shift."]', 'technology', 'K', 73539, 4095, NULL, 'opengloss-v1.1'),
('clock_verb_2', 'clock', 'verb', 2, 'To strike another person with a blow, typically with the fist or a blunt implement.', '["punch", "smack"]', '["miss", "avoid"]', '["physical violence"]', '["punch", "smack"]', '["clock speed", "clock cycle", "clock time", "clock face", "time clock"]', '{"noun_forms": ["clockwork"], "verb_forms": [], "adjective_forms": ["clocklike"], "adverb_forms": []}', '["The guard clocked the intruder with a baton.", "The boxer clocked his opponent in the jaw."]', 'technology', 'K', 73539, 4095, NULL, 'opengloss-v1.1')
