('lights_verb_0', 'lights', 'verb', 0, 'To cause something to begin burning or to commence emitting flame or heat.', '["ignite", "kindle", "burn"]', '["extinguish", "quench", "douse"]', '["burning"]', '["ignition"]', '["light a fire", "light up", "light the way", "light a candle", "light a match", "light the lamp"]', '{"noun_forms": ["lighting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers light a flame to initiate combustion in the apparatus.", "The protocol directs students to light the sample''s catalyst to start the reaction."]', 'technology', 'K', 72472, 4148, NULL, 'opengloss-v1.1'),
('lights_noun_1', 'lights', 'noun', 1, 'The level of illumination in a space produced by lighting, i.e., the amount of brightness.', '["brightness", "illumination level"]', '["darkness", "dimness"]', '["illumination"]', '["ambient light", "direct light", "diffuse light"]', '["city lights", "traffic lights", "stage lights", "bedside lights", "ceiling lights", "reading lights"]', '{"noun_forms": ["lighting", "lightness"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The room''s brightness increased after turning on overhead lights.", "Standards require uniform illumination across the workspace."]', 'technology', 'K', 72472, 4148, NULL, 'opengloss-v1.1'),
('lights_verb_1', 'lights', 'verb', 1, 'To illuminate or brighten a space by turning on lights or by providing illumination.', '["illuminate", "brighten", "light up"]', '["dim", "darken", "extinguish"]', '["illuminate"]', '["lighting"]', '["light a fire", "light up", "light the way", "light a candle", "light a match", "light the lamp"]', '{"noun_forms": ["lighting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The electrician lights the lab to ensure uniform visibility.", "The room lights up when the main switch is activated."]', 'technology', 'K', 72472, 4148, NULL, 'opengloss-v1.1'),
('lights_noun_2', 'lights', 'noun', 2, 'Visible light refers to electromagnetic radiation in the visible spectrum that can be perceived by the human eye.', '["visible light", "color light"]', '["darkness"]', '["electromagnetic radiation"]', '["red light", "green light", "blue light", "white light"]', '["city lights", "traffic lights", "stage lights", "bedside lights", "ceiling lights", "reading lights"]', '{"noun_forms": ["lighting", "lightness"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Red light has a longer wavelength than blue light.", "White light can be decomposed into a color spectrum."]', 'technology', 'K', 72472, 4148, NULL, 'opengloss-v1.1'),
('lights_verb_2', 'lights', 'verb', 2, 'To become bright with emotion or to cause someone to smile or feel happiness.', '["beam", "brighten", "smile"]', '["frown", "darken", "gloom"]', '["emotion"]', '["smile", "beam", "grin"]', '["light a fire", "light up", "light the way", "light a candle", "light a match", "light the lamp"]', '{"noun_forms": ["lighting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Her face lights up when discussing the project.", "Audience members light up with interest when results are presented."]', 'technology', 'K', 72472, 4148, NULL, 'opengloss-v1.1'),
('lights_verb_3', 'lights', 'verb', 3, 'To discover by chance; to come upon unexpectedly.', '["discover"]', '["miss", "overlook", "ignore"]', '["find"]', '["discovery"]', '["light a fire", "light up", "light the way", "light a candle", "light a match", "light the lamp"]', '{"noun_forms": ["lighting"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The researcher lights upon a potential mechanism during analysis.", "The investigation lights upon a trend that informs theory."]', 'technology', 'K', 72472, 4148, NULL, 'opengloss-v1.1')
