('secured_adjective_0', 'secured', 'adjective', 0, 'Fixed or attached firmly to a surface or structure; not easily moved.', '["attached", "fastened", "fixed", "bolted"]', '["loose", "unsecured", "detached"]', '["state", "condition"]', '["bolted joint", "screwed panel"]', '["secured loan", "secured debt", "secured assets", "secured credentials", "secured perimeter", "secured parking"]', '{"noun_forms": ["security", "securement"], "verb_forms": ["secure", "securing"], "adjective_forms": ["secure"], "adverb_forms": ["securely"]}', '["The secured door remained shut during the experiment.", "A secured bolt kept the joint from moving."]', 'technology', '3', 72336, 4155, NULL, 'opengloss-v1.1'),
('secured_verb_0', 'secured', 'verb', 0, 'To fasten or attach something firmly in place.', '["fasten", "attach", "fix"]', '["loosen", "unfasten", "detach"]', '["attach", "fix"]', '["bolt", "screw", "nail"]', '["secured funding", "secured loan", "secured position", "secured area", "secured perimeter", "secured data"]', '{"noun_forms": ["security", "insecurity"], "verb_forms": [], "adjective_forms": ["insecure"], "adverb_forms": ["securely"]}', '["The cabinet was secured to the wall with brackets.", "The lid was secured with a latch."]', 'technology', '3', 72336, 4155, NULL, 'opengloss-v1.1'),
('secured_adjective_1', 'secured', 'adjective', 1, 'Backed by collateral or guaranteed by a pledge; having secured status in finance.', '["guaranteed", "backed", "collateralized", "insured"]', '["unsecured", "unbacked"]', '["financial term"]', '["secured loan", "secured debt"]', '["secured loan", "secured debt", "secured assets", "secured credentials", "secured perimeter", "secured parking"]', '{"noun_forms": ["security", "securement"], "verb_forms": ["secure", "securing"], "adjective_forms": ["secure"], "adverb_forms": ["securely"]}', '["The loan is secured by collateral such as a car.", "The project funding is secured by donor grants."]', 'technology', '3', 72336, 4155, NULL, 'opengloss-v1.1'),
('secured_verb_1', 'secured', 'verb', 1, 'To obtain or guarantee something through effort or negotiation.', '["obtain", "procure", "gain"]', '["lose", "forfeit", "miss"]', '["acquire", "obtain"]', '["funding", "loan", "position"]', '["secured funding", "secured loan", "secured position", "secured area", "secured perimeter", "secured data"]', '{"noun_forms": ["security", "insecurity"], "verb_forms": [], "adjective_forms": ["insecure"], "adverb_forms": ["securely"]}', '["The team secured funding for the science project.", "They secured a scholarship after a long interview."]', 'technology', '3', 72336, 4155, NULL, 'opengloss-v1.1'),
