('libraries_noun_0', 'libraries', 'noun', 0, 'The physical or organizational entity that houses and provides access to a collection of printed and multimedia resources for research and education.', '["book repository", "information center", "reference library", "resource center"]', '["bookless space", "empty shelves"]', '["institution", "facility"]', '["public library", "academic library", "national library", "special library"]', '["public libraries", "academic libraries", "digital libraries", "library catalog", "library system", "standard library"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers consult the university library to locate primary sources.", "Public libraries provide access to digitized archives and reference services."]', 'technology', '2', 72040, 4177, NULL, 'opengloss-v1.1'),
('libraries_noun_1', 'libraries', 'noun', 1, 'The collection of materials held by a library, including books, journals, and media, available for use or loan.', '["library holdings", "resource collection", "book collection"]', '["empty collection", "no holdings"]', '["collection", "resources"]', '["book collection", "special collection", "manuscript collection"]', '["public libraries", "academic libraries", "digital libraries", "library catalog", "library system", "standard library"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The library''s holdings include rare manuscripts and journals.", "Digitization projects expand the library''s holdings beyond physical shelves."]', 'technology', '2', 72040, 4177, NULL, 'opengloss-v1.1'),
('libraries_noun_2', 'libraries', 'noun', 2, 'In computing, a library is a collection of precompiled routines or functions that programs can call to perform common tasks.', '["software library", "code library"]', '["standalone program", "executable file"]', '["software component"]', '["standard library", "math library", "graphics library", "networking library"]', '["public libraries", "academic libraries", "digital libraries", "library catalog", "library system", "standard library"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The Python standard library provides core functionality.", "Developers link to external libraries via package managers."]', 'technology', '2', 72040, 4177, NULL, 'opengloss-v1.1')
