('wheel_noun_0', 'wheel', 'noun', 0, 'A circular rolling element fitted to an axle that reduces friction and supports loads for transport.', '["roller", "disk", "ring"]', '[]', '["rolling element", "machine element", "mechanical component", "simple machine"]', '["cart wheel", "bicycle wheel", "train wheel"]', '["wheel and axle", "drive wheel", "front wheel", "rear wheel", "wheel diameter", "wheel bearing"]', '{"noun_forms": ["flywheel", "steering wheel", "wheelbarrow", "wheelchair", "wheelset"], "verb_forms": ["wheel", "wheeling"], "adjective_forms": [], "adverb_forms": []}', '["Students measure a wheel circumference to calculate distance per revolution.", "A cart wheel reduces friction and supports loads on the axle."]', 'technology', 'K', 71776, 4192, NULL, 'opengloss-v1.1'),
('wheel_verb_0', 'wheel', 'verb', 0, 'To cause an object to move by rolling it on wheels or by placing it on a wheeled platform.', '["roll", "push", "propel", "trundle"]', '[]', '["move", "transport", "manipulate"]', '["trundle along", "roll downhill", "push by hand"]', '["wheel a cart", "wheel a crate", "wheeled vehicle", "wheeled platform", "wheel the robot"]', '{"noun_forms": ["wheel", "wheeler", "wheeling"], "verb_forms": [], "adjective_forms": ["wheeled"], "adverb_forms": []}', '["Wheel the cart to the workbench before starting the experiment.", "Students wheeled the model rover across the lab floor for testing."]', 'technology', 'K', 71776, 4192, NULL, 'opengloss-v1.1'),
('wheel_noun_1', 'wheel', 'noun', 1, 'A circular control interface that an operator turns to steer or direct a vehicle or mechanism.', '["steering wheel", "handwheel", "control wheel"]', '[]', '["control device", "operator interface", "mechanical component"]', '["steering wheel", "handwheel", "tiller"]', '["wheel and axle", "drive wheel", "front wheel", "rear wheel", "wheel diameter", "wheel bearing"]', '{"noun_forms": ["flywheel", "steering wheel", "wheelbarrow", "wheelchair", "wheelset"], "verb_forms": ["wheel", "wheeling"], "adjective_forms": [], "adverb_forms": []}', '["The model car steering wheel turns the front wheels for steering tests.", "Engineers explain torque applied to a steering wheel during control exercises."]', 'technology', 'K', 71776, 4192, NULL, 'opengloss-v1.1'),
('wheel_verb_1', 'wheel', 'verb', 1, 'To change direction or rotate by pivoting on wheels or an axle.', '["turn", "pivot", "swivel", "veer"]', '[]', '["change direction", "move"]', '["pivot around axle", "turn sharply", "swerve slightly"]', '["wheel a cart", "wheel a crate", "wheeled vehicle", "wheeled platform", "wheel the robot"]', '{"noun_forms": ["wheel", "wheeler", "wheeling"], "verb_forms": [], "adjective_forms": ["wheeled"], "adverb_forms": []}', '["Wheel the robot ninety degrees to face the experiment target.", "Wheel the cart slowly and note how the axle pivots."]', 'technology', 'K', 71776, 4192, NULL, 'opengloss-v1.1'),
('wheel_noun_2', 'wheel', 'noun', 2, 'A rotating mechanical member that transmits torque or stores rotational energy in machinery.', '["gear wheel", "flywheel", "pulley"]', '[]', '["rotating component", "machine element", "mechanical part"]', '["gear wheel", "flywheel", "sheave"]', '["wheel and axle", "drive wheel", "front wheel", "rear wheel", "wheel diameter", "wheel bearing"]', '{"noun_forms": ["flywheel", "steering wheel", "wheelbarrow", "wheelchair", "wheelset"], "verb_forms": ["wheel", "wheeling"], "adjective_forms": [], "adverb_forms": []}', '["A flywheel stores kinetic energy to smooth engine speed variations.", "They calculate torque transmitted through the gear wheel in the gearbox."]', 'technology', 'K', 71776, 4192, NULL, 'opengloss-v1.1'),
