INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('microsoft_adjective_0', 'microsoft', 'adjective', 0, 'Of or relating to the Microsoft Corporation, its products, or its branding.', '["Microsoft-related", "Microsoft-branded"]', '["non-Microsoft"]', '["brand adjective", "corporate adjective"]', '["windows-based", "office-suite"]', '["Microsoft software", "Microsoft Windows", "Microsoft Office", "Microsoft ecosystem", "Microsoft Azure", "Microsoft branding"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The Microsoft-related documentation emphasizes security best practices.", "Microsoft-branded hardware undergoes rigorous compatibility testing."]', 'technology', '3', 70380, 4262, NULL, 'opengloss-v1.1'),
('microsoft_noun_0', 'microsoft', 'noun', 0, 'The Microsoft Corporation is a US based multinational technology company that develops, manufactures, licenses, and supports computer software, consumer electronics, and related services.', '["Microsoft Corp", "Microsoft Corporation", "MS Corporation"]', '["nonprofit organization", "public sector"]', '["corporation", "technology company"]', '["software company", "tech giant", "cloud services provider", "enterprise software vendor"]', '["Microsoft Windows", "Microsoft Office", "Microsoft Azure", "Office suite", "Windows OS", "Microsoft Research"]', '{"noun_forms": ["Microsoft product", "Microsoft employee", "Microsoft subsidiary", "Microsoft platform"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Academic analyses describe Microsoft Corporation''s role in platform markets.", "Scholars compare Microsoft''s governance with peer technology firms."]', 'technology', '3', 70380, 4262, NULL, 'opengloss-v1.1'),
('microsoft_adjective_1', 'microsoft', 'adjective', 1, 'Designed to be compatible with or oriented toward Microsoft platforms or ecosystems; pertaining to Microsoft-driven interoperability.', '["Microsoft-compatible", "windows-centric", "office-integrated"]', '["platform-agnostic", "cross-platform"]', '["compatibility adjective", "platform-oriented adjective"]', '["windows-based", "azure-based", "office-integrated"]', '["Microsoft software", "Microsoft Windows", "Microsoft Office", "Microsoft ecosystem", "Microsoft Azure", "Microsoft branding"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The Microsoft-compatible plugins extend legacy workflows.", "Azure-based services often require Microsoft-oriented authentication."]', 'technology', '3', 70380, 4262, NULL, 'opengloss-v1.1'),
('microsoft_noun_1', 'microsoft', 'noun', 1, 'The Microsoft brand denotes the portfolio of software products and services marketed by the Microsoft Corporation.', '["brand", "trademark", "product line"]', '["unbranded product", "generic software"]', '["brand identity", "trademark", "brand"]', '["Office suite", "Windows OS", "Azure cloud", "Surface devices"]', '["Microsoft Windows", "Microsoft Office", "Microsoft Azure", "Office suite", "Windows OS", "Microsoft Research"]', '{"noun_forms": ["Microsoft product", "Microsoft employee", "Microsoft subsidiary", "Microsoft platform"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Brand scholars analyze Microsoft brand equity as a function of ecosystem lock in.", "Academic branding literature examines trademark protection in Microsoft product lines."]', 'technology', '3', 70380, 4262, NULL, 'opengloss-v1.1'),
('microsoft_noun_2', 'microsoft', 'noun', 2, 'In legal and economic scholarship, the word Microsoft refers to the company''s antitrust and competition regulation cases and related enforcement actions.', '["the firm", "the corporation", "the company"]', '["unregulated firm", "unregulated company"]', '["legal case", "regulatory issue"]', '["monopoly case", "consent decree", "settlement case"]', '["Microsoft Windows", "Microsoft Office", "Microsoft Azure", "Office suite", "Windows OS", "Microsoft Research"]', '{"noun_forms": ["Microsoft product", "Microsoft employee", "Microsoft subsidiary", "Microsoft platform"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Law reviews discuss Microsoft''s antitrust actions and settlements.", "Economics papers compare monopoly case outcomes involving Microsoft."]', 'technology', '3', 70380, 4262, NULL, 'opengloss-v1.1'),
('microsoft_noun_3', 'microsoft', 'noun', 3, 'As a global business organization, Microsoft denotes a multinational corporation with operations and subsidiaries across multiple regions and economies.', '["the firm", "the company", "the corporation"]', '["local business", "small business"]', '["global corporation", "multinational business"]', '["subsidiary", "regional office", "global headquarters"]', '["Microsoft Windows", "Microsoft Office", "Microsoft Azure", "Office suite", "Windows OS", "Microsoft Research"]', '{"noun_forms": ["Microsoft product", "Microsoft employee", "Microsoft subsidiary", "Microsoft platform"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Economics literature analyzes Microsoft''s global market strategy.", "Management studies examine Microsoft''s regional subsidiary strategies."]', 'technology', '3', 70380, 4262, NULL, 'opengloss-v1.1')
