-- lexi ETL: till (2026-09-18T16:20:25Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('till_adverb_0', 'till', 'adverb', 0, 'An adverb used to denote a time boundary, meaning up to a specified time or event, equivalent to until in temporal expressions.', '["until"]', '["after"]', '["temporal adverb", "adverb"]', '["till noon", "till dawn", "till midnight", "till now"]', '["till now", "till dawn", "till noon", "till midnight", "till 5 PM", "till the end"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": ["til"]}', '["The library is open till 6 PM.", "Data collection continued till midnight of the observation day."]', 'economics', '2', 68680, 4363, NULL, 'opengloss-v1.1'),
('till_conjunction_0', 'till', 'conjunction', 0, 'A temporal subordinating conjunction indicating that an event continues up to a specified time or moment, typically introducing a time clause.', '["until", "before", "as long as"]', '["after"]', '["subordinator", "conjunction"]', '["time conjunction", "duration conjunction"]', '["till now", "till then", "till later", "till the end", "till tomorrow"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The lecture continued till the end of the period.", "Data collection persisted till the baseline condition was met."]', 'economics', '2', 68680, 4363, NULL, 'opengloss-v1.1'),
('till_noun_0', 'till', 'noun', 0, 'A till is a cash handling device comprising a lockable drawer that holds coins and notes and enables cash transactions in a retail or service environment.', '["cash drawer", "cash box", "till box", "register drawer"]', '["cashless payment", "digital payment"]', '["container", "box", "drawer", "furniture"]', '["till drawer", "till tray", "lockable till"]', '["cash till", "till drawer", "till roll", "till balance", "till slip", "till system"]', '{"noun_forms": ["tiller", "tillage"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The cashier opened the till to count the day''s receipts.", "A securely locked till reduces the risk of petty theft."]', 'economics', '2', 68680, 4363, NULL, 'opengloss-v1.1'),
('till_preposition_0', 'till', 'preposition', 0, 'Till is a preposition used to denote a boundary in time or quantity, meaning up to and including a point; it marks the limit of a duration or amount and is synonymous with until in temporal contexts.', '["until", "up to", "to the time of"]', '["after", "beyond"]', '["preposition", "temporal preposition"]', '["time boundary preposition", "extent preposition", "boundary preposition"]', '["till now", "till midnight", "till tomorrow", "till then", "till date", "till the end"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The store is open till midnight.", "Prices rose till last year."]', 'economics', '2', 68680, 4363, NULL, 'opengloss-v1.1'),
('till_verb_0', 'till', 'verb', 0, 'To till is to cultivate and loosen the soil by turning it over with a tillage implement such as a plow or hoe, in order to prepare a seedbed and improve soil structure.', '["cultivate", "plow", "hoe", "turn"]', '["fallow"]', '["cultivation", "agriculture"]', '["plowing", "hoeing"]', '["till soil", "till the soil", "till the land", "soil tillage", "no tillage", "field tillage"]', '{"noun_forms": ["tillage", "tiller"], "verb_forms": [], "adjective_forms": ["tillable"], "adverb_forms": []}', '["Farmers till the soil in early spring to prepare seedbeds.", "Conventional tillage can disrupt soil structure and moisture retention."]', 'economics', '2', 68680, 4363, NULL, 'opengloss-v1.1'),
('till_noun_1', 'till', 'noun', 1, 'Till as glacial till: an unsorted mixture of gravel, sand, silt and clay deposited directly by a glacier.', '["glacial deposit", "unsorted sediment", "drift"]', '["stratified drift"]', '["sediment", "geological deposit", "glacial deposit"]', '["silty till", "clay till", "granular till"]', '["cash till", "till drawer", "till roll", "till balance", "till slip", "till system"]', '{"noun_forms": ["tiller", "tillage"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Geologists described the till as an unsorted, heterogeneous deposit.", "The study mapped till across the field, noting particle size variation."]', 'economics', '2', 68680, 4363, NULL, 'opengloss-v1.1'),
('till_preposition_1', 'till', 'preposition', 1, 'Variant spelling and usage of until; the meaning is the same as sense 1, used as an orthographic variant in informal or regional contexts.', '["until", "up to"]', '["after", "following"]', '["preposition", "temporal preposition"]', '["archaic form", "regional spelling"]', '["till now", "till midnight", "till tomorrow", "till then", "till date", "till the end"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Till now the project has progressed.", "He waited till the last minute."]', 'economics', '2', 68680, 4363, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
