('facebook_noun_0', 'facebook', 'noun', 0, 'Facebook is a social networking service and online platform operated by Meta Platforms, Inc., launched in 2004, that enables user profiles, friend connections, content sharing, and messaging across devices.', '["social network", "online platform", "social media site"]', '["offline network", "offline platform"]', '["online service", "digital platform", "social media platform"]', '["profile", "page", "group", "story"]', '["Facebook profile", "Facebook page", "Facebook post", "Facebook data", "Facebook account", "Facebook user"]', '{"noun_forms": ["Facebooker"], "verb_forms": ["Facebooking", "Facebooked"], "adjective_forms": [], "adverb_forms": []}', '["Researchers studied information diffusion on Facebook in contemporary politics.", "Students used Facebook to coordinate group projects and share sources."]', 'technology', '1', 68425, 4384, NULL, 'opengloss-v1.1'),
('facebook_verb_0', 'facebook', 'verb', 0, 'To locate, contact, or interact with a person via the Facebook social networking service.', '["connect", "contact", "reach"]', '["ignore", "disconnect", "avoid"]', '["online interaction", "digital communication"]', '["friend request", "profile view"]', '["facebook post", "facebook profile", "facebook page", "facebook account", "facebook friend", "facebook data"]', '{"noun_forms": ["facebooker"], "verb_forms": ["facebooking"], "adjective_forms": ["facebookish"], "adverb_forms": []}', '["Researchers facebooked eligible participants to invite them to the study.", "The recruitment team facebooked potential respondents to confirm eligibility."]', 'technology', '1', 68425, 4384, NULL, 'opengloss-v1.1'),
('facebook_noun_1', 'facebook', 'noun', 1, 'Facebook historically refers to a bound directory listing the photographs and names of members of a college or organization to aid identification.', '["face book", "student directory", "campus directory"]', '["digital directory", "online directory"]', '["directory", "reference work", "print publication"]', '["campus directory", "student roster", "alumni list"]', '["Facebook profile", "Facebook page", "Facebook post", "Facebook data", "Facebook account", "Facebook user"]', '{"noun_forms": ["Facebooker"], "verb_forms": ["Facebooking", "Facebooked"], "adjective_forms": [], "adverb_forms": []}', '["Colleges maintained a face book listing students'' names and photos.", "The term face book predates Facebook on campus catalogs."]', 'technology', '1', 68425, 4384, NULL, 'opengloss-v1.1'),
('facebook_verb_1', 'facebook', 'verb', 1, 'To publish or share information or content on Facebook, i.e., to post on the Facebook platform.', '["post", "publish", "share"]', '["delete", "remove", "unpost"]', '["online posting", "digital communication"]', '["status update", "photo upload"]', '["facebook post", "facebook profile", "facebook page", "facebook account", "facebook friend", "facebook data"]', '{"noun_forms": ["facebooker"], "verb_forms": ["facebooking"], "adjective_forms": ["facebookish"], "adverb_forms": []}', '["The lab facebooked a status update to disseminate the survey.", "Participants were asked to complete the questionnaire after viewing a Facebook post."]', 'technology', '1', 68425, 4384, NULL, 'opengloss-v1.1'),
('facebook_verb_2', 'facebook', 'verb', 2, 'To create, configure, or manage a Facebook account or page for a person or organization, i.e., to establish a presence on Facebook.', '["establish", "set up", "launch"]', '["deactivate", "delete", "retire"]', '["digital presence", "online presence"]', '["business page", "personal account"]', '["facebook post", "facebook profile", "facebook page", "facebook account", "facebook friend", "facebook data"]', '{"noun_forms": ["facebooker"], "verb_forms": ["facebooking"], "adjective_forms": ["facebookish"], "adverb_forms": []}', '["The lab facebooked a page to disseminate findings.", "The nonprofit facebooked an account for outreach."]', 'technology', '1', 68425, 4384, NULL, 'opengloss-v1.1')
