BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('shipping_adjective_0', 'shipping', 'adjective', 0, 'Relating to the transport of goods by ships, especially within the maritime sector and logistics networks.', '["maritime", "seafaring", "nautical"]', '["inland", "land-based"]', '["logistics term", "transportation term", "economic activity"]', '["container shipping", "bulk shipping"]', '["shipping costs", "shipping schedule", "shipping container", "shipping label", "shipping documents", "shipping route"]', '{"noun_forms": ["shipper", "shipment"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Shipping emissions constitute a major portion of the sector''s carbon footprint.", "Shipping regulations influence vessel routing and port infrastructure planning."]', 'economics', '2', 68217, 4393, NULL, 'opengloss-v1.1'),
('shipping_noun_0', 'shipping', 'noun', 0, 'The business and system of transporting goods by sea, air, or land, including carriers, ports, logistics, and related regulatory frameworks.', '["transport", "freight", "logistics"]', '["receiving", "unloading"]', '["commerce", "transportation", "logistics"]', '["ocean shipping", "container shipping", "air shipping"]', '["international shipping", "shipping costs", "container shipping", "ocean shipping", "bulk shipping", "shipping industry"]', '{"noun_forms": ["shipment", "shippability", "shipments"], "verb_forms": ["ship"], "adjective_forms": ["shippable"], "adverb_forms": []}', '["International shipping rates influence global trade patterns.", "Shipping costs affect the competitiveness of exporting firms."]', 'economics', '2', 68217, 4393, NULL, 'opengloss-v1.1'),
('shipping_verb_0', 'shipping', 'verb', 0, 'To move goods or passengers from one location to another as part of logistics, typically via a carrier.', '["send", "dispatch", "transport", "convey", "forward"]', '["unload", "receive"]', '["transportation", "conveyance"]', '["sea shipping", "air freight", "container shipping"]', '["shipping cost", "shipping industry", "air shipping", "express shipping", "international shipping"]', '{"noun_forms": ["shipment", "shipper"], "verb_forms": [], "adjective_forms": ["shippable"], "adverb_forms": []}', '["The company ships electronics worldwide.", "The warehouse ships orders daily."]', 'economics', '2', 68217, 4393, NULL, 'opengloss-v1.1'),
('shipping_adjective_1', 'shipping', 'adjective', 1, 'Relating to or used for the act of sending goods to customers, i.e., distribution and fulfillment activities in commerce.', '["outbound"]', '["inbound"]', '["logistics term", "distribution term"]', '["outbound shipments", "dispatch shipments"]', '["shipping costs", "shipping schedule", "shipping container", "shipping label", "shipping documents", "shipping route"]', '{"noun_forms": ["shipper", "shipment"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The shipping department manages outbound deliveries to customers.", "The shipping schedule affects order fulfillment and customer notifications."]', 'economics', '2', 68217, 4393, NULL, 'opengloss-v1.1'),
('shipping_noun_1', 'shipping', 'noun', 1, 'Shipping as a sector denotes the maritime transport industry including carriers, ports, regulatory regimes, and supporting logistics networks.', '["maritime industry", "carrier sector", "shipping sector"]', '[]', '["industry", "transportation sector"]', '["container shipping", "bulk shipping", "refrigerated shipping"]', '["international shipping", "shipping costs", "container shipping", "ocean shipping", "bulk shipping", "shipping industry"]', '{"noun_forms": ["shipment", "shippability", "shipments"], "verb_forms": ["ship"], "adjective_forms": ["shippable"], "adverb_forms": []}', '["The maritime shipping sector faced regulatory shifts after new safety conventions.", "Registry and port state control influence shipping operations globally."]', 'economics', '2', 68217, 4393, NULL, 'opengloss-v1.1'),
('shipping_verb_1', 'shipping', 'verb', 1, 'To send an item or package to a recipient via postal or courier service.', '["dispatch", "mail", "deliver", "transmit"]', '["receive", "collect"]', '["delivery", "logistics operation"]', '["express shipping", "domestic shipping", "international shipping"]', '["shipping cost", "shipping industry", "air shipping", "express shipping", "international shipping"]', '{"noun_forms": ["shipment", "shipper"], "verb_forms": [], "adjective_forms": ["shippable"], "adverb_forms": []}', '["The publisher ships the manuscript to the reviewer.", "Researchers ship datasets to collaborating laboratories."]', 'economics', '2', 68217, 4393, NULL, 'opengloss-v1.1'),
('shipping_noun_2', 'shipping', 'noun', 2, 'The practice or activity of endorsing or imagining romantic relationships between fictional characters, especially within fan communities and media discourse.', '["pairing", "romance pairing", "coupling"]', '["platonic friendship", "nonromantic pairing"]', '["fandom activity", "media discourse"]', '["ship fiction", "coupling memes", "relationship fan art"]', '["international shipping", "shipping costs", "container shipping", "ocean shipping", "bulk shipping", "shipping industry"]', '{"noun_forms": ["shipment", "shippability", "shipments"], "verb_forms": ["ship"], "adjective_forms": ["shippable"], "adverb_forms": []}', '["Scholars analyze how shipping discourse shapes audience interpretations of character relationships.", "Faculty studies consider shipping as a participatory practice within fan communities."]', 'economics', '2', 68217, 4393, NULL, 'opengloss-v1.1'),
