INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('sharp_adjective_0', 'sharp', 'adjective', 0, 'Having a fine edge, point, or blade capable of cutting or piercing easily.', '["pointed", "keen", "razorlike"]', '["blunt", "dull"]', '["edged", "pointed"]', '["razor sharp", "needle sharp"]', '["sharp increase", "sharp contrast", "sharp turn", "sharp pain"]', '{"noun_forms": ["sharpness", "sharpie"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["The surgeon relied on a sharp scalpel to make precise incisions.", "Handle the sharp knife carefully to avoid injury."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1'),
('sharp_adverb_0', 'sharp', 'adverb', 0, 'Exactly or punctually at a stated time.', '["precisely", "exactly"]', '["approximately"]', '["punctually", "promptly"]', '["right on time"]', '["ten oclock sharp", "stop sharp", "turn sharp"]', '{"noun_forms": ["sharpness"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["The seminar will begin at 10 a.m. sharp.", "Be in your seats by noon sharp or you will not be admitted."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1'),
('sharp_noun_0', 'sharp', 'noun', 0, 'A musical symbol indicating that the pitch of a note is to be raised by one semitone, or a note that has been so raised.', '["sharp sign", "raised note"]', '["flat"]', '["musical symbol", "musical note"]', '["F sharp", "C sharp"]', '["key with three sharps", "card sharp", "F sharp", "C sharp"]', '{"noun_forms": ["sharpness", "sharpie"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["The key signature has three sharps.", "Play the F sharp instead of the natural F in this measure."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1'),
('sharp_verb_0', 'sharp', 'verb', 0, 'To raise the pitch of a musical note by one semitone.', '["raise", "increase"]', '["flatten"]', '["transpose", "alter"]', '["sharp up"]', '["sharp the note", "slightly sharp", "sharps the pitch", "sharping the tone"]', '{"noun_forms": ["sharping"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["The composer decided to sharp the note to create more tension.", "Singers sometimes unintentionally sharp the final note of the phrase."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1'),
('sharp_adjective_1', 'sharp', 'adjective', 1, 'Clear, distinct, or well defined in form, detail, or perception, whether visual, auditory, or intellectual.', '["clear", "distinct", "crisp"]', '["vague", "fuzzy"]', '["precise", "accurate"]', '["sharp focused", "sharp witted"]', '["sharp increase", "sharp contrast", "sharp turn", "sharp pain"]', '{"noun_forms": ["sharpness", "sharpie"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["The microscope produced a sharp image of the cell structure.", "She has a sharp mind and quickly grasped the complex argument."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1'),
('sharp_adverb_1', 'sharp', 'adverb', 1, 'With a sudden or abrupt change in direction or manner.', '["abruptly", "suddenly"]', '["gradually"]', '["abruptly", "swiftly"]', '["sharp left", "sharp right"]', '["ten oclock sharp", "stop sharp", "turn sharp"]', '{"noun_forms": ["sharpness"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["The car turned sharp to avoid the obstacle.", "The road bends sharp after the bridge, so reduce your speed."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1'),
('sharp_noun_1', 'sharp', 'noun', 1, 'A clever or shrewd person, sometimes with the suggestion of being unscrupulous, especially in business or gambling contexts.', '["operator", "hustler", "trickster"]', '["simpleton"]', '["person", "gambler"]', '["card sharp", "pool sharp"]', '["key with three sharps", "card sharp", "F sharp", "C sharp"]', '{"noun_forms": ["sharpness", "sharpie"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["Card sharps used marked decks to cheat unsuspecting players.", "In the financial district, there are plenty of sharps looking for quick profits."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1'),
('sharp_verb_1', 'sharp', 'verb', 1, 'To become sharp or to make something sharp, particularly in tuning or in informal usage about tones or attitudes becoming keener or harsher.', '["sharpen", "intensify"]', '["soften"]', '["adjust", "modify"]', '["sharp slightly"]', '["sharp the note", "slightly sharp", "sharps the pitch", "sharping the tone"]', '{"noun_forms": ["sharping"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["If you sharp the violin slightly, it will match the piano.", "His tone began to sharp as the debate grew more heated."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1'),
('sharp_adjective_2', 'sharp', 'adjective', 2, 'Sudden, steep, or severe in degree or intensity, especially in changes, angles, or sensations.', '["abrupt", "steep", "severe"]', '["gradual", "gentle"]', '["intense", "marked"]', '["sharp rise", "sharp turn"]', '["sharp increase", "sharp contrast", "sharp turn", "sharp pain"]', '{"noun_forms": ["sharpness", "sharpie"], "verb_forms": ["sharpen"], "adjective_forms": ["sharpish"], "adverb_forms": ["sharply"]}', '["The data show a sharp increase in population over the last decade.", "He felt a sharp pain in his chest and called for medical assistance."]', 'technology', '1', 68151, 4401, NULL, 'opengloss-v1.1')
