('execution_noun_0', 'execution', 'noun', 0, 'The act of carrying out or implementing a plan, order, or instruction.', '["implementation", "performance", "fulfillment"]', '["failure", "incompletion"]', '["action", "process"]', '["plan execution", "project execution"]', '["capital punishment", "execution time", "plan execution", "perfect execution", "legal execution", "rapid execution"]', '{"noun_forms": ["executioner"], "verb_forms": [], "adjective_forms": ["executory"], "adverb_forms": []}', '["The execution of the science experiment followed the plan precisely.", "Careful execution of the project steps helps a team finish on time."]', 'law', '4', 67746, 4424, NULL, 'opengloss-v1.1'),
('execution_noun_1', 'execution', 'noun', 1, 'The act of killing a person as punishment under the law; the death penalty.', '["death penalty", "capital punishment"]', '["life sentence", "clemency"]', '["punishment", "legal penalty"]', '["hanging", "electrocution", "gas chamber", "firing squad"]', '["capital punishment", "execution time", "plan execution", "perfect execution", "legal execution", "rapid execution"]', '{"noun_forms": ["executioner"], "verb_forms": [], "adjective_forms": ["executory"], "adverb_forms": []}', '["Historically capital punishment was used for serious crimes.", "The court ordered the execution after a lengthy trial."]', 'law', '4', 67746, 4424, NULL, 'opengloss-v1.1'),
