INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('pilots_noun_0', 'pilots', 'noun', 0, 'A person who operates an aircraft; a trained professional responsible for piloting aircraft.', '["aviator", "airman", "aircrew member", "flight officer"]', '["passenger", "nonpilot"]', '["occupation", "profession"]', '["fighter pilot", "commercial pilot", "test pilot"]', '["pilot study", "pilot project", "pilot program", "airline pilot", "harbor pilot", "pilot episode"]', '{"noun_forms": ["pilotage", "copilot"], "verb_forms": ["piloting"], "adjective_forms": ["pilotless", "pilotlike"], "adverb_forms": []}', '["Airline pilots must log flight hours and pass checks.", "Researchers studied pilot decision making in simulators."]', 'technology', '2', 67503, 4441, NULL, 'opengloss-v1.1'),
('pilots_verb_0', 'pilots', 'verb', 0, 'To steer or operate a vehicle, especially an aircraft, by controlling its flight path.', '["steer", "navigate", "operate", "fly"]', '["misnavigate", "misoperate"]', '["control", "maneuver"]', '["aircraft piloting", "helicopter piloting", "drone piloting"]', '["pilot study", "pilot program", "pilot project", "pilot test", "pilot flight", "pilot run"]', '{"noun_forms": ["pilotage"], "verb_forms": ["repilot"], "adjective_forms": ["pilotless", "pilotable"], "adverb_forms": []}', '["The test pilot will pilot the experimental aircraft under instrument conditions.", "Researchers model how crews pilot aircraft in severe weather simulations."]', 'technology', '2', 67503, 4441, NULL, 'opengloss-v1.1'),
('pilots_noun_1', 'pilots', 'noun', 1, 'A professional who guides ships through hazardous or congested waters, typically by boarding the vessel at a designated point.', '["harbor pilot", "marine pilot", "channel pilot"]', '["shipmaster", "captain"]', '["occupation", "profession"]', '["harbor pilot", "river pilot", "coastal pilot"]', '["pilot study", "pilot project", "pilot program", "airline pilot", "harbor pilot", "pilot episode"]', '{"noun_forms": ["pilotage", "copilot"], "verb_forms": ["piloting"], "adjective_forms": ["pilotless", "pilotlike"], "adverb_forms": []}', '["Maritime pilots navigate ships entering crowded harbors.", "Harbor pilots are licensed professionals with specialized vessels."]', 'technology', '2', 67503, 4441, NULL, 'opengloss-v1.1'),
('pilots_verb_1', 'pilots', 'verb', 1, 'To guide, direct, or oversee the development or implementation of a project, program, or policy.', '["guide", "direct", "lead", "steer"]', '["derail", "abandon"]', '["leadership", "management"]', '["pilot program", "pilot project", "pilot policy"]', '["pilot study", "pilot program", "pilot project", "pilot test", "pilot flight", "pilot run"]', '{"noun_forms": ["pilotage"], "verb_forms": ["repilot"], "adjective_forms": ["pilotless", "pilotable"], "adverb_forms": []}', '["The committee will pilot the new data sharing policy in two departments.", "Researchers piloting a policy to reduce energy consumption across campuses."]', 'technology', '2', 67503, 4441, NULL, 'opengloss-v1.1'),
('pilots_noun_2', 'pilots', 'noun', 2, 'A small-scale preliminary study or program conducted to assess feasibility, time, cost, risk, and adverse events of a project before wider deployment.', '["pilot study", "pilot project", "feasibility test"]', '["full scale deployment", "mass rollout"]', '["experiment", "study"]', '["feasibility study", "small scale test", "feasibility trial"]', '["pilot study", "pilot project", "pilot program", "airline pilot", "harbor pilot", "pilot episode"]', '{"noun_forms": ["pilotage", "copilot"], "verb_forms": ["piloting"], "adjective_forms": ["pilotless", "pilotlike"], "adverb_forms": []}', '["A pilot study was conducted to assess intervention feasibility.", "The department launched a pilot project to evaluate curriculum changes."]', 'technology', '2', 67503, 4441, NULL, 'opengloss-v1.1'),
('pilots_verb_2', 'pilots', 'verb', 2, 'To undertake a small-scale preliminary trial of a method or intervention to assess feasibility, time, costs, and effect sizes.', '["trial", "test", "evaluate"]', '["full rollout", "scale up"]', '["testing", "evaluation"]', '["pilot study", "pilot test", "pilot trial"]', '["pilot study", "pilot program", "pilot project", "pilot test", "pilot flight", "pilot run"]', '{"noun_forms": ["pilotage"], "verb_forms": ["repilot"], "adjective_forms": ["pilotless", "pilotable"], "adverb_forms": []}', '["The researchers will pilot the study design in a small sample.", "We will pilot the data collection protocol in a small cohort."]', 'technology', '2', 67503, 4441, NULL, 'opengloss-v1.1'),
('pilots_noun_3', 'pilots', 'noun', 3, 'The first episode produced to pilot a television series, used to gauge audience interest and attract network orders.', '["pilot episode", "first episode", "premiere episode"]', '["final episode", "series finale"]', '["television episode"]', '["network pilot", "streaming pilot", "web series pilot"]', '["pilot study", "pilot project", "pilot program", "airline pilot", "harbor pilot", "pilot episode"]', '{"noun_forms": ["pilotage", "copilot"], "verb_forms": ["piloting"], "adjective_forms": ["pilotless", "pilotlike"], "adverb_forms": []}', '["The network ordered more episodes after the pilot influenced executives.", "The pilot episode introduced the main characters and setting."]', 'technology', '2', 67503, 4441, NULL, 'opengloss-v1.1')
