('buses_noun_0', 'buses', 'noun', 0, 'A road vehicle designed to carry passengers along scheduled routes, operating on public streets and serving as a standard form of mass transit.', '["public transit vehicle", "mass transit vehicle"]', '[]', '["vehicle", "land vehicle"]', '["double-decker bus", "minibus", "articulated bus", "school bus"]', '["bus stop", "bus schedule", "bus route", "city bus", "express bus", "bus protocol"]', '{"noun_forms": ["busload", "busman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Cities rely on buses to connect neighborhoods and reduce congestion.", "The school bus operates along a fixed morning route."]', 'technology', '1', 66984, 4474, NULL, 'opengloss-v1.1'),
('buses_verb_0', 'buses', 'verb', 0, 'To clear tables in a dining setting after customers have finished dining, removing dishes, glassware, utensils, and debris as part of table service.', '["clear tables", "bus dishes"]', '["set tables", "prepare tables"]', '["table service"]', '["clearing dishes"]', '["bus tables", "bus dishes", "bus passengers", "bus route", "bus stop", "bus service"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The server trained new staff to bus tables efficiently after lunch.", "During the dinner rush, workers must bus tables quickly to keep service moving."]', 'technology', '1', 66984, 4474, NULL, 'opengloss-v1.1'),
('buses_noun_1', 'buses', 'noun', 1, 'In computing, a bus is a communication subsystem that transfers data, addresses, and control signals among components within a computer or between computers.', '["computer bus", "data bus"]', '[]', '["electronic system", "computer hardware"]', '["address bus", "data bus", "control bus"]', '["bus stop", "bus schedule", "bus route", "city bus", "express bus", "bus protocol"]', '{"noun_forms": ["busload", "busman"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The data bus carries processor data between the CPU and memory.", "An address bus conveys memory addresses to fetch data."]', 'technology', '1', 66984, 4474, NULL, 'opengloss-v1.1'),
('buses_verb_1', 'buses', 'verb', 1, 'To convey passengers by bus as a mode of transportation, whether in urban public transit or private charter operations.', '["take the bus", "travel by bus"]', '["walk", "drive"]', '["move people"]', '["bus travel", "bus commute"]', '["bus tables", "bus dishes", "bus passengers", "bus route", "bus stop", "bus service"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["He buses passengers along the main corridor every morning.", "The company buses students from the campus to the stadium for events."]', 'technology', '1', 66984, 4474, NULL, 'opengloss-v1.1')
