('layer_noun_0', 'layer', 'noun', 0, 'A sheet or thin thickness of material that rests on a surface.', '["coating", "stratum", "lamina"]', '["unlayered", "uncoated"]', '["coating", "stratum"]', '["dust layer", "ice layer"]', '["layer of paint", "layer of dust", "layer of sediment", "cake layer", "top layer", "lower layer"]', '{"noun_forms": ["layering", "layerer"], "verb_forms": [], "adjective_forms": ["layered", "layerable"], "adverb_forms": []}', '["A thin layer of paint covers the wall.", "A layer of dust forms on the science bench."]', 'science', '2', 66760, 4488, NULL, 'opengloss-v1.1'),
('layer_verb_0', 'layer', 'verb', 0, 'To place or arrange something in a series of layers or coverings.', '["stack", "coat", "overlay", "laminate"]', '["expose", "uncover"]', '["arrange", "organize"]', '["laminate", "overlay"]', '["layer cake", "layer of paint", "thin layers", "thick layers", "layer height"]', '{"noun_forms": ["layerer"], "verb_forms": ["relayer"], "adjective_forms": ["layered"], "adverb_forms": []}', '["Researchers layer soil samples to reveal stratification.", "Students layer data by categories to illustrate progression."]', 'science', '2', 66760, 4488, NULL, 'opengloss-v1.1'),
