INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('pc_noun_0', 'pc', 'noun', 0, 'An abbreviation for personal computer, a general-purpose computer designed for use by an individual, typically consisting of a central processing unit, memory, storage, and input-output devices.', '["personal computer", "desktop", "workstation"]', '["mainframe", "supercomputer"]', '["computer", "microcomputer"]', '["desktop pc", "laptop pc"]', '["pc user", "pc market", "pc industry", "pc compatible"]', '{"noun_forms": ["pc user", "pc industry", "pc market"], "verb_forms": ["pc-enable"], "adjective_forms": ["pc-based", "pc-compatible"], "adverb_forms": ["pc-wise"]}', '["Most students now own a pc that they use for writing papers and conducting online research.", "The laboratory provides each researcher with a dedicated pc for data analysis and simulation work."]', 'technology', '2', 64385, 4623, NULL, 'opengloss-v1.1'),
('pc_noun_1', 'pc', 'noun', 1, 'In general discourse, any small, privately used computing device, such as a desktop or laptop, regardless of operating system or manufacturer.', '["computer", "machine", "system"]', '["server"]', '["device", "computer"]', '["gaming pc", "office pc"]', '["pc user", "pc market", "pc industry", "pc compatible"]', '{"noun_forms": ["pc user", "pc industry", "pc market"], "verb_forms": ["pc-enable"], "adjective_forms": ["pc-based", "pc-compatible"], "adverb_forms": ["pc-wise"]}', '["Her old pc could not handle the latest statistical software required for the course.", "The survey asked participants whether they accessed the platform via a pc, tablet, or smartphone."]', 'technology', '2', 64385, 4623, NULL, 'opengloss-v1.1'),
('pc_noun_2', 'pc', 'noun', 2, 'In contrastive usage, a computer compatible with the IBM PC standard and typically running a Microsoft Windows operating system, as opposed to other platforms such as Macintosh systems.', '["windows pc", "ibm-compatible", "windows machine"]', '["mac", "macintosh"]', '["personal computer", "computer"]', '["windows desktop", "windows laptop"]', '["pc user", "pc market", "pc industry", "pc compatible"]', '{"noun_forms": ["pc user", "pc industry", "pc market"], "verb_forms": ["pc-enable"], "adjective_forms": ["pc-based", "pc-compatible"], "adverb_forms": ["pc-wise"]}', '["The software was released for pc first, with a Mac version planned for the following year.", "Historically, many academic institutions standardized on pc platforms to reduce hardware and support costs."]', 'technology', '2', 64385, 4623, NULL, 'opengloss-v1.1')
