('inspector_noun_0', 'inspector', 'noun', 0, 'An individual who examines materials, equipment, or premises to verify compliance with technical, safety, or regulatory standards.', '["examiner", "auditor", "assessor", "verifier"]', '["inspectee", "noninspector"]', '["profession", "occupation"]', '["quality inspector", "building inspector", "health inspector", "safety inspector"]', '["building inspector", "quality inspector", "police inspector", "inspector general", "home inspector", "fire inspector"]', '{"noun_forms": ["inspectorship", "inspectorate"], "verb_forms": ["inspect"], "adjective_forms": [], "adverb_forms": []}', '["The quality inspector verified conformity of the batch.", "Regulatory inspectors audit facilities to ensure safety compliance."]', 'technology', '3', 64363, 4625, NULL, 'opengloss-v1.1'),
('inspector_noun_1', 'inspector', 'noun', 1, 'A police officer holding the rank of inspector, typically responsible for supervisory duties within a precinct.', '["police officer", "senior officer", "police supervisor"]', '["constable", "junior officer"]', '["law enforcement officer", "police rank"]', '["regional inspector", "district inspector"]', '["building inspector", "quality inspector", "police inspector", "inspector general", "home inspector", "fire inspector"]', '{"noun_forms": ["inspectorship", "inspectorate"], "verb_forms": ["inspect"], "adjective_forms": [], "adverb_forms": []}', '["The inspector led the investigation into the fraud case.", "In many forces, an inspector commands a squad of officers."]', 'technology', '3', 64363, 4625, NULL, 'opengloss-v1.1'),
('inspector_noun_2', 'inspector', 'noun', 2, 'A software tool used to inspect the structure, state, or behavior of code, documents, or web pages.', '["debugger", "analyzer", "viewer"]', '["compiler", "minifier"]', '["software tool", "development tool"]', '["DOM inspector", "network inspector", "style inspector", "rendering inspector"]', '["building inspector", "quality inspector", "police inspector", "inspector general", "home inspector", "fire inspector"]', '{"noun_forms": ["inspectorship", "inspectorate"], "verb_forms": ["inspect"], "adjective_forms": [], "adverb_forms": []}', '["The browser inspector reveals the DOM structure and CSS rules.", "Developers use the inspector to examine runtime values during debugging."]', 'technology', '3', 64363, 4625, NULL, 'opengloss-v1.1'),
('inspector_noun_3', 'inspector', 'noun', 3, 'A senior official who oversees inspections or audits within an organization, sometimes titled inspector general or internal inspector.', '["oversight official", "auditor", "supervisor"]', '["subordinate"]', '["official", "civil servant"]', '["inspector general", "internal inspector"]', '["building inspector", "quality inspector", "police inspector", "inspector general", "home inspector", "fire inspector"]', '{"noun_forms": ["inspectorship", "inspectorate"], "verb_forms": ["inspect"], "adjective_forms": [], "adverb_forms": []}', '["An internal inspector audited the company compliance program.", "The inspector general oversees investigative and audit functions."]', 'technology', '3', 64363, 4625, NULL, 'opengloss-v1.1')
