('accessible_adjective_0', 'accessible', 'adjective', 0, 'Capable of being reached, entered, or obtained, within reach or easily accessed in a physical, digital, or procedural sense.', '["reachable", "attainable", "approachable", "obtainable"]', '["unreachable", "inaccessible", "blocked", "closed"]', '["property", "descriptor", "attribute"]', '["accessible entrance", "wheelchair accessible", "step-free entry"]', '["accessible text", "accessible website", "accessible design", "accessible information", "accessible formats"]', '{"noun_forms": ["accessibility"], "verb_forms": [], "adjective_forms": ["inaccessible"], "adverb_forms": ["accessibly"]}', '["The library entrance is accessible to all students.", "The digital portal is accessible from tablets and laptops."]', 'technology', '7', 64292, 4628, NULL, 'opengloss-v1.1'),
('accessible_adjective_1', 'accessible', 'adjective', 1, 'Easily understood or usable by many people, especially for learners at varying reading levels, with clear and straightforward language or design.', '["clear", "readable", "plain", "user friendly", "comprehensible"]', '["confusing", "ambiguous", "incomprehensible", "opaque"]', '["readability feature", "communication property", "descriptor"]', '["plain language", "simple instructions", "clear diagrams"]', '["accessible text", "accessible website", "accessible design", "accessible information", "accessible formats"]', '{"noun_forms": ["accessibility"], "verb_forms": [], "adjective_forms": ["inaccessible"], "adverb_forms": ["accessibly"]}', '["The workbook uses plain language and large print.", "The lesson uses clear, step by step instructions."]', 'technology', '7', 64292, 4628, NULL, 'opengloss-v1.1'),
('accessible_adjective_2', 'accessible', 'adjective', 2, 'Designed to be usable by people with a range of disabilities, i.e., barrier-free and inclusive in facilities, media, and activities.', '["inclusive", "barrier free", "easy to use for all", "universal design"]', '["exclusive", "inaccessible", "restricted", "difficult to use"]', '["accessibility feature", "design property"]', '["captioned videos", "keyboard accessible", "screen reader friendly"]', '["accessible text", "accessible website", "accessible design", "accessible information", "accessible formats"]', '{"noun_forms": ["accessibility"], "verb_forms": [], "adjective_forms": ["inaccessible"], "adverb_forms": ["accessibly"]}', '["The campus has wheelchair accessible entrances.", "Materials are available in accessible formats for diverse learners."]', 'technology', '7', 64292, 4628, NULL, 'opengloss-v1.1')
