INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('interstate_adjective_0', 'interstate', 'adjective', 0, 'Of or relating to relations or activities between states within a federation, especially across state borders.', '["cross-state", "between-state"]', '["intrastate"]', '["descriptive adjective"]', '["interstate commerce", "interstate travel", "interstate regulation"]', '["interstate commerce", "interstate highway", "interstate agreement", "interstate boundary", "interstate compact", "interstate system"]', '{"noun_forms": ["interstate"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Interstate commerce laws regulate transactions crossing state boundaries.", "Interstate agreements coordinate policy across member states."]', 'technology', '5', 64281, 4629, NULL, 'opengloss-v1.1'),
('interstate_noun_0', 'interstate', 'noun', 0, 'An entire national network of controlled-access highways designated as part of the Interstate Highway System, spanning multiple states and enabling high-speed cross-state travel.', '["highway system", "federal highway system"]', '["local road", "intrastate route"]', '["highway", "road"]', '["I-5", "I-95"]', '["interstate highway", "interstate system", "interstate commerce", "interstate travel", "interstate route"]', '{"noun_forms": ["interstate commerce", "interstate highway"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The Interstate Highway System reshaped freight transport and commuting in the United States.", "Policy analyses assess funding and maintenance across the interstate network."]', 'technology', '5', 64281, 4629, NULL, 'opengloss-v1.1'),
('interstate_adjective_1', 'interstate', 'adjective', 1, 'Of or relating to highways or road networks that cross state boundaries, particularly the federally designated interstate highway system.', '["cross-state"]', '["intrastate"]', '["transport term", "descriptive adjective", "geopolitical term"]', '["interstate tollway", "interstate expressway", "interstate route"]', '["interstate commerce", "interstate highway", "interstate agreement", "interstate boundary", "interstate compact", "interstate system"]', '{"noun_forms": ["interstate"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Interstate highways connect major cities across the United States.", "Interstate transport projects require federal and state coordination."]', 'technology', '5', 64281, 4629, NULL, 'opengloss-v1.1'),
