('stress_noun_0', 'stress', 'noun', 0, 'The internal distribution of force within a material, expressed as pressure per area that can cause deformation or failure.', '["pressure", "load", "force"]', '["relief", "ease", "no stress"]', '["physical quantity", "engineering concept"]', '["tensile stress", "compressive stress", "shear stress"]', '["stress test", "stress level", "stress management", "mental stress", "academic stress"]', '{"noun_forms": ["stressor", "stressfulness"], "verb_forms": ["stress"], "adjective_forms": ["stressful", "unstressed"], "adverb_forms": ["stressfully"]}', '["The stress on the beam must be calculated to prevent failure.", "Engineers study stress to design safer structures."]', 'science', '2', 64086, 4639, NULL, 'opengloss-v1.1'),
('stress_verb_0', 'stress', 'verb', 0, 'To give special importance or emphasis to something in speech or writing.', '["emphasize"]', '["downplay"]', '["emphasis"]', '["underline", "accent"]', '["stress test", "stress level", "stress management", "stress fracture", "stress response"]', '{"noun_forms": ["stressor", "stressfulness"], "verb_forms": [], "adjective_forms": ["stressful"], "adverb_forms": ["stressfully"]}', '["The teacher stressed the need for careful proofreading.", "She stressed the main idea in her essay to help readers."]', 'science', '2', 64086, 4639, NULL, 'opengloss-v1.1'),
('stress_noun_1', 'stress', 'noun', 1, 'The emphasis or accent placed on a syllable or word during pronunciation.', '["emphasis", "accent"]', '["unstressed"]', '["linguistic feature", "prosodic feature"]', '["primary stress", "secondary stress", "word stress", "sentence stress"]', '["stress test", "stress level", "stress management", "mental stress", "academic stress"]', '{"noun_forms": ["stressor", "stressfulness"], "verb_forms": ["stress"], "adjective_forms": ["stressful", "unstressed"], "adverb_forms": ["stressfully"]}', '["In the word banana the syllable with stress is second.", "Poets use stress to create rhythm in lines."]', 'science', '2', 64086, 4639, NULL, 'opengloss-v1.1'),
('stress_verb_1', 'stress', 'verb', 1, 'To subject to physical or mental pressure or demand; to cause strain.', '["strain", "pressurize"]', '["ease", "relieve"]', '["pressure"]', '["strain", "overload"]', '["stress test", "stress level", "stress management", "stress fracture", "stress response"]', '{"noun_forms": ["stressor", "stressfulness"], "verb_forms": [], "adjective_forms": ["stressful"], "adverb_forms": ["stressfully"]}', '["Prolonged studying can stress a student''s nerves.", "Excess load can stress the bridge."]', 'science', '2', 64086, 4639, NULL, 'opengloss-v1.1'),
('stress_noun_2', 'stress', 'noun', 2, 'A state of mental or emotional strain resulting from demanding circumstances.', '["pressure", "anxiety", "tension"]', '["calm", "relief", "ease"]', '["emotional state", "psychological condition"]', '["acute stress", "chronic stress", "academic stress", "test stress"]', '["stress test", "stress level", "stress management", "mental stress", "academic stress"]', '{"noun_forms": ["stressor", "stressfulness"], "verb_forms": ["stress"], "adjective_forms": ["stressful", "unstressed"], "adverb_forms": ["stressfully"]}', '["Exams often bring academic stress for students.", "Chronic stress can affect health and learning."]', 'science', '2', 64086, 4639, NULL, 'opengloss-v1.1'),
('stress_verb_2', 'stress', 'verb', 2, 'To mark a syllable with greater emphasis when pronouncing a word.', '["accent", "emphasize"]', '["deemphasize"]', '["pronunciation"]', '["primary stress", "secondary stress"]', '["stress test", "stress level", "stress management", "stress fracture", "stress response"]', '{"noun_forms": ["stressor", "stressfulness"], "verb_forms": [], "adjective_forms": ["stressful"], "adverb_forms": ["stressfully"]}', '["In multisyllabic words you stress the second syllable.", "Some vocabulary words have primary stress on the first syllable."]', 'science', '2', 64086, 4639, NULL, 'opengloss-v1.1')
