('switch_noun_0', 'switch', 'noun', 0, 'An electrical on off device that opens or closes an electric circuit to start or stop current flow.', '["toggle", "on off switch", "lever", "pushbutton"]', '[]', '["electrical component", "control", "device"]', '["knife switch", "toggle switch", "slide switch", "push button switch"]', '["light switch", "toggle switch", "knife switch", "selector switch", "circuit switch", "switch contact"]', '{"noun_forms": ["switching", "switcher"], "verb_forms": ["switch"], "adjective_forms": ["switchable"], "adverb_forms": []}', '["Flip the switch to complete the circuit and light the bulb during the lab.", "A closed switch lets current flow through the copper wire to the motor."]', 'technology', '3', 63952, 4648, NULL, 'opengloss-v1.1'),
('switch_verb_0', 'switch', 'verb', 0, 'To cause an electrical circuit or device to change between conducting and nonconducting states by operating a control.', '["toggle", "flip", "activate", "deactivate"]', '[]', '["circuit control", "electrical control", "control", "operation"]', '["button press", "lever throw", "relay activation", "circuit closure"]', '["flip switch", "toggle switch", "power switch", "open circuit", "close circuit"]', '{"noun_forms": ["switch", "switching", "switchgear"], "verb_forms": [], "adjective_forms": ["switchable", "switched"], "adverb_forms": []}', '["The student flips the switch to complete the circuit and light the bulb.", "A worn switch can open the circuit and stop current flow during testing."]', 'technology', '3', 63952, 4648, NULL, 'opengloss-v1.1'),
('switch_noun_1', 'switch', 'noun', 1, 'A selector device that routes a signal or current between two or more paths or outputs in a circuit.', '["selector", "multiway switch", "rotary switch", "transfer switch"]', '[]', '["signal router", "electrical component", "control device"]', '["three way switch", "rotary switch", "transfer switch"]', '["light switch", "toggle switch", "knife switch", "selector switch", "circuit switch", "switch contact"]', '{"noun_forms": ["switching", "switcher"], "verb_forms": ["switch"], "adjective_forms": ["switchable"], "adverb_forms": []}', '["Use the selector switch to send the sensor signal to either meter A or meter B.", "A three way switch can route current between two different circuit branches."]', 'technology', '3', 63952, 4648, NULL, 'opengloss-v1.1'),
('switch_verb_1', 'switch', 'verb', 1, 'To change a connection from one source or pathway to another to reroute power or signals.', '["transfer", "redirect", "reroute", "shift"]', '[]', '["connection control", "signal control", "control", "operation"]', '["source selection", "path selection", "changeover switch", "selector switch"]', '["flip switch", "toggle switch", "power switch", "open circuit", "close circuit"]', '{"noun_forms": ["switch", "switching", "switchgear"], "verb_forms": [], "adjective_forms": ["switchable", "switched"], "adverb_forms": []}', '["The system automatically switches from battery power to solar power during the day.", "Technicians switch the input to compare sensor signals under different conditions."]', 'technology', '3', 63952, 4648, NULL, 'opengloss-v1.1'),
('switch_noun_2', 'switch', 'noun', 2, 'A safety disconnect that isolates a circuit or component so people can work on it without electrical hazard.', '["isolator", "disconnect", "safety switch", "circuit isolator"]', '[]', '["protective device", "electrical device", "safety equipment"]', '["disconnect switch", "lockable switch", "fused switch"]', '["light switch", "toggle switch", "knife switch", "selector switch", "circuit switch", "switch contact"]', '{"noun_forms": ["switching", "switcher"], "verb_forms": ["switch"], "adjective_forms": ["switchable"], "adverb_forms": []}', '["Turn the disconnect switch off before changing the battery to avoid a shock.", "A lockable switch keeps the circuit isolated during maintenance in the lab."]', 'technology', '3', 63952, 4648, NULL, 'opengloss-v1.1'),
('switch_verb_2', 'switch', 'verb', 2, 'To change an experimental condition or device setting as part of a procedure or measurement.', '["change", "adjust", "alter", "set"]', '[]', '["modify", "adjustment", "control", "operation"]', '["change setting", "adjust voltage", "set position", "toggle mode"]', '["flip switch", "toggle switch", "power switch", "open circuit", "close circuit"]', '{"noun_forms": ["switch", "switching", "switchgear"], "verb_forms": [], "adjective_forms": ["switchable", "switched"], "adverb_forms": []}', '["Switch the dial to increase the voltage for the next trial.", "Switching the variable lets students observe how force affects motion."]', 'technology', '3', 63952, 4648, NULL, 'opengloss-v1.1')
