INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('bin_noun_0', 'bin', 'noun', 0, 'A rigid container used for storage and organization of items, typically with a lid or opening.', '["container", "receptacle", "box", "storage bin"]', '["uncontained item"]', '["container"]', '["laundry bin", "recycling bin", "storage bin"]', '["trash bin", "garbage bin", "recycling bin", "storage bin", "histogram bin", "bin directory"]', '{"noun_forms": ["binning"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers stored samples in labeled storage bins for analysis.", "The lab organized reagents in separate bins to prevent cross-contamination."]', 'technology', '3', 63706, 4666, NULL, 'opengloss-v1.1'),
('bin_verb_0', 'bin', 'verb', 0, 'To discard or dispose of an item by placing it in a waste receptacle.', '["discard", "throw away", "delete", "junk"]', '["retain", "keep", "preserve"]', '["eliminate", "dispose"]', '["trash", "delete file"]', '["data bin", "bin data", "histogram bin", "bin edge", "equal width binning", "equal frequency binning"]', '{"noun_forms": ["dustbin", "binning"], "verb_forms": [], "adjective_forms": ["binable"], "adverb_forms": []}', '["Researchers bin obsolete records after audit.", "The team bin extraneous samples to streamline analysis."]', 'technology', '3', 63706, 4666, NULL, 'opengloss-v1.1'),
('bin_noun_1', 'bin', 'noun', 1, 'In statistics, a histogram bin is the interval used to group a range of continuous values for frequency tallies.', '["interval", "bucket"]', '["unbinned value"]', '["range"]', '["empty bin", "edge bin"]', '["trash bin", "garbage bin", "recycling bin", "storage bin", "histogram bin", "bin directory"]', '{"noun_forms": ["binning"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The data were divided into five histogram bins.", "Wider bins reduce resolution but improve stability of counts."]', 'technology', '3', 63706, 4666, NULL, 'opengloss-v1.1'),
('bin_verb_1', 'bin', 'verb', 1, 'To group a continuous variable into discrete bins for analysis; to discretize data by assigning values to bins.', '["bucketize", "classify", "discretize"]', '["disaggregate", "unbin"]', '["classify", "organize"]', '["equal width binning", "equal frequency binning", "custom binning"]', '["data bin", "bin data", "histogram bin", "bin edge", "equal width binning", "equal frequency binning"]', '{"noun_forms": ["dustbin", "binning"], "verb_forms": [], "adjective_forms": ["binable"], "adverb_forms": []}', '["We bin the data into ten equal width intervals.", "Histogram construction requires binning continuous measurements."]', 'technology', '3', 63706, 4666, NULL, 'opengloss-v1.1'),
('bin_noun_2', 'bin', 'noun', 2, 'In computing, a bin is a directory that contains executable programs on a Unix-like operating system, typically at /bin or in a similar path.', '["directory", "folder"]', '[]', '["filesystem location"]', '["system bin", "user bin"]', '["trash bin", "garbage bin", "recycling bin", "storage bin", "histogram bin", "bin directory"]', '{"noun_forms": ["binning"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["System utilities are usually found in the bin directory.", "Users can run programs located in the user bin via PATH."]', 'technology', '3', 63706, 4666, NULL, 'opengloss-v1.1'),
('bin_verb_2', 'bin', 'verb', 2, 'To place or store something into a bin or container for organization or inventory control.', '["store", "place in storage", "shelve"]', '["remove", "take out"]', '["store", "organize"]', '["labeled bin storage", "color coded bin"]', '["data bin", "bin data", "histogram bin", "bin edge", "equal width binning", "equal frequency binning"]', '{"noun_forms": ["dustbin", "binning"], "verb_forms": [], "adjective_forms": ["binable"], "adverb_forms": []}', '["Archivists bin specimens into labeled bins.", "Researchers bin samples by collection site."]', 'technology', '3', 63706, 4666, NULL, 'opengloss-v1.1')
