INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('telephone_adjective_0', 'telephone', 'adjective', 0, 'Relating to the telephone as a device, system, or service; used attributively to describe equipment and infrastructure associated with telephone communications.', '["telephonic"]', '["nontelephonic"]', '["communication technology", "information technology"]', '["telephone set", "telephone equipment"]', '["telephone service", "telephone line", "telephone network", "telephone directory", "telephone exchange", "telephone system"]', '{"noun_forms": ["telephony"], "verb_forms": ["telephone"], "adjective_forms": ["telephonic"], "adverb_forms": ["telephonically"]}', '["In this study, telephone networks were modeled to assess resilience.", "The analysis evaluated telephone service reliability under peak demand."]', 'technology', '1', 62630, 4726, NULL, 'opengloss-v1.1'),
('telephone_noun_0', 'telephone', 'noun', 0, 'An electronic device that converts vocal input into electrical signals for transmission over a network and converts received signals back into sound to enable voice communication.', '["phone"]', '[]', '["communication device", "electronic device", "telecommunications system"]', '["landline", "mobile phone", "smartphone", "rotary dial phone", "cell phone"]', '["landline telephone", "mobile phone", "telephone number", "telephone directory", "telephone line", "telecommunication network"]', '{"noun_forms": ["telephonist", "telephony"], "verb_forms": [], "adjective_forms": ["telephonic"], "adverb_forms": []}', '["The laboratory adopted a shared telephone system to coordinate field visits.", "Researchers used the telephone to collect data from remote sites."]', 'technology', '1', 62630, 4726, NULL, 'opengloss-v1.1'),
('telephone_verb_0', 'telephone', 'verb', 0, 'To contact someone by telephone by placing a call.', '["phone", "call"]', '["hang up", "not contact"]', '["communication"]', '["emergency call", "conference call"]', '["telephone call", "telephone number", "telephone line", "telephone exchange", "telephone service", "telephone directory"]', '{"noun_forms": ["telephone", "telephony", "telephonist"], "verb_forms": [], "adjective_forms": ["telephonic"], "adverb_forms": []}', '["Researchers telephoned participants to confirm interviews.", "The analyst telephoned the supervisor to report results."]', 'technology', '1', 62630, 4726, NULL, 'opengloss-v1.1'),
('telephone_adjective_1', 'telephone', 'adjective', 1, 'Relating to communication conducted by a telephone call; describing aspects of voice communication over the telephone.', '["phone-based"]', '[]', '["communication technology"]', '["voice call", "phone call"]', '["telephone service", "telephone line", "telephone network", "telephone directory", "telephone exchange", "telephone system"]', '{"noun_forms": ["telephony"], "verb_forms": ["telephone"], "adjective_forms": ["telephonic"], "adverb_forms": ["telephonically"]}', '["Survey data were collected by telephone call.", "Telephone call duration was recorded for latency analysis."]', 'technology', '1', 62630, 4726, NULL, 'opengloss-v1.1'),
('telephone_noun_1', 'telephone', 'noun', 1, 'The system and technology for transmitting voice communications across networks, collectively known as telephony.', '["telephony"]', '[]', '["communication system", "electronic communications"]', '["telephone network", "voice over IP", "mobile network", "landline system", "telephony switch"]', '["landline telephone", "mobile phone", "telephone number", "telephone directory", "telephone line", "telecommunication network"]', '{"noun_forms": ["telephonist", "telephony"], "verb_forms": [], "adjective_forms": ["telephonic"], "adverb_forms": []}', '["Telephony infrastructure supports emergency response systems.", "Advances in telephony technology have reshaped organizational communication strategies."]', 'technology', '1', 62630, 4726, NULL, 'opengloss-v1.1'),
('telephone_verb_1', 'telephone', 'verb', 1, 'To report information by telephone to a person or organization.', '["call in", "phone in"]', '["withhold information", "conceal report"]', '["communication"]', '["incident report", "update"]', '["telephone call", "telephone number", "telephone line", "telephone exchange", "telephone service", "telephone directory"]', '{"noun_forms": ["telephone", "telephony", "telephonist"], "verb_forms": [], "adjective_forms": ["telephonic"], "adverb_forms": []}', '["The nurse telephoned in an update about patient status.", "Analysts telephoned in a preliminary incident report."]', 'technology', '1', 62630, 4726, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
