('tested_adjective_0', 'tested', 'adjective', 0, 'Having undergone testing or empirical evaluation to determine conformance to criteria; used to describe a device, method, or result that has been subjected to procedures intended to verify its reliability or validity.', '["proven", "validated", "verified", "demonstrated"]', '["untested", "unproven", "unverified", "questionable"]', '["evaluation", "verification", "quality"]', '["lab-tested", "field-tested"]', '["lab-tested", "field-tested", "stress-tested", "testable hypothesis", "testable design"]', '{"noun_forms": ["tester", "testability"], "verb_forms": ["test"], "adjective_forms": ["testable"], "adverb_forms": ["testably"]}', '["The tested instrument produced consistent results across trials.", "A tested protocol ensures data comparability across laboratories."]', 'science', '2', 62225, 4745, NULL, 'opengloss-v1.1'),
('tested_verb_0', 'tested', 'verb', 0, 'To administer an examination or measure to determine the properties, performance, or validity of a subject, device, or model.', '["assess", "evaluate", "examine", "probe"]', '["ignore", "neglect", "disregard"]', '["examination", "assessment", "evaluation"]', '["field test", "laboratory test", "pilot test"]', '["field test", "laboratory test", "diagnostic test", "pilot test", "robustness test", "validation test"]', '{"noun_forms": ["tester", "testability"], "verb_forms": ["retest"], "adjective_forms": ["testable"], "adverb_forms": ["testably"]}', '["Researchers tested the hypothesis using a controlled experiment.", "The instrument was tested under varying temperatures."]', 'science', '2', 62225, 4745, NULL, 'opengloss-v1.1'),
('tested_verb_1', 'tested', 'verb', 1, 'To undergo testing or evaluation, typically under controlled or defined conditions.', '["undergo", "evaluate", "examine", "probe"]', '["ignore", "omit", "skip"]', '["examination", "evaluation", "testing"]', '["field test", "laboratory test", "trial"]', '["field test", "laboratory test", "diagnostic test", "pilot test", "robustness test", "validation test"]', '{"noun_forms": ["tester", "testability"], "verb_forms": ["retest"], "adjective_forms": ["testable"], "adverb_forms": ["testably"]}', '["The device underwent accelerated life testing.", "The software prototypes were evaluated under simulated loads."]', 'science', '2', 62225, 4745, NULL, 'opengloss-v1.1'),
('tested_verb_2', 'tested', 'verb', 2, 'Used as a participial adjective to indicate proven reliability or validity after testing.', '["proven", "validated", "verified", "confirmed"]', '["unproven", "unvalidated", "unverified"]', '["validity", "reliability"]', '["pilot tested", "field tested", "laboratory tested"]', '["field test", "laboratory test", "diagnostic test", "pilot test", "robustness test", "validation test"]', '{"noun_forms": ["tester", "testability"], "verb_forms": ["retest"], "adjective_forms": ["testable"], "adverb_forms": ["testably"]}', '["A tested protocol is recommended.", "The tested method demonstrated robust performance."]', 'science', '2', 62225, 4745, NULL, 'opengloss-v1.1')
