-- lexi ETL: files (2026-09-18T16:20:27Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('files_noun_0', 'files', 'noun', 0, 'Collections of documents, data, or records that are stored together and treated as a single unit, often for purposes of organization, retrieval, or analysis.', '["records", "documents", "dossiers"]', '["void", "absence"]', '["collection", "archive"]', '["case files", "patient files"]', '["digital files", "confidential files", "patient files", "case files"]', '{"noun_forms": ["filing", "file system"], "verb_forms": ["file", "refile", "prefile"], "adjective_forms": ["file-based", "fileless"], "adverb_forms": ["filewise"]}', '["The researcher stored all participant consent forms in separate files by year.", "Digital files can be backed up automatically to prevent data loss."]', 'technology', '4', 62149, 4747, NULL, 'opengloss-v1.1'),
('files_verb_0', 'files', 'verb', 0, 'To submit a document or set of documents formally to an authority, institution, or system for official consideration, record, or processing.', '["submit", "lodge", "register"]', '["withdraw", "retract"]', '["send", "present"]', '["e-file", "refile"]', '["files a complaint", "files an appeal", "files documents", "files electronically"]', '{"noun_forms": ["filing", "filer"], "verb_forms": ["refile", "misfile"], "adjective_forms": ["filed", "filing"], "adverb_forms": []}', '["Participants were required to file their applications before the deadline.", "The company files its annual report with the regulatory agency each March."]', 'technology', '4', 62149, 4747, NULL, 'opengloss-v1.1'),
('files_noun_1', 'files', 'noun', 1, 'Digital data objects stored on a computer or similar device, typically identified by a name and format, and managed by an operating system.', '["data files", "computer files", "documents"]', '["corruption", "blank"]', '["data", "resource"]', '["text files", "binary files"]', '["digital files", "confidential files", "patient files", "case files"]', '{"noun_forms": ["filing", "file system"], "verb_forms": ["file", "refile", "prefile"], "adjective_forms": ["file-based", "fileless"], "adverb_forms": ["filewise"]}', '["The dataset is divided into three files corresponding to different experimental conditions.", "All configuration files must be updated before running the new software version."]', 'technology', '4', 62149, 4747, NULL, 'opengloss-v1.1'),
('files_verb_1', 'files', 'verb', 1, 'To arrange or store documents, records, or data in an ordered system so that they can be easily located and retrieved.', '["archive", "organize", "classify"]', '["scatter", "misplace"]', '["store", "arrange"]', '["cross-file", "color-code"]', '["files a complaint", "files an appeal", "files documents", "files electronically"]', '{"noun_forms": ["filing", "filer"], "verb_forms": ["refile", "misfile"], "adjective_forms": ["filed", "filing"], "adverb_forms": []}', '["Research assistants carefully file interview transcripts by date and participant code.", "All correspondence must be filed immediately after it is read."]', 'technology', '4', 62149, 4747, NULL, 'opengloss-v1.1'),
('files_noun_2', 'files', 'noun', 2, 'Organized sets of information maintained about individuals, organizations, or cases, especially in administrative, legal, medical, or security contexts.', '["records", "dossiers", "profiles"]', '["anonymity"]', '["record", "document"]', '["medical files", "legal files"]', '["digital files", "confidential files", "patient files", "case files"]', '{"noun_forms": ["filing", "file system"], "verb_forms": ["file", "refile", "prefile"], "adjective_forms": ["file-based", "fileless"], "adverb_forms": ["filewise"]}', '["The hospital is required to keep patient files for at least ten years.", "The agency maintains files on companies that repeatedly violate regulations."]', 'technology', '4', 62149, 4747, NULL, 'opengloss-v1.1'),
('files_verb_2', 'files', 'verb', 2, 'To smooth, shape, or abrade a surface, especially of metal, wood, or nails, using a file tool.', '["smooth", "grind", "polish"]', '["roughen"]', '["shape", "abrade"]', '["nail-file", "hand-file"]', '["files a complaint", "files an appeal", "files documents", "files electronically"]', '{"noun_forms": ["filing", "filer"], "verb_forms": ["refile", "misfile"], "adjective_forms": ["filed", "filing"], "adverb_forms": []}', '["The technician filed the metal edges to prevent injury during handling.", "Before the experiment, the samples were filed and cleaned to ensure a uniform surface."]', 'technology', '4', 62149, 4747, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
