('signals_noun_0', 'signals', 'noun', 0, 'A sign or prompt that conveys information or cues someone to act.', '["sign", "cue", "indicator"]', '["silence", "noise"]', '["indicator", "sign"]', '["alarm signal", "traffic signal", "warning signal"]', '["traffic signals", "signal strength", "signal processing", "alarm signal", "digital signal", "signal flare"]', '{"noun_forms": ["signaler", "signalization", "signaling", "signalment"], "verb_forms": ["signal", "signaled", "signaling", "signals"], "adjective_forms": [], "adverb_forms": []}', '["Traffic signals regulate when cars may proceed at an intersection.", "A teacher’s nod can be a signal that a student understands the concept."]', 'technology', '4', 61770, 4768, NULL, 'opengloss-v1.1'),
('signals_verb_0', 'signals', 'verb', 0, 'To transmit information or instructions to others by a signal such as a gesture, sound, or device, with the expectation that others respond.', '["inform", "convey", "alert"]', '["conceal", "ignore", "withhold"]', '["communicate", "inform"]', '["gesture", "beep", "indicator"]', '["signal a warning", "signal readiness", "signal danger", "signal intent", "visual signal"]', '{"noun_forms": ["signalling", "signaller", "signalization"], "verb_forms": ["signalize"], "adjective_forms": ["signalable"], "adverb_forms": ["signally"]}', '["The teacher signals the class to begin the test with a whistle.", "A blinking light signals when the machine is ready."]', 'technology', '4', 61770, 4768, NULL, 'opengloss-v1.1'),
('signals_noun_1', 'signals', 'noun', 1, 'An electrical or electronic impulse that carries information in a system or device.', '["transmission", "pulse", "waveform"]', '["noise", "static"]', '["data unit"]', '["digital signal", "analog signal", "radio signal"]', '["traffic signals", "signal strength", "signal processing", "alarm signal", "digital signal", "signal flare"]', '{"noun_forms": ["signaler", "signalization", "signaling", "signalment"], "verb_forms": ["signal", "signaled", "signaling", "signals"], "adjective_forms": [], "adverb_forms": []}', '["A digital signal carries data in a computer circuit.", "An analog signal changes smoothly over time to transmit information."]', 'technology', '4', 61770, 4768, NULL, 'opengloss-v1.1'),
('signals_verb_1', 'signals', 'verb', 1, 'To indicate or point to something as a sign or omen of a future event or condition.', '["indicate", "denote"]', '["conceal", "ignore"]', '["inform", "indicate"]', '["alarm", "warning light", "sound cue"]', '["signal a warning", "signal readiness", "signal danger", "signal intent", "visual signal"]', '{"noun_forms": ["signalling", "signaller", "signalization"], "verb_forms": ["signalize"], "adjective_forms": ["signalable"], "adverb_forms": ["signally"]}', '["Dark clouds signal an approaching storm.", "A rising stock price signals economic improvement."]', 'technology', '4', 61770, 4768, NULL, 'opengloss-v1.1')
