('utc_adjective_0', 'utc', 'adjective', 0, 'Relating to the time standard Coordinated Universal Time used as the global reference for timekeeping; used to express times and timestamps without time-zone designation.', '["universal time", "UTC time"]', '["local time"]', '["time standard"]', '["UTC offset", "UTC timestamp"]', '["utc time", "utc offset", "utc timestamp", "utc clock", "utc date", "utc format"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Experiment logs were recorded in UTC time to ensure cross site comparability.", "Satellite telemetry uses UTC timestamps to avoid daylight saving complexities."]', 'science', 'BS', 61397, 4789, NULL, 'opengloss-v1.1'),
('utc_noun_0', 'utc', 'noun', 0, 'Coordinated Universal Time is the global time standard used to regulate clocks and timekeeping across science, industry, and civil life.', '["Coordinated Universal Time", "UTC time", "time standard", "global time standard"]', '["local time", "solar time"]', '["time standard", "temporal standard"]', '["UTC offset zero"]', '["Coordinated Universal Time", "UTC offset", "UTC time", "UTC clock", "UTC standard", "UTC-based"]', '{"noun_forms": ["time standard"], "verb_forms": [], "adjective_forms": ["UTC-based", "UTC-aligned"], "adverb_forms": []}', '["The event was scheduled for UTC 15:00.", "Researchers compare measurements using UTC as the reference clock."]', 'science', 'BS', 61397, 4789, NULL, 'opengloss-v1.1'),
