INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('plastic_adjective_0', 'plastic', 'adjective', 0, 'Capable of being shaped or formed; able to be molded without breaking.', '["moldable", "malleable", "pliant", "shapeable"]', '["rigid", "inflexible", "stiff"]', '["adjective", "quality"]', '["moldable", "shapeable", "pliable"]', '["moldable plastic", "made of plastic", "plastic product", "plastic bottle", "plastic material", "plastic toy"]', '{"noun_forms": ["plasticity"], "verb_forms": ["plasticize"], "adjective_forms": ["plasticky"], "adverb_forms": ["plastically"]}', '["Modeling clay is plastic when warmed, allowing shapes to be formed.", "The sculptor described plastic clay as moldable under heat."]', 'science', '1', 60172, 4876, NULL, 'opengloss-v1.1'),
('plastic_noun_0', 'plastic', 'noun', 0, 'A synthetic polymer material used to make many everyday objects; it can be molded when soft and set into a rigid shape.', '["polymer", "synthetic material", "plastic material", "resin"]', '["natural material", "organic material"]', '["material", "substance"]', '["polyethylene", "polypropylene", "polyvinyl chloride"]', '["plastic bag", "plastic bottle", "plastic straw", "plastic container", "recycled plastic", "plastic pollution"]', '{"noun_forms": ["plastics", "plasticity"], "verb_forms": ["plasticize"], "adjective_forms": ["plasticizable"], "adverb_forms": []}', '["Many products such as bottles are made of plastic.", "Polymers form the basis of modern plastic materials."]', 'science', '1', 60172, 4876, NULL, 'opengloss-v1.1'),
('plastic_adjective_1', 'plastic', 'adjective', 1, 'Made of plastic material; composed of synthetic polymer.', '["polymeric", "synthetic"]', '["natural", "wooden", "ceramic"]', '["adjective", "material type"]', '["plastic bottle", "plastic product", "plastic item"]', '["moldable plastic", "made of plastic", "plastic product", "plastic bottle", "plastic material", "plastic toy"]', '{"noun_forms": ["plasticity"], "verb_forms": ["plasticize"], "adjective_forms": ["plasticky"], "adverb_forms": ["plastically"]}', '["The bottle is made of plastic material and is light.", "Many toys are plastic products designed to be lightweight."]', 'science', '1', 60172, 4876, NULL, 'opengloss-v1.1'),
('plastic_noun_1', 'plastic', 'noun', 1, 'A credit or debit card issued by a bank or retailer, often called plastic, used to make payments electronically.', '["credit card", "bank card", "payment card", "card"]', '["cash", "coins"]', '["card", "payment instrument"]', '["debit card", "gift card", "prepaid card"]', '["plastic bag", "plastic bottle", "plastic straw", "plastic container", "recycled plastic", "plastic pollution"]', '{"noun_forms": ["plastics", "plasticity"], "verb_forms": ["plasticize"], "adjective_forms": ["plasticizable"], "adverb_forms": []}', '["Students often pay for school lunches with plastic.", "The plastic helped pay for books at the library."]', 'science', '1', 60172, 4876, NULL, 'opengloss-v1.1'),
('plastic_adjective_2', 'plastic', 'adjective', 2, 'Artificial or insincere; lacking natural authenticity.', '["artificial", "insincere", "fake", "phony"]', '["genuine", "authentic", "sincere", "natural"]', '["adjective", "appearance quality"]', '["fake smile", "phony gesture", "artificial expression"]', '["moldable plastic", "made of plastic", "plastic product", "plastic bottle", "plastic material", "plastic toy"]', '{"noun_forms": ["plasticity"], "verb_forms": ["plasticize"], "adjective_forms": ["plasticky"], "adverb_forms": ["plastically"]}', '["Her plastic smile hid her sadness from the audience.", "The critic called the scene a plastic performance lacking honesty."]', 'science', '1', 60172, 4876, NULL, 'opengloss-v1.1'),
('plastic_adjective_3', 'plastic', 'adjective', 3, 'In engineering, able to undergo permanent deformation without fracture.', '["ductile", "malleable", "deformable"]', '["brittle", "rigid", "fragile"]', '["adjective", "mechanical property"]', '["ductile metal", "deformable polymer"]', '["moldable plastic", "made of plastic", "plastic product", "plastic bottle", "plastic material", "plastic toy"]', '{"noun_forms": ["plasticity"], "verb_forms": ["plasticize"], "adjective_forms": ["plasticky"], "adverb_forms": ["plastically"]}', '["Under strong pressure the metal shows plastic deformation.", "Some plastics exhibit permanent shape change when stressed."]', 'science', '1', 60172, 4876, NULL, 'opengloss-v1.1')
