('workshop_noun_0', 'workshop', 'noun', 0, 'A room or building in which goods are manufactured or repaired; a space equipped for performing manual or craft work.', '["shop", "workroom", "studio"]', '["office"]', '["facility", "space", "building"]', '["machine shop", "maker space", "art studio"]', '["workshop schedule", "workshop leader", "workshop materials", "coding workshop", "hands on workshop", "maker space workshop"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The university maintains a woodshop where students practice carpentry.", "Local makers use the workshop as a space for prototyping."]', 'technology', '4', 59660, 4912, NULL, 'opengloss-v1.1'),
('workshop_verb_0', 'workshop', 'verb', 0, 'To subject a document, plan, or proposal to a structured collaborative revision process by organizing or participating in a workshop.', '["revise", "refine", "edit", "rework"]', '["discard", "ignore", "finalize"]', '["edit", "review", "modify", "process"]', '["rework the draft", "redraft the proposal", "polish the manuscript", "refine the protocol"]', '["workshop format", "workshop session", "workshop plan", "workshop agenda", "research workshop"]', '{"noun_forms": [], "verb_forms": ["workshopping", "workshopped"], "adjective_forms": [], "adverb_forms": []}', '["The committee will workshop the policy draft during the meeting.", "Researchers will workshop the experimental design before submission."]', 'technology', '4', 59660, 4912, NULL, 'opengloss-v1.1'),
('workshop_noun_1', 'workshop', 'noun', 1, 'A structured session, typically hands-on, in which participants learn about a topic or develop a skill, often as part of a course or professional development.', '["seminar", "training session"]', '["lecture"]', '["event", "training program"]', '["seminar", "tutorial", "hands-on session"]', '["workshop schedule", "workshop leader", "workshop materials", "coding workshop", "hands on workshop", "maker space workshop"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The department offered a hands-on data analysis workshop for researchers.", "A coding workshop attracted software developers seeking practical skills."]', 'technology', '4', 59660, 4912, NULL, 'opengloss-v1.1')
