('lab_noun_1', 'lab', 'noun', 1, 'A room or area designated for a specific instructional or computational activity within an institution, such as a computer lab.', '["computer lab", "language lab", "teaching lab"]', '["field", "outdoors"]', '["facility", "room"]', '["computer lab", "language lab"]', '["lab coat", "lab bench", "lab report", "lab equipment", "lab safety"]', '{"noun_forms": ["laboratory"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Students use the computer lab for data analysis.", "The language lab supports phonetic practice with audio resources."]', 'science', '5', 58707, 4985, NULL, 'opengloss-v1.1'),
('lab_noun_2', 'lab', 'noun', 2, 'A medium to large breed of dog, Labrador Retriever, commonly kept as a companion and working dog.', '["Labrador Retriever", "Labrador"]', '["cat"]', '["dog", "canine"]', '["yellow lab", "black lab"]', '["lab coat", "lab bench", "lab report", "lab equipment", "lab safety"]', '{"noun_forms": ["laboratory"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Many labs are friendly family dogs.", "A well trained lab can fetch and retrieve."]', 'science', '5', 58707, 4985, NULL, 'opengloss-v1.1')
