('boards_noun_0', 'boards', 'noun', 0, 'A flat rectangular piece of wood used in construction and carpentry, typically cut to standard thickness and length.', '["plank", "slab", "lumber", "wood piece"]', '["block"]', '["lumber", "wood product", "construction material"]', '["oak board", "pine board", "walnut board", "birch board"]', '["wooden board", "pine board", "board of directors", "executive board", "whiteboard", "circuit board"]', '{"noun_forms": ["boarder"], "verb_forms": ["boarded", "boarding"], "adjective_forms": ["boardlike"], "adverb_forms": []}', '["The researchers cut oak boards for the frame assembly.", "Pine boards were prepared as surface panels in the test rig."]', 'technology', '1', 57624, 5059, NULL, 'opengloss-v1.1'),
('boards_verb_0', 'boards', 'verb', 0, 'To get on or into a vehicle or vessel in order to travel.', '["enter", "embark"]', '["alight"]', '["entering vehicle", "movement"]', '["plane boarding", "train boarding", "bus boarding", "ship boarding"]', '["boarding pass", "plane boarding", "train boarding", "bus boarding", "boarding process"]', '{"noun_forms": ["boarder"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Passengers board the train at platform nine.", "Researchers board the research vessel after safety briefing."]', 'technology', '1', 57624, 5059, NULL, 'opengloss-v1.1'),
('boards_noun_1', 'boards', 'noun', 1, 'A formal governing body responsible for directing the affairs of an organization.', '["panel", "council", "committee", "trustees"]', '["staff"]', '["governing body", "organization body", "corporate entity"]', '["executive board", "advisory board", "board of directors"]', '["wooden board", "pine board", "board of directors", "executive board", "whiteboard", "circuit board"]', '{"noun_forms": ["boarder"], "verb_forms": ["boarded", "boarding"], "adjective_forms": ["boardlike"], "adverb_forms": []}', '["The board approved the policy after consulting stakeholders.", "The audit committee reported to the board during the annual session."]', 'technology', '1', 57624, 5059, NULL, 'opengloss-v1.1'),
('boards_verb_1', 'boards', 'verb', 1, 'To cover by fastening wooden boards over an opening, such as a window or doorway.', '["cover", "seal"]', '["uncover", "unseal"]', '["covering"]', '["window boarding", "door boarding", "storefront boarding"]', '["boarding pass", "plane boarding", "train boarding", "bus boarding", "boarding process"]', '{"noun_forms": ["boarder"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The storefront was boarded up after the storm.", "Contractors boarded the windows to secure the building."]', 'technology', '1', 57624, 5059, NULL, 'opengloss-v1.1'),
('boards_noun_2', 'boards', 'noun', 2, 'A flat rigid surface used for writing or display, or as a substrate for mounting components.', '["whiteboard", "chalkboard", "blackboard"]', '[]', '["surface", "writing surface", "display surface"]', '["whiteboard", "chalkboard", "blackboard", "dry erase board"]', '["wooden board", "pine board", "board of directors", "executive board", "whiteboard", "circuit board"]', '{"noun_forms": ["boarder"], "verb_forms": ["boarded", "boarding"], "adjective_forms": ["boardlike"], "adverb_forms": []}', '["Students annotated results on the whiteboard during seminar.", "The chalkboard displayed the derivation steps during the lecture."]', 'technology', '1', 57624, 5059, NULL, 'opengloss-v1.1')
