('mirror_noun_0', 'mirror', 'noun', 0, 'A polished surface that forms an image of objects in front of it.', '["looking glass", "reflecting surface"]', '["nonreflective surface"]', '["device", "instrument", "apparatus"]', '["plane mirror", "concave mirror", "convex mirror"]', '["rearview mirror", "bathroom mirror", "hand mirror", "plane mirror", "mirror image", "mirror surface"]', '{"noun_forms": [], "verb_forms": ["mirror"], "adjective_forms": ["mirrorlike"], "adverb_forms": []}', '[]', 'science', '2', 57229, 5077, NULL, 'opengloss-v1.1'),
('mirror_verb_0', 'mirror', 'verb', 0, 'To throw back or reproduce an image from a surface such as a mirror.', '["reflect", "reproduce", "display"]', '["conceal", "absorb"]', '["verb", "reflective action"]', '["mirror image", "reflected image"]', '["mirror image", "mirror data", "mirror results", "mirror progress", "mirror effect", "mirror model"]', '{"noun_forms": ["mirror image"], "verb_forms": [], "adjective_forms": ["mirrorlike"], "adverb_forms": []}', '["A calm lake mirrors the surrounding mountains at dawn.", "The polished window mirrors the classroom clearly in bright light."]', 'science', '2', 57229, 5077, NULL, 'opengloss-v1.1'),
('mirror_noun_1', 'mirror', 'noun', 1, 'A thing that reveals or represents the true character or state of something, often used metaphorically.', '["example", "model"]', '["distortion", "misrepresentation"]', '["representation", "depiction"]', '["paradigm", "archetype", "template"]', '["rearview mirror", "bathroom mirror", "hand mirror", "plane mirror", "mirror image", "mirror surface"]', '{"noun_forms": [], "verb_forms": ["mirror"], "adjective_forms": ["mirrorlike"], "adverb_forms": []}', '[]', 'science', '2', 57229, 5077, NULL, 'opengloss-v1.1'),
('mirror_verb_1', 'mirror', 'verb', 1, 'To imitate or copy closely.', '["imitate", "copy", "simulate", "emulate"]', '["differ", "vary"]', '["verb", "imitative action"]', '["mimic", "simulate"]', '["mirror image", "mirror data", "mirror results", "mirror progress", "mirror effect", "mirror model"]', '{"noun_forms": ["mirror image"], "verb_forms": [], "adjective_forms": ["mirrorlike"], "adverb_forms": []}', '["Students mirror their mentor''s study habits.", "The new dancer mirrors the professional''s movements."]', 'science', '2', 57229, 5077, NULL, 'opengloss-v1.1'),
('mirror_noun_2', 'mirror', 'noun', 2, 'The exact image produced by reflecting a figure across a line or plane in geometry.', '["reflection", "mirror image"]', '["original"]', '["image", "depiction"]', '["left-right flip", "vertical flip", "horizontal flip", "inverted image"]', '["rearview mirror", "bathroom mirror", "hand mirror", "plane mirror", "mirror image", "mirror surface"]', '{"noun_forms": [], "verb_forms": ["mirror"], "adjective_forms": ["mirrorlike"], "adverb_forms": []}', '[]', 'science', '2', 57229, 5077, NULL, 'opengloss-v1.1'),
