INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('flash_adjective_0', 'flash', 'adjective', 0, 'Bright or vivid due to a brief emission of light; emitting a sudden, momentary brightness.', '["bright", "brilliant", "gleaming", "radiant"]', '["dull", "dim", "faint"]', '["brightness", "lightness", "visual property"]', '["glowing", "gleaming", "shimmering"]', '["flash memory", "flash sale", "flash photography", "flash flood", "flash point", "flash drive"]', '{"noun_forms": ["flashiness"], "verb_forms": [], "adjective_forms": ["flashy"], "adverb_forms": ["flashily"]}', '["The flash lighting in the lab helped reveal tiny details.", "The display relied on flash brightness to highlight key ideas."]', 'technology', '1', 56603, 5117, NULL, 'opengloss-v1.1'),
('flash_noun_0', 'flash', 'noun', 0, 'A brief burst of bright light produced by a sudden luminous source.', '["glint", "gleam", "flare", "burst"]', '["darkness", "shadow"]', '["light", "illumination"]', '["camera flash", "lightning flash", "strobe flash"]', '["camera flash", "flash memory", "flash drive", "flash card", "bright flash", "flash of light"]', '{"noun_forms": ["flashcard", "flashiness"], "verb_forms": [], "adjective_forms": ["flashy"], "adverb_forms": []}', '["The photographer used a flash to light the scene.", "A sudden flash of lightning lit the sky."]', 'technology', '1', 56603, 5117, NULL, 'opengloss-v1.1'),
('flash_verb_0', 'flash', 'verb', 0, 'To emit a brief, bright burst of light.', '["glare", "flare", "gleam"]', '["dim", "darken"]', '["shine"]', '["glimmer"]', '["flash a photo", "camera flash", "flash of light", "in a flash", "flash by", "flash message"]', '{"noun_forms": ["flasher", "flashiness"], "verb_forms": ["reflash"], "adjective_forms": ["flashy"], "adverb_forms": ["flashily"]}', '["The camera flashed as the group posed for the yearbook photo.", "Lightning flashed across the night sky during the thunderstorm."]', 'technology', '1', 56603, 5117, NULL, 'opengloss-v1.1'),
('flash_adjective_1', 'flash', 'adjective', 1, 'Done or occurring in a very short time; rapid or immediate.', '["instant", "rapid", "swift", "sudden"]', '["slow", "delayed", "gradual"]', '["speed"]', '["instantaneous", "swift", "rapid"]', '["flash memory", "flash sale", "flash photography", "flash flood", "flash point", "flash drive"]', '{"noun_forms": ["flashiness"], "verb_forms": [], "adjective_forms": ["flashy"], "adverb_forms": ["flashily"]}', '["The class completed the quiz in a flash.", "The device responded with a flash decision after the prompt."]', 'technology', '1', 56603, 5117, NULL, 'opengloss-v1.1'),
('flash_noun_1', 'flash', 'noun', 1, 'A brief, sudden display of a quality, memory, or emotion.', '["glimpse", "spark", "flare", "glimmer"]', '["calmness", "steadiness"]', '["appearance", "occurrence"]', '["flash of anger", "flash of memory", "flash of realization"]', '["camera flash", "flash memory", "flash drive", "flash card", "bright flash", "flash of light"]', '{"noun_forms": ["flashcard", "flashiness"], "verb_forms": [], "adjective_forms": ["flashy"], "adverb_forms": []}', '["A flash of anger crossed her face.", "A flash of memory returned when the name was mentioned."]', 'technology', '1', 56603, 5117, NULL, 'opengloss-v1.1'),
('flash_verb_1', 'flash', 'verb', 1, 'To display something briefly or conspicuously, such as a badge, card, or message.', '["display", "show", "exhibit"]', '["conceal", "hide"]', '["present"]', '["badge display", "screen pop"]', '["flash a photo", "camera flash", "flash of light", "in a flash", "flash by", "flash message"]', '{"noun_forms": ["flasher", "flashiness"], "verb_forms": ["reflash"], "adjective_forms": ["flashy"], "adverb_forms": ["flashily"]}', '["The security guard flashed his badge to gain entry.", "A warning message flashed on the screen during the lecture."]', 'technology', '1', 56603, 5117, NULL, 'opengloss-v1.1'),
('flash_adjective_2', 'flash', 'adjective', 2, 'Ostentatiously bright or elaborate; designed to attract attention.', '["showy", "gaudy", "ostentatious", "flashy"]', '["modest", "simple", "subtle"]', '["appearance descriptor", "visual style"]', '["gaudy color", "loud print", "ornate design"]', '["flash memory", "flash sale", "flash photography", "flash flood", "flash point", "flash drive"]', '{"noun_forms": ["flashiness"], "verb_forms": [], "adjective_forms": ["flashy"], "adverb_forms": ["flashily"]}', '["The poster used flash colors to grab attention.", "A flash jacket and bold colors marked the presentation."]', 'technology', '1', 56603, 5117, NULL, 'opengloss-v1.1'),
('flash_noun_2', 'flash', 'noun', 2, 'A type of nonvolatile memory storage used in electronics.', '["memory", "storage", "nonvolatile memory"]', '[]', '["memory type", "storage medium"]', '["usb flash drive", "sd card", "memory card"]', '["camera flash", "flash memory", "flash drive", "flash card", "bright flash", "flash of light"]', '{"noun_forms": ["flashcard", "flashiness"], "verb_forms": [], "adjective_forms": ["flashy"], "adverb_forms": []}', '["Many USB drives use flash memory.", "Flash memory helps phones store apps."]', 'technology', '1', 56603, 5117, NULL, 'opengloss-v1.1')
