BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('blog_noun_0', 'blog', 'noun', 0, 'A blog is a frequently updated online publication consisting of discrete entries, typically displayed in reverse chronological order, that presents commentary, narrative, or analysis on a particular topic, authored by an individual or group.', '["weblog", "online diary", "digital journal"]', '["print publication", "newspaper"]', '["online publication", "digital media"]', '["personal blog", "corporate blog", "photoblog"]', '["blog post", "personal blog", "corporate blog", "blogging platform", "online journal", "photoblog"]', '{"noun_forms": ["blogger", "blogging"], "verb_forms": ["blog"], "adjective_forms": ["bloggable"], "adverb_forms": []}', '["Scholars maintain a blog to document field observations.", "The blog offers peer reviewed commentary on education policy."]', 'technology', '4', 56579, 5120, NULL, 'opengloss-v1.1'),
('blog_verb_0', 'blog', 'verb', 0, 'To maintain and publish regular content on a weblog by creating, editing, and posting entries online.', '["post", "publish", "write"]', '["delete", "unpublish"]', '["write online content"]', '["microblog", "vlog"]', '["blog post", "blog entry", "blogging platform", "academic blogging", "guest blog post"]', '{"noun_forms": ["blogger"], "verb_forms": [], "adjective_forms": ["bloggable"], "adverb_forms": []}', '["Researchers regularly blog about methodological updates to invite critique.", "Faculty members blog to disseminate interim findings to peers."]', 'technology', '4', 56579, 5120, NULL, 'opengloss-v1.1'),
('blog_noun_1', 'blog', 'noun', 1, 'A blog post is an individual article or note published on a blog, typically appearing as a single item within a blog’s reverse chronological stream.', '["entry", "post", "note"]', '["offline note", "print article"]', '["online content", "digital publication"]', '["text post", "image post", "video post"]', '["blog post", "personal blog", "corporate blog", "blogging platform", "online journal", "photoblog"]', '{"noun_forms": ["blogger", "blogging"], "verb_forms": ["blog"], "adjective_forms": ["bloggable"], "adverb_forms": []}', '["The latest blog post discusses methodological issues.", "An individual post can include figures and references."]', 'technology', '4', 56579, 5120, NULL, 'opengloss-v1.1'),
('blog_verb_1', 'blog', 'verb', 1, 'To publish a single blog post; to post an entry on a weblog.', '["post", "publish", "upload"]', '["unpublish", "delete"]', '["post online content"]', '["short post", "image post"]', '["blog post", "blog entry", "blogging platform", "academic blogging", "guest blog post"]', '{"noun_forms": ["blogger"], "verb_forms": [], "adjective_forms": ["bloggable"], "adverb_forms": []}', '["The researcher posted a brief post detailing experimental setup.", "Students uploaded a post summarizing results."]', 'technology', '4', 56579, 5120, NULL, 'opengloss-v1.1'),
('blog_verb_2', 'blog', 'verb', 2, 'To blog about a topic as part of scholarly communication, typically to provide commentary or critique or dissemination.', '["discuss", "comment", "analyze"]', '["ignore", "conceal"]', '["academic writing"]', '["research blog", "topic blog"]', '["blog post", "blog entry", "blogging platform", "academic blogging", "guest blog post"]', '{"noun_forms": ["blogger"], "verb_forms": [], "adjective_forms": ["bloggable"], "adverb_forms": []}', '["Scholars routinely blog methods to engage nonexpert audiences.", "Public engagement is advanced by faculty blogs about ongoing studies."]', 'technology', '4', 56579, 5120, NULL, 'opengloss-v1.1')
