-- lexi ETL: tape (2026-09-18T16:20:29Z) — opengloss-v1.1
BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('tape_noun_0', 'tape', 'noun', 0, 'A flexible strip of material coated with a pressure sensitive adhesive, used to bond, seal, or secure surfaces in engineering and manufacturing contexts.', '["sticky tape", "pressure sensitive tape", "scotch tape", "adhesive strip"]', '["nonadhesive tape"]', '["adhesive material"]', '["masking tape", "duct tape", "electrical tape", "double sided tape"]', '["adhesive tape", "sticky tape", "masking tape", "duct tape", "electrical tape", "tape measure"]', '{"noun_forms": ["tape measure"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The engineer sealed the joint with adhesive tape.", "During assembly, sticky tape secured the panel edges."]', 'technology', 'K', 56261, 5148, NULL, 'opengloss-v1.1'),
('tape_verb_0', 'tape', 'verb', 0, 'To record data on magnetic tape or other tape-based media using a recording device, as used in laboratory or industrial data capture.', '["record", "log", "document"]', '["erase", "delete"]', '["data recording"]', '["audio recording", "video recording"]', '["magnetic tape", "adhesive tape", "masking tape", "double sided tape", "pressure sensitive tape", "tape drive"]', '{"noun_forms": [], "verb_forms": ["taping"], "adjective_forms": [], "adverb_forms": []}', '["Spectral data were taped to magnetic tape for archival analysis.", "Researchers taped the sensor output onto reel tape during the experiment."]', 'technology', 'K', 56261, 5148, NULL, 'opengloss-v1.1'),
('tape_noun_1', 'tape', 'noun', 1, 'A flexible ruler used to measure length, typically retractable in a case.', '["tape measure", "measuring tape"]', '["rigid ruler", "fixed ruler"]', '["measuring instrument"]', '["steel tape", "fiberglass tape", "invar tape"]', '["adhesive tape", "sticky tape", "masking tape", "duct tape", "electrical tape", "tape measure"]', '{"noun_forms": ["tape measure"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The measuring tape was used to determine the length.", "The project required a steel tape for precision."]', 'technology', 'K', 56261, 5148, NULL, 'opengloss-v1.1'),
('tape_verb_1', 'tape', 'verb', 1, 'To fasten or seal a joint, boundary, or surface by applying tape.', '["attach", "bind", "seal"]', '["unseal", "unfasten", "detach"]', '["attach"]', '["tape fastening", "joint sealing", "surface sealing"]', '["magnetic tape", "adhesive tape", "masking tape", "double sided tape", "pressure sensitive tape", "tape drive"]', '{"noun_forms": [], "verb_forms": ["taping"], "adjective_forms": [], "adverb_forms": []}', '["The technician taped the seam to prevent leakage during testing.", "Components were taped together to maintain alignment throughout assembly."]', 'technology', 'K', 56261, 5148, NULL, 'opengloss-v1.1'),
('tape_noun_2', 'tape', 'noun', 2, 'A magnetic storage medium consisting of a long strip of magnetized material used to record digital data, typically wound on reels or in cartridges.', '["data tape", "magnetic tape"]', '["solid state storage"]', '["storage medium"]', '["LTO tape", "DAT tape", "DLT tape", "half inch tape"]', '["adhesive tape", "sticky tape", "masking tape", "duct tape", "electrical tape", "tape measure"]', '{"noun_forms": ["tape measure"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Backups were archived on magnetic tape in the data center.", "The library migrated historic files to LTO tape storage."]', 'technology', 'K', 56261, 5148, NULL, 'opengloss-v1.1'),
('tape_verb_2', 'tape', 'verb', 2, 'To mask or protect a surface by applying tape to isolate a region during processing such as painting or etching.', '["mask", "cover"]', '["unmask", "uncover"]', '["protect"]', '["edge masking", "area masking"]', '["magnetic tape", "adhesive tape", "masking tape", "double sided tape", "pressure sensitive tape", "tape drive"]', '{"noun_forms": [], "verb_forms": ["taping"], "adjective_forms": [], "adverb_forms": []}', '["During etching, the operator taped the edges to protect adjacent features.", "Paint was restricted by masking tape to delineate the circuit boundary."]', 'technology', 'K', 56261, 5148, NULL, 'opengloss-v1.1')
ON CONFLICT (source_id) DO UPDATE SET word = EXCLUDED.word, pos = EXCLUDED.pos, sense_index = EXCLUDED.sense_index, definition = EXCLUDED.definition, synonyms = EXCLUDED.synonyms, antonyms = EXCLUDED.antonyms, hypernyms = EXCLUDED.hypernyms, hyponyms = EXCLUDED.hyponyms, collocations = EXCLUDED.collocations, derivations = EXCLUDED.derivations, examples = EXCLUDED.examples, domain = EXCLUDED.domain, reading_level = EXCLUDED.reading_level, wiki_frequency = EXCLUDED.wiki_frequency, wiki_frequency_rank = EXCLUDED.wiki_frequency_rank, term_acr = EXCLUDED.term_acr, source = EXCLUDED.source;
