INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('jet_adjective_0', 'jet', 'adjective', 0, 'Jet is an adjective describing the color black, especially a very deep glossy black like polished jet.', '["black", "ebony", "inky", "sooty"]', '["white", "pale", "bright"]', '["color", "shade"]', '["pitch black", "inky black", "coal black"]', '["jet black", "jet-powered", "jet-like", "jet engine", "jet stream"]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": ["jetlike"], "adverb_forms": []}', '["The raven''s feathers looked jet black in the sunlight.", "She wore a jacket in jet black to match her hair."]', 'science', '1', 56045, 5159, NULL, 'opengloss-v1.1'),
('jet_noun_0', 'jet', 'noun', 0, 'A jet is a fast stream of liquid or gas forced out of a nozzle.', '["stream", "spray", "flow"]', '["calm", "stagnation"]', '["flow"]', '["water jet", "steam jet"]', '["jet engine", "fighter jet", "jet stream", "water jet", "jet fuel", "jet lag"]', '{"noun_forms": ["jetting"], "verb_forms": [], "adjective_forms": ["jetlike"], "adverb_forms": []}', '["A jet of water sprayed from the lab faucet.", "The scientist observed a jet of air in the wind tunnel."]', 'science', '1', 56045, 5159, NULL, 'opengloss-v1.1'),
('jet_verb_0', 'jet', 'verb', 0, 'To move quickly and suddenly, often with forward propulsion or acceleration.', '["speed", "dash", "race"]', '["crawl", "creep"]', '["move", "travel"]', '["dart", "sprint", "bolt"]', '["jet engine", "jet stream", "jet propulsion", "jet lag", "jet pack"]', '{"noun_forms": ["jetter", "jetting"], "verb_forms": ["jetting"], "adjective_forms": [], "adverb_forms": []}', '["The race car jets down the track.", "The rocket jets into space after liftoff."]', 'science', '1', 56045, 5159, NULL, 'opengloss-v1.1'),
('jet_noun_1', 'jet', 'noun', 1, 'A jet is a type of aircraft powered by jet engines.', '["aircraft", "airplane"]', '["propeller plane"]', '["aircraft"]', '["fighter jet", "passenger jet"]', '["jet engine", "fighter jet", "jet stream", "water jet", "jet fuel", "jet lag"]', '{"noun_forms": ["jetting"], "verb_forms": [], "adjective_forms": ["jetlike"], "adverb_forms": []}', '["The fighter jet performed a precision maneuver over the field.", "A passenger jet flew across the continent for students on a field trip."]', 'science', '1', 56045, 5159, NULL, 'opengloss-v1.1'),
('jet_verb_1', 'jet', 'verb', 1, 'To emit or spout a stream, as water or steam, from a nozzle.', '["spray", "spout", "emit"]', '["absorb", "retain"]', '["emit", "release"]', '["spray", "spout", "erupt"]', '["jet engine", "jet stream", "jet propulsion", "jet lag", "jet pack"]', '{"noun_forms": ["jetter", "jetting"], "verb_forms": ["jetting"], "adjective_forms": [], "adverb_forms": []}', '["Water jets from the fountain each afternoon.", "Steam jets from the kettle when boiled."]', 'science', '1', 56045, 5159, NULL, 'opengloss-v1.1'),
('jet_noun_2', 'jet', 'noun', 2, 'Jet is a black lignite mineral used especially in jewelry.', '["fossil coal", "lignite"]', '[]', '["mineral"]', '["jet bead", "jet pendant"]', '["jet engine", "fighter jet", "jet stream", "water jet", "jet fuel", "jet lag"]', '{"noun_forms": ["jetting"], "verb_forms": [], "adjective_forms": ["jetlike"], "adverb_forms": []}', '["The pendant is carved from jet.", "Whitby jet jewelry was popular during the Victorian era."]', 'science', '1', 56045, 5159, NULL, 'opengloss-v1.1'),
('jet_noun_3', 'jet', 'noun', 3, 'Jet is a deep black color or shade.', '["ebony", "onyx"]', '["white", "pale"]', '["color", "shade"]', '["ebony", "onyx"]', '["jet engine", "fighter jet", "jet stream", "water jet", "jet fuel", "jet lag"]', '{"noun_forms": ["jetting"], "verb_forms": [], "adjective_forms": ["jetlike"], "adverb_forms": []}', '["The dress color is jet.", "Color charts list jet as a deep black."]', 'science', '1', 56045, 5159, NULL, 'opengloss-v1.1')
