('fill_noun_0', 'fill', 'noun', 0, 'A substance or material used to fill a hole, space, or cavity.', '["filler", "material", "substance"]', '["hole", "void"]', '["material", "substance"]', '["earth fill", "cement fill", "sand fill", "rock fill"]', '[]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The dentist placed a fill to seal the cavity.", "Earth fill was added to the trench to raise the ground."]', 'technology', '1', 54770, 5241, NULL, 'opengloss-v1.1'),
('fill_verb_0', 'fill', 'verb', 0, 'To put a substance or material into a container until it reaches capacity, making the content full.', '["load", "pack", "stuff"]', '["empty", "drain"]', '["volume change"]', '["fill a container", "fill a glass", "fill a tank"]', '["fill in", "fill out", "fill up", "fill a form", "fill the gap", "fill with water"]', '{"noun_forms": ["filler", "filling"], "verb_forms": ["refill"], "adjective_forms": ["filled", "unfilled"], "adverb_forms": []}', '["Fill the bottle with water until the level reaches the rim.", "The jar was filled with marbles to teach counting."]', 'technology', '1', 54770, 5241, NULL, 'opengloss-v1.1'),
('fill_noun_1', 'fill', 'noun', 1, 'The amount of material used to fill a space or container or the act of filling.', '["volume", "quantity", "level", "amount"]', '["hole", "vacancy"]', '["measurement", "quantity"]', '["volume", "capacity", "amount"]', '[]', '{"noun_forms": [], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The fill amount should equal the container capacity.", "Check the fill level before continuing the experiment."]', 'technology', '1', 54770, 5241, NULL, 'opengloss-v1.1'),
