BEGIN;
INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('computing_adjective_0', 'computing', 'adjective', 0, 'Relating to computers, computation, or the use of computational methods and systems.', '["computational", "computer based", "digital"]', '["analog", "noncomputational"]', '["technological", "digital"]', '["high performance computing", "distributed computing"]', '["computing technology", "computing infrastructure", "computing skills", "computing education"]', '{"noun_forms": ["computing", "computation"], "verb_forms": ["compute"], "adjective_forms": ["computational", "computerized"], "adverb_forms": ["computationally"]}', '["The computing infrastructure of the institution supports thousands of simultaneous users.", "Advances in computing technology have enabled large scale simulations in physics and engineering."]', 'technology', '4', 54540, 5265, NULL, 'opengloss-v1.1'),
('computing_noun_0', 'computing', 'noun', 0, 'The systematic study or practice of using computers and computational processes to solve problems, process information, and automate tasks.', '["computer science", "information technology", "computation"]', '["manual work", "noncomputing"]', '["technology", "engineering discipline"]', '["scientific computing", "cloud computing"]', '["cloud computing", "scientific computing", "personal computing", "ubiquitous computing"]', '{"noun_forms": ["computer", "computation", "computability"], "verb_forms": ["compute", "recompute"], "adjective_forms": ["computational", "computing related"], "adverb_forms": ["computationally"]}', '["Computing has transformed how scientists analyze large datasets in fields such as genomics and climate science.", "The university offers several undergraduate degrees in computing, including software engineering and data science."]', 'technology', '4', 54540, 5265, NULL, 'opengloss-v1.1'),
('computing_verb_0', 'computing', 'verb', 0, 'Present participle of compute: to determine a result or value by means of a mathematical or algorithmic process, typically using a computer.', '["calculating", "processing", "evaluating"]', '["guessing", "estimating"]', '["calculating", "processing"]', '["parallel computing", "iterative computing"]', '["computing results", "computing resources", "computing time", "computing power"]', '{"noun_forms": ["computation", "computer", "computing"], "verb_forms": ["recompute", "precompute"], "adjective_forms": ["computational", "computed"], "adverb_forms": ["computationally"]}', '["The algorithm is currently computing the optimal route for all delivery trucks in the network.", "While the model is computing, the researcher prepares the next batch of input data."]', 'technology', '4', 54540, 5265, NULL, 'opengloss-v1.1'),
('computing_adjective_1', 'computing', 'adjective', 1, 'Involving or characterized by the practical application of computer systems and software in a specific context or domain.', '["IT related", "computer oriented"]', '["nontechnical"]', '["technical", "applied"]', '["mobile computing", "embedded computing"]', '["computing technology", "computing infrastructure", "computing skills", "computing education"]', '{"noun_forms": ["computing", "computation"], "verb_forms": ["compute"], "adjective_forms": ["computational", "computerized"], "adverb_forms": ["computationally"]}', '["The course provides an introduction to computing skills for social science students.", "Computing education has become essential for preparing students for the modern workforce."]', 'technology', '4', 54540, 5265, NULL, 'opengloss-v1.1'),
('computing_noun_1', 'computing', 'noun', 1, 'The activity or process of operating computer systems, including hardware, software, and networks, in practical contexts such as business, research, and everyday life.', '["computer use", "computer operation", "IT work"]', '["paperwork", "analog processing"]', '["computer activity", "information processing"]', '["mobile computing", "personal computing"]', '["cloud computing", "scientific computing", "personal computing", "ubiquitous computing"]', '{"noun_forms": ["computer", "computation", "computability"], "verb_forms": ["compute", "recompute"], "adjective_forms": ["computational", "computing related"], "adverb_forms": ["computationally"]}', '["Modern business computing relies heavily on distributed systems and networked databases.", "Personal computing has become ubiquitous with the widespread adoption of smartphones and laptops."]', 'technology', '4', 54540, 5265, NULL, 'opengloss-v1.1'),
('computing_verb_1', 'computing', 'verb', 1, 'Engaging in the act of using computers to perform tasks such as data analysis, simulation, or information retrieval.', '["using computers", "processing data"]', '["working offline"]', '["working", "operating"]', '["batch computing", "interactive computing"]', '["computing results", "computing resources", "computing time", "computing power"]', '{"noun_forms": ["computation", "computer", "computing"], "verb_forms": ["recompute", "precompute"], "adjective_forms": ["computational", "computed"], "adverb_forms": ["computationally"]}', '["Students were computing on the lab machines for most of the afternoon.", "Researchers spent several weeks computing on a high performance cluster to complete the simulation."]', 'technology', '4', 54540, 5265, NULL, 'opengloss-v1.1'),
('computing_noun_2', 'computing', 'noun', 2, 'The academic and professional field encompassing the theory, design, development, and application of computer systems and algorithms.', '["computing discipline", "computing field"]', '["nontechnical field"]', '["academic discipline", "STEM field"]', '["theoretical computing", "human centered computing"]', '["cloud computing", "scientific computing", "personal computing", "ubiquitous computing"]', '{"noun_forms": ["computer", "computation", "computability"], "verb_forms": ["compute", "recompute"], "adjective_forms": ["computational", "computing related"], "adverb_forms": ["computationally"]}', '["Interdisciplinary computing bridges computer science with disciplines like biology and economics.", "Ethics in computing has become a central concern in the development of artificial intelligence systems."]', 'technology', '4', 54540, 5265, NULL, 'opengloss-v1.1')
