INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('rag_noun_0', 'rag', 'noun', 0, 'A fragment or strip of fabric, typically torn from textile material, used as a disposable cleaning or wiping implement.', '["scrap", "shred", "fragment"]', '["new fabric", "whole cloth"]', '["cloth", "fabric", "textile", "material"]', '["scrap", "strip"]', '["cleaning rag", "dust rag", "old rag", "rag paper", "rag bag", "rag trade"]', '{"noun_forms": ["ragtime", "ragbag", "ragpicker"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The study used rag samples as baseline textile scraps.", "Rag fragments served as wiping material in solvent compatibility tests."]', 'general', '1', 8011, 19824, 'RAG', 'opengloss-v1.1'),
('rag_verb_0', 'rag', 'verb', 0, 'To tease, mock, or harass someone by making jokes about them, typically in social or academic contexts.', '["tease", "mock", "badger"]', '["praise", "compliment"]', '["mocking", "social behavior", "action"]', '["razz", "rib"]', '["ragging incident", "ragging policy", "ragging culture", "ragged edge", "ragged fabric", "ragging"]', '{"noun_forms": ["ragger", "ragging"], "verb_forms": [], "adjective_forms": ["ragged"], "adverb_forms": []}', '["Senior students rag the junior analyst about citation style.", "Mentors sometimes rag the novice researcher for minor methodological mistakes."]', 'general', '1', 8011, 19824, 'RAG', 'opengloss-v1.1'),
('rag_noun_1', 'rag', 'noun', 1, 'A newspaper, especially a low quality or sensational one; pejorative term for such publications.', '["tabloid", "newspaper", "publication"]', '["quality press", "serious press"]', '["publication", "periodical", "press"]', '["tabloid", "yellow press"]', '["cleaning rag", "dust rag", "old rag", "rag paper", "rag bag", "rag trade"]', '{"noun_forms": ["ragtime", "ragbag", "ragpicker"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The local rag was cited in media studies to analyze sensational framing.", "Archive reviews describe the rag''s influence on public opinion during the period."]', 'general', '1', 8011, 19824, 'RAG', 'opengloss-v1.1'),
('rag_verb_1', 'rag', 'verb', 1, 'To harass or nag persistently about faults or mistakes, often over an extended period.', '["harass", "nag", "badger"]', '["praise", "encourage"]', '["harassment", "behavior", "action"]', '["badger", "nag"]', '["ragging incident", "ragging policy", "ragging culture", "ragged edge", "ragged fabric", "ragging"]', '{"noun_forms": ["ragger", "ragging"], "verb_forms": [], "adjective_forms": ["ragged"], "adverb_forms": []}', '["The committee ragged the intern about late data submission for weeks.", "In fieldwork, supervisors rag the assistant about protocol deviations repeatedly."]', 'general', '1', 8011, 19824, 'RAG', 'opengloss-v1.1'),
('rag_verb_2', 'rag', 'verb', 2, 'To tear or pull fabric or other material roughly, often causing it to become ragged.', '["tear", "rip"]', '["mend", "repair"]', '["tearing", "damage", "action"]', '["tear", "rip"]', '["ragging incident", "ragging policy", "ragging culture", "ragged edge", "ragged fabric", "ragging"]', '{"noun_forms": ["ragger", "ragging"], "verb_forms": [], "adjective_forms": ["ragged"], "adverb_forms": []}', '["The wind ragged the sails.", "Heavy rainfall ragged the banner leaving tatters."]', 'general', '1', 8011, 19824, 'RAG', 'opengloss-v1.1')
