INSERT INTO lexi_senses (source_id, word, pos, sense_index, definition, synonyms, antonyms, hypernyms, hyponyms, collocations, derivations, examples, domain, reading_level, wiki_frequency, wiki_frequency_rank, term_acr, source) VALUES
('saas_noun_0', 'saas', 'noun', 0, 'A software licensing and delivery model in which applications are hosted by a provider and made available to customers over a network, typically the internet, on a subscription or pay-per-use basis.', '["software as a service", "cloud application", "hosted software"]', '["on-premises software", "perpetual license"]', '["software model", "service model"]', '["customer relationship management saas", "enterprise resource planning saas"]', '["saas model", "saas provider", "saas platform", "saas application"]', '{"noun_forms": ["saas provider", "saas platform", "saas application"], "verb_forms": ["productize as saas"], "adjective_forms": ["saas based", "saas enabled"], "adverb_forms": ["as saas"]}', '["Many startups choose a saas model to reduce upfront infrastructure costs and accelerate deployment.", "The university migrated its email system to a saas solution managed by an external vendor."]', 'technology', 'BS', 2420, 40176, 'SaaS', 'opengloss-v1.1'),
('saas_noun_1', 'saas', 'noun', 1, 'A business or revenue model in which value is delivered primarily through ongoing access to remotely hosted software, usually involving recurring billing, service-level agreements, and continuous updates.', '["subscription software model", "recurring software service"]', '["one-time purchase model"]', '["business model", "revenue model"]', '["freemium saas", "enterprise saas"]', '["saas model", "saas provider", "saas platform", "saas application"]', '{"noun_forms": ["saas provider", "saas platform", "saas application"], "verb_forms": ["productize as saas"], "adjective_forms": ["saas based", "saas enabled"], "adverb_forms": ["as saas"]}', '["Investors often favor saas companies because their recurring revenues are more predictable than traditional license sales.", "From a strategic perspective, saas alters incentives by tying vendor profits to long-term customer retention rather than one-time transactions."]', 'technology', 'BS', 2420, 40176, 'SaaS', 'opengloss-v1.1'),
('saas_noun_2', 'saas', 'noun', 2, 'An individual product, platform, or company that operates according to the software as a service model, often contrasted with platform as a service or infrastructure as a service.', '["saas product", "saas platform"]', '["on-premises application"]', '["cloud service", "software service"]', '["vertical saas", "horizontal saas"]', '["saas model", "saas provider", "saas platform", "saas application"]', '{"noun_forms": ["saas provider", "saas platform", "saas application"], "verb_forms": ["productize as saas"], "adjective_forms": ["saas based", "saas enabled"], "adverb_forms": ["as saas"]}', '["The research compares a traditional enterprise resource planning system with a cloud-native saas in terms of total cost of ownership.", "The firm offers multiple cloud services, including iaas, paas, and a flagship saas for data analytics."]', 'technology', 'BS', 2420, 40176, 'SaaS', 'opengloss-v1.1')
